{"command":"cd /tmp/fp && cat > cmp3.py <<'EOF'
from decimal import Decimal, getcontext
getcontext().prec=800
vals=[float(l) for l in open('vals.txt')]
outs=[l.rstrip('\n') for l in open('out.txt')]
def digits(v, n):
    # exact digits of |v|: return (digitstring of length n via truncation, exponent)
    d=Decimal(abs(v))
    s,dg,e=d.as_tuple()
    ds=''.join(map(str,dg))
    # decimal point position: value = 0.ds * 10^(len(ds)+e)
    dp=len(ds)+e
    ds=ds.lstrip('0')
    return ds, dp
def roundstr(ds, n):
    # round half up digit string to n digits; returns (str, carry)
    if len(ds)<=n: return ds, 0
    head=list(ds[:n])
    if ds[n]>='5':
        j=n-1
        while True:
            if head[j]=='9':
                head[j]='0'
                if j==0:
                    head=['1']+head
                    return ''.join(head[:n]),1
                j-=1
            else:
                head[j]=chr(ord(head[j])+1); break
    return ''.join(head),0
def render(neg, ds, dp):
    ds=ds.rstrip('0') or '0'
    # mimic %!.Ng: exponent = dp-1
    e=dp-1
    p=17
    if e< -4 or e>=p:
        m=ds[0]+'.'+(ds[1:] or '0')
        s=m+'e'+('-' if e<0 else '+')+'%02d'%abs(e)
    else:
        if dp<=0:
            s='0.'+'0'*(-dp)+ds
        elif dp>=len(ds):
            s=ds+'0'*(dp-len(ds))+'.0'
        else:
            s=ds[:dp]+'.'+ds[dp:]
    return ('-' if neg else '')+s
def fmt(v, n, dbl):
    ds,dp=digits(v,0)
    if dbl:
        ds19=ds[:19]  # truncate to 19 digits
        ds,c=roundstr(ds19,18); dp+=c
        ds,c=roundstr(ds,n); dp+=c
    else:
        ds,c=roundstr(ds,n); dp+=c
    return render(v<0, ds, dp)
def H1(v):
    if v==0: return '0.0'
    s=fmt(v,15,False)
    if float(s)==v: return s
    return fmt(v,17,True)
bad=0
for v,o in zip(vals,outs):
    h=H1(v)
    if h!=o:
        bad+=1
        if bad<40: print(repr(v),o,h)
print('bad',bad)
EOF
