    dp=len(ip)+e
    st=ds.lstrip('0'); dp-= (len(ds)-len(st))
    return st, dp
def rnd(ds,dp,n):
    if len(ds)<=n: return ds,dp
    x=int(ds[:n])
    if ds[n]>='5': x+=1
    s=str(x)
    if len(s)>n: dp+=1; s=s[:n]
    return s,dp
def render(neg,ds,dp):
    ds=ds.rstrip('0') or '0'
