	"strings"
)

type Kind uint8

const (
	KNull Kind = iota
	KInt
	KReal
	KText
	KBlob
)

type Value struct {
	K Kind
	I int64
	F float64
	S string
}

var NullValue = Value{}

func IntValue(i int64) Value    { return Value{K: KInt, I: i} }
func RealValue(f float64) Value { return Value{K: KReal, F: f} }
func TextValue(s string) Value  { return Value{K: KText, S: s} }
func BlobValue(s string) Value  { return Value{K: KBlob, S: s} }
func BoolValue(b bool) Value {
	if b {
		return IntValue(1)
	}
	return IntValue(0)
}

func (v Value) IsNull() bool { return v.K == KNull }

func (v Value) TypeName() string {
	switch v.K {
	case KInt:
		return "integer"
	case KReal:
		return "real"
	case KText:
		return "text"
	case KBlob:
		return "blob"
	}
	return "null"
}

// Text conversion (sqlite3_value_text)
func (v Value) Text() string {
	switch v.K {
	case KInt:
		return strconv.FormatInt(v.I, 10)
	case KReal:
		return FormatReal(v.F)
	case KText, KBlob:
		return v.S
	}
	return ""
}

func FormatReal(f float64) string {
	return fmtG17(f)
}

// isSpace per sqlite
func isSpaceByte(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\f' || c == '\r' || c == '\v'
}

// parseNumPrefix parses a numeric prefix of s following sqlite3AtoF rules.
// returns: value as float, whether it is integer-valued text (no '.', no 'e'),
// the int value if integer and fits, number of bytes consumed (incl leading space),
// and whether the entire string (allowing trailing spaces) is a valid number.
type numParse struct {
	ok       bool // some digits found
	full     bool // entire string consumed (with trailing spaces)
	isInt    bool // no decimal point or exponent
	intOK    bool // integer fits in int64
	i        int64
	f        float64
	consumed int
}

func parseNumber(s string) numParse {
	var r numParse
	i := 0
	n := len(s)
	for i < n && isSpaceByte(s[i]) {
		i++
	}
	start := i
	neg := false
	if i < n && (s[i] == '+' || s[i] == '-') {
		neg = s[i] == '-'
		i++
	}
	digStart := i
	for i < n && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	intDigits := i - digStart
	fracDigits := 0
	isInt := true
	if i < n && s[i] == '.' {
		j := i + 1
		for j < n && s[j] >= '0' && s[j] <= '9' {
			j++
		}
		fracDigits = j - i - 1
		if intDigits > 0 || fracDigits > 0 {
			isInt = false
			i = j
		}
	}
	if intDigits == 0 && fracDigits == 0 {
		r.consumed = 0
		_ = start
		return r
	}
	mantEnd := i
	if i < n && (s[i] == 'e' || s[i] == 'E') {
		j := i + 1
		if j < n && (s[j] == '+' || s[j] == '-') {
			j++
		}
		k := j
		for k < n && s[k] >= '0' && s[k] <= '9' {
			k++
		}
		if k > j {
			isInt = false
			i = k
		}
	}
	r.ok = true
	r.consumed = i
	j := i
	for j < n && isSpaceByte(s[j]) {
		j++
	}
	r.full = j == n
	r.isInt = isInt
	numStr := s[start:i]
	if isInt {
		iv, err := strconv.ParseInt(numStr, 10, 64)
		if err == nil {
			r.intOK = true
			r.i = iv
			r.f = float64(iv)
		} else {
			f, _ := strconv.ParseFloat(numStr, 64)
			r.f = f
		}
	} else {
		f, err := strconv.ParseFloat(numStr, 64)
		if err != nil {
			// may be range error; ParseFloat returns +-Inf or 0 appropriately
			_ = err
		}
		r.f = f
	}
	_ = neg
	_ = mantEnd
	return r
}

// numeric value of v for arithmetic: returns int or real Value
func (v Value) Numeric() Value {
	switch v.K {
	case KInt, KReal:
		return v
	case KNull:
		return v
	case KText, KBlob:
		p := parseNumber(v.S)
		if !p.ok {
			return IntValue(0)
		}
		if p.isInt && p.intOK {
			return IntValue(p.i)
		}
		if p.isInt {
			return RealValue(p.f)
		}
		return RealValue(p.f)
	}
	return v
}

func (v Value) Float() float64 {
	switch v.K {
	case KInt:
		return float64(v.I)
	case KReal:
		return v.F
	case KText, KBlob:
		p := parseNumber(v.S)
		if !p.ok {
			return 0
		}
		return p.f
	}
	return 0
}

func floatToInt(f float64) int64 {
	if math.IsNaN(f) {
		return 0
	}
	if f >= 9223372036854775807.0 {
		return math.MaxInt64
	}
	if f <= -9223372036854775808.0 {
		return math.MinInt64
	}
	return int64(f)
}

// Int conversion like sqlite3VdbeIntValue
func (v Value) Int() int64 {
	switch v.K {
	case KInt:
		return v.I
	case KReal:
		return floatToInt(v.F)
	case KText, KBlob:
		return atoiPrefix(v.S)
	}
	return 0
}

// atoiPrefix: integer prefix of string (sqlite3Atoi64 semantics with clamping)
func atoiPrefix(s string) int64 {
	i := 0
	n := len(s)
	for i < n && isSpaceByte(s[i]) {
		i++
	}
	neg := false
	if i < n && (s[i] == '+' || s[i] == '-') {
		neg = s[i] == '-'
		i++
	}
	var u uint64
	overflow := false
	for i < n && s[i] >= '0' && s[i] <= '9' {
		d := uint64(s[i] - '0')
		if u > (math.MaxUint64-d)/10 {
			overflow = true
		} else {
			u = u*10 + d
		}
		i++
	}
	if neg {
		if overflow || u > 1<<63 {
			return math.MinInt64
		}
		return -int64(u)
	}
	if overflow || u > math.MaxInt64 {
		return math.MaxInt64
	}
	return int64(u)
}

func (v Value) Bool() bool {
	switch v.K {
	case KInt:
		return v.I != 0
	case KReal:
		return v.F != 0
	case KText, KBlob:
		return v.Float() != 0
	}
	return false
}

// Affinity
type Affinity uint8

const (
	AffNone Affinity = iota // BLOB
	AffText
	AffNumeric
	AffInteger
	AffReal
)

func affinityOfType(decl string) Affinity {
	u := strings.ToUpper(decl)
	if strings.Contains(u, "INT") {
		return AffInteger
	}
	if strings.Contains(u, "CHAR") || strings.Contains(u, "CLOB") || strings.Contains(u, "TEXT") {
		return AffText
	}
	if strings.Contains(u, "BLOB") || u == "" {
		return AffNone
	}
	if strings.Contains(u, "REAL") || strings.Contains(u, "FLOA") || strings.Contains(u, "DOUB") {
		return AffReal
	}
	return AffNumeric
}

// applyAffinity converts value for storage in a column of affinity a.
func applyAffinity(v Value, a Affinity) Value {
	switch a {
	case AffText:
		if v.K == KInt || v.K == KReal {
			return TextValue(v.Text())
		}
		return v
	case AffNumeric, AffInteger:
		if v.K == KText {
			return textToNumericAff(v)
		}
		if v.K == KReal {
			// real that is integral stays real for NUMERIC? sqlite: REAL stays REAL
			return v
		}
		return v
	case AffReal:
		if v.K == KText {
			n := textToNumericAff(v)
			if n.K == KInt {
				return RealValue(float64(n.I))
			}
			return n
		}
		if v.K == KInt {
			return RealValue(float64(v.I))
		}
		return v
	}
	return v
}

// textToNumericAff: if text looks like a number, convert to INTEGER or REAL
func textToNumericAff(v Value) Value {
	p := parseNumber(v.S)
	if !p.ok || !p.full {
		return v
	}
	// hex not allowed
	if p.isInt {
		if p.intOK {
			return IntValue(p.i)
		}
		return RealValue(p.f)
	}
	f := p.f
	// if real is integral and fits, convert to integer
	if f == math.Trunc(f) && math.Abs(f) < 9.2233720368547758e18 {
		iv := int64(f)
		if float64(iv) == f {
			return IntValue(iv)
		}
	}
	return RealValue(f)
}

// numeric affinity applied in comparisons (does not lose text that isn't numeric)
func applyNumericAffinityCmp(v Value) Value {
	if v.K == KText {
		p := parseNumber(v.S)
		if p.ok && p.full {
			if p.isInt && p.intOK {
				return IntValue(p.i)
			}
			return RealValue(p.f)
		}
	}
	return v
}

// Collation
type Collation func(a, b string) int

func collBinary(a, b string) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func asciiLower(c byte) byte {
	if c >= 'A' && c <= 'Z' {
		return c + 32
	}
	return c
}

func collNocase(a, b string) int {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		x, y := asciiLower(a[i]), asciiLower(b[i])
		if x != y {
			if x < y {
				return -1
			}
			return 1
		}
	}
	if len(a) < len(b) {
		return -1
	}
	if len(a) > len(b) {
		return 1
	}
	return 0
}

func collRtrim(a, b string) int {
	return collBinary(strings.TrimRight(a, " "), strings.TrimRight(b, " "))
}

func getCollation(name string) Collation {
	switch strings.ToUpper(name) {
	case "BINARY", "":
		return collBinary
	case "NOCASE":
		return collNocase
	case "RTRIM":
		return collRtrim
	}
	return nil
}

func cmpIntFloat(i int64, f float64) int {
	if math.IsNaN(f) {
		return 1
	}
	if f < -9223372036854775808.0 {
		return 1
	}
	if f >= 9223372036854775808.0 {
		return -1
	}
	fi := float64(i)
	if fi < f {
		return -1
	}
	if fi > f {
		return 1
	}
	// fi == f; compare precisely
	t := int64(f)
	if i < t {
		return -1
	}
	if i > t {
		return 1
	}
	return 0
}

// Compare two values with sqlite ordering. coll used for text.
func compareValues(a, b Value, coll Collation) int {
	ka, kb := a.K, b.K
	ca, cb := classOf(ka), classOf(kb)
	if ca != cb {
		if ca < cb {
			return -1
		}
		return 1
	}
	switch ca {
	case 0:
		return 0
	case 1:
		if ka == KInt && kb == KInt {
			if a.I < b.I {
				return -1
			}
			if a.I > b.I {
				return 1
			}
			return 0
		}
		if ka == KReal && kb == KReal {
			if a.F < b.F {
				return -1
			}
			if a.F > b.F {
				return 1
			}
			return 0
		}
		if ka == KInt {
			return cmpIntFloat(a.I, b.F)
		}
		return -cmpIntFloat(b.I, a.F)
	case 2:
		if coll == nil {
			coll = collBinary
		}
		return coll(a.S, b.S)
	default:
		return collBinary(a.S, b.S)
	}
}

func classOf(k Kind) int {
	switch k {
	case KNull:
		return 0
	case KInt, KReal:
		return 1
	case KText:
		return 2
	}
	return 3
}

func (v Value) Equal(o Value) bool {
	return v.K == o.K && compareValues(v, o, collBinary) == 0
}

// quote a value as SQL literal
func sqlQuote(v Value) string {
	switch v.K {
	case KNull:
		return "NULL"
	case KInt:
		return strconv.FormatInt(v.I, 10)
	case KReal:
		return quoteReal(v.F)
	case KText:
		return "'" + strings.ReplaceAll(v.S, "'", "''") + "'"
	case KBlob:
		return "X'" + strings.ToUpper(hexEncode(v.S)) + "'"
	}
	return ""
}

func quoteReal(f float64) string {
	if math.IsInf(f, 1) {
		return "9.0e+999"
	}
	if math.IsInf(f, -1) {
		return "-9.0e+999"
	}
	return FormatReal(f)
}

const hexdigits = "0123456789abcdef"

func hexEncode(s string) string {
	b := make([]byte, len(s)*2)
	for i := 0; i < len(s); i++ {
		b[2*i] = hexdigits[s[i]>>4]
		b[2*i+1] = hexdigits[s[i]&15]
	}
	return string(b)
}
