// decodeDigits computes v = round(r*10^k) with k chosen so v has 18-19 digits.
func decodeDigits(r float64) ([]byte, int) {
	bits := math.Float64bits(r)
	exp := int((bits >> 52) & 0x7ff)
	mant := bits & ((1 << 52) - 1)
	var e2 int
	if exp == 0 {
		// subnormal
		exp = 1
	} else {
		mant |= 1 << 52
	}
	e := exp - 1075 // r = mant * 2^e
	// binary exponent of leading bit
	lb := 0
	for t := mant; t > 1; t >>= 1 {
		lb++
