	e2 = e + lb
	fl := (e2 * 78913) >> 18
	k := 17 - fl
	// x = mant * 2^e * 10^k
	num := new(big.Int).SetUint64(mant)
	den := big.NewInt(1)
	if k >= 0 {
		num.Mul(num, pow10BigCached(k))
	} else {
		den.Mul(den, pow10BigCached(-k))
	}
	if e >= 0 {
		num.Lsh(num, uint(e))
	} else {
