package main

import (
	"math"
	"math/big"
	"strconv"
)

type fpDec struct {
	neg     bool
	special int // 0 normal, 1 inf, 2 nan
	z       []byte
	n       int
	iDP     int
}

var bigTen = big.NewInt(10)

func pow10Big(k int) *big.Int {
	return new(big.Int).Exp(bigTen, big.NewInt(int64(k)), nil)
}

var pow10Cache = map[int]*big.Int{}

func pow10BigCached(k int) *big.Int {
	if p, ok := pow10Cache[k]; ok {
		return p
	}
	p := pow10Big(k)
	pow10Cache[k] = p
	return p
}

// decodeDigits computes v = round(r*10^k) with k chosen so v has 18-19 digits.
func decodeDigits(r float64) ([]byte, int) {
	bits := math.Float64bits(r)
	exp := int((bits >> 52) & 0x7ff)
	mant := bits & ((1 << 52) - 1)
	var e2 int
	if exp == 0 {
		// subnormal
		exp = 1
	} else {
		mant |= 1 << 52
	}
	e := exp - 1075 // r = mant * 2^e
	// binary exponent of leading bit
	lb := 0
	for t := mant; t > 1; t >>= 1 {
		lb++
	}
	e2 = e + lb
	fl := (e2 * 78913) >> 18
	k := 17 - fl
	// x = mant * 2^e * 10^k
	num := new(big.Int).SetUint64(mant)
	den := big.NewInt(1)
	if k >= 0 {
		num.Mul(num, pow10BigCached(k))
	} else {
		den.Mul(den, pow10BigCached(-k))
	}
	if e >= 0 {
		num.Lsh(num, uint(e))
	} else {
		den.Lsh(den, uint(-e))
	}
	// v = floor((2*num + den) / (2*den))
	num.Lsh(num, 1)
	num.Add(num, den)
	den.Lsh(den, 1)
	num.Quo(num, den)
	s := num.String()
	return []byte(s), len(s) - k
}

func fpDecode(r float64, iRound, mxRound int) fpDec {
	var p fpDec
	if r < 0 {
		p.neg = true
		r = -r
	}
	if math.IsNaN(r) {
		p.special = 2
		return p
	}
	if math.IsInf(r, 0) {
		p.special = 1
		return p
	}
	if r == 0 {
		p.z = []byte{'0'}
		p.n = 1
		p.iDP = 1
		return p
	}
	z, iDP := decodeDigits(r)
	p.n = len(z)
	p.iDP = iDP
	if iRound <= 0 {
		iRound = p.iDP - iRound
		if iRound == 0 && z[0] >= '5' {
			iRound = 1
			z = append([]byte{'0'}, z...)
			p.n++
			p.iDP++
		}
	}
	if iRound > 0 && (iRound < p.n || p.n > mxRound) {
		if iRound > mxRound {
			iRound = mxRound
		}
		orig := z
		_ = orig
		p.n = iRound
		if z[iRound] >= '5' {
			j := iRound - 1
			for {
				z[j]++
				if z[j] <= '9' {
					break
				}
				z[j] = '0'
				if j == 0 {
					z = append([]byte{'1'}, z...)
					p.n++
					p.iDP++
					break
				}
				j--
			}
		}
		z = z[:p.n]
		if iRound == 17 && p.n == 17 && z[16] != '0' {
			if (z[13] == '0' && z[14] == '0' && z[15] == '0') || (z[14] == '9' && z[15] == '9') {
				// try 15 digit rounding
				c := make([]byte, 15)
				copy(c, z[:15])
				cdp := p.iDP
				if z[15] >= '5' {
					j := 14
					for {
						c[j]++
						if c[j] <= '9' {
							break
						}
						c[j] = '0'
						if j == 0 {
							c = append([]byte{'1'}, c[:14]...)
							cdp++
							break
						}
						j--
					}
				}
				str := "0." + string(c) + "e" + strconv.Itoa(cdp)
				f, err := strconv.ParseFloat(str, 64)
				if err == nil && f == r {
					z = c
					p.n = 15
					p.iDP = cdp
				}
			}
		}
	} else if iRound < 0 {
		// number too small for the requested precision
		p.n = 0
	}
	for p.n > 0 && z[p.n-1] == '0' {
		p.n--
	}
	p.z = z[:p.n]
	return p
}

type fmtFlags struct {
	leftJustify bool
	plus        bool
	blank       bool
	alt         bool // '#'
	alt2        bool // '!'
	zeropad     bool
	thousand    bool
}

// formatFloatSQL implements sqlite printf %f %e %g (%E %G with upper)
func formatFloatSQL(realvalue float64, xtype byte, precision int, width int, fl fmtFlags) string {
	upper := false
	if xtype == 'E' || xtype == 'G' {
		upper = true
		xtype = xtype + 32
	}
	if precision < 0 {
		precision = 6
	}
	var iRound int
	switch xtype {
	case 'f':
		iRound = -precision
	case 'g':
		if precision == 0 {
			precision = 1
		}
		iRound = precision
	default:
		iRound = precision + 1
	}
	mx := 16
	if fl.alt2 {
		mx = 26
	}
	s := fpDecode(realvalue, iRound, mx)
	var prefix byte
	if fl.plus {
		prefix = '+'
	} else if fl.blank {
		prefix = ' '
	}
	var out string
	if s.special != 0 {
		if s.special == 2 {
			if fl.zeropad {
				out = "null"
			} else {
				out = "NaN"
			}
			return padStr(out, width, fl.leftJustify)
		}
		if fl.zeropad {
			s.z = []byte{'9'}
			s.iDP = 1000
			s.n = 1
		} else {
			if s.neg {
				out = "-Inf"
			} else if prefix != 0 {
				out = string(prefix) + "Inf"
			} else {
				out = "Inf"
			}
			return padStr(out, width, fl.leftJustify)
		}
	}
	if s.neg {
		prefix = '-'
	}
	exp := s.iDP - 1
	if xtype == 'g' && precision > 0 {
		precision--
	}
	var rtz bool
	if xtype == 'g' {
		rtz = !fl.alt
		if exp < -4 || exp > precision {
			xtype = 'e'
		} else {
			precision = precision - exp
			xtype = 'f'
		}
	} else {
		rtz = fl.alt2
	}
	var e2 int
	if xtype == 'e' {
		e2 = 0
	} else {
		e2 = s.iDP - 1
	}
	buf := make([]byte, 0, 32)
	flagDP := precision > 0 || fl.alt || fl.alt2
	if prefix != 0 {
		buf = append(buf, prefix)
	}
	j := 0
	if e2 < 0 {
		buf = append(buf, '0')
	} else {
		for ; e2 >= 0; e2-- {
			if j < s.n {
				buf = append(buf, s.z[j])
				j++
			} else {
				buf = append(buf, '0')
			}
			if fl.thousand && (e2%3) == 0 && e2 > 1 {
				buf = append(buf, ',')
			}
		}
	}
	if flagDP {
		buf = append(buf, '.')
	}
	for e2++; e2 < 0 && precision > 0; precision, e2 = precision-1, e2+1 {
		buf = append(buf, '0')
	}
	for ; precision > 0; precision-- {
		if j < s.n {
			buf = append(buf, s.z[j])
			j++
		} else {
			buf = append(buf, '0')
		}
	}
	if rtz && flagDP {
		for len(buf) > 0 && buf[len(buf)-1] == '0' {
			buf = buf[:len(buf)-1]
		}
		if len(buf) > 0 && buf[len(buf)-1] == '.' {
			if fl.alt2 {
				buf = append(buf, '0')
			} else {
				buf = buf[:len(buf)-1]
			}
		}
	}
	if xtype == 'e' {
		exp = s.iDP - 1
		if upper {
			buf = append(buf, 'E')
		} else {
			buf = append(buf, 'e')
		}
		if s.n == 0 || (s.n == 1 && s.z[0] == '0') {
			// zero value
		}
		if exp < 0 {
			buf = append(buf, '-')
			exp = -exp
		} else {
			buf = append(buf, '+')
		}
		if exp >= 100 {
			buf = append(buf, byte(exp/100)+'0')
			exp %= 100
		}
		buf = append(buf, byte(exp/10)+'0', byte(exp%10)+'0')
	}
	if fl.zeropad && !fl.leftJustify && len(buf) < width {
		nPad := width - len(buf)
		pos := 0
		if prefix != 0 {
			pos = 1
		}
		nb := make([]byte, 0, width)
		nb = append(nb, buf[:pos]...)
		for i := 0; i < nPad; i++ {
			nb = append(nb, '0')
		}
		nb = append(nb, buf[pos:]...)
		buf = nb
	}
	return padStr(string(buf), width, fl.leftJustify)
}

func padStr(s string, width int, left bool) string {
	n := utf8Len(s)
	if n >= width {
		return s
	}
	pad := make([]byte, width-n)
	for i := range pad {
		pad[i] = ' '
	}
	if left {
		return s + string(pad)
	}
	return string(pad) + s
}

func utf8Len(s string) int {
	n := 0
	for i := 0; i < len(s); i++ {
		if s[i]&0xc0 != 0x80 {
			n++
		}
	}
	return n
}

func fmtG17(f float64) string {
	return formatFloatSQL(f, 'g', 17, 0, fmtFlags{alt2: true})
}
