		if i == pos+1 {
			return mk(TIllegal, i)
		}
		return mk(TVariable, i)
	case (c == 'x' || c == 'X') && pos+1 < n && src[pos+1] == '\'':
		i := pos + 2
		for i < n && isHex(src[i]) {
			i++
		}
		if i < n && src[i] == '\'' && (i-pos-2)%2 == 0 {
			t := Token{T: TBlob, S: src[start : i+1], V: src[pos+2 : i], Pos: start}
			return t, i + 1
		}
		// illegal: consume to closing quote
		for i < n && src[i] != '\'' {
			i++
		}
		if i < n {
			i++
		}
		return mk(TIllegal, i)
	case isIdStart(c):
		i := pos + 1
		for i < n && isIdChar(src[i]) {
			i++
		}
		word := src[start:i]
		up := strings.ToUpper(word)
		if keywords[up] {
			return Token{T: TKeyword, S: word, V: up, Pos: start}, i
		}
		return Token{T: TIdent, S: word, V: word, Pos: start}, i
	}
	return mk(TIllegal, pos+1)
}

func scanNumber(src string, pos int) (Token, int) {
	n := len(src)
	i := pos
	start := pos
	t := TInteger
	illegal := false
	if src[i] == '0' && i+1 < n && (src[i+1] == 'x' || src[i+1] == 'X') && i+2 < n && isHex(src[i+2]) {
		i += 2
		for i < n && (isHex(src[i]) || src[i] == '_') {
			if src[i] == '_' && !(i+1 < n && isHex(src[i+1])) {
				illegal = true
			}
			i++
		}
	} else if src[i] == '0' && i+1 < n && (src[i+1] == 'x' || src[i+1] == 'X') {
		i += 2
		for i < n && isIdChar(src[i]) {
			i++
		}
		return Token{T: TIllegal, S: src[start:i], V: src[start:i], Pos: start}, i
	} else {
		digits := func() {
			for i < n && (isDigit(src[i]) || src[i] == '_') {
				if src[i] == '_' && !(i+1 < n && isDigit(src[i+1])) {
					illegal = true
				}
				i++
			}
		}
		digits()
		if i < n && src[i] == '.' {
			t = TFloat
			i++
			digits()
		}
		if i < n && (src[i] == 'e' || src[i] == 'E') && ((i+1 < n && isDigit(src[i+1])) || (i+2 < n && (src[i+1] == '+' || src[i+1] == '-') && isDigit(src[i+2]))) {
			t = TFloat
			i += 2
			digits()
		}
	}
	for i < n && isIdChar(src[i]) {
		i++
		illegal = true
	}
	if illegal {
		return Token{T: TIllegal, S: src[start:i], V: src[start:i], Pos: start}, i
	}
	raw := src[start:i]
	v := raw
	if strings.IndexByte(raw, '_') >= 0 {
		v = strings.ReplaceAll(raw, "_", "")
	}
	return Token{T: t, S: raw, V: v, Pos: start}, i
}

// sqliteComplete: returns true if sql ends with a complete statement (semicolon outside
// of string/comment/trigger body).
func sqliteComplete(sql string) bool {
	// state machine similar to sqlite3_complete
	const (
		sInvalid = iota
		sStart
		sNormal
		sExplain
		sCreate
		sTrigger
		sSemi
		sEnd
	)
	// token classes
	const (
		tkSEMI = iota
		tkWS
		tkOTHER
		tkEXPLAIN
		tkCREATE
		tkTEMP
		tkTRIGGER
		tkEND
	)
	trans := [8][8]int{
		/* State:       **  SEMI  WS  OTHER  EXPLAIN  CREATE  TEMP  TRIGGER  END */
		/* 0 INVALID: */ {1, 0, 2, 3, 4, 2, 2, 2},
		/* 1   START: */ {1, 1, 2, 3, 4, 2, 2, 2},
		/* 2  NORMAL: */ {1, 2, 2, 2, 2, 2, 2, 2},
		/* 3 EXPLAIN: */ {1, 3, 3, 2, 4, 2, 2, 2},
		/* 4  CREATE: */ {1, 4, 2, 2, 2, 4, 5, 2},
		/* 5 TRIGGER: */ {6, 5, 5, 5, 5, 5, 5, 5},
		/* 6    SEMI: */ {6, 6, 5, 5, 5, 5, 5, 7},
		/* 7     END: */ {1, 7, 5, 5, 5, 5, 5, 5},
	}
	state := 0
	i := 0
	n := len(sql)
	for i < n {
		c := sql[i]
		var tok int
		switch {
		case c == ';':
			tok = tkSEMI
			i++
		case isSpaceByte(c):
			tok = tkWS
			i++
		case c == '/':
			if i+1 < n && sql[i+1] == '*' {
				j := i + 2
				for j+1 < n && !(sql[j] == '*' && sql[j+1] == '/') {
					j++
				}
				if j+1 >= n {
					return false
				}
				i = j + 2
				tok = tkWS
			} else {
				tok = tkOTHER
				i++
			}
		case c == '-':
			if i+1 < n && sql[i+1] == '-' {
				j := i + 2
				for j < n && sql[j] != '\n' {
					j++
				}
				if j >= n {
					return state == 1
				}
				i = j
				tok = tkWS
			} else {
				tok = tkOTHER
				i++
			}
		case c == '[':
			j := i + 1
			for j < n && sql[j] != ']' {
				j++
			}
			if j >= n {
				return false
			}
			i = j + 1
			tok = tkOTHER
		case c == '`' || c == '"' || c == '\'':
			j := i + 1
			for j < n && sql[j] != c {
				j++
			}
			if j >= n {
				return false
			}
			i = j + 1
			tok = tkOTHER
		default:
			if isIdChar(c) {
				j := i
				for j < n && isIdChar(sql[j]) {
					j++
				}
				w := strings.ToUpper(sql[i:j])
				switch w {
				case "CREATE":
					tok = tkCREATE
				case "TRIGGER":
					tok = tkTRIGGER
				case "TEMP", "TEMPORARY":
					tok = tkTEMP
				case "END":
					tok = tkEND
				case "EXPLAIN":
					tok = tkEXPLAIN
				default:
					tok = tkOTHER
				}
				i = j
			} else {
				tok = tkOTHER
				i++
			}
		}
		state = trans[state][tok]
	}
	return state == 1
}
