func isIdChar(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '$' || c >= 0x80
}
func isIdStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c >= 0x80
}
func isDigit(c byte) bool { return c >= '0' && c <= '9' }
func isHex(c byte) bool {
	return isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

// nextToken scans one token starting at pos. Returns token and new position.
func nextToken(src string, pos int) (Token, int) {
	n := len(src)
	if pos >= n {
		return Token{T: TEOF, Pos: pos}, pos
	}
	c := src[pos]
	start := pos
	mk := func(t TokType, end int) (Token, int) {
		return Token{T: t, S: src[start:end], V: src[start:end], Pos: start}, end
	}
	switch {
	case isSpaceByte(c):
		i := pos
		for i < n && isSpaceByte(src[i]) {
			i++
		}
		return mk(TSpace, i)
	case c == '-':
		if pos+1 < n && src[pos+1] == '-' {
			i := pos + 2
			for i < n && src[i] != '\n' {
				i++
			}
			return mk(TSpace, i)
		}
		if pos+1 < n && src[pos+1] == '>' {
			if pos+2 < n && src[pos+2] == '>' {
				return mk(TOp, pos+3)
			}
			return mk(TOp, pos+2)
		}
		return mk(TOp, pos+1)
	case c == '/':
		if pos+1 < n && src[pos+1] == '*' {
			i := pos + 2
			for i < n && !(src[i] == '*' && i+1 < n && src[i+1] == '/') {
				i++
			}
			if i < n {
				i += 2
			}
			return mk(TSpace, i)
		}
		return mk(TOp, pos+1)
	case c == ';':
		return mk(TSemi, pos+1)
	case c == '(' || c == ')' || c == '+' || c == '*' || c == '%' || c == ',' || c == '&' || c == '~':
		return mk(TOp, pos+1)
	case c == '=':
		if pos+1 < n && src[pos+1] == '=' {
			return mk(TOp, pos+2)
		}
		return mk(TOp, pos+1)
	case c == '<':
		if pos+1 < n && (src[pos+1] == '=' || src[pos+1] == '>' || src[pos+1] == '<') {
			return mk(TOp, pos+2)
		}
		return mk(TOp, pos+1)
	case c == '>':
		if pos+1 < n && (src[pos+1] == '=' || src[pos+1] == '>') {
			return mk(TOp, pos+2)
		}
		return mk(TOp, pos+1)
	case c == '!':
		if pos+1 < n && src[pos+1] == '=' {
			return mk(TOp, pos+2)
		}
		return mk(TIllegal, pos+1)
	case c == '|':
		if pos+1 < n && src[pos+1] == '|' {
			return mk(TOp, pos+2)
		}
		return mk(TOp, pos+1)
	case c == '\'' || c == '"' || c == '`':
