				if i+1 < n && src[i+1] == q {
					sb.WriteByte(q)
					i += 2
					continue
				}
				i++
				break
			}
			sb.WriteByte(src[i])
			i++
		}
		t := Token{S: src[start:i], V: sb.String(), Pos: start}
		if q == '\'' {
			t.T = TString
		} else {
			t.T = TIdent
			t.Quot = true
			t.DQ = q == '"'
		}
		return t, i
	case c == '.':
		if pos+1 < n && isDigit(src[pos+1]) {
			return scanNumber(src, pos)
		}
