		i := pos + 1
		for i < n && src[i] != ']' {
			i++
		}
		if i >= n {
			return mk(TIllegal, n)
		}
		t := Token{T: TIdent, S: src[start : i+1], V: src[start+1 : i], Pos: start, Quot: true}
		return t, i + 1
	case c == '?':
		i := pos + 1
		for i < n && isDigit(src[i]) {
			i++
		}
		return mk(TVariable, i)
	case c == '$' || c == '@' || c == ':' || c == '#':
		i := pos + 1
		for i < n {
			if isIdChar(src[i]) {
				i++
			} else if c == '$' && src[i] == ':' && i+1 < n && src[i+1] == ':' {
				i += 2
			} else if c == '$' && src[i] == '(' {
