			t := Token{T: TBlob, S: src[start : i+1], V: src[pos+2 : i], Pos: start}
			return t, i + 1
		}
		// illegal: consume to closing quote
		for i < n && src[i] != '\'' {
			i++
		}
		if i < n {
			i++
		}
		return mk(TIllegal, i)
	case isIdStart(c):
		i := pos + 1
		for i < n && isIdChar(src[i]) {
			i++
		}
		word := src[start:i]
		up := strings.ToUpper(word)
