{"command":"cd /workspace/src && cat > parser.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type ParseError struct {
	Msg string
	Pos int // -1 if none
}

func (e *ParseError) Error() string { return e.Msg }

type Parser struct {
	src  string
	toks []Token
	p    int
	// for error reporting
	nParam int
}

var joinKW = map[string]bool{"LEFT": true, "RIGHT": true, "FULL": true, "INNER": true, "CROSS": true, "NATURAL": true, "OUTER": true}

func tokenize(src string) ([]Token, *ParseError) {
	var toks []Token
	pos := 0
	for {
		t, np := nextToken(src, pos)
		if t.T == TEOF {
			toks = append(toks, t)
			break
		}
		pos = np
		if t.T == TSpace {
			continue
		}
		toks = append(toks, t)
	}
	return toks, nil
}

func (p *Parser) peek() Token { return p.toks[p.p] }
func (p *Parser) peekN(n int) Token {
	if p.p+n < len(p.toks) {
		return p.toks[p.p+n]
	}
	return p.toks[len(p.toks)-1]
}
func (p *Parser) next() Token {
	t := p.toks[p.p]
	if t.T != TEOF {
		p.p++
	}
	return t
}

func (p *Parser) errAt(t Token) *ParseError {
	if t.T == TEOF {
		return &ParseError{Msg: "incomplete input", Pos: -1}
	}
	if t.T == TIllegal {
		return &ParseError{Msg: fmt.Sprintf("unrecognized token: \"%s\"", t.S), Pos: t.Pos}
	}
	return &ParseError{Msg: fmt.Sprintf("near \"%s\": syntax error", t.S), Pos: t.Pos}
}

func (p *Parser) fail() { panic(p.errAt(p.peek())) }

func (p *Parser) isKW(kw string) bool {
	t := p.peek()
	return t.T == TKeyword && t.V == kw
}
func (p *Parser) isKWn(n int, kw string) bool {
	t := p.peekN(n)
	return t.T == TKeyword && t.V == kw
}
func (p *Parser) acceptKW(kw string) bool {
	if p.isKW(kw) {
		p.p++
		return true
	}
	return false
}
func (p *Parser) expectKW(kw string) Token {
	if !p.isKW(kw) {
		p.fail()
	}
	return p.next()
}
func (p *Parser) isOp(op string) bool {
	t := p.peek()
	return t.T == TOp && t.S == op
}
func (p *Parser) acceptOp(op string) bool {
	if p.isOp(op) {
		p.p++
		return true
	}
	return false
}
func (p *Parser) expectOp(op string) Token {
	if !p.isOp(op) {
		p.fail()
	}
	return p.next()
}

// identifier usable as a name (nm): ID, STRING, JOIN_KW, fallback keywords
func (p *Parser) isNameTok(t Token) bool {
	switch t.T {
	case TIdent:
		return true
	case TString:
		return true
	case TKeyword:
		return !reservedWords[t.V]
	}
	return false
}

// ID only (no STRING); fallback keywords allowed but not join kw
func (p *Parser) isIdTok(t Token) bool {
	switch t.T {
	case TIdent:
		return true
	case TKeyword:
		return !reservedWords[t.V] && !joinKW[t.V]
	}
	return false
}

func (p *Parser) parseName() string {
	t := p.peek()
	if !p.isNameTok(t) {
		p.fail()
	}
	p.next()
	return t.V
}

func (p *Parser) parseNameTok() Token {
	t := p.peek()
	if !p.isNameTok(t) {
		p.fail()
	}
	p.next()
	if t.T == TKeyword {
		t.V = t.S
	}
	return t
}

func nameOf(t Token) string {
	if t.T == TKeyword {
		return t.S
	}
	return t.V
}

// ParseAll parses one statement starting at current position. Returns nil at EOF.
func ParseStatement(src string, start int) (stmt Stmt, end int, perr *ParseError) {
	toks, e := tokenize(src[start:])
	if e != nil {
		return nil, len(src), e
	}
	for i := range toks {
		toks[i].Pos += start
	}
	p := &Parser{src: src, toks: toks}
	defer func() {
		if r := recover(); r != nil {
			if pe, ok := r.(*ParseError); ok {
				stmt = nil
				perr = pe
				end = len(src)
				return
			}
			panic(r)
		}
	}()
	// skip empty statements
	for p.peek().T == TSemi {
		p.next()
	}
	if p.peek().T == TEOF {
		return nil, len(src), nil
	}
	for _, t := range toks {
		if t.T == TIllegal {
			_ = t
			break
		}
	}
	stmt = p.parseStmt()
	t := p.peek()
	if t.T == TSemi {
		end = t.Pos + 1
	} else if t.T == TEOF {
		end = len(src)
	} else {
		p.fail()
	}
	return stmt, end, nil
}

func (p *Parser) stmtEndPos() int {
	// position just after the last consumed token
	if p.p == 0 {
		return 0
	}
	t := p.toks[p.p-1]
	return t.Pos + len(t.S)
}

func (p *Parser) parseStmt() Stmt {
	t := p.peek()
	if t.T == TIllegal {
		p.fail()
	}
	if t.T != TKeyword {
		if t.T == TOp && t.S == "(" {
			// not allowed at statement start
		}
		p.fail()
	}
	switch t.V {
	case "EXPLAIN":
		p.next()
		qp := false
		if p.acceptKW("QUERY") {
			p.expectKW("PLAN")
			qp = true
		}
		startPos := p.peek().Pos
		s := p.parseStmt()
		return &ExplainStmt{QueryPlan: qp, Stmt: s, SQL: p.src[startPos:p.stmtEndPos()]}
	case "SELECT", "VALUES":
		return &SelectStmt{Sel: p.parseSelect()}
	case "WITH":
		w := p.parseWith()
		t2 := p.peek()
		if t2.T == TKeyword {
			switch t2.V {
			case "SELECT", "VALUES":
				s := p.parseSelect()
				s.With = mergeWith(w, s.With)
				return &SelectStmt{Sel: s}
			case "INSERT", "REPLACE":
				s := p.parseInsert()
				s.With = w
				return s
			case "UPDATE":
				s := p.parseUpdate()
				s.With = w
				return s
			case "DELETE":
				s := p.parseDelete()
				s.With = w
				return s
			}
		}
		p.fail()
	case "INSERT", "REPLACE":
		return p.parseInsert()
	case "UPDATE":
		return p.parseUpdate()
	case "DELETE":
		return p.parseDelete()
	case "CREATE":
		return p.parseCreate()
	case "DROP":
		return p.parseDrop()
	case "ALTER":
		return p.parseAlter()
	case "BEGIN":
		p.next()
		mode := ""
		if p.isKW("DEFERRED") || p.isKW("IMMEDIATE") || p.isKW("EXCLUSIVE") {
			mode = p.next().V
		}
		p.acceptKW("TRANSACTION")
		return &TxnStmt{Kind: "BEGIN", Mode: mode}
	case "COMMIT", "END":
		p.next()
		p.acceptKW("TRANSACTION")
		return &TxnStmt{Kind: "COMMIT"}
	case "ROLLBACK":
		p.next()
		p.acceptKW("TRANSACTION")
		if p.acceptKW("TO") {
			p.acceptKW("SAVEPOINT")
			n := p.parseName()
			return &TxnStmt{Kind: "ROLLBACK", Name: n}
		}
		return &TxnStmt{Kind: "ROLLBACK"}
	case "SAVEPOINT":
		p.next()
		return &TxnStmt{Kind: "SAVEPOINT", Name: p.parseName()}
	case "RELEASE":
		p.next()
		p.acceptKW("SAVEPOINT")
		return &TxnStmt{Kind: "RELEASE", Name: p.parseName()}
	case "PRAGMA":
		return p.parsePragma()
	case "ATTACH":
		p.next()
		p.acceptKW("DATABASE")
		f := p.parseExpr()
		p.expectKW("AS")
		n := p.parseExpr()
		return &AttachStmt{File: f, Name: n}
	case "DETACH":
		p.next()
		p.acceptKW("DATABASE")
		e := p.parseExpr()
		name := ""
		if e.Op == EColumn {
			name = e.Column
		} else if e.Op == ELit {
			name = e.Val.Text()
		}
		return &DetachStmt{Name: name}
	case "VACUUM":
		p.next()
		v := &VacuumStmt{}
		if p.isNameTok(p.peek()) && !p.isKW("INTO") {
			v.Schema = p.parseName()
		}
		if p.acceptKW("INTO") {
			v.Into = p.parseExpr()
		}
		return v
	case "ANALYZE":
		p.next()
		a := &AnalyzeStmt{}
		if p.isNameTok(p.peek()) {
			a.Name = p.parseName()
			if p.acceptOp(".") {
				a.Name = p.parseName()
			}
		}
		return a
	case "REINDEX":
		p.next()
		a := &ReindexStmt{}
		if p.isNameTok(p.peek()) {
			a.Name = p.parseName()
			if p.acceptOp(".") {
				a.Name = p.parseName()
			}
		}
		return a
	}
	p.fail()
	return nil
}

func mergeWith(a, b *With) *With {
	if b == nil {
		return a
	}
	return a
}

func (p *Parser) parsePragma() Stmt {
	p.next()
	ps := &PragmaStmt{}
	n := p.parseName()
	if p.acceptOp(".") {
		ps.Schema = n
		n = p.parseName()
	}
	ps.Name = n
	if p.acceptOp("=") {
		ps.HasVal = true
		ps.Value = p.parsePragmaValue()
	} else if p.acceptOp("(") {
		ps.HasVal = true
		ps.Call = true
		ps.Value = p.parsePragmaValue()
		p.expectOp(")")
	}
	return ps
}

func (p *Parser) parsePragmaValue() *Expr {
	t := p.peek()
	neg := false
	if t.T == TOp && (t.S == "-" || t.S == "+") {
		neg = t.S == "-"
		p.next()
		t = p.peek()
	}
	switch t.T {
	case TInteger, TFloat:
		e := p.parsePrimary()
		if neg {
			return &Expr{Op: EUnary, Name: "-", L: e}
		}
		return e
	case TString:
		p.next()
		return &Expr{Op: ELit, Val: TextValue(t.V)}
	case TIdent, TKeyword:
		p.next()
		return &Expr{Op: ELit, Val: TextValue(nameOf(t))}
	}
	p.fail()
	return nil
}

func (p *Parser) parseWith() *With {
	p.expectKW("WITH")
	w := &With{}
	if p.acceptKW("RECURSIVE") {
		w.Recursive = true
	}
	for {
		c := &CTE{}
		c.Name = nameOf(p.parseNameTok())
		if p.acceptOp("(") {
			for {
				c.Cols = append(c.Cols, nameOf(p.parseNameTok()))
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp(")")
		}
		p.expectKW("AS")
		if p.acceptKW("NOT") {
			p.expectKW("MATERIALIZED")
			c.Materialized = 2
		} else if p.acceptKW("MATERIALIZED") {
			c.Materialized = 1
		}
		p.expectOp("(")
		c.Sel = p.parseSelect()
		p.expectOp(")")
		w.CTEs = append(w.CTEs, c)
		if !p.acceptOp(",") {
			break
		}
	}
	return w
}

// ---------------- SELECT ----------------

func (p *Parser) parseSelect() *Select {
	var with *With
	if p.isKW("WITH") {
		with = p.parseWith()
	}
	s := p.parseSelectCore()
	for {
		op := ""
		if p.isKW("UNION") {
			p.next()
			if p.acceptKW("ALL") {
				op = "UNION ALL"
			} else {
				op = "UNION"
			}
		} else if p.isKW("INTERSECT") {
			p.next()
			op = "INTERSECT"
		} else if p.isKW("EXCEPT") {
			p.next()
			op = "EXCEPT"
		} else {
			break
		}
		r := p.parseSelectCore()
		r.CompoundOp = op
		r.Prior = s
		s = r
	}
	if p.isKW("ORDER") {
		p.next()
		p.expectKW("BY")
		s.OrderBy = p.parseOrderList()
	}
	if p.isKW("LIMIT") {
		p.next()
		s.Limit = p.parseExpr()
		if p.acceptKW("OFFSET") {
			s.Offset = p.parseExpr()
		} else if p.acceptOp(",") {
			s.Offset = s.Limit
			s.Limit = p.parseExpr()
		}
	}
	s.With = with
	return s
}

func (p *Parser) parseOrderList() []*OrderTerm {
	var list []*OrderTerm
	for {
		ot := &OrderTerm{E: p.parseExpr()}
		if p.acceptKW("ASC") {
		} else if p.acceptKW("DESC") {
			ot.Desc = true
		}
		if p.acceptKW("NULLS") {
			if p.acceptKW("FIRST") {
				ot.Nulls = 1
			} else {
				p.expectKW("LAST")
				ot.Nulls = 2
			}
		}
		list = append(list, ot)
		if !p.acceptOp(",") {
			break
		}
	}
	return list
}

func (p *Parser) parseSelectCore() *Select {
	s := &Select{Pos: p.peek().Pos}
	if p.acceptKW("VALUES") {
		for {
			p.expectOp("(")
			var row []*Expr
			for {
				row = append(row, p.parseExpr())
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp(")")
			s.Values = append(s.Values, row)
			if !p.acceptOp(",") {
				break
			}
		}
		return s
	}
	p.expectKW("SELECT")
	if p.acceptKW("DISTINCT") {
		s.Distinct = true
	} else {
		p.acceptKW("ALL")
	}
	s.Cols = p.parseResultCols()
	if p.acceptKW("FROM") {
		s.From = p.parseFrom()
	}
	if p.acceptKW("WHERE") {
		s.Where = p.parseExpr()
	}
	if p.isKW("GROUP") {
		p.next()
		p.expectKW("BY")
		for {
			s.GroupBy = append(s.GroupBy, p.parseExpr())
			if !p.acceptOp(",") {
				break
			}
		}
	}
	if p.acceptKW("HAVING") {
		s.Having = p.parseExpr()
	}
	if p.isKW("WINDOW") {
		p.next()
		for {
			name := nameOf(p.parseNameTok())
			p.expectKW("AS")
			w := p.parseWindowSpec()
			w.Name = name
			s.Windows = append(s.Windows, w)
			if !p.acceptOp(",") {
				break
			}
		}
	}
	return s
}

func (p *Parser) parseResultCols() []*ResultCol {
	var cols []*ResultCol
	for {
		t := p.peek()
		if t.T == TOp && t.S == "*" {
			p.next()
			cols = append(cols, &ResultCol{Star: true})
		} else if p.isNameTok(t) && p.peekN(1).T == TOp && p.peekN(1).S == "." && p.peekN(2).T == TOp && p.peekN(2).S == "*" {
			p.next()
			p.next()
			p.next()
			cols = append(cols, &ResultCol{Star: true, Table: nameOf(t)})
		} else {
			startTok := p.peek()
			e := p.parseExpr()
			rc := &ResultCol{E: e}
			rc.Span = p.src[startTok.Pos:p.stmtEndPos()]
			if p.acceptKW("AS") {
				at := p.peek()
				if !p.isNameTok(at) {
					p.fail()
				}
				p.next()
				rc.Alias = nameOf(at)
			} else {
				at := p.peek()
				if p.isIdTok(at) || at.T == TString {
					p.next()
					rc.Alias = nameOf(at)
				}
			}
			cols = append(cols, rc)
		}
		if !p.acceptOp(",") {
			break
		}
	}
	return cols
}

func (p *Parser) parseFrom() []*FromItem {
	var items []*FromItem
	first := p.parseFromItem()
	items = append(items, first)
	for {
		jt := JoinType(0)
		if p.acceptOp(",") {
			jt = JInner | JCross
			// comma join
			it := p.parseFromItem()
			it.Join = JInner
			items = append(items, it)
			continue
		}
		seen := false
		for {
			t := p.peek()
			if t.T == TKeyword && joinKW[t.V] {
				p.next()
				seen = true
				switch t.V {
				case "LEFT":
					jt |= JLeft
				case "RIGHT":
					jt |= JRight
				case "FULL":
					jt |= JLeft | JRight
				case "INNER":
					jt |= JInner
				case "CROSS":
					jt |= JCross
				case "NATURAL":
					jt |= JNatural
				case "OUTER":
					jt |= JOuter
				}
				continue
			}
			break
		}
		if p.isKW("JOIN") {
			p.next()
		} else {
			if seen {
				p.fail()
			}
			break
		}
		if jt&(JLeft|JRight) == 0 {
			jt |= JInner
		}
		it := p.parseFromItem()
		it.Join = jt
		if p.acceptKW("ON") {
			it.On = p.parseExpr()
		} else if p.acceptKW("USING") {
			p.expectOp("(")
			for {
				it.Using = append(it.Using, nameOf(p.parseNameTok()))
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp(")")
		}
		items = append(items, it)
	}
	// ON/USING for comma joins
	return items
}

func (p *Parser) parseFromItem() *FromItem {
	it := &FromItem{Pos: p.peek().Pos}
	if p.isOp("(") {
		p.next()
		if p.isKW("SELECT") || p.isKW("VALUES") || p.isKW("WITH") {
			it.Sel = p.parseSelect()
			p.expectOp(")")
		} else {
			// parenthesized join
			items := p.parseFrom()
			p.expectOp(")")
			if len(items) == 1 {
				it = items[0]
			} else {
				it.Paren = items
			}
		}
	} else {
		t := p.peek()
		if !p.isNameTok(t) {
			p.fail()
		}
		p.next()
		it.Name = nameOf(t)
		if p.acceptOp(".") {
			it.Schema = it.Name
			t2 := p.peek()
			if !p.isNameTok(t2) {
				p.fail()
			}
			p.next()
			it.Name = nameOf(t2)
		}
		if p.isOp("(") {
			p.next()
			it.IsFunc = true
			if !p.isOp(")") {
				for {
					it.FuncArgs = append(it.FuncArgs, p.parseExpr())
					if !p.acceptOp(",") {
						break
					}
				}
			}
			p.expectOp(")")
		}
	}
	// alias
	if p.acceptKW("AS") {
		it.Alias = nameOf(p.parseNameTok())
	} else {
		t := p.peek()
		if p.isIdTok(t) || t.T == TString {
			p.next()
			it.Alias = nameOf(t)
		}
	}
	if p.isKW("INDEXED") {
		p.next()
		p.expectKW("BY")
		it.Indexed = p.parseName()
	} else if p.isKW("NOT") && p.isKWn(1, "INDEXED") {
		p.next()
		p.next()
		it.NotIndexed = true
	}
	return it
}

func (p *Parser) parseWindowSpec() *WindowDef {
	p.expectOp("(")
	w := &WindowDef{}
	t := p.peek()
	if p.isIdTok(t) && !(t.T == TKeyword && (t.V == "PARTITION" || t.V == "ORDER" || t.V == "ROWS" || t.V == "RANGE" || t.V == "GROUPS")) {
		p.next()
		w.Base = nameOf(t)
	}
	if p.acceptKW("PARTITION") {
		p.expectKW("BY")
		for {
			w.Partition = append(w.Partition, p.parseExpr())
			if !p.acceptOp(",") {
				break
			}
		}
	}
	if p.isKW("ORDER") {
		p.next()
		p.expectKW("BY")
		w.OrderBy = p.parseOrderList()
	}
	if p.isKW("ROWS") || p.isKW("RANGE") || p.isKW("GROUPS") {
		f := &FrameSpec{Type: p.next().V}
		if p.acceptKW("BETWEEN") {
			f.Start = p.parseFrameBound()
			p.expectKW("AND")
			f.End = p.parseFrameBound()
		} else {
			f.Start = p.parseFrameBound()
			f.End = FrameBound{Kind: "CURRENT ROW"}
		}
		if p.acceptKW("EXCLUDE") {
			if p.acceptKW("NO") {
				p.expectKW("OTHERS")
				f.Exclude = ""
			} else if p.acceptKW("CURRENT") {
				p.expectKW("ROW")
				f.Exclude = "CURRENT ROW"
			} else if p.acceptKW("GROUP") {
				f.Exclude = "GROUP"
			} else {
				p.expectKW("TIES")
				f.Exclude = "TIES"
			}
		}
		w.Frame = f
	}
	p.expectOp(")")
	return w
}

func (p *Parser) parseFrameBound() FrameBound {
	if p.acceptKW("UNBOUNDED") {
		if p.acceptKW("PRECEDING") {
			return FrameBound{Kind: "UNBOUNDED PRECEDING"}
		}
		p.expectKW("FOLLOWING")
		return FrameBound{Kind: "UNBOUNDED FOLLOWING"}
	}
	if p.isKW("CURRENT") {
		p.next()
		p.expectKW("ROW")
		return FrameBound{Kind: "CURRENT ROW"}
	}
	e := p.parseExpr()
	if p.acceptKW("PRECEDING") {
		return FrameBound{Kind: "PRECEDING", Expr: e}
	}
	p.expectKW("FOLLOWING")
	return FrameBound{Kind: "FOLLOWING", Expr: e}
}

// ---------------- Expressions ----------------

func (p *Parser) parseExpr() *Expr {
	return p.parseOr()
}

func (p *Parser) parseOr() *Expr {
	l := p.parseAnd()
	for p.isKW("OR") {
		t := p.next()
		r := p.parseAnd()
		l = &Expr{Op: EBinary, Name: "OR", L: l, R: r, Pos: t.Pos}
	}
	return l
}

func (p *Parser) parseAnd() *Expr {
	l := p.parseNot()
	for p.isKW("AND") {
		t := p.next()
		r := p.parseNot()
		l = &Expr{Op: EBinary, Name: "AND", L: l, R: r, Pos: t.Pos}
	}
	return l
}

func (p *Parser) parseNot() *Expr {
	if p.isKW("NOT") {
		t := p.next()
		e := p.parseNot()
		return &Expr{Op: EUnary, Name: "NOT", L: e, Pos: t.Pos}
	}
	return p.parseEquality()
}

func (p *Parser) parseEquality() *Expr {
	l := p.parseComparison()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "=" || t.S == "==" || t.S == "!=" || t.S == "<>") {
			p.next()
			r := p.parseComparison()
			op := t.S
			if op == "==" {
				op = "="
			} else if op == "<>" {
				op = "!="
			}
			l = &Expr{Op: EBinary, Name: op, L: l, R: r, Pos: t.Pos}
			continue
		}
		if t.T != TKeyword {
			return l
		}
		switch t.V {
		case "IS":
			p.next()
			not := p.acceptKW("NOT")
			if p.acceptKW("DISTINCT") {
				p.expectKW("FROM")
				not = !not
			}
			r := p.parseComparison()
			op := "IS"
			if not {
				op = "IS NOT"
			}
			l = &Expr{Op: EBinary, Name: op, L: l, R: r, Pos: t.Pos}
		case "ISNULL":
			p.next()
			l = &Expr{Op: EIsNull, L: l, Pos: t.Pos}
		case "NOTNULL":
			p.next()
			l = &Expr{Op: EIsNull, L: l, Not: true, Pos: t.Pos}
		case "NOT":
			t1 := p.peekN(1)
			if t1.T == TKeyword && t1.V == "NULL" {
				p.next()
				p.next()
				l = &Expr{Op: EIsNull, L: l, Not: true, Pos: t.Pos}
			} else if t1.T == TKeyword && (t1.V == "IN" || t1.V == "LIKE" || t1.V == "GLOB" || t1.V == "REGEXP" || t1.V == "MATCH" || t1.V == "BETWEEN") {
				p.next()
				l = p.parseEqualityOp(l, true)
			} else {
				return l
			}
		case "IN", "LIKE", "GLOB", "REGEXP", "MATCH", "BETWEEN":
			l = p.parseEqualityOp(l, false)
		default:
			return l
		}
	}
}

func (p *Parser) parseEqualityOp(l *Expr, not bool) *Expr {
	t := p.next()
	switch t.V {
	case "IN":
		e := &Expr{Op: EIn, L: l, Not: not, Pos: t.Pos}
		if p.acceptOp("(") {
			if p.isKW("SELECT") || p.isKW("VALUES") || p.isKW("WITH") {
				e.Sel = p.parseSelect()
			} else if !p.isOp(")") {
				for {
					e.List = append(e.List, p.parseExpr())
					if !p.acceptOp(",") {
						break
					}
				}
			} else {
				e.List = []*Expr{}
			}
			p.expectOp(")")
		} else {
			nt := p.peek()
			if !p.isNameTok(nt) {
				p.fail()
			}
			p.next()
			name := nameOf(nt)
			if p.acceptOp(".") {
				name = nameOf(p.parseNameTok())
			}
			e.Name = name
			if p.acceptOp("(") {
				e.TblArgs = []*Expr{}
				if !p.isOp(")") {
					for {
						e.TblArgs = append(e.TblArgs, p.parseExpr())
						if !p.acceptOp(",") {
							break
						}
					}
				}
				p.expectOp(")")
			}
		}
		return e
	case "BETWEEN":
		lo := p.parseComparison()
		p.expectKW("AND")
		hi := p.parseComparison()
		return &Expr{Op: EBetween, L: l, List: []*Expr{lo, hi}, Not: not, Pos: t.Pos}
	default:
		r := p.parseComparison()
		e := &Expr{Op: ELike, Name: t.V, L: l, R: r, Not: not, Pos: t.Pos}
		if p.acceptKW("ESCAPE") {
			e.Escape = p.parseComparison()
		}
		return e
	}
}

func (p *Parser) parseComparison() *Expr {
	l := p.parseBitwise()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "<" || t.S == "<=" || t.S == ">" || t.S == ">=") {
			p.next()
			r := p.parseBitwise()
			l = &Expr{Op: EBinary, Name: t.S, L: l, R: r, Pos: t.Pos}
			continue
		}
		return l
	}
}

func (p *Parser) parseBitwise() *Expr {
	l := p.parseAdd()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "&" || t.S == "|" || t.S == "<<" || t.S == ">>") {
			p.next()
			r := p.parseAdd()
			l = &Expr{Op: EBinary, Name: t.S, L: l, R: r, Pos: t.Pos}
			continue
		}
		return l
	}
}

func (p *Parser) parseAdd() *Expr {
	l := p.parseMul()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "+" || t.S == "-") {
			p.next()
			r := p.parseMul()
			l = &Expr{Op: EBinary, Name: t.S, L: l, R: r, Pos: t.Pos}
			continue
		}
		return l
	}
}

func (p *Parser) parseMul() *Expr {
	l := p.parseConcat()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "*" || t.S == "/" || t.S == "%") {
			p.next()
			r := p.parseConcat()
			l = &Expr{Op: EBinary, Name: t.S, L: l, R: r, Pos: t.Pos}
			continue
		}
		return l
	}
}

func (p *Parser) parseConcat() *Expr {
	l := p.parseCollate()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "||" || t.S == "->" || t.S == "->>") {
			p.next()
			r := p.parseCollate()
			l = &Expr{Op: EBinary, Name: t.S, L: l, R: r, Pos: t.Pos}
			continue
		}
		return l
	}
}

func (p *Parser) parseCollate() *Expr {
	l := p.parseUnary()
	for p.isKW("COLLATE") {
		t := p.next()
		nt := p.peek()
		if !p.isNameTok(nt) {
			p.fail()
		}
		p.next()
		l = &Expr{Op: ECollate, L: l, Name: nameOf(nt), Pos: t.Pos}
	}
	return l
}

func (p *Parser) parseUnary() *Expr {
	t := p.peek()
	if t.T == TOp && (t.S == "-" || t.S == "+" || t.S == "~") {
		p.next()
		e := p.parseUnary()
		// fold negative numeric literals
		if t.S == "-" && e.Op == ELit && !e.Paren && (e.Val.K == KInt || e.Val.K == KReal) && e.Name == "num" {
			if e.Val.K == KInt {
				return &Expr{Op: ELit, Val: IntValue(-e.Val.I), Pos: t.Pos, Name: "num"}
			}
			return &Expr{Op: ELit, Val: RealValue(-e.Val.F), Pos: t.Pos, Name: "num"}
		}
		if t.S == "-" && e.Op == ELit && e.Name == "bigint" {
			// -9223372036854775808
			if e.Val.K == KReal && e.Val.F == 9223372036854775808.0 {
				return &Expr{Op: ELit, Val: IntValue(-9223372036854775808), Pos: t.Pos, Name: "num"}
			}
		}
		return &Expr{Op: EUnary, Name: t.S, L: e, Pos: t.Pos}
	}
	return p.parsePrimary()
}

func (p *Parser) parsePrimary() *Expr {
	t := p.peek()
	switch t.T {
	case TInteger:
		p.next()
		s := t.V
		var v Value
		if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
			u, err := strconv.ParseUint(s[2:], 16, 64)
			if err != nil {
				panic(&ParseError{Msg: fmt.Sprintf("hex literal too big: %s", t.S), Pos: t.Pos})
			}
			v = IntValue(int64(u))
			return &Expr{Op: ELit, Val: v, Pos: t.Pos, End: t.Pos + len(t.S), Name: "num"}
		}
		i, err := strconv.ParseInt(s, 10, 64)
		if err != nil {
			f, _ := strconv.ParseFloat(s, 64)
			return &Expr{Op: ELit, Val: RealValue(f), Pos: t.Pos, End: t.Pos + len(t.S), Name: "bigint"}
		}
		return &Expr{Op: ELit, Val: IntValue(i), Pos: t.Pos, End: t.Pos + len(t.S), Name: "num"}
	case TFloat:
		p.next()
		f, _ := strconv.ParseFloat(t.V, 64)
		return &Expr{Op: ELit, Val: RealValue(f), Pos: t.Pos, End: t.Pos + len(t.S), Name: "num"}
	case TString:
		p.next()
		return &Expr{Op: ELit, Val: TextValue(t.V), Pos: t.Pos, End: t.Pos + len(t.S)}
	case TBlob:
		p.next()
		b := make([]byte, len(t.V)/2)
		for i := 0; i < len(b); i++ {
			x, _ := strconv.ParseUint(t.V[2*i:2*i+2], 16, 8)
			b[i] = byte(x)
		}
		return &Expr{Op: ELit, Val: BlobValue(string(b)), Pos: t.Pos, End: t.Pos + len(t.S)}
	case TVariable:
		p.next()
		return &Expr{Op: EParam, Name: t.S, Pos: t.Pos}
	case TOp:
		if t.S == "(" {
			p.next()
			if p.isKW("SELECT") || p.isKW("VALUES") || p.isKW("WITH") {
				s := p.parseSelect()
				p.expectOp(")")
				return &Expr{Op: ESubquery, Sel: s, Pos: t.Pos}
			}
			e := p.parseExpr()
			if p.isOp(",") {
				list := []*Expr{e}
				for p.acceptOp(",") {
					list = append(list, p.parseExpr())
				}
				p.expectOp(")")
				return &Expr{Op: EVector, List: list, Pos: t.Pos}
			}
			p.expectOp(")")
			e.Paren = true
			return e
		}
	case TKeyword:
		switch t.V {
		case "NULL":
			p.next()
			return &Expr{Op: ELit, Val: NullValue, Pos: t.Pos}
		case "CURRENT_TIME", "CURRENT_DATE", "CURRENT_TIMESTAMP":
			p.next()
			return &Expr{Op: EFunc, Name: strings.ToLower(t.V), Pos: t.Pos}
		case "CAST":
			if p.peekN(1).T == TOp && p.peekN(1).S == "(" {
				p.next()
				p.next()
				e := p.parseExpr()
				p.expectKW("AS")
				typ := p.parseTypeName()
				p.expectOp(")")
				return &Expr{Op: ECast, L: e, Name: typ, Pos: t.Pos}
			}
		case "CASE":
			p.next()
			e := &Expr{Op: ECase, Pos: t.Pos}
			if !p.isKW("WHEN") {
				e.L = p.parseExpr()
			}
			for p.acceptKW("WHEN") {
				w := p.parseExpr()
				p.expectKW("THEN")
				th := p.parseExpr()
				e.List = append(e.List, w, th)
			}
			if len(e.List) == 0 {
				p.fail()
			}
			if p.acceptKW("ELSE") {
				e.R = p.parseExpr()
			}
			p.expectKW("END")
			return e
		case "EXISTS":
			if p.peekN(1).T == TOp && p.peekN(1).S == "(" {
				p.next()
				p.next()
				s := p.parseSelect()
				p.expectOp(")")
				return &Expr{Op: EExists, Sel: s, Pos: t.Pos}
			}
		case "NOT":
			if p.isKWn(1, "EXISTS") {
				p.next()
				e := p.parsePrimary()
				return &Expr{Op: EUnary, Name: "NOT", L: e, Pos: t.Pos}
			}
		case "RAISE":
			if p.peekN(1).T == TOp && p.peekN(1).S == "(" {
				p.next()
				p.next()
				e := &Expr{Op: ERaise, Pos: t.Pos}
				if p.acceptKW("IGNORE") {
					e.Name = "IGNORE"
				} else {
					k := p.peek()
					if k.T == TKeyword && (k.V == "ROLLBACK" || k.V == "ABORT" || k.V == "FAIL") {
						p.next()
						e.Name = k.V
					} else {
						p.fail()
					}
					p.expectOp(",")
					e.L = p.parseExpr()
				}
				p.expectOp(")")
				return e
			}
		}
	}
	// identifier / function
	if t.T == TIdent || (t.T == TKeyword && !reservedWords[t.V]) || (t.T == TString && false) {
		p.next()
		name := nameOf(t)
		nt := p.peek()
		if nt.T == TOp && nt.S == "(" && !t.Quot {
			return p.parseFunctionCall(t)
		}
		if nt.T == TOp && nt.S == "(" && t.Quot {
			return p.parseFunctionCall(t)
		}
		if nt.T == TOp && nt.S == "." {
			p.next()
			t2 := p.peek()
			if !p.isNameTok(t2) {
				p.fail()
			}
			p.next()
			if p.isOp(".") {
				p.next()
				t3 := p.peek()
				if !p.isNameTok(t3) {
					p.fail()
				}
				p.next()
				return &Expr{Op: EColumn, Schema: name, Table: nameOf(t2), Column: nameOf(t3), Pos: t.Pos, ColQuot: t3.DQ}
			}
			return &Expr{Op: EColumn, Table: name, Column: nameOf(t2), Pos: t.Pos, ColQuot: t2.DQ}
		}
		return &Expr{Op: EColumn, Column: name, Pos: t.Pos, ColQuot: t.DQ}
	}
	p.fail()
	return nil
}

func (p *Parser) parseTypeName() string {
	var parts []string
	for {
		t := p.peek()
		if t.T == TIdent || (t.T == TKeyword && !reservedWords[t.V]) || t.T == TString {
			if t.T == TKeyword && (t.V == "CONSTRAINT") {
				break
			}
			p.next()
			if t.T == TIdent && t.Quot {
				parts = append(parts, t.V)
			} else {
				parts = append(parts, t.S)
			}
			continue
		}
		break
	}
	typ := strings.Join(parts, " ")
	if p.isOp("(") {
		start := p.peek().Pos
		p.next()
		p.parseSignedNum()
		if p.acceptOp(",") {
			p.parseSignedNum()
		}
		end := p.expectOp(")")
		_ = start
		_ = end
		// Keep original text of type including parens
		typ = typ + p.src[start:end.Pos+1]
	}
	return typ
}

func (p *Parser) parseSignedNum() {
	if p.isOp("+") || p.isOp("-") {
		p.next()
	}
	t := p.peek()
	if t.T == TInteger || t.T == TFloat {
		p.next()
		return
	}
	if p.isIdTok(t) {
		p.next()
		return
	}
	p.fail()
}

func (p *Parser) parseFunctionCall(t Token) *Expr {
	p.expectOp("(")
	e := &Expr{Op: EFunc, Name: strings.ToLower(nameOf(t)), Pos: t.Pos}
	if p.acceptOp("*") {
		e.Star = true
	} else if !p.isOp(")") {
		if p.acceptKW("DISTINCT") {
			e.Distinct = true
		} else {
			p.acceptKW("ALL")
		}
		for {
			e.List = append(e.List, p.parseExpr())
			if !p.acceptOp(",") {
				break
			}
		}
		if p.isKW("ORDER") {
			p.next()
			p.expectKW("BY")
			e.OrderBy = p.parseOrderList()
		}
	}
	p.expectOp(")")
	if p.isKW("FILTER") {
		p.next()
		p.expectOp("(")
		p.expectKW("WHERE")
		e.Filter = p.parseExpr()
		p.expectOp(")")
	}
	if p.isKW("OVER") {
		p.next()
		if p.isOp("(") {
			e.Over = p.parseWindowSpec()
		} else {
			e.Over = &WindowDef{Base: nameOf(p.parseNameTok())}
		}
	}
	return e
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > parser.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type ParseError struct {
	Msg string
	Pos int // -1 if none
}

func (e *ParseError) Error() string { return e.Msg }

type Parser struct {
	src  string
	toks []Token
	p    int
	// for error reporting
	nParam int
}

var joinKW = map[string]bool{"LEFT": true, "RIGHT": true, "FULL": true, "INNER": true, "CROSS": true, "NATURAL": true, "OUTER": true}

func tokenize(src string) ([]Token, *ParseError) {
	var toks []Token
	pos := 0
	for {
		t, np := nextToken(src, pos)
		if t.T == TEOF {
			toks = append(toks, t)
			break
		}
		pos = np
		if t.T == TSpace {
			continue
		}
		toks = append(toks, t)
	}
	return toks, nil
}

func (p *Parser) peek() Token { return p.toks[p.p] }
func (p *Parser) peekN(n int) Token {
	if p.p+n < len(p.toks) {
		return p.toks[p.p+n]
	}
	return p.toks[len(p.toks)-1]
}
func (p *Parser) next() Token {
	t := p.toks[p.p]
	if t.T != TEOF {
		p.p++
	}
	return t
}

func (p *Parser) errAt(t Token) *ParseError {
	if t.T == TEOF {
		return &ParseError{Msg: "incomplete input", Pos: -1}
	}
	if t.T == TIllegal {
		return &ParseError{Msg: fmt.Sprintf("unrecognized token: \"%s\"", t.S), Pos: t.Pos}
	}
	return &ParseError{Msg: fmt.Sprintf("near \"%s\": syntax error", t.S), Pos: t.Pos}
}

func (p *Parser) fail() { panic(p.errAt(p.peek())) }

func (p *Parser) isKW(kw string) bool {
	t := p.peek()
	return t.T == TKeyword && t.V == kw
}
func (p *Parser) isKWn(n int, kw string) bool {
	t := p.peekN(n)
	return t.T == TKeyword && t.V == kw
}
func (p *Parser) acceptKW(kw string) bool {
	if p.isKW(kw) {
		p.p++
		return true
	}
	return false
}
func (p *Parser) expectKW(kw string) Token {
	if !p.isKW(kw) {
		p.fail()
	}
	return p.next()
}
func (p *Parser) isOp(op string) bool {
	t := p.peek()
	return t.T == TOp && t.S == op
}
func (p *Parser) acceptOp(op string) bool {
	if p.isOp(op) {
		p.p++
		return true
	}
	return false
}
func (p *Parser) expectOp(op string) Token {
	if !p.isOp(op) {
		p.fail()
	}
	return p.next()
}

// identifier usable as a name (nm): ID, STRING, JOIN_KW, fallback keywords
func (p *Parser) isNameTok(t Token) bool {
	switch t.T {
	case TIdent:
		return true
	case TString:
		return true
	case TKeyword:
		return !reservedWords[t.V]
	}
	return false
}

// ID only (no STRING); fallback keywords allowed but not join kw
func (p *Parser) isIdTok(t Token) bool {
	switch t.T {
	case TIdent:
		return true
	case TKeyword:
		return !reservedWords[t.V] && !joinKW[t.V]
	}
	return false
}

func (p *Parser) parseName() string {
	t := p.peek()
	if !p.isNameTok(t) {
		p.fail()
	}
	p.next()
	return t.V
}

func (p *Parser) parseNameTok() Token {
	t := p.peek()
	if !p.isNameTok(t) {
		p.fail()
	}
	p.next()
	if t.T == TKeyword {
		t.V = t.S
	}
	return t
}

func nameOf(t Token) string {
	if t.T == TKeyword {
		return t.S
	}
	return t.V
}

// ParseAll parses one statement starting at current position. Returns nil at EOF.
func ParseStatement(src string, start int) (stmt Stmt, end int, perr *ParseError) {
	toks, e := tokenize(src[start:])
	if e != nil {
		return nil, len(src), e
	}
	for i := range toks {
		toks[i].Pos += start
	}
	p := &Parser{src: src, toks: toks}
	defer func() {
		if r := recover(); r != nil {
			if pe, ok := r.(*ParseError); ok {
				stmt = nil
				perr = pe
				end = len(src)
				return
			}
			panic(r)
		}
	}()
	// skip empty statements
	for p.peek().T == TSemi {
		p.next()
	}
	if p.peek().T == TEOF {
		return nil, len(src), nil
	}
	for _, t := range toks {
		if t.T == TIllegal {
			_ = t
			break
		}
	}
	stmt = p.parseStmt()
	t := p.peek()
	if t.T == TSemi {
		end = t.Pos + 1
	} else if t.T == TEOF {
		end = len(src)
	} else {
		p.fail()
	}
	return stmt, end, nil
}

func (p *Parser) stmtEndPos() int {
	// position just after the last consumed token
	if p.p == 0 {
		return 0
	}
	t := p.toks[p.p-1]
	return t.Pos + len(t.S)
}

func (p *Parser) parseStmt() Stmt {
	t := p.peek()
	if t.T == TIllegal {
		p.fail()
	}
	if t.T != TKeyword {
		if t.T == TOp && t.S == "(" {
			// not allowed at statement start
		}
		p.fail()
	}
	switch t.V {
	case "EXPLAIN":
		p.next()
		qp := false
		if p.acceptKW("QUERY") {
			p.expectKW("PLAN")
			qp = true
		}
		startPos := p.peek().Pos
		s := p.parseStmt()
		return &ExplainStmt{QueryPlan: qp, Stmt: s, SQL: p.src[startPos:p.stmtEndPos()]}
	case "SELECT", "VALUES":
		return &SelectStmt{Sel: p.parseSelect()}
	case "WITH":
		w := p.parseWith()
		t2 := p.peek()
		if t2.T == TKeyword {
			switch t2.V {
			case "SELECT", "VALUES":
				s := p.parseSelect()
				s.With = mergeWith(w, s.With)
				return &SelectStmt{Sel: s}
			case "INSERT", "REPLACE":
				s := p.parseInsert()
				s.With = w
				return s
			case "UPDATE":
				s := p.parseUpdate()
				s.With = w
				return s
			case "DELETE":
				s := p.parseDelete()
				s.With = w
				return s
			}
		}
		p.fail()
	case "INSERT", "REPLACE":
		return p.parseInsert()
	case "UPDATE":
		return p.parseUpdate()
	case "DELETE":
		return p.parseDelete()
	case "CREATE":
		return p.parseCreate()
	case "DROP":
		return p.parseDrop()
	case "ALTER":
		return p.parseAlter()
	case "BEGIN":
		p.next()
		mode := ""
		if p.isKW("DEFERRED") || p.isKW("IMMEDIATE") || p.isKW("EXCLUSIVE") {
			mode = p.next().V
		}
		p.acceptKW("TRANSACTION")
		return &TxnStmt{Kind: "BEGIN", Mode: mode}
	case "COMMIT", "END":
		p.next()
		p.acceptKW("TRANSACTION")
		return &TxnStmt{Kind: "COMMIT"}
	case "ROLLBACK":
		p.next()
		p.acceptKW("TRANSACTION")
		if p.acceptKW("TO") {
			p.acceptKW("SAVEPOINT")
			n := p.parseName()
			return &TxnStmt{Kind: "ROLLBACK", Name: n}
		}
		return &TxnStmt{Kind: "ROLLBACK"}
	case "SAVEPOINT":
		p.next()
		return &TxnStmt{Kind: "SAVEPOINT", Name: p.parseName()}
	case "RELEASE":
		p.next()
		p.acceptKW("SAVEPOINT")
		return &TxnStmt{Kind: "RELEASE", Name: p.parseName()}
	case "PRAGMA":
		return p.parsePragma()
	case "ATTACH":
		p.next()
		p.acceptKW("DATABASE")
		f := p.parseExpr()
		p.expectKW("AS")
		n := p.parseExpr()
		return &AttachStmt{File: f, Name: n}
	case "DETACH":
		p.next()
		p.acceptKW("DATABASE")
		e := p.parseExpr()
		name := ""
		if e.Op == EColumn {
			name = e.Column
		} else if e.Op == ELit {
			name = e.Val.Text()
		}
		return &DetachStmt{Name: name}
	case "VACUUM":
		p.next()
		v := &VacuumStmt{}
		if p.isNameTok(p.peek()) && !p.isKW("INTO") {
			v.Schema = p.parseName()
		}
		if p.acceptKW("INTO") {
			v.Into = p.parseExpr()
		}
		return v
	case "ANALYZE":
		p.next()
		a := &AnalyzeStmt{}
		if p.isNameTok(p.peek()) {
			a.Name = p.parseName()
			if p.acceptOp(".") {
				a.Name = p.parseName()
			}
		}
		return a
	case "REINDEX":
		p.next()
		a := &ReindexStmt{}
		if p.isNameTok(p.peek()) {
			a.Name = p.parseName()
			if p.acceptOp(".") {
				a.Name = p.parseName()
			}
		}
		return a
	}
	p.fail()
	return nil
}

func mergeWith(a, b *With) *With {
	if b == nil {
		return a
	}
	return a
}

func (p *Parser) parsePragma() Stmt {
	p.next()
	ps := &PragmaStmt{}
	n := p.parseName()
	if p.acceptOp(".") {
		ps.Schema = n
		n = p.parseName()
	}
	ps.Name = n
	if p.acceptOp("=") {
		ps.HasVal = true
		ps.Value = p.parsePragmaValue()
	} else if p.acceptOp("(") {
		ps.HasVal = true
		ps.Call = true
		ps.Value = p.parsePragmaValue()
		p.expectOp(")")
	}
	return ps
}

func (p *Parser) parsePragmaValue() *Expr {
	t := p.peek()
	neg := false
	if t.T == TOp && (t.S == "-" || t.S == "+") {
		neg = t.S == "-"
		p.next()
		t = p.peek()
	}
	switch t.T {
	case TInteger, TFloat:
		e := p.parsePrimary()
		if neg {
			return &Expr{Op: EUnary, Name: "-", L: e}
		}
		return e
	case TString:
		p.next()
		return &Expr{Op: ELit, Val: TextValue(t.V)}
	case TIdent, TKeyword:
		p.next()
		return &Expr{Op: ELit, Val: TextValue(nameOf(t))}
	}
	p.fail()
	return nil
}

func (p *Parser) parseWith() *With {
	p.expectKW("WITH")
	w := &With{}
	if p.acceptKW("RECURSIVE") {
		w.Recursive = true
	}
	for {
		c := &CTE{}
		c.Name = nameOf(p.parseNameTok())
		if p.acceptOp("(") {
			for {
				c.Cols = append(c.Cols, nameOf(p.parseNameTok()))
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp(")")
		}
		p.expectKW("AS")
		if p.acceptKW("NOT") {
			p.expectKW("MATERIALIZED")
			c.Materialized = 2
		} else if p.acceptKW("MATERIALIZED") {
			c.Materialized = 1
		}
		p.expectOp("(")
		c.Sel = p.parseSelect()
		p.expectOp(")")
		w.CTEs = append(w.CTEs, c)
		if !p.acceptOp(",") {
			break
		}
	}
	return w
}

// ---------------- SELECT ----------------

func (p *Parser) parseSelect() *Select {
	var with *With
	if p.isKW("WITH") {
		with = p.parseWith()
	}
	s := p.parseSelectCore()
	for {
		op := ""
		if p.isKW("UNION") {
			p.next()
			if p.acceptKW("ALL") {
				op = "UNION ALL"
			} else {
				op = "UNION"
			}
		} else if p.isKW("INTERSECT") {
			p.next()
			op = "INTERSECT"
		} else if p.isKW("EXCEPT") {
			p.next()
			op = "EXCEPT"
		} else {
			break
		}
		r := p.parseSelectCore()
		r.CompoundOp = op
		r.Prior = s
		s = r
	}
	if p.isKW("ORDER") {
		p.next()
		p.expectKW("BY")
		s.OrderBy = p.parseOrderList()
	}
	if p.isKW("LIMIT") {
		p.next()
		s.Limit = p.parseExpr()
		if p.acceptKW("OFFSET") {
			s.Offset = p.parseExpr()
		} else if p.acceptOp(",") {
			s.Offset = s.Limit
			s.Limit = p.parseExpr()
		}
	}
	s.With = with
	return s
}

func (p *Parser) parseOrderList() []*OrderTerm {
	var list []*OrderTerm
	for {
		ot := &OrderTerm{E: p.parseExpr()}
		if p.acceptKW("ASC") {
		} else if p.acceptKW("DESC") {
			ot.Desc = true
		}
		if p.acceptKW("NULLS") {
			if p.acceptKW("FIRST") {
				ot.Nulls = 1
			} else {
				p.expectKW("LAST")
				ot.Nulls = 2
			}
		}
		list = append(list, ot)
		if !p.acceptOp(",") {
			break
		}
	}
	return list
}

func (p *Parser) parseSelectCore() *Select {
	s := &Select{Pos: p.peek().Pos}
	if p.acceptKW("VALUES") {
		for {
			p.expectOp("(")
			var row []*Expr
			for {
				row = append(row, p.parseExpr())
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp(")")
			s.Values = append(s.Values, row)
			if !p.acceptOp(",") {
				break
			}
		}
		return s
	}
	p.expectKW("SELECT")
	if p.acceptKW("DISTINCT") {
		s.Distinct = true
	} else {
		p.acceptKW("ALL")
	}
	s.Cols = p.parseResultCols()
	if p.acceptKW("FROM") {
		s.From = p.parseFrom()
	}
	if p.acceptKW("WHERE") {
		s.Where = p.parseExpr()
	}
	if p.isKW("GROUP") {
		p.next()
		p.expectKW("BY")
		for {
			s.GroupBy = append(s.GroupBy, p.parseExpr())
			if !p.acceptOp(",") {
				break
			}
		}
	}
	if p.acceptKW("HAVING") {
		s.Having = p.parseExpr()
	}
	if p.isKW("WINDOW") {
		p.next()
		for {
			name := nameOf(p.parseNameTok())
			p.expectKW("AS")
			w := p.parseWindowSpec()
			w.Name = name
			s.Windows = append(s.Windows, w)
			if !p.acceptOp(",") {
				break
			}
		}
	}
	return s
}

func (p *Parser) parseResultCols() []*ResultCol {
	var cols []*ResultCol
	for {
		t := p.peek()
		if t.T == TOp && t.S == "*" {
			p.next()
			cols = append(cols, &ResultCol{Star: true})
		} else if p.isNameTok(t) && p.peekN(1).T == TOp && p.peekN(1).S == "." && p.peekN(2).T == TOp && p.peekN(2).S == "*" {
			p.next()
			p.next()
			p.next()
			cols = append(cols, &ResultCol{Star: true, Table: nameOf(t)})
		} else {
			startTok := p.peek()
			e := p.parseExpr()
			rc := &ResultCol{E: e}
			rc.Span = p.src[startTok.Pos:p.stmtEndPos()]
			if p.acceptKW("AS") {
				at := p.peek()
				if !p.isNameTok(at) {
					p.fail()
				}
				p.next()
				rc.Alias = nameOf(at)
			} else {
				at := p.peek()
				if p.isIdTok(at) || at.T == TString {
					p.next()
					rc.Alias = nameOf(at)
				}
			}
			cols = append(cols, rc)
		}
		if !p.acceptOp(",") {
			break
		}
	}
	return cols
}

func (p *Parser) parseFrom() []*FromItem {
	var items []*FromItem
	first := p.parseFromItem()
	items = append(items, first)
	for {
		jt := JoinType(0)
		if p.acceptOp(",") {
			jt = JInner | JCross
			// comma join
			it := p.parseFromItem()
			it.Join = JInner
			items = append(items, it)
			continue
		}
		seen := false
		for {
			t := p.peek()
			if t.T == TKeyword && joinKW[t.V] {
				p.next()
				seen = true
				switch t.V {
				case "LEFT":
					jt |= JLeft
				case "RIGHT":
					jt |= JRight
				case "FULL":
					jt |= JLeft | JRight
				case "INNER":
					jt |= JInner
				case "CROSS":
					jt |= JCross
				case "NATURAL":
					jt |= JNatural
				case "OUTER":
					jt |= JOuter
				}
				continue
			}
			break
		}
		if p.isKW("JOIN") {
			p.next()
		} else {
			if seen {
				p.fail()
			}
			break
		}
		if jt&(JLeft|JRight) == 0 {
			jt |= JInner
		}
		it := p.parseFromItem()
		it.Join = jt
		if p.acceptKW("ON") {
			it.On = p.parseExpr()
		} else if p.acceptKW("USING") {
			p.expectOp("(")
			for {
				it.Using = append(it.Using, nameOf(p.parseNameTok()))
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp(")")
		}
		items = append(items, it)
	}
	// ON/USING for comma joins
	return items
}

func (p *Parser) parseFromItem() *FromItem {
	it := &FromItem{Pos: p.peek().Pos}
	if p.isOp("(") {
		p.next()
		if p.isKW("SELECT") || p.isKW("VALUES") || p.isKW("WITH") {
			it.Sel = p.parseSelect()
			p.expectOp(")")
		} else {
			// parenthesized join
			items := p.parseFrom()
			p.expectOp(")")
			if len(items) == 1 {
				it = items[0]
			} else {
				it.Paren = items
			}
		}
	} else {
		t := p.peek()
		if !p.isNameTok(t) {
			p.fail()
		}
		p.next()
		it.Name = nameOf(t)
		if p.acceptOp(".") {
			it.Schema = it.Name
			t2 := p.peek()
			if !p.isNameTok(t2) {
				p.fail()
			}
			p.next()
			it.Name = nameOf(t2)
		}
		if p.isOp("(") {
			p.next()
			it.IsFunc = true
			if !p.isOp(")") {
				for {
					it.FuncArgs = append(it.FuncArgs, p.parseExpr())
					if !p.acceptOp(",") {
						break
					}
				}
			}
			p.expectOp(")")
		}
	}
	// alias
	if p.acceptKW("AS") {
		it.Alias = nameOf(p.parseNameTok())
	} else {
		t := p.peek()
		if p.isIdTok(t) || t.T == TString {
			p.next()
			it.Alias = nameOf(t)
		}
	}
	if p.isKW("INDEXED") {
		p.next()
		p.expectKW("BY")
		it.Indexed = p.parseName()
	} else if p.isKW("NOT") && p.isKWn(1, "INDEXED") {
		p.next()
		p.next()
		it.NotIndexed = true
	}
	return it
}

func (p *Parser) parseWindowSpec() *WindowDef {
	p.expectOp("(")
	w := &WindowDef{}
	t := p.peek()
	if p.isIdTok(t) && !(t.T == TKeyword && (t.V == "PARTITION" || t.V == "ORDER" || t.V == "ROWS" || t.V == "RANGE" || t.V == "GROUPS")) {
		p.next()
		w.Base = nameOf(t)
	}
	if p.acceptKW("PARTITION") {
		p.expectKW("BY")
		for {
			w.Partition = append(w.Partition, p.parseExpr())
			if !p.acceptOp(",") {
				break
			}
		}
	}
	if p.isKW("ORDER") {
		p.next()
		p.expectKW("BY")
		w.OrderBy = p.parseOrderList()
	}
	if p.isKW("ROWS") || p.isKW("RANGE") || p.isKW("GROUPS") {
		f := &FrameSpec{Type: p.next().V}
		if p.acceptKW("BETWEEN") {
			f.Start = p.parseFrameBound()
			p.expectKW("AND")
			f.End = p.parseFrameBound()
		} else {
			f.Start = p.parseFrameBound()
			f.End = FrameBound{Kind: "CURRENT ROW"}
		}
		if p.acceptKW("EXCLUDE") {
			if p.acceptKW("NO") {
				p.expectKW("OTHERS")
				f.Exclude = ""
			} else if p.acceptKW("CURRENT") {
				p.expectKW("ROW")
				f.Exclude = "CURRENT ROW"
			} else if p.acceptKW("GROUP") {
				f.Exclude = "GROUP"
			} else {
				p.expectKW("TIES")
				f.Exclude = "TIES"
			}
		}
		w.Frame = f
	}
	p.expectOp(")")
	return w
}

func (p *Parser) parseFrameBound() FrameBound {
	if p.acceptKW("UNBOUNDED") {
		if p.acceptKW("PRECEDING") {
			return FrameBound{Kind: "UNBOUNDED PRECEDING"}
		}
		p.expectKW("FOLLOWING")
		return FrameBound{Kind: "UNBOUNDED FOLLOWING"}
	}
	if p.isKW("CURRENT") {
		p.next()
		p.expectKW("ROW")
		return FrameBound{Kind: "CURRENT ROW"}
	}
	e := p.parseExpr()
	if p.acceptKW("PRECEDING") {
		return FrameBound{Kind: "PRECEDING", Expr: e}
	}
	p.expectKW("FOLLOWING")
	return FrameBound{Kind: "FOLLOWING", Expr: e}
}

// ---------------- Expressions ----------------

func (p *Parser) parseExpr() *Expr {
	return p.parseOr()
}

func (p *Parser) parseOr() *Expr {
	l := p.parseAnd()
	for p.isKW("OR") {
		t := p.next()
		r := p.parseAnd()
		l = &Expr{Op: EBinary, Name: "OR", L: l, R: r, Pos: t.Pos}
	}
	return l
}

func (p *Parser) parseAnd() *Expr {
	l := p.parseNot()
	for p.isKW("AND") {
		t := p.next()
		r := p.parseNot()
		l = &Expr{Op: EBinary, Name: "AND", L: l, R: r, Pos: t.Pos}
	}
	return l
}

func (p *Parser) parseNot() *Expr {
	if p.isKW("NOT") {
		t := p.next()
		e := p.parseNot()
		return &Expr{Op: EUnary, Name: "NOT", L: e, Pos: t.Pos}
	}
	return p.parseEquality()
}

func (p *Parser) parseEquality() *Expr {
	l := p.parseComparison()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "=" || t.S == "==" || t.S == "!=" || t.S == "<>") {
			p.next()
			r := p.parseComparison()
			op := t.S
			if op == "==" {
				op = "="
			} else if op == "<>" {
				op = "!="
			}
			l = &Expr{Op: EBinary, Name: op, L: l, R: r, Pos: t.Pos}
			continue
		}
		if t.T != TKeyword {
			return l
		}
		switch t.V {
		case "IS":
			p.next()
			not := p.acceptKW("NOT")
			if p.acceptKW("DISTINCT") {
				p.expectKW("FROM")
				not = !not
			}
			r := p.parseComparison()
			op := "IS"
			if not {
				op = "IS NOT"
			}
			l = &Expr{Op: EBinary, Name: op, L: l, R: r, Pos: t.Pos}
		case "ISNULL":
			p.next()
			l = &Expr{Op: EIsNull, L: l, Pos: t.Pos}
		case "NOTNULL":
			p.next()
			l = &Expr{Op: EIsNull, L: l, Not: true, Pos: t.Pos}
		case "NOT":
			t1 := p.peekN(1)
			if t1.T == TKeyword && t1.V == "NULL" {
				p.next()
				p.next()
				l = &Expr{Op: EIsNull, L: l, Not: true, Pos: t.Pos}
			} else if t1.T == TKeyword && (t1.V == "IN" || t1.V == "LIKE" || t1.V == "GLOB" || t1.V == "REGEXP" || t1.V == "MATCH" || t1.V == "BETWEEN") {
				p.next()
				l = p.parseEqualityOp(l, true)
			} else {
				return l
			}
		case "IN", "LIKE", "GLOB", "REGEXP", "MATCH", "BETWEEN":
			l = p.parseEqualityOp(l, false)
		default:
			return l
		}
	}
}

func (p *Parser) parseEqualityOp(l *Expr, not bool) *Expr {
	t := p.next()
	switch t.V {
	case "IN":
		e := &Expr{Op: EIn, L: l, Not: not, Pos: t.Pos}
		if p.acceptOp("(") {
			if p.isKW("SELECT") || p.isKW("VALUES") || p.isKW("WITH") {
				e.Sel = p.parseSelect()
			} else if !p.isOp(")") {
				for {
					e.List = append(e.List, p.parseExpr())
					if !p.acceptOp(",") {
						break
					}
				}
			} else {
				e.List = []*Expr{}
			}
			p.expectOp(")")
		} else {
			nt := p.peek()
			if !p.isNameTok(nt) {
				p.fail()
			}
			p.next()
			name := nameOf(nt)
			if p.acceptOp(".") {
				name = nameOf(p.parseNameTok())
			}
			e.Name = name
			if p.acceptOp("(") {
				e.TblArgs = []*Expr{}
				if !p.isOp(")") {
					for {
						e.TblArgs = append(e.TblArgs, p.parseExpr())
						if !p.acceptOp(",") {
							break
						}
					}
				}
				p.expectOp(")")
			}
		}
		return e
	case "BETWEEN":
		lo := p.parseComparison()
		p.expectKW("AND")
		hi := p.parseComparison()
		return &Expr{Op: EBetween, L: l, List: []*Expr{lo, hi}, Not: not, Pos: t.Pos}
	default:
		r := p.parseComparison()
		e := &Expr{Op: ELike, Name: t.V, L: l, R: r, Not: not, Pos: t.Pos}
		if p.acceptKW("ESCAPE") {
			e.Escape = p.parseComparison()
		}
		return e
	}
}

func (p *Parser) parseComparison() *Expr {
	l := p.parseBitwise()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "<" || t.S == "<=" || t.S == ">" || t.S == ">=") {
			p.next()
			r := p.parseBitwise()
			l = &Expr{Op: EBinary, Name: t.S, L: l, R: r, Pos: t.Pos}
			continue
		}
		return l
	}
}

func (p *Parser) parseBitwise() *Expr {
	l := p.parseAdd()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "&" || t.S == "|" || t.S == "<<" || t.S == ">>") {
			p.next()
			r := p.parseAdd()
			l = &Expr{Op: EBinary, Name: t.S, L: l, R: r, Pos: t.Pos}
			continue
		}
		return l
	}
}

func (p *Parser) parseAdd() *Expr {
	l := p.parseMul()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "+" || t.S == "-") {
			p.next()
			r := p.parseMul()
			l = &Expr{Op: EBinary, Name: t.S, L: l, R: r, Pos: t.Pos}
			continue
		}
		return l
	}
}

func (p *Parser) parseMul() *Expr {
	l := p.parseConcat()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "*" || t.S == "/" || t.S == "%") {
			p.next()
			r := p.parseConcat()
			l = &Expr{Op: EBinary, Name: t.S, L: l, R: r, Pos: t.Pos}
			continue
		}
		return l
	}
}

func (p *Parser) parseConcat() *Expr {
	l := p.parseCollate()
	for {
		t := p.peek()
		if t.T == TOp && (t.S == "||" || t.S == "->" || t.S == "->>") {
			p.next()
			r := p.parseCollate()
			l = &Expr{Op: EBinary, Name: t.S, L: l, R: r, Pos: t.Pos}
			continue
		}
		return l
	}
}

func (p *Parser) parseCollate() *Expr {
	l := p.parseUnary()
	for p.isKW("COLLATE") {
		t := p.next()
		nt := p.peek()
		if !p.isNameTok(nt) {
			p.fail()
		}
		p.next()
		l = &Expr{Op: ECollate, L: l, Name: nameOf(nt), Pos: t.Pos}
	}
	return l
}

func (p *Parser) parseUnary() *Expr {
	t := p.peek()
	if t.T == TOp && (t.S == "-" || t.S == "+" || t.S == "~") {
		p.next()
		e := p.parseUnary()
		// fold negative numeric literals
		if t.S == "-" && e.Op == ELit && !e.Paren && (e.Val.K == KInt || e.Val.K == KReal) && e.Name == "num" {
			if e.Val.K == KInt {
				return &Expr{Op: ELit, Val: IntValue(-e.Val.I), Pos: t.Pos, Name: "num"}
			}
			return &Expr{Op: ELit, Val: RealValue(-e.Val.F), Pos: t.Pos, Name: "num"}
		}
		if t.S == "-" && e.Op == ELit && e.Name == "bigint" {
			// -9223372036854775808
			if e.Val.K == KReal && e.Val.F == 9223372036854775808.0 {
				return &Expr{Op: ELit, Val: IntValue(-9223372036854775808), Pos: t.Pos, Name: "num"}
			}
		}
		return &Expr{Op: EUnary, Name: t.S, L: e, Pos: t.Pos}
	}
	return p.parsePrimary()
}

func (p *Parser) parsePrimary() *Expr {
	t := p.peek()
	switch t.T {
	case TInteger:
		p.next()
		s := t.V
		var v Value
		if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
			u, err := strconv.ParseUint(s[2:], 16, 64)
			if err != nil {
				panic(&ParseError{Msg: fmt.Sprintf("hex literal too big: %s", t.S), Pos: t.Pos})
			}
			v = IntValue(int64(u))
			return &Expr{Op: ELit, Val: v, Pos: t.Pos, End: t.Pos + len(t.S), Name: "num"}
		}
		i, err := strconv.ParseInt(s, 10, 64)
		if err != nil {
			f, _ := strconv.ParseFloat(s, 64)
			return &Expr{Op: ELit, Val: RealValue(f), Pos: t.Pos, End: t.Pos + len(t.S), Name: "bigint"}
		}
		return &Expr{Op: ELit, Val: IntValue(i), Pos: t.Pos, End: t.Pos + len(t.S), Name: "num"}
	case TFloat:
		p.next()
		f, _ := strconv.ParseFloat(t.V, 64)
		return &Expr{Op: ELit, Val: RealValue(f), Pos: t.Pos, End: t.Pos + len(t.S), Name: "num"}
	case TString:
		p.next()
		return &Expr{Op: ELit, Val: TextValue(t.V), Pos: t.Pos, End: t.Pos + len(t.S)}
	case TBlob:
		p.next()
		b := make([]byte, len(t.V)/2)
		for i := 0; i < len(b); i++ {
			x, _ := strconv.ParseUint(t.V[2*i:2*i+2], 16, 8)
			b[i] = byte(x)
		}
		return &Expr{Op: ELit, Val: BlobValue(string(b)), Pos: t.Pos, End: t.Pos + len(t.S)}
	case TVariable:
		p.next()
		return &Expr{Op: EParam, Name: t.S, Pos: t.Pos}
	case TOp:
		if t.S == "(" {
			p.next()
			if p.isKW("SELECT") || p.isKW("VALUES") || p.isKW("WITH") {
				s := p.parseSelect()
				p.expectOp(")")
				return &Expr{Op: ESubquery, Sel: s, Pos: t.Pos}
			}
			e := p.parseExpr()
			if p.isOp(",") {
				list := []*Expr{e}
				for p.acceptOp(",") {
					list = append(list, p.parseExpr())
				}
				p.expectOp(")")
				return &Expr{Op: EVector, List: list, Pos: t.Pos}
			}
			p.expectOp(")")
			e.Paren = true
			return e
		}
	case TKeyword:
		switch t.V {
		case "NULL":
			p.next()
			return &Expr{Op: ELit, Val: NullValue, Pos: t.Pos}
		case "CURRENT_TIME", "CURRENT_DATE", "CURRENT_TIMESTAMP":
			p.next()
			return &Expr{Op: EFunc, Name: strings.ToLower(t.V), Pos: t.Pos}
		case "CAST":
			if p.peekN(1).T == TOp && p.peekN(1).S == "(" {
				p.next()
				p.next()
				e := p.parseExpr()
				p.expectKW("AS")
				typ := p.parseTypeName()
				p.expectOp(")")
				return &Expr{Op: ECast, L: e, Name: typ, Pos: t.Pos}
			}
		case "CASE":
			p.next()
			e := &Expr{Op: ECase, Pos: t.Pos}
			if !p.isKW("WHEN") {
				e.L = p.parseExpr()
			}
			for p.acceptKW("WHEN") {
				w := p.parseExpr()
				p.expectKW("THEN")
				th := p.parseExpr()
				e.List = append(e.List, w, th)
			}
			if len(e.List) == 0 {
				p.fail()
			}
			if p.acceptKW("ELSE") {
				e.R = p.parseExpr()
			}
			p.expectKW("END")
			return e
		case "EXISTS":
			if p.peekN(1).T == TOp && p.peekN(1).S == "(" {
				p.next()
				p.next()
				s := p.parseSelect()
				p.expectOp(")")
				return &Expr{Op: EExists, Sel: s, Pos: t.Pos}
			}
		case "NOT":
			if p.isKWn(1, "EXISTS") {
				p.next()
				e := p.parsePrimary()
				return &Expr{Op: EUnary, Name: "NOT", L: e, Pos: t.Pos}
			}
		case "RAISE":
			if p.peekN(1).T == TOp && p.peekN(1).S == "(" {
				p.next()
				p.next()
				e := &Expr{Op: ERaise, Pos: t.Pos}
				if p.acceptKW("IGNORE") {
					e.Name = "IGNORE"
				} else {
					k := p.peek()
					if k.T == TKeyword && (k.V == "ROLLBACK" || k.V == "ABORT" || k.V == "FAIL") {
						p.next()
						e.Name = k.V
					} else {
						p.fail()
					}
					p.expectOp(",")
					e.L = p.parseExpr()
				}
				p.expectOp(")")
				return e
			}
		}
	}
	// identifier / function
	if t.T == TIdent || (t.T == TKeyword && !reservedWords[t.V]) || (t.T == TString && false) {
		p.next()
		name := nameOf(t)
		nt := p.peek()
		if nt.T == TOp && nt.S == "(" && !t.Quot {
			return p.parseFunctionCall(t)
		}
		if nt.T == TOp && nt.S == "(" && t.Quot {
			return p.parseFunctionCall(t)
		}
		if nt.T == TOp && nt.S == "." {
			p.next()
			t2 := p.peek()
			if !p.isNameTok(t2) {
				p.fail()
			}
			p.next()
			if p.isOp(".") {
				p.next()
				t3 := p.peek()
				if !p.isNameTok(t3) {
					p.fail()
				}
				p.next()
				return &Expr{Op: EColumn, Schema: name, Table: nameOf(t2), Column: nameOf(t3), Pos: t.Pos, ColQuot: t3.DQ}
			}
			return &Expr{Op: EColumn, Table: name, Column: nameOf(t2), Pos: t.Pos, ColQuot: t2.DQ}
		}
		return &Expr{Op: EColumn, Column: name, Pos: t.Pos, ColQuot: t.DQ}
	}
	p.fail()
	return nil
}

func (p *Parser) parseTypeName() string {
	var parts []string
	for {
		t := p.peek()
		if t.T == TIdent || (t.T == TKeyword && !reservedWords[t.V]) || t.T == TString {
			if t.T == TKeyword && (t.V == "CONSTRAINT") {
				break
			}
			p.next()
			if t.T == TIdent && t.Quot {
				parts = append(parts, t.V)
			} else {
				parts = append(parts, t.S)
			}
			continue
		}
		break
	}
	typ := strings.Join(parts, " ")
	if p.isOp("(") {
		start := p.peek().Pos
		p.next()
		p.parseSignedNum()
		if p.acceptOp(",") {
			p.parseSignedNum()
		}
		end := p.expectOp(")")
		_ = start
		_ = end
		// Keep original text of type including parens
		typ = typ + p.src[start:end.Pos+1]
	}
	return typ
}

func (p *Parser) parseSignedNum() {
	if p.isOp("+") || p.isOp("-") {
		p.next()
	}
	t := p.peek()
	if t.T == TInteger || t.T == TFloat {
		p.next()
		return
	}
	if p.isIdTok(t) {
		p.next()
		return
	}
	p.fail()
}

func (p *Parser) parseFunctionCall(t Token) *Expr {
	p.expectOp("(")
	e := &Expr{Op: EFunc, Name: strings.ToLower(nameOf(t)), Pos: t.Pos}
	if p.acceptOp("*") {
		e.Star = true
	} else if !p.isOp(")") {
		if p.acceptKW("DISTINCT") {
			e.Distinct = true
		} else {
			p.acceptKW("ALL")
		}
		for {
			e.List = append(e.List, p.parseExpr())
			if !p.acceptOp(",") {
				break
			}
		}
		if p.isKW("ORDER") {
			p.next()
			p.expectKW("BY")
			e.OrderBy = p.parseOrderList()
		}
	}
	p.expectOp(")")
	if p.isKW("FILTER") {
		p.next()
		p.expectOp("(")
		p.expectKW("WHERE")
		e.Filter = p.parseExpr()
		p.expectOp(")")
	}
	if p.isKW("OVER") {
		p.next()
		if p.isOp("(") {
			e.Over = p.parseWindowSpec()
		} else {
			e.Over = &WindowDef{Base: nameOf(p.parseNameTok())}
		}
	}
	return e
}
