func (p *Parser) parseConflictClause() string {
	if p.isKW("ON") && p.isKWn(1, "CONFLICT") {
		p.next()
		p.next()
		t := p.next()
		if t.T == TKeyword && (t.V == "ROLLBACK" || t.V == "ABORT" || t.V == "FAIL" || t.V == "IGNORE" || t.V == "REPLACE") {
			return t.V
		}
		p.p--
		p.fail()
	}
	return ""
}

func (p *Parser) parseQualifiedName() (string, string) {
	n := nameOf(p.parseNameTok())
	if p.acceptOp(".") {
		return n, nameOf(p.parseNameTok())
	}
	return "", n
}

func (p *Parser) parseReturning() []*ResultCol {
	if p.acceptKW("RETURNING") {
		return p.parseResultCols()
	}
	return nil
}

func (p *Parser) parseInsert() *InsertStmt {
	st := &InsertStmt{Pos: p.peek().Pos}
	if p.acceptKW("REPLACE") {
		st.OrConflict = "REPLACE"
	} else {
		p.expectKW("INSERT")
		if p.acceptKW("OR") {
			t := p.next()
			if t.T == TKeyword && (t.V == "ROLLBACK" || t.V == "ABORT" || t.V == "FAIL" || t.V == "IGNORE" || t.V == "REPLACE") {
				st.OrConflict = t.V
			} else {
				p.p--
				p.fail()
			}
		}
	}
	p.expectKW("INTO")
	st.Schema, st.Table = p.parseQualifiedName()
	if p.acceptKW("AS") {
		st.Alias = nameOf(p.parseNameTok())
	}
	if p.isOp("(") {
		p.next()
		for {
			st.Cols = append(st.Cols, nameOf(p.parseNameTok()))
			if !p.acceptOp(",") {
				break
			}
		}
		p.expectOp(")")
	}
	if p.isKW("DEFAULT") {
		p.next()
		p.expectKW("VALUES")
		st.Default = true
	} else if p.isKW("SELECT") || p.isKW("VALUES") || p.isKW("WITH") {
		st.Sel = p.parseSelect()
	} else {
		p.fail()
	}
	for p.isKW("ON") && p.isKWn(1, "CONFLICT") {
		p.next()
		p.next()
		u := &Upsert{}
		if p.acceptOp("(") {
			u.Target = p.parseIndexedCols()
			p.expectOp(")")
			if p.acceptKW("WHERE") {
				u.TargetWhere = p.parseExpr()
			}
		}
		p.expectKW("DO")
		if p.acceptKW("NOTHING") {
			u.DoNothing = true
		} else {
			p.expectKW("UPDATE")
			p.expectKW("SET")
			u.Set = p.parseSetList()
			if p.acceptKW("WHERE") {
				u.Where = p.parseExpr()
			}
		}
		st.Upserts = append(st.Upserts, u)
	}
	st.Returning = p.parseReturning()
	return st
}

func (p *Parser) parseSetList() []*SetClause {
	var list []*SetClause
	for {
		sc := &SetClause{}
		if p.acceptOp("(") {
			for {
				sc.Cols = append(sc.Cols, nameOf(p.parseNameTok()))
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp(")")
		} else {
			sc.Cols = []string{nameOf(p.parseNameTok())}
		}
		p.expectOp("=")
		sc.E = p.parseExpr()
		list = append(list, sc)
		if !p.acceptOp(",") {
			break
		}
	}
	return list
}

func (p *Parser) parseUpdate() *UpdateStmt {
	st := &UpdateStmt{Pos: p.peek().Pos}
	p.expectKW("UPDATE")
	if p.acceptKW("OR") {
		t := p.next()
		if t.T == TKeyword && (t.V == "ROLLBACK" || t.V == "ABORT" || t.V == "FAIL" || t.V == "IGNORE" || t.V == "REPLACE") {
			st.OrConflict = t.V
		} else {
			p.p--
			p.fail()
		}
	}
	st.Schema, st.Table = p.parseQualifiedName()
	if p.acceptKW("AS") {
		st.Alias = nameOf(p.parseNameTok())
	} else if p.isIdTok(p.peek()) && !p.isKW("SET") {
		st.Alias = nameOf(p.next())
	}
	if p.isKW("INDEXED") {
		p.next()
		p.expectKW("BY")
		st.Indexed = p.parseName()
	} else if p.isKW("NOT") && p.isKWn(1, "INDEXED") {
		p.next()
		p.next()
	}
	p.expectKW("SET")
	st.Set = p.parseSetList()
	if p.acceptKW("FROM") {
		st.From = p.parseFrom()
	}
	if p.acceptKW("WHERE") {
		st.Where = p.parseExpr()
	}
	st.Returning = p.parseReturning()
	if p.isKW("ORDER") {
		p.next()
		p.expectKW("BY")
		st.OrderBy = p.parseOrderList()
	}
	if p.acceptKW("LIMIT") {
		st.Limit = p.parseExpr()
		if p.acceptKW("OFFSET") {
			st.Offset = p.parseExpr()
		} else if p.acceptOp(",") {
			st.Offset = st.Limit
			st.Limit = p.parseExpr()
		}
	}
	return st
}

func (p *Parser) parseDelete() *DeleteStmt {
	st := &DeleteStmt{Pos: p.peek().Pos}
	p.expectKW("DELETE")
	p.expectKW("FROM")
	st.Schema, st.Table = p.parseQualifiedName()
	if p.acceptKW("AS") {
		st.Alias = nameOf(p.parseNameTok())
	} else if p.isIdTok(p.peek()) {
		st.Alias = nameOf(p.next())
	}
	if p.isKW("INDEXED") {
		p.next()
		p.expectKW("BY")
		p.parseName()
	} else if p.isKW("NOT") && p.isKWn(1, "INDEXED") {
		p.next()
		p.next()
	}
	if p.acceptKW("WHERE") {
		st.Where = p.parseExpr()
	}
	st.Returning = p.parseReturning()
	if p.isKW("ORDER") {
		p.next()
		p.expectKW("BY")
		st.OrderBy = p.parseOrderList()
	}
	if p.acceptKW("LIMIT") {
		st.Limit = p.parseExpr()
		if p.acceptKW("OFFSET") {
			st.Offset = p.parseExpr()
		} else if p.acceptOp(",") {
			st.Offset = st.Limit
			st.Limit = p.parseExpr()
		}
	}
	return st
}

func (p *Parser) parseIndexedCols() []IndexedCol {
	var cols []IndexedCol
	for {
		e := p.parseExpr()
		ic := IndexedCol{E: e}
		if e.Op == ECollate {
			ic.Collate = e.Name
			e = e.L
			ic.E = e
		}
		if e.Op == EColumn && e.Table == "" {
			ic.Name = e.Column
		}
		if p.acceptKW("ASC") {
		} else if p.acceptKW("DESC") {
			ic.Desc = true
		}
		cols = append(cols, ic)
		if !p.acceptOp(",") {
			break
		}
	}
	return cols
}

func (p *Parser) parseCreate() Stmt {
	startTok := p.expectKW("CREATE")
	_ = startTok
	temp := false
	if p.acceptKW("TEMP") || p.acceptKW("TEMPORARY") {
		temp = true
	}
	unique := false
	if p.acceptKW("UNIQUE") {
		unique = true
		if !p.isKW("INDEX") {
			p.fail()
		}
	}
	t := p.peek()
	if t.T != TKeyword {
		p.fail()
	}
	switch t.V {
	case "TABLE":
		p.next()
		return p.parseCreateTable(temp)
	case "INDEX":
		p.next()
		st := &CreateIndexStmt{Unique: unique}
		if p.isKW("IF") {
			p.next()
			p.expectKW("NOT")
			p.expectKW("EXISTS")
			st.IfNotExists = true
		}
		nameStart := p.peek().Pos
		st.Schema, st.Name = p.parseQualifiedName()
		if st.Schema != "" {
			nameStart = p.toks[p.p-1].Pos
		}
		p.expectKW("ON")
		st.Table = nameOf(p.parseNameTok())
		p.expectOp("(")
		st.Cols = p.parseIndexedCols()
		p.expectOp(")")
		if p.acceptKW("WHERE") {
			st.Where = p.parseExpr()
		}
		u := ""
		if unique {
			u = " UNIQUE"
		}
		st.SQL = "CREATE" + u + " INDEX " + p.src[nameStart:p.stmtEndPos()]
		return st
	case "VIEW":
		p.next()
		st := &CreateViewStmt{Temp: temp}
		if p.isKW("IF") {
			p.next()
			p.expectKW("NOT")
			p.expectKW("EXISTS")
			st.IfNotExists = true
		}
		nameStart := p.peek().Pos
		st.Schema, st.Name = p.parseQualifiedName()
		if st.Schema != "" {
			nameStart = p.toks[p.p-1].Pos
		}
		if p.acceptOp("(") {
			for {
				st.Cols = append(st.Cols, nameOf(p.parseNameTok()))
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp(")")
		}
		p.expectKW("AS")
		st.Sel = p.parseSelect()
		st.SQL = "CREATE VIEW " + p.src[nameStart:p.stmtEndPos()]
		return st
	case "TRIGGER":
		p.next()
		return p.parseCreateTrigger(temp)
	case "VIRTUAL":
		p.next()
		p.expectKW("TABLE")
		st := &CreateVirtualStmt{}
		if p.isKW("IF") {
			p.next()
			p.expectKW("NOT")
			p.expectKW("EXISTS")
			st.IfNotExists = true
		}
		nameStart := p.peek().Pos
		_, st.Name = p.parseQualifiedName()
		p.expectKW("USING")
		st.Module = nameOf(p.parseNameTok())
		if p.isOp("(") {
			p.next()
			depth := 0
			argStart := p.peek().Pos
			for {
				tk := p.peek()
				if tk.T == TEOF {
					p.fail()
				}
				if tk.T == TOp && tk.S == "(" {
					depth++
				} else if tk.T == TOp && tk.S == ")" {
					if depth == 0 {
						if tk.Pos > argStart {
							st.Args = append(st.Args, strings.TrimSpace(p.src[argStart:tk.Pos]))
						}
						p.next()
						break
					}
					depth--
				} else if tk.T == TOp && tk.S == "," && depth == 0 {
					st.Args = append(st.Args, strings.TrimSpace(p.src[argStart:tk.Pos]))
					p.next()
					argStart = p.peek().Pos
					continue
				}
				p.next()
			}
		}
		st.SQL = "CREATE VIRTUAL TABLE " + p.src[nameStart:p.stmtEndPos()]
		return st
	}
	p.fail()
	return nil
}

func (p *Parser) parseCreateTable(temp bool) *CreateTableStmt {
	st := &CreateTableStmt{Temp: temp}
	if p.isKW("IF") {
		p.next()
		p.expectKW("NOT")
		p.expectKW("EXISTS")
		st.IfNotExists = true
	}
	nameStart := p.peek().Pos
	st.Schema, st.Name = p.parseQualifiedName()
	if st.Schema != "" {
		nameStart = p.toks[p.p-1].Pos
	}
	if p.acceptKW("AS") {
		st.AsSelect = p.parseSelect()
		return st
	}
	p.expectOp("(")
	for {
		// table constraint?
		if p.isKW("CONSTRAINT") || p.isKW("PRIMARY") || p.isKW("UNIQUE") || p.isKW("CHECK") || p.isKW("FOREIGN") {
			break
		}
		st.Cols = append(st.Cols, p.parseColumnDef())
		if !p.acceptOp(",") {
			goto done
		}
	}
	for {
		tc := &TableConstraint{}
		if p.acceptKW("CONSTRAINT") {
			tc.Name = nameOf(p.parseNameTok())
		}
		switch {
		case p.acceptKW("PRIMARY"):
			p.expectKW("KEY")
			tc.Kind = "PRIMARY"
			p.expectOp("(")
			tc.Cols = p.parseIndexedCols()
			if p.acceptKW("AUTOINCREMENT") {
				tc.AutoInc = true
			}
			p.expectOp(")")
			tc.Conflict = p.parseConflictClause()
		case p.acceptKW("UNIQUE"):
			tc.Kind = "UNIQUE"
			p.expectOp("(")
			tc.Cols = p.parseIndexedCols()
			p.expectOp(")")
			tc.Conflict = p.parseConflictClause()
		case p.isKW("CHECK"):
			p.next()
			tc.Kind = "CHECK"
			p.expectOp("(")
			s := p.peek().Pos
			tc.Check = p.parseExpr()
			tc.CheckText = p.src[s:p.stmtEndPos()]
			p.expectOp(")")
			tc.Conflict = p.parseConflictClause()
		case p.acceptKW("FOREIGN"):
			p.expectKW("KEY")
			tc.Kind = "FOREIGN"
			p.expectOp("(")
			var cols []string
			for {
				cols = append(cols, nameOf(p.parseNameTok()))
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp(")")
			fk := p.parseFKClause()
			fk.Cols = cols
			tc.FK = fk
		default:
			p.fail()
		}
		st.Constraints = append(st.Constraints, tc)
		if !p.acceptOp(",") {
			if p.isKW("CONSTRAINT") || p.isKW("PRIMARY") || p.isKW("UNIQUE") || p.isKW("CHECK") || p.isKW("FOREIGN") {
				continue
			}
			break
		}
	}
done:
	p.expectOp(")")
	for {
		if p.isKW("WITHOUT") {
			p.next()
			t := p.peek()
			if t.T == TIdent && strings.EqualFold(t.V, "rowid") {
				p.next()
				st.WithoutRowid = true
			} else {
				panic(&ParseError{Msg: "unknown table option: " + t.S, Pos: t.Pos})
			}
		} else if p.peek().T == TIdent && strings.EqualFold(p.peek().V, "strict") {
			p.next()
			st.Strict = true
		} else if p.peek().T == TIdent {
			t := p.peek()
			panic(&ParseError{Msg: "unknown table option: " + t.S, Pos: t.Pos})
		} else {
			break
		}
		if !p.acceptOp(",") {
			break
		}
	}
	st.SQL = "CREATE TABLE " + p.src[nameStart:p.stmtEndPos()]
	return st
}

func (p *Parser) parseFKClause() *ForeignKey {
	p.expectKW("REFERENCES")
	fk := &ForeignKey{}
	fk.Table = nameOf(p.parseNameTok())
	if p.acceptOp("(") {
		for {
			fk.RefCols = append(fk.RefCols, nameOf(p.parseNameTok()))
			if !p.acceptOp(",") {
				break
			}
		}
		p.expectOp(")")
	}
	for {
		if p.isKW("ON") && (p.isKWn(1, "DELETE") || p.isKWn(1, "UPDATE")) {
			p.next()
			which := p.next().V
			var action string
			if p.acceptKW("SET") {
				if p.acceptKW("NULL") {
					action = "SET NULL"
				} else {
					p.expectKW("DEFAULT")
					action = "SET DEFAULT"
				}
			} else if p.acceptKW("CASCADE") {
				action = "CASCADE"
			} else if p.acceptKW("RESTRICT") {
				action = "RESTRICT"
			} else if p.acceptKW("NO") {
				p.expectKW("ACTION")
				action = "NO ACTION"
			} else {
				p.fail()
			}
			if which == "DELETE" {
				fk.OnDelete = action
			} else {
				fk.OnUpdate = action
			}
			continue
		}
		if p.acceptKW("MATCH") {
			p.parseName()
			continue
		}
		break
	}
	if p.isKW("NOT") && p.isKWn(1, "DEFERRABLE") {
		p.next()
		p.next()
		if p.acceptKW("INITIALLY") {
			p.next()
		}
	} else if p.acceptKW("DEFERRABLE") {
		if p.acceptKW("INITIALLY") {
			if p.acceptKW("DEFERRED") {
				fk.Deferred = true
			} else {
				p.expectKW("IMMEDIATE")
			}
		}
	}
	return fk
}

func (p *Parser) parseColumnDef() *ColumnDef {
	cd := &ColumnDef{}
	cd.Name = nameOf(p.parseNameTok())
	// type
	var parts []string
	typStart := -1
	typEnd := -1
	for {
		t := p.peek()
		if t.T == TIdent || t.T == TString || (t.T == TKeyword && !reservedWords[t.V]) {
			if t.T == TKeyword && t.V == "GENERATED" && p.isKWn(1, "ALWAYS") {
				break
			}
			if typStart < 0 {
				typStart = t.Pos
			}
			p.next()
			typEnd = t.Pos + len(t.S)
			parts = append(parts, nameOf(t))
			continue
		}
		break
	}
	if typStart >= 0 && p.isOp("(") {
		p.next()
		p.parseSignedNum()
		if p.acceptOp(",") {
			p.parseSignedNum()
		}
		e := p.expectOp(")")
		typEnd = e.Pos + 1
	}
	if typStart >= 0 {
		// normalize spaces between words
		raw := p.src[typStart:typEnd]
		_ = raw
		cd.Type = strings.Join(parts, " ")
		if idx := strings.Index(raw, "("); idx >= 0 {
			cd.Type = cd.Type + raw[idx:]
			// remove spaces before paren from words part
			cd.Type = strings.Join(parts, " ") + raw[idx:]
		}
	}
	for {
		if p.acceptKW("CONSTRAINT") {
			p.parseName()
		}
		switch {
		case p.isKW("PRIMARY"):
			p.next()
			p.expectKW("KEY")
			cd.PrimaryKey = true
			if p.acceptKW("ASC") {
			} else if p.acceptKW("DESC") {
				cd.PKDesc = true
			}
			cd.PKConflict = p.parseConflictClause()
			if p.acceptKW("AUTOINCREMENT") {
				cd.AutoInc = true
			}
		case p.isKW("NOT"):
			p.next()
			p.expectKW("NULL")
			cd.NotNull = true
			cd.NNConflict = p.parseConflictClause()
		case p.isKW("NULL"):
			p.next()
			p.parseConflictClause()
		case p.isKW("UNIQUE"):
			p.next()
			cd.Unique = true
			cd.UQConflict = p.parseConflictClause()
		case p.isKW("CHECK"):
			p.next()
			p.expectOp("(")
			s := p.peek().Pos
			e := p.parseExpr()
			cd.Check = append(cd.Check, e)
			cd.CheckText = append(cd.CheckText, p.src[s:p.stmtEndPos()])
			p.expectOp(")")
		case p.isKW("DEFAULT"):
			p.next()
			s := p.peek().Pos
			if p.isOp("(") {
				p.next()
				cd.Default = p.parseExpr()
				p.expectOp(")")
			} else if p.isOp("-") || p.isOp("+") {
				op := p.next()
				t := p.peek()
				if t.T != TInteger && t.T != TFloat {
					p.fail()
				}
				e := p.parsePrimary()
				if op.S == "-" {
					if e.Val.K == KInt {
						e = &Expr{Op: ELit, Val: IntValue(-e.Val.I)}
					} else {
						e = &Expr{Op: ELit, Val: RealValue(-e.Val.F)}
					}
				}
				cd.Default = e
			} else {
				t := p.peek()
				switch t.T {
				case TInteger, TFloat, TString, TBlob:
					cd.Default = p.parsePrimary()
				case TKeyword:
					if t.V == "NULL" || t.V == "CURRENT_TIME" || t.V == "CURRENT_DATE" || t.V == "CURRENT_TIMESTAMP" {
						cd.Default = p.parsePrimary()
					} else if !reservedWords[t.V] {
						p.next()
						cd.Default = &Expr{Op: ELit, Val: TextValue(t.S)}
					} else {
						p.fail()
					}
				case TIdent:
					p.next()
					cd.Default = &Expr{Op: ELit, Val: TextValue(t.V)}
				default:
					p.fail()
				}
			}
			cd.DefaultText = p.src[s:p.stmtEndPos()]
		case p.isKW("COLLATE"):
			p.next()
			cd.Collate = nameOf(p.parseNameTok())
		case p.isKW("REFERENCES"):
			fk := p.parseFKClause()
			fk.Cols = []string{cd.Name}
			cd.FK = fk
		case p.isKW("GENERATED") || p.isKW("AS"):
			if p.acceptKW("GENERATED") {
				p.expectKW("ALWAYS")
			}
			p.expectKW("AS")
			p.expectOp("(")
			cd.Generated = p.parseExpr()
			p.expectOp(")")
			t := p.peek()
			if t.T == TIdent && strings.EqualFold(t.V, "STORED") {
				p.next()
				cd.GenStored = true
			} else if t.T == TIdent && strings.EqualFold(t.V, "VIRTUAL") || p.isKW("VIRTUAL") {
				p.next()
			}
		default:
			return cd
		}
	}
}

func (p *Parser) parseCreateTrigger(temp bool) *CreateTriggerStmt {
	st := &CreateTriggerStmt{Temp: temp}
	if p.isKW("IF") {
		p.next()
		p.expectKW("NOT")
		p.expectKW("EXISTS")
		st.IfNotExists = true
	}
	nameStart := p.peek().Pos
	st.Schema, st.Name = p.parseQualifiedName()
	if st.Schema != "" {
		nameStart = p.toks[p.p-1].Pos
	}
	if p.acceptKW("BEFORE") {
		st.Time = "BEFORE"
	} else if p.acceptKW("AFTER") {
		st.Time = "AFTER"
	} else if p.acceptKW("INSTEAD") {
		p.expectKW("OF")
		st.Time = "INSTEAD OF"
	} else {
		st.Time = "BEFORE"
	}
	t := p.next()
	if t.T != TKeyword {
		p.p--
		p.fail()
	}
	switch t.V {
	case "DELETE", "INSERT":
		st.Event = t.V
	case "UPDATE":
		st.Event = "UPDATE"
		if p.acceptKW("OF") {
			for {
				st.UpdateCols = append(st.UpdateCols, nameOf(p.parseNameTok()))
				if !p.acceptOp(",") {
					break
				}
			}
		}
	default:
		p.p--
		p.fail()
	}
	p.expectKW("ON")
	st.Table = nameOf(p.parseNameTok())
	if p.acceptOp(".") {
		st.Table = nameOf(p.parseNameTok())
	}
	if p.acceptKW("FOR") {
		p.expectKW("EACH")
		p.expectKW("ROW")
	}
	if p.acceptKW("WHEN") {
		st.When = p.parseExpr()
	}
	p.expectKW("BEGIN")
	for {
		if p.isKW("END") {
			break
		}
		s0 := p.peek().Pos
		var s Stmt
		tk := p.peek()
		if tk.T == TKeyword {
			switch tk.V {
			case "INSERT", "REPLACE":
				s = p.parseInsert()
			case "UPDATE":
				s = p.parseUpdate()
			case "DELETE":
				s = p.parseDelete()
			case "SELECT", "VALUES":
				s = &SelectStmt{Sel: p.parseSelect()}
			case "WITH":
				w := p.parseWith()
				if p.isKW("SELECT") || p.isKW("VALUES") {
					sel := p.parseSelect()
					sel.With = w
					s = &SelectStmt{Sel: sel}
				} else if p.isKW("INSERT") || p.isKW("REPLACE") {
					x := p.parseInsert()
					x.With = w
					s = x
				} else if p.isKW("UPDATE") {
					x := p.parseUpdate()
					x.With = w
					s = x
				} else if p.isKW("DELETE") {
					x := p.parseDelete()
					x.With = w
					s = x
				} else {
					p.fail()
				}
			default:
				p.fail()
			}
		} else {
			p.fail()
		}
		st.Body = append(st.Body, s)
		st.BodyText = append(st.BodyText, p.src[s0:p.stmtEndPos()])
		if p.peek().T != TSemi {
			p.fail()
		}
		p.next()
	}
	p.expectKW("END")
	st.SQL = "CREATE TRIGGER " + p.src[nameStart:p.stmtEndPos()]
	return st
}

func (p *Parser) parseDrop() *DropStmt {
	p.expectKW("DROP")
	t := p.next()
	if t.T != TKeyword || (t.V != "TABLE" && t.V != "INDEX" && t.V != "VIEW" && t.V != "TRIGGER") {
		p.p--
		p.fail()
	}
	st := &DropStmt{Kind: t.V}
	if p.isKW("IF") {
		p.next()
		p.expectKW("EXISTS")
		st.IfExists = true
	}
	st.Pos = p.peek().Pos
	st.Schema, st.Name = p.parseQualifiedName()
	return st
}

func (p *Parser) parseAlter() *AlterStmt {
	p.expectKW("ALTER")
	p.expectKW("TABLE")
	st := &AlterStmt{Pos: p.peek().Pos}
	st.Schema, st.Table = p.parseQualifiedName()
	if p.acceptKW("RENAME") {
		if p.acceptKW("TO") {
			st.Kind = "RENAME"
			st.NewName = nameOf(p.parseNameTok())
			return st
		}
		p.acceptKW("COLUMN")
		st.Kind = "RENAMECOL"
		st.ColPos = p.peek().Pos
		st.OldCol = nameOf(p.parseNameTok())
		p.expectKW("TO")
		st.NewName = nameOf(p.parseNameTok())
		return st
	}
	if p.acceptKW("ADD") {
		p.acceptKW("COLUMN")
		st.Kind = "ADD"
		s := p.peek().Pos
		st.Col = p.parseColumnDef()
		st.ColSQL = p.src[s:p.stmtEndPos()]
		return st
	}
	if p.acceptKW("DROP") {
		p.acceptKW("COLUMN")
		st.Kind = "DROP"
		st.ColPos = p.peek().Pos
		st.OldCol = nameOf(p.parseNameTok())
		return st
	}
	p.fail()
	return nil
}
