package main

import "fmt"

const (
	SQLITE_ERROR      = 1
	SQLITE_ABORT      = 4
	SQLITE_BUSY       = 5
	SQLITE_CONSTRAINT = 19
	SQLITE_MISMATCH   = 20
	SQLITE_RANGE      = 25
	SQLITE_TOOBIG     = 18
)

type SQLError struct {
	Msg  string
	Code int
	Pos  int
	// for RAISE(IGNORE)
	ignore bool
	// conflict resolution
	rollback bool
	fail     bool
}

func (e *SQLError) Error() string { return e.Msg }

func newErr(format string, args ...interface{}) *SQLError {
	return &SQLError{Msg: fmt.Sprintf(format, args...), Code: SQLITE_ERROR, Pos: -1}
}

func newErrPos(pos int, format string, args ...interface{}) *SQLError {
	return &SQLError{Msg: fmt.Sprintf(format, args...), Code: SQLITE_ERROR, Pos: pos}
}

func throw(format string, args ...interface{}) {
	panic(newErr(format, args...))
}

func throwPos(pos int, format string, args ...interface{}) {
	panic(newErrPos(pos, format, args...))
}

func constraintErr(msg string) *SQLError {
	return &SQLError{Msg: msg, Code: SQLITE_CONSTRAINT, Pos: -1}
}

// catch converts a panic carrying *SQLError into a returned error.
func catch(err *error) {
	if r := recover(); r != nil {
		if e, ok := r.(*SQLError); ok {
			*err = e
			return
		}
		if e, ok := r.(*ParseError); ok {
			*err = &SQLError{Msg: e.Msg, Code: SQLITE_ERROR, Pos: e.Pos}
			return
		}
		panic(r)
	}
}
