package main

import (
	"math"
	"strings"
	"unicode/utf8"
)

func isNumericAff(a Affinity) bool { return a >= AffNumeric }

func arith(op byte, a, b Value) Value {
	if a.K == KNull || b.K == KNull {
		return NullValue
	}
	x := a.Numeric()
	y := b.Numeric()
	if x.K == KInt && y.K == KInt {
		i, j := x.I, y.I
		switch op {
		case '+':
			r := i + j
			if (i >= 0) == (j >= 0) && (r >= 0) != (i >= 0) {
				return RealValue(float64(i) + float64(j))
			}
			return IntValue(r)
		case '-':
			r := i - j
			if (i >= 0) != (j >= 0) && (r >= 0) != (i >= 0) {
				return RealValue(float64(i) - float64(j))
			}
			return IntValue(r)
		case '*':
			if i == 0 || j == 0 {
				return IntValue(0)
			}
			r := i * j
			if r/j != i || (i == -1 && j == math.MinInt64) || (j == -1 && i == math.MinInt64) {
				return RealValue(float64(i) * float64(j))
			}
			return IntValue(r)
		case '/':
			if j == 0 {
				return NullValue
			}
			if i == math.MinInt64 && j == -1 {
				return RealValue(float64(i) / float64(j))
			}
			return IntValue(i / j)
		case '%':
			if j == 0 {
				return NullValue
			}
			if j == -1 {
				return IntValue(0)
			}
			return IntValue(i % j)
		}
	}
	f := x.Float()
	g := y.Float()
	switch op {
	case '+':
		return realResult(f + g)
	case '-':
		return realResult(f - g)
	case '*':
		return realResult(f * g)
	case '/':
		if g == 0 {
			return NullValue
		}
		return realResult(f / g)
	case '%':
		ia := floatToInt(f)
		ib := floatToInt(g)
		if ib == 0 {
			return NullValue
		}
		if ib == -1 {
			ib = 1
		}
		return RealValue(float64(ia % ib))
	}
	return NullValue
}

func realResult(f float64) Value {
	if math.IsNaN(f) {
		return NullValue
	}
	return RealValue(f)
}

func concatValues(a, b Value) Value {
	if a.K == KNull || b.K == KNull {
		return NullValue
	}
	return TextValue(a.Text() + b.Text())
}

func applyCmpAff(v Value, aff Affinity) Value {
	if isNumericAff(aff) {
		if v.K == KText {
			return applyNumericAffinityCmp(v)
		}
		return v
	}
	if aff == AffText {
		if v.K == KInt || v.K == KReal {
			return TextValue(v.Text())
		}
	}
	return v
}

// LIKE implementation
func likeMatch(pattern, str string, esc rune, noCase bool) bool {
	return patternMatch(pattern, str, esc, noCase, false)
}

func globMatch(pattern, str string) bool {
	return patternMatch(pattern, str, 0, false, true)
}

func foldRune(r rune, noCase bool) rune {
	if noCase && r < 128 {
		if r >= 'A' && r <= 'Z' {
			return r + 32
		}
	}
	return r
}

func patternMatch(pat, str string, esc rune, noCase, glob bool) bool {
	var matchAll, matchOne rune = '%', '_'
	if glob {
		matchAll, matchOne = '*', '?'
	}
	pi, si := 0, 0
	for pi < len(pat) {
		c, w := utf8.DecodeRuneInString(pat[pi:])
		pi += w
		if c == matchAll {
			// skip consecutive wildcards
			for pi < len(pat) {
				c2, w2 := utf8.DecodeRuneInString(pat[pi:])
