				return true
			}
			for si <= len(str) {
				if patternMatch(pat[pi:], str[si:], esc, noCase, glob) {
					return true
				}
				if si >= len(str) {
					break
				}
				_, sw := utf8.DecodeRuneInString(str[si:])
				si += sw
			}
