package main

import (
	"math"
	"strings"
	"unicode/utf8"
)

func isNumericAff(a Affinity) bool { return a >= AffNumeric }

func arith(op byte, a, b Value) Value {
	if a.K == KNull || b.K == KNull {
		return NullValue
	}
	x := a.Numeric()
	y := b.Numeric()
	if x.K == KInt && y.K == KInt {
		i, j := x.I, y.I
		switch op {
		case '+':
			r := i + j
			if (i >= 0) == (j >= 0) && (r >= 0) != (i >= 0) {
				return RealValue(float64(i) + float64(j))
			}
			return IntValue(r)
		case '-':
			r := i - j
			if (i >= 0) != (j >= 0) && (r >= 0) != (i >= 0) {
				return RealValue(float64(i) - float64(j))
			}
			return IntValue(r)
		case '*':
			if i == 0 || j == 0 {
				return IntValue(0)
			}
			r := i * j
			if r/j != i || (i == -1 && j == math.MinInt64) || (j == -1 && i == math.MinInt64) {
				return RealValue(float64(i) * float64(j))
			}
			return IntValue(r)
		case '/':
			if j == 0 {
				return NullValue
			}
			if i == math.MinInt64 && j == -1 {
				return RealValue(float64(i) / float64(j))
			}
			return IntValue(i / j)
		case '%':
			if j == 0 {
				return NullValue
			}
			if j == -1 {
				return IntValue(0)
			}
			return IntValue(i % j)
		}
	}
	f := x.Float()
	g := y.Float()
	switch op {
	case '+':
		return realResult(f + g)
	case '-':
		return realResult(f - g)
	case '*':
		return realResult(f * g)
	case '/':
		if g == 0 {
			return NullValue
		}
		return realResult(f / g)
	case '%':
		ia := floatToInt(f)
		ib := floatToInt(g)
		if ib == 0 {
			return NullValue
		}
		if ib == -1 {
			ib = 1
		}
		return RealValue(float64(ia % ib))
	}
	return NullValue
}

func realResult(f float64) Value {
	if math.IsNaN(f) {
		return NullValue
	}
	return RealValue(f)
}

func concatValues(a, b Value) Value {
	if a.K == KNull || b.K == KNull {
		return NullValue
	}
	return TextValue(a.Text() + b.Text())
}

func applyCmpAff(v Value, aff Affinity) Value {
	if isNumericAff(aff) {
		if v.K == KText {
			return applyNumericAffinityCmp(v)
		}
		return v
	}
	if aff == AffText {
		if v.K == KInt || v.K == KReal {
			return TextValue(v.Text())
		}
	}
	return v
}

// LIKE implementation
func likeMatch(pattern, str string, esc rune, noCase bool) bool {
	return patternMatch(pattern, str, esc, noCase, false)
}

func globMatch(pattern, str string) bool {
	return patternMatch(pattern, str, 0, false, true)
}

func foldRune(r rune, noCase bool) rune {
	if noCase && r < 128 {
		if r >= 'A' && r <= 'Z' {
			return r + 32
		}
	}
	return r
}

func patternMatch(pat, str string, esc rune, noCase, glob bool) bool {
	var matchAll, matchOne rune = '%', '_'
	if glob {
		matchAll, matchOne = '*', '?'
	}
	pi, si := 0, 0
	for pi < len(pat) {
		c, w := utf8.DecodeRuneInString(pat[pi:])
		pi += w
		if c == matchAll {
			// skip consecutive wildcards
			for pi < len(pat) {
				c2, w2 := utf8.DecodeRuneInString(pat[pi:])
				if c2 == matchAll {
					pi += w2
				} else if c2 == matchOne {
					if si >= len(str) {
						return false
					}
					_, sw := utf8.DecodeRuneInString(str[si:])
					si += sw
					pi += w2
				} else {
					break
				}
			}
			if pi >= len(pat) {
				return true
			}
			for si <= len(str) {
				if patternMatch(pat[pi:], str[si:], esc, noCase, glob) {
					return true
				}
				if si >= len(str) {
					break
				}
				_, sw := utf8.DecodeRuneInString(str[si:])
				si += sw
			}
			return false
		}
		if c == matchOne {
			if si >= len(str) {
				return false
			}
			_, sw := utf8.DecodeRuneInString(str[si:])
			si += sw
			continue
		}
		if glob && c == '[' {
			if si >= len(str) {
				return false
			}
			sc, sw := utf8.DecodeRuneInString(str[si:])
			si += sw
			invert := false
			seen := false
			if pi < len(pat) && pat[pi] == '^' {
				invert = true
				pi++
			}
			if pi < len(pat) && pat[pi] == ']' {
				if sc == ']' {
					seen = true
				}
				pi++
			}
			var prev rune = -1
			closed := false
			for pi < len(pat) {
				pc, pw := utf8.DecodeRuneInString(pat[pi:])
				if pc == ']' {
					pi += pw
					closed = true
					break
				}
				if pc == '-' && prev >= 0 && pi+pw < len(pat) && pat[pi+pw] != ']' {
					pi += pw
					hi, hw := utf8.DecodeRuneInString(pat[pi:])
					pi += hw
					if sc >= prev && sc <= hi {
						seen = true
					}
					prev = -1
					continue
				}
				if pc == sc {
					seen = true
				}
				prev = pc
				pi += pw
			}
			if !closed {
				return false
			}
			if seen == invert {
				return false
			}
			continue
		}
		if !glob && esc != 0 && c == esc {
			if pi >= len(pat) {
				return false
			}
			c, w = utf8.DecodeRuneInString(pat[pi:])
			pi += w
		}
		if si >= len(str) {
			return false
		}
		sc, sw := utf8.DecodeRuneInString(str[si:])
		si += sw
		if foldRune(c, noCase) != foldRune(sc, noCase) {
			return false
		}
	}
	return si >= len(str)
}

func boolOf(v Value) (bool, bool) { // value, isNull
	if v.K == KNull {
		return false, true
	}
	return v.Bool(), false
}

func lowerASCII(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] >= 'A' && s[i] <= 'Z' {
			return strings.Map(func(r rune) rune {
				if r >= 'A' && r <= 'Z' {
					return r + 32
				}
				return r
			}, s)
		}
	}
	return s
}

func upperASCII(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] >= 'a' && s[i] <= 'z' {
			return strings.Map(func(r rune) rune {
				if r >= 'a' && r <= 'z' {
					return r - 32
				}
				return r
			}, s)
		}
	}
	return s
}
