{"command":"cd /workspace/src && cat > expr.go <<'EOF'
package main

import (
	"strconv"
	"strings"
)

type evalFn func(c *Ctx) Value

type Ctx struct {
	conn    *Conn
	rows    [][]Value
	rowids  []int64
	parent  *Ctx
	aggVals []Value
	winVals []Value
}

type cexpr struct {
	fn           evalFn
	aff          Affinity
	hasAff       bool
	coll         string
	explicitColl bool
	isConst      bool
	val          Value
	isColumn     bool
	srcIdx       int
	colIdx       int
	depth        int
	nCols        int // for vectors/subqueries
	sub          []cexpr
}

type srcInfo struct {
	name      string
	cols      []string
	aff       []Affinity
	hasAff    []bool
	coll      []string
	table     *Table
	hasRowid  bool
	idx       int
	hiddenCol []bool // hidden from * and unqualified lookups (USING right side)
	usingCol  map[string]bool
	joinType  JoinType
	isTrigger bool
	colExpr   []*Expr
}

type level struct {
	aggs       []*aggCall
	wins       []*winCall
	allowAgg   bool
	allowWin   bool
	inAgg      bool
	aliases    []*ResultCol
	aliasBusy  map[int]bool
	correlated bool
	aggRefDepth int
	sel        *Select
	windows    []*WindowDef
	hasMinMax  int
	minmaxAgg  *aggCall
	orderByMode bool
}

type scope struct {
	srcs   []*srcInfo
	parent *scope
	lvl    *level
	ctes   *cteScope
}

type compiler struct {
	conn *Conn
}

func constExpr(v Value) cexpr {
	return cexpr{fn: func(c *Ctx) Value { return v }, isConst: true, val: v}
}

func (cp *compiler) compileExpr(e *Expr, sc *scope) cexpr {
	switch e.Op {
	case ELit:
		return constExpr(e.Val)
	case EParam:
		name := e.Name
		conn := cp.conn
		if name == "?" {
			conn.paramCounter++
			name = "?" + strconv.Itoa(conn.paramCounter)
		} else if strings.HasPrefix(name, "?") {
			n, _ := strconv.Atoi(name[1:])
			if n > conn.paramCounter {
				conn.paramCounter = n
			}
		}
		return cexpr{fn: func(c *Ctx) Value {
			if v, ok := c.conn.params[name]; ok {
				return v
			}
			return NullValue
		}}
	case EColumn:
		return cp.compileColumn(e, sc)
	case EUnary:
		return cp.compileUnary(e, sc)
	case EBinary:
		return cp.compileBinary(e, sc)
	case ECollate:
		x := cp.compileExpr(e.L, sc)
		if getCollation(e.Name) == nil {
			throwPos(e.Pos, "no such collation sequence: %s", e.Name)
		}
		x.coll = strings.ToUpper(e.Name)
		if x.coll == "BINARY" {
			x.coll = ""
		}
		x.explicitColl = true
		x.isConst = false
		return x
	case ECast:
		return cp.compileCast(e, sc)
	case EIsNull:
		x := cp.compileExpr(e.L, sc)
		not := e.Not
		f := x.fn
		return cexpr{fn: func(c *Ctx) Value {
			v := f(c)
			return BoolValue((v.K == KNull) != not)
		}}
	case EBetween:
		return cp.compileBetween(e, sc)
	case ELike:
		return cp.compileLike(e, sc)
	case EIn:
		return cp.compileIn(e, sc)
	case ECase:
		return cp.compileCase(e, sc)
	case EFunc:
		return cp.compileFunc(e, sc)
	case ESubquery:
		return cp.compileScalarSubquery(e, sc)
	case EExists:
		return cp.compileExists(e, sc)
	case EVector:
		subs := make([]cexpr, len(e.List))
		for i, x := range e.List {
			subs[i] = cp.compileExpr(x, sc)
		}
		return cexpr{fn: func(c *Ctx) Value {
			throw("row value misused")
			return NullValue
		}, nCols: len(subs), sub: subs}
	case ERaise:
		return cp.compileRaise(e, sc)
	}
	throw("unsupported expression")
	return cexpr{}
}

func (cp *compiler) compileRaise(e *Expr, sc *scope) cexpr {
	kind := e.Name
	var msg cexpr
	if e.L != nil {
		msg = cp.compileExpr(e.L, sc)
	}
	if !cp.conn.inTriggerCompile {
		throwPos(e.Pos, "RAISE() may only be used within a trigger-program")
	}
	return cexpr{fn: func(c *Ctx) Value {
		if kind == "IGNORE" {
			panic(&SQLError{Msg: "", ignore: true, Pos: -1})
		}
		m := msg.fn(c).Text()
		err := &SQLError{Msg: m, Code: SQLITE_CONSTRAINT, Pos: -1}
		if kind == "ROLLBACK" {
			err.rollback = true
		} else if kind == "FAIL" {
			err.fail = true
		}
		panic(err)
	}}
}

func isRowidName(n string) bool {
	l := strings.ToLower(n)
	return l == "rowid" || l == "oid" || l == "_rowid_"
}

func (cp *compiler) compileColumn(e *Expr, sc *scope) cexpr {
	depth := 0
	for s := sc; s != nil; s = s.parent {
		r, ok := cp.lookupInScope(e, s, depth)
		if ok {
			if depth > 0 {
				for t := sc; t != nil && t != s; t = t.parent {
					if t.lvl != nil {
						t.lvl.correlated = true
					}
				}
			}
			return r
		}
		// alias lookup (only unqualified, current level only)
		if e.Table == "" && s.lvl != nil && s.lvl.aliases != nil {
			for i, rc := range s.lvl.aliases {
				if rc.Alias != "" && strings.EqualFold(rc.Alias, e.Column) && rc.E != nil {
					if s.lvl.aliasBusy == nil {
						s.lvl.aliasBusy = map[int]bool{}
					}
					if s.lvl.aliasBusy[i] {
						continue
					}
					s.lvl.aliasBusy[i] = true
					x := cp.compileExpr(rc.E, s)
					delete(s.lvl.aliasBusy, i)
					if depth > 0 {
						for t := sc; t != nil && t != s; t = t.parent {
							if t.lvl != nil {
								t.lvl.correlated = true
							}
						}
						// evaluate in parent ctx
						f := x.fn
						d := depth
						x.fn = func(c *Ctx) Value {
							for k := 0; k < d; k++ {
								c = c.parent
							}
							return f(c)
						}
					}
					return x
				}
			}
		}
		depth++
	}
	name := e.Column
	if e.Table != "" {
		name = e.Table + "." + e.Column
		if e.Schema != "" {
			name = e.Schema + "." + name
		}
	}
	if e.ColQuot && e.Table == "" {
		throwPos(e.Pos, "no such column: \"%s\" - should this be a string literal in single-quotes?", e.Column)
	}
	throwPos(e.Pos, "no such column: %s", name)
	return cexpr{}
}

func makeColReader(depth, srcIdx, colIdx int) evalFn {
	if depth == 0 {
		return func(c *Ctx) Value {
			r := c.rows[srcIdx]
			if r == nil {
				return NullValue
			}
			return r[colIdx]
		}
	}
	return func(c *Ctx) Value {
		for i := 0; i < depth; i++ {
			c = c.parent
		}
		r := c.rows[srcIdx]
		if r == nil {
			return NullValue
		}
		return r[colIdx]
	}
}

func makeRowidReader(depth, srcIdx int) evalFn {
	return func(c *Ctx) Value {
		for i := 0; i < depth; i++ {
			c = c.parent
		}
		if c.rows[srcIdx] == nil {
			return NullValue
		}
		return IntValue(c.rowids[srcIdx])
	}
}

func (cp *compiler) lookupInScope(e *Expr, s *scope, depth int) (cexpr, bool) {
	var found *srcInfo
	foundCol := -1
	isRowid := false
	count := 0
	for _, src := range s.srcs {
		if e.Table != "" {
			if !strings.EqualFold(src.name, e.Table) {
				continue
			}
			if e.Schema != "" && src.table != nil && src.table.Schema != nil && !strings.EqualFold(src.table.Schema.Name, e.Schema) {
				continue
			}
		}
		ci := -1
		for i, cn := range src.cols {
			if strings.EqualFold(cn, e.Column) {
				if e.Table == "" && src.hiddenCol != nil && src.hiddenCol[i] {
					continue
				}
				ci = i
				break
			}
		}
		if ci >= 0 {
			if found != nil && e.Table == "" {
				// USING columns are not ambiguous
				if src.usingCol != nil && src.usingCol[strings.ToLower(e.Column)] {
					continue
				}
				count++
				continue
			}
			if found == nil {
				found = src
				foundCol = ci
				count = 1
			}
			continue
		}
		if src.hasRowid && isRowidName(e.Column) && found == nil {
			found = src
			isRowid = true
			count = 1
		}
	}
	if found == nil {
		return cexpr{}, false
	}
	if count > 1 {
		name := e.Column
		if e.Table != "" {
			name = e.Table + "." + e.Column
		}
		throwPos(e.Pos, "ambiguous column name: %s", name)
	}
	if isRowid {
		return cexpr{fn: makeRowidReader(depth, found.idx), aff: AffInteger, hasAff: true, isColumn: true, srcIdx: found.idx, colIdx: -1, depth: depth}, true
	}
	r := cexpr{fn: makeColReader(depth, found.idx, foundCol), isColumn: true, srcIdx: found.idx, colIdx: foundCol, depth: depth}
	if found.aff != nil {
		r.aff = found.aff[foundCol]
		r.hasAff = found.hasAff == nil || found.hasAff[foundCol]
	}
	if found.coll != nil {
		r.coll = found.coll[foundCol]
	}
	if s.lvl != nil && s.lvl.inAgg && depth > 0 {
		// reference to outer column inside aggregate
	}
	return r, true
}

func (cp *compiler) compileUnary(e *Expr, sc *scope) cexpr {
	x := cp.compileExpr(e.L, sc)
	f := x.fn
	var r cexpr
	switch e.Name {
	case "-":
		r.fn = func(c *Ctx) Value {
			v := f(c)
			switch v.K {
			case KNull:
				return v
			case KInt:
				if v.I == -9223372036854775808 {
					return RealValue(9223372036854775808.0)
				}
				return IntValue(-v.I)
			case KReal:
				return RealValue(-v.F)
			}
			n := v.Numeric()
			if n.K == KInt {
				if n.I == -9223372036854775808 {
					return RealValue(9223372036854775808.0)
				}
				return IntValue(-n.I)
			}
			return RealValue(-n.F)
		}
	case "+":
		x.isConst = false
		return x
	case "~":
		r.fn = func(c *Ctx) Value {
			v := f(c)
			if v.K == KNull {
				return v
			}
			return IntValue(^v.Numeric().Int())
		}
	case "NOT":
		r.fn = func(c *Ctx) Value {
			v := f(c)
			if v.K == KNull {
				return v
			}
			return BoolValue(!v.Bool())
		}
	}
	if x.isConst {
		v := r.fn(nil)
		return constExpr(v)
	}
	return r
}

func cmpCollation(a, b cexpr) string {
	if a.explicitColl {
		return a.coll
	}
	if b.explicitColl {
		return b.coll
	}
	if a.coll != "" {
		return a.coll
	}
	return b.coll
}

func cmpAffinity(a, b cexpr) Affinity {
	if a.hasAff && b.hasAff {
		if isNumericAff(a.aff) || isNumericAff(b.aff) {
			return AffNumeric
		}
		return AffNone
	}
	if a.hasAff {
		return a.aff
	}
	if b.hasAff {
		return b.aff
	}
	return AffNone
}

func (cp *compiler) compileBinary(e *Expr, sc *scope) cexpr {
	op := e.Name
	if e.L.Op == EVector || e.R.Op == EVector || (e.L.Op == ESubquery && cp.subqueryCols(e.L, sc) > 1) {
		return cp.compileVectorCompare(e, sc)
	}
	l := cp.compileExpr(e.L, sc)
	r := cp.compileExpr(e.R, sc)
	if r.nCols > 1 || l.nCols > 1 {
		throwPos(e.Pos, "row value misused")
	}
	lf, rf := l.fn, r.fn
	var res cexpr
	switch op {
	case "+", "-", "*", "/", "%":
		o := op[0]
		res.fn = func(c *Ctx) Value { return arith(o, lf(c), rf(c)) }
	case "||":
		res.fn = func(c *Ctx) Value { return concatValues(lf(c), rf(c)) }
	case "AND":
		res.fn = func(c *Ctx) Value {
			a := lf(c)
			if a.K != KNull && !a.Bool() {
				return IntValue(0)
			}
			b := rf(c)
			if b.K != KNull && !b.Bool() {
				return IntValue(0)
			}
			if a.K == KNull || b.K == KNull {
				return NullValue
			}
			return IntValue(1)
		}
	case "OR":
		res.fn = func(c *Ctx) Value {
			a := lf(c)
			if a.K != KNull && a.Bool() {
				return IntValue(1)
			}
			b := rf(c)
			if b.K != KNull && b.Bool() {
				return IntValue(1)
			}
			if a.K == KNull || b.K == KNull {
				return NullValue
			}
			return IntValue(0)
		}
	case "=", "!=", "<", "<=", ">", ">=", "IS", "IS NOT":
		aff := cmpAffinity(l, r)
		coll := getCollation(cmpCollation(l, r))
		isIs := op == "IS" || op == "IS NOT"
		test := cmpTest(op)
		res.fn = func(c *Ctx) Value {
			a := lf(c)
			b := rf(c)
			if a.K == KNull || b.K == KNull {
				if isIs {
					eq := a.K == KNull && b.K == KNull
					if op == "IS" {
						return BoolValue(eq)
					}
					return BoolValue(!eq)
				}
				return NullValue
			}
			if aff != AffNone {
				a = applyCmpAff(a, aff)
				b = applyCmpAff(b, aff)
			}
			return BoolValue(test(compareValues(a, b, coll)))
		}
	case "&", "|", "<<", ">>":
		res.fn = func(c *Ctx) Value {
			a := lf(c)
			b := rf(c)
			if a.K == KNull || b.K == KNull {
				return NullValue
			}
			x := a.Numeric().Int()
			y := b.Numeric().Int()
			switch op {
			case "&":
				return IntValue(x & y)
			case "|":
				return IntValue(x | y)
			case "<<":
				return IntValue(shiftLeft(x, y))
			default:
				return IntValue(shiftLeft(x, -y))
			}
		}
	case "->", "->>":
		isText := op == "->>"
		res.fn = func(c *Ctx) Value {
			return jsonArrow(lf(c), rf(c), isText)
		}
	default:
		throw("unknown operator %s", op)
	}
	if l.isConst && r.isConst {
		v := res.fn(nil)
		return constExpr(v)
	}
	return res
}

func shiftLeft(x, y int64) int64 {
	if y >= 64 {
		return 0
	}
	if y <= -64 {
		if x < 0 {
			return -1
		}
		return 0
	}
	if y >= 0 {
		return x << uint(y)
	}
	return x >> uint(-y)
}

func cmpTest(op string) func(int) bool {
	switch op {
	case "=", "IS":
		return func(c int) bool { return c == 0 }
	case "!=", "IS NOT":
		return func(c int) bool { return c != 0 }
	case "<":
		return func(c int) bool { return c < 0 }
	case "<=":
		return func(c int) bool { return c <= 0 }
	case ">":
		return func(c int) bool { return c > 0 }
	case ">=":
		return func(c int) bool { return c >= 0 }
	}
	return nil
}

func (cp *compiler) subqueryCols(e *Expr, sc *scope) int {
	if e.Op != ESubquery {
		return 1
	}
	n := countSelectCols(cp, e.Sel, sc)
	return n
}

func (cp *compiler) vectorParts(e *Expr, sc *scope) ([]cexpr, func(c *Ctx) []Value) {
	if e.Op == EVector {
		parts := make([]cexpr, len(e.List))
		for i, x := range e.List {
			parts[i] = cp.compileExpr(x, sc)
			if parts[i].nCols > 1 {
				throwPos(x.Pos, "row value misused")
			}
		}
		return parts, func(c *Ctx) []Value {
			vals := make([]Value, len(parts))
			for i, p := range parts {
				vals[i] = p.fn(c)
			}
			return vals
		}
	}
	if e.Op == ESubquery {
		cs := cp.compileSubSelect(e.Sel, sc)
		n := len(cs.colNames)
		parts := make([]cexpr, n)
		for i := range parts {
			parts[i] = cexpr{aff: cs.colAff[i], hasAff: cs.colHasAff[i], coll: cs.colColl[i]}
		}
		return parts, func(c *Ctx) []Value {
			var res []Value
			cs.run(c, func(row []Value) bool {
				res = append([]Value(nil), row...)
				return false
			})
			if res == nil {
				res = make([]Value, n)
			}
			return res
		}
	}
	x := cp.compileExpr(e, sc)
	return []cexpr{x}, func(c *Ctx) []Value { return []Value{x.fn(c)} }
}

func (cp *compiler) compileVectorCompare(e *Expr, sc *scope) cexpr {
	op := e.Name
	lp, lf := cp.vectorParts(e.L, sc)
	rp, rf := cp.vectorParts(e.R, sc)
	if len(lp) != len(rp) {
		throwPos(e.Pos, "row value misused")
	}
	n := len(lp)
	affs := make([]Affinity, n)
	colls := make([]Collation, n)
	for i := 0; i < n; i++ {
		affs[i] = cmpAffinity(lp[i], rp[i])
		colls[i] = getCollation(cmpCollation(lp[i], rp[i]))
	}
	switch op {
	case "=", "!=", "IS", "IS NOT", "<", "<=", ">", ">=":
	default:
		throwPos(e.Pos, "row value misused")
	}
	return cexpr{fn: func(c *Ctx) Value {
		a := lf(c)
		b := rf(c)
		switch op {
		case "=", "!=", "IS", "IS NOT":
			hasNull := false
			for i := 0; i < n; i++ {
				x, y := a[i], b[i]
				if x.K == KNull || y.K == KNull {
					if op == "IS" || op == "IS NOT" {
						if (x.K == KNull) != (y.K == KNull) {
							return BoolValue(op == "IS NOT")
						}
						continue
					}
					hasNull = true
					continue
				}
				x = applyCmpAff(x, affs[i])
				y = applyCmpAff(y, affs[i])
				if compareValues(x, y, colls[i]) != 0 {
					return BoolValue(op == "!=" || op == "IS NOT")
				}
			}
			if hasNull {
				return NullValue
			}
			return BoolValue(op == "=" || op == "IS")
		default:
			for i := 0; i < n; i++ {
				x, y := a[i], b[i]
				if x.K == KNull || y.K == KNull {
					return NullValue
				}
				x = applyCmpAff(x, affs[i])
				y = applyCmpAff(y, affs[i])
				cmp := compareValues(x, y, colls[i])
				if cmp != 0 {
					return BoolValue(cmpTest(op)(cmp))
				}
			}
			return BoolValue(op == "<=" || op == ">=")
		}
	}}
}

func castAffinity(typ string) Affinity {
	return affinityOfType(typ)
}

func castValue(v Value, typ string) Value {
	if v.K == KNull {
		return v
	}
	aff := castAffinity(typ)
	switch aff {
	case AffText:
		if v.K == KText {
			return v
		}
		return TextValue(v.Text())
	case AffNone:
		if v.K == KBlob {
			return v
		}
		return BlobValue(v.Text())
	case AffInteger:
		switch v.K {
		case KInt:
			return v
		case KReal:
			return IntValue(floatToInt(v.F))
		default:
			return IntValue(castTextToInt(v.S))
		}
	case AffReal:
		switch v.K {
		case KReal:
			return v
		case KInt:
			return RealValue(float64(v.I))
		default:
			p := parseNumber(v.S)
			if !p.ok {
				return RealValue(0)
			}
			return RealValue(p.f)
		}
	case AffNumeric:
		switch v.K {
		case KInt, KReal:
			return v
		default:
			return castTextToNumeric(v.S)
		}
	}
	return v
}

func castTextToInt(s string) int64 {
	return atoiPrefix(s)
}

func castTextToNumeric(s string) Value {
	p := parseNumber(s)
	if !p.ok {
		return IntValue(0)
	}
	if p.isInt {
		if p.intOK {
			return IntValue(p.i)
		}
		return RealValue(p.f)
	}
	f := p.f
	if f == float64(int64(f)) && f > -9.2233720368547758e18 && f < 9.2233720368547758e18 {
		return IntValue(int64(f))
	}
	return RealValue(f)
}

func (cp *compiler) compileCast(e *Expr, sc *scope) cexpr {
	x := cp.compileExpr(e.L, sc)
	typ := e.Name
	f := x.fn
	r := cexpr{fn: func(c *Ctx) Value { return castValue(f(c), typ) }, aff: castAffinity(typ), hasAff: true, coll: x.coll, explicitColl: x.explicitColl}
	if x.isConst {
		v := r.fn(nil)
		r2 := constExpr(v)
		r2.aff = r.aff
		r2.hasAff = true
		r2.isConst = false
		return r2
	}
	return r
}

func (cp *compiler) compileBetween(e *Expr, sc *scope) cexpr {
	x := cp.compileExpr(e.L, sc)
	lo := cp.compileExpr(e.List[0], sc)
	hi := cp.compileExpr(e.List[1], sc)
	aff1 := cmpAffinity(x, lo)
	aff2 := cmpAffinity(x, hi)
	coll1 := getCollation(cmpCollation(x, lo))
	coll2 := getCollation(cmpCollation(x, hi))
	not := e.Not
	xf, lf, hf := x.fn, lo.fn, hi.fn
	return cexpr{fn: func(c *Ctx) Value {
		v := xf(c)
		a := lf(c)
		b := hf(c)
		// v >= a
		var r1, r2 Value
		if v.K == KNull || a.K == KNull {
			r1 = NullValue
		} else {
			r1 = BoolValue(compareValues(applyCmpAff(v, aff1), applyCmpAff(a, aff1), coll1) >= 0)
		}
		if v.K == KNull || b.K == KNull {
			r2 = NullValue
		} else {
			r2 = BoolValue(compareValues(applyCmpAff(v, aff2), applyCmpAff(b, aff2), coll2) <= 0)
		}
		var res Value
		if (r1.K != KNull && !r1.Bool()) || (r2.K != KNull && !r2.Bool()) {
			res = IntValue(0)
		} else if r1.K == KNull || r2.K == KNull {
			res = NullValue
		} else {
			res = IntValue(1)
		}
		if not && res.K != KNull {
			return BoolValue(!res.Bool())
		}
		return res
	}}
}

func (cp *compiler) compileLike(e *Expr, sc *scope) cexpr {
	x := cp.compileExpr(e.L, sc)
	pat := cp.compileExpr(e.R, sc)
	var esc *cexpr
	if e.Escape != nil {
		t := cp.compileExpr(e.Escape, sc)
		esc = &t
	}
	not := e.Not
	kind := e.Name
	xf, pf := x.fn, pat.fn
	// user can override like() via function; we just implement builtins
	return cexpr{fn: func(c *Ctx) Value {
		s := xf(c)
		p := pf(c)
		var r Value
		switch kind {
		case "LIKE":
			var escR rune
			if esc != nil {
				ev := esc.fn(c)
				if ev.K == KNull {
					return NullValue
				}
				es := ev.Text()
				if utf8Len(es) != 1 {
					throw("ESCAPE expression must be a single character")
				}
				escR = []rune(es)[0]
			}
			if s.K == KNull || p.K == KNull {
				return NullValue
			}
			r = BoolValue(likeMatch(p.Text(), s.Text(), escR, !c.conn.caseSensitiveLike))
		case "GLOB":
			if s.K == KNull || p.K == KNull {
				return NullValue
			}
			r = BoolValue(globMatch(p.Text(), s.Text()))
		case "REGEXP":
			if s.K == KNull || p.K == KNull {
				return NullValue
			}
			r = regexpMatch(p.Text(), s.Text())
		default:
			throw("unable to use function MATCH in the requested context")
		}
		if not && r.K != KNull {
			return BoolValue(!r.Bool())
		}
		return r
	}}
}

func (cp *compiler) compileCase(e *Expr, sc *scope) cexpr {
	var base *cexpr
	if e.L != nil {
		b := cp.compileExpr(e.L, sc)
		base = &b
	}
	n := len(e.List) / 2
	whens := make([]cexpr, n)
	thens := make([]cexpr, n)
	for i := 0; i < n; i++ {
		whens[i] = cp.compileExpr(e.List[2*i], sc)
		thens[i] = cp.compileExpr(e.List[2*i+1], sc)
	}
	var els *cexpr
	if e.R != nil {
		x := cp.compileExpr(e.R, sc)
		els = &x
	}
	var colls []Collation
	var affs []Affinity
	if base != nil {
		colls = make([]Collation, n)
		affs = make([]Affinity, n)
		for i := 0; i < n; i++ {
			colls[i] = getCollation(cmpCollation(*base, whens[i]))
			affs[i] = cmpAffinity(*base, whens[i])
		}
	}
	return cexpr{fn: func(c *Ctx) Value {
		if base != nil {
			bv := base.fn(c)
			for i := 0; i < n; i++ {
				w := whens[i].fn(c)
				if bv.K == KNull || w.K == KNull {
					continue
				}
				if compareValues(applyCmpAff(bv, affs[i]), applyCmpAff(w, affs[i]), colls[i]) == 0 {
					return thens[i].fn(c)
				}
			}
		} else {
			for i := 0; i < n; i++ {
				w := whens[i].fn(c)
				if w.K != KNull && w.Bool() {
					return thens[i].fn(c)
				}
			}
		}
		if els != nil {
			return els.fn(c)
		}
		return NullValue
	}}
}
EOF
echo ok"}

