// valueKey produces a hashable key respecting equality semantics and collation
func appendValueKey(b []byte, v Value, coll string) []byte {
	switch v.K {
	case KNull:
		return append(b, 'n')
	case KInt:
		b = append(b, 'i')
		return binary.BigEndian.AppendUint64(b, uint64(v.I))
	case KReal:
		f := v.F
		if f == math.Trunc(f) && f >= -9.2233720368547758e18 && f < 9.2233720368547758e18 {
