	collName := cmpCollation(x, rhs)
	type inSet struct {
		set     map[string]bool
		hasNull bool
		empty   bool
	}
	var cached *inSet
	var cacheGen int64 = -1
	build := func(c *Ctx) *inSet {
		s := &inSet{set: map[string]bool{}, empty: true}
		cs.run(c, func(row []Value) bool {
			s.empty = false
			v := row[0]
			if v.K == KNull {
				s.hasNull = true
				return true
			}
			v = applyCmpAff(v, aff)
			s.set[string(appendValueKey(nil, v, collName))] = true
			return true
		})
		return s
	}
	return cexpr{fn: func(c *Ctx) Value {
		var s *inSet
		if !cs.correlated {
			if cacheGen != c.conn.stmtGen || cached == nil {
				cached = build(c)
				cacheGen = c.conn.stmtGen
			}
			s = cached
		} else {
			s = build(c)
		}
		if s.empty {
			return BoolValue(not)
		}
		v := xf(c)
		if v.K == KNull {
			return NullValue
		}
