func (cp *compiler) compileVectorIn(e *Expr, sc *scope) cexpr {
	lp, lf := cp.vectorParts(e.L, sc)
	n := len(lp)
	not := e.Not
	if e.Sel == nil {
		// list of vectors
		var rows [][]cexpr
		for _, it := range e.List {
			if it.Op != EVector || len(it.List) != n {
				throwPos(e.Pos, "row value misused")
			}
			var r []cexpr
			for _, x := range it.List {
				r = append(r, cp.compileExpr(x, sc))
			}
			rows = append(rows, r)
		}
		return cexpr{fn: func(c *Ctx) Value {
			a := lf(c)
			sawNull := false
			for _, r := range rows {
				match := true
				null := false
				for i := 0; i < n; i++ {
					w := r[i].fn(c)
					if a[i].K == KNull || w.K == KNull {
						null = true
						continue
					}
					aff := cmpAffinity(lp[i], r[i])
					if compareValues(applyCmpAff(a[i], aff), applyCmpAff(w, aff), getCollation(cmpCollation(lp[i], r[i]))) != 0 {
						match = false
						break
					}
				}
				if match && !null {
					return BoolValue(!not)
				}
				if match && null {
					sawNull = true
				}
			}
			if sawNull {
				return NullValue
			}
			return BoolValue(not)
		}}
	}
	cs := cp.compileSubSelect(e.Sel, sc)
	if len(cs.colNames) != n {
		throwPos(e.Pos, "sub-select returns %d columns - expected %d", len(cs.colNames), n)
	}
	affs := make([]Affinity, n)
	colls := make([]string, n)
	for i := 0; i < n; i++ {
		rhs := cexpr{aff: cs.colAff[i], hasAff: cs.colHasAff[i], coll: cs.colColl[i]}
		affs[i] = cmpAffinity(lp[i], rhs)
		colls[i] = cmpCollation(lp[i], rhs)
	}
	return cexpr{fn: func(c *Ctx) Value {
		a := lf(c)
		found := false
		sawNull := false
		cs.run(c, func(row []Value) bool {
			match := true
			null := false
			for i := 0; i < n; i++ {
				if a[i].K == KNull || row[i].K == KNull {
					null = true
					continue
				}
				if compareValues(applyCmpAff(a[i], affs[i]), applyCmpAff(row[i], affs[i]), getCollation(colls[i])) != 0 {
					match = false
					break
				}
			}
			if match && !null {
				found = true
				return false
			}
			if match && null {
				sawNull = true
			}
			return true
		})
		if found {
			return BoolValue(!not)
		}
		if sawNull {
			return NullValue
		}
		return BoolValue(not)
	}}
}

func (cp *compiler) compileScalarSubquery(e *Expr, sc *scope) cexpr {
	cs := cp.compileSubSelect(e.Sel, sc)
	n := len(cs.colNames)
	var cached Value
	var cacheGen int64 = -1
	f := func(c *Ctx) Value {
		if !cs.correlated && cacheGen == c.conn.stmtGen {
			return cached
		}
		res := NullValue
		cs.run(c, func(row []Value) bool {
			res = row[0]
			return false
		})
		if !cs.correlated {
			cached = res
			cacheGen = c.conn.stmtGen
		}
		return res
	}
	r := cexpr{fn: f, nCols: n}
	if n >= 1 {
		r.aff = cs.colAff[0]
		r.hasAff = cs.colHasAff[0]
		r.coll = cs.colColl[0]
	}
	return r
}

func (cp *compiler) compileExists(e *Expr, sc *scope) cexpr {
	cs := cp.compileSubSelect(e.Sel, sc)
	var cached Value
	var cacheGen int64 = -1
	return cexpr{fn: func(c *Ctx) Value {
		if !cs.correlated && cacheGen == c.conn.stmtGen {
			return cached
		}
		found := false
		cs.run(c, func(row []Value) bool {
			found = true
			return false
		})
		r := BoolValue(found)
		if !cs.correlated {
			cached = r
			cacheGen = c.conn.stmtGen
		}
		return r
	}}
}
