// valueKey produces a hashable key respecting equality semantics and collation
func appendValueKey(b []byte, v Value, coll string) []byte {
	switch v.K {
	case KNull:
		return append(b, 'n')
	case KInt:
		b = append(b, 'i')
		return binary.BigEndian.AppendUint64(b, uint64(v.I))
	case KReal:
		f := v.F
		if f == math.Trunc(f) && f >= -9.2233720368547758e18 && f < 9.2233720368547758e18 {
			b = append(b, 'i')
			return binary.BigEndian.AppendUint64(b, uint64(int64(f)))
		}
		b = append(b, 'r')
		return binary.BigEndian.AppendUint64(b, math.Float64bits(f))
	case KText:
		s := v.S
		switch coll {
		case "NOCASE":
			s = lowerASCII(s)
		case "RTRIM":
			s = strings.TrimRight(s, " ")
		}
		b = append(b, 't')
		b = binary.BigEndian.AppendUint32(b, uint32(len(s)))
		return append(b, s...)
	case KBlob:
		b = append(b, 'b')
		b = binary.BigEndian.AppendUint32(b, uint32(len(v.S)))
		return append(b, v.S...)
	}
	return b
}

