package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

type compiledSelect struct {
	colNames    []string
	colAff      []Affinity
	colHasAff   []bool
	colColl     []string
	colDeclType []string
	colOrigin   []*colOrigin
	run         func(parent *Ctx, emit func([]Value) bool) bool
	correlated  bool
}

type colOrigin struct {
	table *Table
	col   int
}

type cteDef struct {
	cte        *CTE
	scope      *scope
	ctes       *cteScope
	compiled   *compiledSelect
	compiling  bool
	recursive  bool
	recCurrent [][]Value
	cache      [][]Value
	cacheGen   int64
	recNames   []string
	recAff     []Affinity
	recHasAff  []bool
	recColl    []string
}

type cteScope struct {
	defs   map[string]*cteDef
	parent *cteScope
}

func (cs *cteScope) find(name string) *cteDef {
	l := strings.ToLower(name)
	for s := cs; s != nil; s = s.parent {
		if d, ok := s.defs[l]; ok {
			return d
		}
	}
	return nil
}

func ordinal(n int) string {
	suffix := "th"
	switch n % 10 {
	case 1:
		if n%100 != 11 {
			suffix = "st"
		}
	case 2:
		if n%100 != 12 {
			suffix = "nd"
		}
	case 3:
		if n%100 != 13 {
			suffix = "rd"
		}
	}
	return strconv.Itoa(n) + suffix
}

// compileSubSelect compiles a subquery (scalar, IN, EXISTS) with sc as parent scope
func (cp *compiler) compileSubSelect(sel *Select, sc *scope) *compiledSelect {
	var ctes *cteScope
	if sc != nil {
		ctes = sc.ctes
	}
	return cp.compileSelect(sel, sc, ctes)
}

func countSelectCols(cp *compiler, sel *Select, sc *scope) int {
	// compile to count columns (cheap enough)
	s := sel
	for s.Prior != nil {
		s = s.Prior
	}
	if s.Values != nil {
		return len(s.Values[0])
	}
	n := 0
	for _, rc := range s.Cols {
		if rc.Star {
			cs := cp.compileSubSelect(sel, sc)
			return len(cs.colNames)
		}
		n++
	}
	return n
}

func (cp *compiler) compileSelect(sel *Select, parent *scope, ctes *cteScope) *compiledSelect {
	if sel.With != nil {
		ns := &cteScope{defs: map[string]*cteDef{}, parent: ctes}
		for _, c := range sel.With.CTEs {
			d := &cteDef{cte: c, scope: parent, ctes: ns, recursive: sel.With.Recursive && selectReferences(c.Sel, c.Name)}
			ns.defs[strings.ToLower(c.Name)] = d
		}
		ctes = ns
	}
	if sel.Prior != nil {
		return cp.compileCompound(sel, parent, ctes)
	}
	return cp.compileCore(sel, parent, ctes, sel.OrderBy, sel.Limit, sel.Offset)
}

// does the select reference table name (for recursive CTE detection)
func selectReferences(sel *Select, name string) bool {
	for s := sel; s != nil; s = s.Prior {
		if fromReferences(s.From, name) {
			return true
		}
	}
	return false
}

func fromReferences(items []*FromItem, name string) bool {
	for _, f := range items {
		if f.Sel == nil && f.Paren == nil && strings.EqualFold(f.Name, name) && f.Schema == "" {
			return true
		}
		if f.Paren != nil && fromReferences(f.Paren, name) {
			return true
		}
		if f.Sel != nil && selectReferences(f.Sel, name) {
			return true
		}
	}
	return false
}

type outRow struct {
	vals []Value
	keys []Value
}

type orderSpec struct {
	desc  bool
	nulls int
	coll  Collation
}

func sortRows(rows []outRow, specs []orderSpec) {
	sort.SliceStable(rows, func(i, j int) bool {
		return cmpOrderKeys(rows[i].keys, rows[j].keys, specs) < 0
	})
}

func cmpOrderKeys(a, b []Value, specs []orderSpec) int {
	for k, sp := range specs {
		x, y := a[k], b[k]
		xn, yn := x.K == KNull, y.K == KNull
		if xn || yn {
			if xn && yn {
				continue
			}
			nullsFirst := !sp.desc
			if sp.nulls == 1 {
				nullsFirst = true
			} else if sp.nulls == 2 {
				nullsFirst = false
			}
			if xn {
				if nullsFirst {
					return -1
				}
				return 1
			}
			if nullsFirst {
				return 1
			}
			return -1
		}
		c := compareValues(x, y, sp.coll)
		if c != 0 {
			if sp.desc {
				return -c
			}
			return c
		}
	}
	return 0
}

func evalLimit(c *Ctx, e *cexpr) int64 {
	if e == nil {
		return -1
	}
	v := e.fn(c)
	if v.K == KInt {
		return v.I
	}
	if v.K == KReal && v.F == float64(int64(v.F)) {
		return int64(v.F)
	}
	if v.K == KText {
		n := textToNumericAff(v)
		if n.K == KInt {
			return n.I
		}
	}
	panic(&SQLError{Msg: "datatype mismatch", Code: SQLITE_MISMATCH, Pos: -1})
}

func (cp *compiler) compileLimit(limit, offset *Expr, sc *scope) (*cexpr, *cexpr) {
	var lim, off *cexpr
	if limit != nil {
		x := cp.compileExpr(limit, &scope{parent: sc, lvl: &level{}})
		lim = &x
	}
	if offset != nil {
		x := cp.compileExpr(offset, &scope{parent: sc, lvl: &level{}})
		off = &x
	}
	return lim, off
}

// postProcess handles distinct/order/limit given a producer.
type rowSink struct {
	emit     func([]Value) bool
	distinct bool
	distColl []string
	seen     map[string]bool
	order    []orderSpec
	buf      []outRow
	limit    int64
	offset   int64
	count    int64
	stopped  bool
}

func (s *rowSink) add(vals []Value, keys []Value) bool {
	if s.stopped {
		return false
	}
	if s.distinct {
		k := rowKey(vals, s.distColl)
		if s.seen[k] {
			return true
		}
		s.seen[k] = true
	}
	if s.order != nil {
		s.buf = append(s.buf, outRow{vals: vals, keys: keys})
		return true
	}
	return s.pass(vals)
}

func (s *rowSink) pass(vals []Value) bool {
	if s.offset > 0 {
		s.offset--
		return true
	}
	if s.limit >= 0 && s.count >= s.limit {
		s.stopped = true
		return false
	}
	s.count++
	if !s.emit(vals) {
		s.stopped = true
		return false
	}
	if s.limit >= 0 && s.count >= s.limit {
		s.stopped = true
		return false
	}
	return true
}

func (s *rowSink) finish() bool {
	if s.order != nil {
		sortRows(s.buf, s.order)
		for _, r := range s.buf {
			if !s.pass(r.vals) {
				return false
			}
		}
		s.buf = nil
	}
	return !s.stopped
}

func newSink(c *Ctx, emit func([]Value) bool, distinct bool, distColl []string, order []orderSpec, lim, off *cexpr) *rowSink {
	s := &rowSink{emit: emit, distinct: distinct, distColl: distColl, order: order, limit: -1}
	if distinct {
		s.seen = map[string]bool{}
	}
	s.limit = evalLimit(c, lim)
	if off != nil {
		s.offset = evalLimit(c, off)
		if s.offset < 0 {
			s.offset = 0
		}
	}
	if s.limit == 0 {
		s.stopped = true
	}
	return s
}

// ---------------- compound ----------------

func (cp *compiler) compileCompound(sel *Select, parent *scope, ctes *cteScope) *compiledSelect {
	// flatten chain
	var parts []*Select
	for s := sel; s != nil; s = s.Prior {
		parts = append([]*Select{s}, parts...)
	}
	comp := make([]*compiledSelect, len(parts))
	for i, p := range parts {
		comp[i] = cp.compileCore(p, parent, ctes, nil, nil, nil)
		if i > 0 && len(comp[i].colNames) != len(comp[0].colNames) {
			op := parts[i].CompoundOp
			throwPos(-1, "SELECTs to the left and right of %s do not have the same number of result columns", op)
		}
	}
	first := comp[0]
	n := len(first.colNames)
	res := &compiledSelect{colNames: first.colNames, colAff: first.colAff, colHasAff: first.colHasAff, colColl: first.colColl, colDeclType: first.colDeclType, colOrigin: first.colOrigin}
	for _, c := range comp {
		if c.correlated {
			res.correlated = true
		}
	}
	// collations per column: first non-empty
	colls := make([]string, n)
	for i := 0; i < n; i++ {
		for _, c := range comp {
			if c.colColl[i] != "" {
				colls[i] = c.colColl[i]
				break
			}
		}
	}
	// ORDER BY resolution against result columns
	var order []orderSpec
	var orderIdx []int
	var orderExtra []*Expr
	if sel.OrderBy != nil {
		for ti, ot := range sel.OrderBy {
			e := ot.E
			coll := ""
			if e.Op == ECollate {
				coll = strings.ToUpper(e.Name)
				e = e.L
			}
			idx := -1
			if e.Op == ELit && e.Val.K == KInt {
				k := int(e.Val.I)
				if k < 1 || k > n {
					throwPos(-1, "%s ORDER BY term out of range - should be between 1 and %d", ordinal(ti+1), n)
				}
				idx = k - 1
			} else {
				// match alias/name of first select
				if e.Op == EColumn && e.Table == "" {
					for i, nm := range first.colNames {
						if strings.EqualFold(nm, e.Column) {
							idx = i
							break
						}
					}
				}
				if idx < 0 {
					// match expression text of any select's result columns
					for pi := len(parts) - 1; pi >= 0 && idx < 0; pi-- {
						p := parts[pi]
						for i, rc := range p.Cols {
							if rc.E != nil && exprEqual(rc.E, e) {
								idx = i
								break
							}
						}
					}
				}
				if idx < 0 && e.Op == EColumn && e.Table != "" {
					for pi := len(parts) - 1; pi >= 0 && idx < 0; pi-- {
						for i, rc := range parts[pi].Cols {
							if rc.E != nil && rc.E.Op == EColumn && strings.EqualFold(rc.E.Column, e.Column) {
								idx = i
								break
							}
						}
					}
				}
				if idx < 0 {
					throwPos(-1, "%s ORDER BY term does not match any column in the result set", ordinal(ti+1))
				}
			}
			if coll == "" {
				coll = colls[idx]
			}
			if coll == "BINARY" {
				coll = ""
			}
			order = append(order, orderSpec{desc: ot.Desc, nulls: ot.Nulls, coll: getCollation(coll)})
			orderIdx = append(orderIdx, idx)
		}
	}
	_ = orderExtra
	lim, off := cp.compileLimit(sel.Limit, sel.Offset, parent)
	ops := make([]string, len(parts))
	for i, p := range parts {
		ops[i] = p.CompoundOp
	}
	allUnionAll := true
	for i := 1; i < len(parts); i++ {
		if ops[i] != "UNION ALL" {
			allUnionAll = false
		}
	}
	res.run = func(pc *Ctx, emit func([]Value) bool) bool {
		c := &Ctx{conn: cp.conn, parent: pc}
		var ord []orderSpec
		if order != nil {
			ord = order
		}
		sink := newSink(c, emit, false, nil, ord, lim, off)
		if sink.stopped {
			return true
		}
		addRow := func(vals []Value) bool {
			var keys []Value
			if ord != nil {
				keys = make([]Value, len(orderIdx))
				for i, ix := range orderIdx {
					keys[i] = vals[ix]
				}
			}
			return sink.add(vals, keys)
		}
		if allUnionAll {
			for _, p := range comp {
				ok := p.run(pc, func(vals []Value) bool {
					return addRow(append([]Value(nil), vals...))
				})
				if !ok || sink.stopped {
					break
				}
			}
			sink.finish()
			return !sink.stopped
		}
		// general: process left to right with set semantics
		type entry struct {
			vals []Value
		}
		var cur []entry
		keyOf := func(v []Value) string { return rowKey(v, colls) }
		curSet := map[string]int{}
		distinctAdd := func(v []Value) {
			k := keyOf(v)
			if _, ok := curSet[k]; ok {
				return
			}
			curSet[k] = len(cur)
			cur = append(cur, entry{vals: v})
		}
		// first part
		if len(parts) > 1 && ops[1] == "UNION ALL" {
			comp[0].run(pc, func(vals []Value) bool {
				cur = append(cur, entry{vals: append([]Value(nil), vals...)})
				return true
			})
		} else {
			comp[0].run(pc, func(vals []Value) bool {
				distinctAdd(append([]Value(nil), vals...))
				return true
			})
		}
		for i := 1; i < len(parts); i++ {
			switch ops[i] {
			case "UNION ALL":
				comp[i].run(pc, func(vals []Value) bool {
					cur = append(cur, entry{vals: append([]Value(nil), vals...)})
					return true
				})
			case "UNION":
				// rebuild set from cur (may include dups from union all)
				ncur := cur
				cur = nil
				curSet = map[string]int{}
				for _, e := range ncur {
					distinctAdd(e.vals)
				}
				comp[i].run(pc, func(vals []Value) bool {
					distinctAdd(append([]Value(nil), vals...))
					return true
				})
			case "INTERSECT":
				right := map[string]bool{}
				comp[i].run(pc, func(vals []Value) bool {
					right[keyOf(vals)] = true
					return true
				})
				ncur := cur
				cur = nil
				curSet = map[string]int{}
				for _, e := range ncur {
					if right[keyOf(e.vals)] {
						distinctAdd(e.vals)
					}
				}
			case "EXCEPT":
				right := map[string]bool{}
				comp[i].run(pc, func(vals []Value) bool {
					right[keyOf(vals)] = true
					return true
				})
				ncur := cur
				cur = nil
				curSet = map[string]int{}
				for _, e := range ncur {
					if !right[keyOf(e.vals)] {
						distinctAdd(e.vals)
					}
				}
			}
		}
		// set operations produce sorted output (ephemeral index order) when last op is not UNION ALL
		if ops[len(ops)-1] != "UNION ALL" {
			specs := make([]orderSpec, n)
			for i := 0; i < n; i++ {
				specs[i] = orderSpec{coll: getCollation(colls[i])}
			}
			sort.SliceStable(cur, func(a, b int) bool { return cmpOrderKeys(cur[a].vals, cur[b].vals, specs) < 0 })
		}
		for _, e := range cur {
			if !addRow(e.vals) {
				break
			}
		}
		sink.finish()
		return !sink.stopped
	}
	return res
}

func exprEqual(a, b *Expr) bool {
	if a == nil || b == nil {
		return a == b
	}
	if a.Op != b.Op {
		return false
	}
	switch a.Op {
	case ELit:
		return a.Val.K == b.Val.K && compareValues(a.Val, b.Val, nil) == 0
	case EColumn:
		return strings.EqualFold(a.Column, b.Column) && strings.EqualFold(a.Table, b.Table)
	case EParam:
		return a.Name == b.Name
	}
	if !strings.EqualFold(a.Name, b.Name) || a.Not != b.Not || a.Distinct != b.Distinct || a.Star != b.Star {
		return false
	}
	if !exprEqual(a.L, b.L) || !exprEqual(a.R, b.R) {
		return false
	}
	if len(a.List) != len(b.List) {
		return false
	}
	for i := range a.List {
		if !exprEqual(a.List[i], b.List[i]) {
			return false
		}
	}
	if a.Sel != nil || b.Sel != nil {
		return a.Sel == b.Sel
	}
	if (a.Over == nil) != (b.Over == nil) {
		return false
	}
	return true
}

// unique names for subquery columns
func uniqueColNames(names []string) []string {
	out := make([]string, len(names))
	seen := map[string]int{}
	for i, n := range names {
		l := strings.ToLower(n)
		if _, ok := seen[l]; !ok {
			seen[l] = 0
			out[i] = n
			continue
		}
		cnt := seen[l]
		for {
			cnt++
			cand := fmt.Sprintf("%s:%d", n, cnt)
			if _, ok := seen[strings.ToLower(cand)]; !ok {
				seen[l] = cnt
				seen[strings.ToLower(cand)] = 0
				out[i] = cand
				break
			}
		}
	}
	return out
}
