				g.rows = make([][]Value, nsrc)
				g.rowids = make([]int64, nsrc)
				order = append(order, g)
			}
			if groupBy != nil {
				specs := make([]orderSpec, len(groupBy))
				for i := range groupBy {
					specs[i] = orderSpec{coll: getCollation(groupColl[i])}
				}
				sort.SliceStable(order, func(i, j int) bool { return cmpOrderKeys(order[i].key, order[j].key, specs) < 0 })
