					}
				}
				if !addBase() {
					break
				}
			}
		} else {
			plan.run(c, func() bool {
				return addBase()
			})
		}
		if hasWin {
			n := len(bases)
			wvals := make([][]Value, n)
			for i := range wvals {
				wvals[i] = make([]Value, len(wins))
			}
			setRow := func(i int) {
				b := bases[i]
				copy(c.rows, b.rows)
				copy(c.rowids, b.rowids)
				c.aggVals = b.aggVals
				c.winVals = wvals[i]
			}
			outOrder := computeWindows(c, wins, n, setRow, wvals)
			for _, i := range outOrder {
				setRow(i)
				vals, keys := computeOut(c)
				if !sink.add(vals, keys) {
					break
				}
			}
		}
		sink.finish()
		return !sink.stopped
	}
	return res
}

func splitAnd(e *Expr) []*Expr {
	if e.Op == EBinary && e.Name == "AND" {
		return append(splitAnd(e.L), splitAnd(e.R)...)
	}
	return []*Expr{e}
}

func (cp *compiler) columnDisplayName(e *Expr, sc *scope) string {
	if e.srcHint > 0 {
		return e.Column
	}
	// find declared column name
	for _, s := range sc.srcs {
		if e.Table != "" && !strings.EqualFold(s.name, e.Table) {
			continue
		}
		for _, cn := range s.cols {
			if strings.EqualFold(cn, e.Column) {
				return cn
			}
		}
		if s.hasRowid && isRowidName(e.Column) {
			return e.Column
		}
	}
	return e.Column
}

// compileWithDeps compiles e and returns the bitmask of sources (in sc) it references.
func (cp *compiler) compileWithDeps(e *Expr, sc *scope) (cexpr, uint64) {
	saved := cp.refTrack
	cp.refTrack = &refTracker{sc: sc}
	x := cp.compileExpr(e, sc)
	deps := cp.refTrack.mask
	if cp.refTrack.unknown {
		deps = ^uint64(0) >> 1
	}
	cp.refTrack = saved
	if saved != nil {
		saved.mask |= 0
	}
	return x, deps
}

type refTracker struct {
	sc      *scope
	mask    uint64
	unknown bool
}

func (cp *compiler) compileValues(sel *Select, parent *scope, ctes *cteScope, orderBy []*OrderTerm, limit, offset *Expr) *compiledSelect {
	lvl := &level{}
	sc := &scope{parent: parent, lvl: lvl, ctes: ctes}
	n := len(sel.Values[0])
	rows := make([][]cexpr, len(sel.Values))
	for i, r := range sel.Values {
		if len(r) != n {
			throwPos(-1, "all VALUES must have the same number of terms")
		}
		rows[i] = make([]cexpr, n)
		for j, e := range r {
			rows[i][j] = cp.compileExpr(e, sc)
		}
	}
	res := &compiledSelect{colNames: make([]string, n), colAff: make([]Affinity, n), colHasAff: make([]bool, n), colColl: make([]string, n), colDeclType: make([]string, n), colOrigin: make([]*colOrigin, n)}
	for i := 0; i < n; i++ {
		res.colNames[i] = "column" + itoa(i+1)
	}
	res.correlated = lvl.correlated
	var obs []int
	var specs []orderSpec
	for ti, ot := range orderBy {
		e := ot.E
		idx := -1
		if e.Op == ELit && e.Val.K == KInt {
			idx = int(e.Val.I) - 1
			if idx < 0 || idx >= n {
				throwPos(-1, "%s ORDER BY term out of range - should be between 1 and %d", ordinal(ti+1), n)
			}
		} else if e.Op == EColumn {
			for i, nm := range res.colNames {
				if strings.EqualFold(nm, e.Column) {
					idx = i
				}
			}
		}
		if idx < 0 {
			throwPos(-1, "%s ORDER BY term does not match any column in the result set", ordinal(ti+1))
		}
		obs = append(obs, idx)
		specs = append(specs, orderSpec{desc: ot.Desc, nulls: ot.Nulls})
	}
	lim, off := cp.compileLimit(limit, offset, parent)
	res.run = func(pc *Ctx, emit func([]Value) bool) bool {
		c := &Ctx{conn: cp.conn, parent: pc}
		sink := newSink(c, emit, false, nil, specs, lim, off)
		for _, r := range rows {
			if sink.stopped {
				break
			}
			vals := make([]Value, n)
			for j := range r {
				vals[j] = r[j].fn(c)
			}
			var keys []Value
			if specs != nil {
				keys = make([]Value, len(obs))
				for k, ix := range obs {
					keys[k] = vals[ix]
				}
			}
			if !sink.add(vals, keys) {
				break
			}
		}
		sink.finish()
		return !sink.stopped
	}
	return res
}

func itoa(i int) string {
	return strings.TrimSpace(strings.Replace(string(rune('0')), "0", "", 1)) + intToStr(i)
}

func intToStr(i int) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var b [20]byte
	p := len(b)
	for i > 0 {
		p--
		b[p] = byte('0' + i%10)
		i /= 10
	}
	if neg {
		p--
		b[p] = '-'
	}
	return string(b[p:])
}
