cd /workspace/src && cat > core.go <<'EOF'
package main

import (
	"sort"
	"strings"
)

const (
	srcTable = iota
	srcSub
	srcCTE
	srcRecCTE
	srcTVF
	srcSingle
)

type fromSrc struct {
	info      *srcInfo
	kind      int
	table     *Table
	sub       *compiledSelect
	cte       *cteDef
	tvf       *tvfDef
	tvfArgs   []cexpr
	join      JoinType
	onExpr    *Expr
	using     []string
	on        *cexpr
	terms     []cexpr
	path      *accessPath
	item      *FromItem
	subCache  [][]Value
	subGen    int64
	matched   map[int]bool
	order     int
	indexedBy string
	notIndexed bool
}

type termInfo struct {
	e      *Expr
	c      cexpr
	deps   uint64
	isOn   bool
	srcIdx int // for ON terms of left join: the source index
	used   bool
}

func (cp *compiler) compileCore(sel *Select, parent *scope, ctes *cteScope, orderBy []*OrderTerm, limit, offset *Expr) *compiledSelect {
	if sel.Values != nil {
		return cp.compileValues(sel, parent, ctes, orderBy, limit, offset)
	}
	lvl := &level{sel: sel, windows: sel.Windows}
	sc := &scope{parent: parent, lvl: lvl, ctes: ctes}
	srcs := cp.compileFrom(sel.From, sc)
	nsrc := len(srcs)
	// expand result columns
	type rcol struct {
		e     *Expr
		name  string
		c     cexpr
		alias string
	}
	var cols []*ResultCol
	for _, rc := range sel.Cols {
		if rc.Star {
			found := false
			for _, s := range srcs {
				if rc.Table != "" && !strings.EqualFold(s.info.name, rc.Table) {
					continue
				}
				for ci, cn := range s.info.cols {
					if rc.Table == "" && s.info.hiddenCol != nil && s.info.hiddenCol[ci] {
						continue
					}
					if s.table != nil && ci < len(s.table.Cols) && s.table.Cols[ci].Hidden != 0 {
						continue
					}
					found = true
					cols = append(cols, &ResultCol{E: &Expr{Op: EColumn, Table: s.info.name, Column: cn, Pos: -1, srcHint: s.info.idx + 1, colHint: ci + 1}, Alias: "", Span: cn, Star: false})
				}
			}
			if !found {
				if rc.Table != "" {
					throwPos(-1, "no such table: %s", rc.Table)
				}
				throwPos(-1, "no tables specified")
			}
			continue
		}
		cols = append(cols, rc)
	}
	lvl.aliases = cols
	ncol := len(cols)
	res := &compiledSelect{}
	res.colNames = make([]string, ncol)
	res.colAff = make([]Affinity, ncol)
	res.colHasAff = make([]bool, ncol)
	res.colColl = make([]string, ncol)
	res.colDeclType = make([]string, ncol)
	res.colOrigin = make([]*colOrigin, ncol)
	colFns := make([]cexpr, ncol)
	lvl.allowAgg = true
	lvl.allowWin = true
	for i, rc := range cols {
		x := cp.compileExpr(rc.E, sc)
		if x.nCols > 1 {
			throwPos(rc.E.Pos, "row value misused")
		}
		colFns[i] = x
		res.colAff[i] = x.aff
		res.colHasAff[i] = x.hasAff
		res.colColl[i] = x.coll
		name := rc.Alias
		if name == "" {
			if rc.E.Op == EColumn {
				name = cp.columnDisplayName(rc.E, sc)
			} else {
				name = rc.Span
			}
		}
		res.colNames[i] = name
		if rc.E.Op == EColumn && x.isColumn && x.depth == 0 {
			for _, s := range srcs {
				if s.info.idx == x.srcIdx && s.table != nil {
					if x.colIdx >= 0 {
						res.colDeclType[i] = s.table.Cols[x.colIdx].Type
						res.colOrigin[i] = &colOrigin{table: s.table, col: x.colIdx}
					} else {
						res.colDeclType[i] = "INTEGER"
					}
				}
			}
		}
	}
	// HAVING
	var having *cexpr
	if sel.Having != nil {
		lvl.allowWin = false
		x := cp.compileExpr(sel.Having, sc)
		having = &x
	}
	// WHERE
	lvl.allowAgg = false
	lvl.allowWin = false
	var terms []*termInfo
	if sel.Where != nil {
		for _, t := range splitAnd(sel.Where) {
			ti := &termInfo{e: t}
			ti.c, ti.deps = cp.compileWithDeps(t, sc)
			terms = append(terms, ti)
		}
	}
	// ON clauses
	for i, s := range srcs {
		if s.onExpr == nil {
			continue
		}
		for _, t := range splitAnd(s.onExpr) {
			ti := &termInfo{e: t, isOn: true, srcIdx: i}
			ti.c, ti.deps = cp.compileWithDeps(t, sc)
			if s.join&(JLeft|JRight) == 0 {
				ti.isOn = false
			}
			terms = append(terms, ti)
		}
	}
	// GROUP BY
	var groupBy []cexpr
	var groupColl []string
	if sel.GroupBy != nil {
		for _, g := range sel.GroupBy {
			if g.Op == ELit && g.Val.K == KInt {
				k := int(g.Val.I)
				if k < 1 || k > ncol {
					throwPos(-1, "%s GROUP BY term out of range - should be between 1 and %d", ordinal(len(groupBy)+1), ncol)
				}
				groupBy = append(groupBy, colFns[k-1])
				groupColl = append(groupColl, colFns[k-1].coll)
				continue
			}
			x := cp.compileExpr(g, sc)
			groupBy = append(groupBy, x)
			groupColl = append(groupColl, x.coll)
		}
	}
	isAgg := len(lvl.aggs) > 0 || sel.GroupBy != nil
	// ORDER BY
	lvl.allowAgg = isAgg
	lvl.allowWin = true
	type obTerm struct {
		colIdx int
		c      cexpr
		spec   orderSpec
	}
	var obs []obTerm
	for ti, ot := range orderBy {
		e := ot.E
		var collOverride string
		hasCollOverride := false
		inner := e
		if inner.Op == ECollate {
			collOverride = strings.ToUpper(inner.Name)
			hasCollOverride = true
			inner = inner.L
		}
		t := obTerm{colIdx: -1, spec: orderSpec{desc: ot.Desc, nulls: ot.Nulls}}
		if inner.Op == ELit && inner.Val.K == KInt {
			k := int(inner.Val.I)
			if k < 1 || k > ncol {
				throwPos(-1, "%s ORDER BY term out of range - should be between 1 and %d", ordinal(ti+1), ncol)
			}
			t.colIdx = k - 1
		} else if inner.Op == EColumn && inner.Table == "" {
			for i, rc := range cols {
				if rc.Alias != "" && strings.EqualFold(rc.Alias, inner.Column) {
					t.colIdx = i
					break
				}
			}
		}
		if t.colIdx < 0 {
			for i, rc := range cols {
				if rc.E != nil && rc.Alias == "" && exprEqual(rc.E, inner) && inner.Op != EFunc {
					t.colIdx = i
					break
				}
			}
		}
		var coll string
		if t.colIdx >= 0 {
			coll = colFns[t.colIdx].coll
		} else {
			saveAliases := lvl.aliases
			t.c = cp.compileExpr(inner, sc)
			lvl.aliases = saveAliases
			coll = t.c.coll
		}
		if hasCollOverride {
			if getCollation(collOverride) == nil {
				throwPos(e.Pos, "no such collation sequence: %s", collOverride)
			}
			coll = collOverride
		}
		if coll == "BINARY" {
			coll = ""
		}
		t.spec.coll = getCollation(coll)
		obs = append(obs, t)
	}
	if !isAgg && len(lvl.aggs) > 0 {
		isAgg = true
	}
	lim, off := cp.compileLimit(limit, offset, parent)
	// distinct collations
	var distColl []string
	if sel.Distinct {
		distColl = make([]string, ncol)
		for i := range colFns {
			distColl[i] = colFns[i].coll
		}
	}
	hasWin := len(lvl.wins) > 0
	// plan joins
	plan := cp.planJoins(srcs, terms, sc, cols, sel, isAgg)
	res.correlated = lvl.correlated
	aggs := lvl.aggs
	wins := lvl.wins
	var orderSpecs []orderSpec
	if len(obs) > 0 {
		orderSpecs = make([]orderSpec, len(obs))
		for i, o := range obs {
			orderSpecs[i] = o.spec
		}
	}
	singleMinMax := -1
	if len(aggs) == 1 && (aggs[0].name == "min" || aggs[0].name == "max") && len(aggs[0].args) == 1 {
		singleMinMax = 0
	}
	conn := cp.conn
	computeOut := func(c *Ctx) ([]Value, []Value) {
		vals := make([]Value, ncol)
		for i := range colFns {
			vals[i] = colFns[i].fn(c)
		}
		var keys []Value
		if len(obs) > 0 {
			keys = make([]Value, len(obs))
			for i, o := range obs {
				if o.colIdx >= 0 {
					keys[i] = vals[o.colIdx]
				} else {
					keys[i] = o.c.fn(c)
				}
			}
		}
		return vals, keys
	}
	res.run = func(pc *Ctx, emit func([]Value) bool) bool {
		c := &Ctx{conn: conn, parent: pc, rows: make([][]Value, nsrc), rowids: make([]int64, nsrc)}
		sink := newSink(c, emit, sel.Distinct, distColl, orderSpecs, lim, off)
		if sink.stopped {
			return true
		}
		if !isAgg && !hasWin {
			plan.run(c, func() bool {
				vals, keys := computeOut(c)
				return sink.add(vals, keys)
			})
			sink.finish()
			return !sink.stopped
		}
		type baseRow struct {
			rows    [][]Value
			rowids  []int64
			aggVals []Value
		}
		var bases []baseRow
		addBase := func() bool {
			if hasWin {
				br := baseRow{rows: append([][]Value(nil), c.rows...), rowids: append([]int64(nil), c.rowids...), aggVals: c.aggVals}
				bases = append(bases, br)
				return true
			}
			vals, keys := computeOut(c)
			return sink.add(vals, keys)
		}
		if isAgg {
			type group struct {
				key    []Value
				states []aggState
				rows   [][]Value
				rowids []int64
				seen   []map[string]bool
			}
			groups := map[string]*group{}
			var order []*group
			newGroup := func(key []Value) *group {
				g := &group{key: key, states: make([]aggState, len(aggs)), seen: make([]map[string]bool, len(aggs))}
				for i, a := range aggs {
					g.states[i] = a.def.newState(a)
					if a.distinct {
						g.seen[i] = map[string]bool{}
					}
				}
				return g
			}
			plan.run(c, func() bool {
				var key []Value
				var k string
				if groupBy != nil {
					key = make([]Value, len(groupBy))
					for i, g := range groupBy {
						key[i] = g.fn(c)
					}
					k = rowKey(key, groupColl)
				}
				g := groups[k]
				if g == nil {
					g = newGroup(key)
					groups[k] = g
					order = append(order, g)
				}
				updateRep := true
				for i, a := range aggs {
					if a.filter != nil {
						fv := a.filter.fn(c)
						if !fv.Bool() {
							if i == singleMinMax {
								updateRep = g.rows == nil
							}
							continue
						}
					}
					args := make([]Value, len(a.args))
					for j, ae := range a.args {
						args[j] = ae.fn(c)
					}
					if a.distinct {
						dk := rowKey(args, a.argColls)
						if g.seen[i][dk] {
							if i == singleMinMax {
								updateRep = false
							}
							continue
						}
						g.seen[i][dk] = true
					}
					var okeys []Value
					if len(a.orderBy) > 0 {
						okeys = make([]Value, len(a.orderBy))
						for j, oe := range a.orderBy {
							okeys[j] = oe.fn(c)
						}
					}
					changed := g.states[i].step(args, okeys)
					if i == singleMinMax {
						updateRep = changed || g.rows == nil
					}
				}
				if updateRep {
					if g.rows == nil {
						g.rows = make([][]Value, nsrc)
						g.rowids = make([]int64, nsrc)
					}
					copy(g.rows, c.rows)
					copy(g.rowids, c.rowids)
				}
				return true
			})
			if groupBy == nil && len(order) == 0 {
				g := newGroup(nil)
				g.rows = make([][]Value, nsrc)
				g.rowids = make([]int64, nsrc)
				order = append(order, g)
			}
			if groupBy != nil {
				specs := make([]orderSpec, len(groupBy))
				for i := range groupBy {
					specs[i] = orderSpec{coll: getCollation(groupColl[i])}
				}
				sort.SliceStable(order, func(i, j int) bool { return cmpOrderKeys(order[i].key, order[j].key, specs) < 0 })
			}
			for _, g := range order {
				vals := make([]Value, len(aggs))
				for i := range aggs {
					vals[i] = g.states[i].final()
				}
				if g.rows == nil {
					g.rows = make([][]Value, nsrc)
					g.rowids = make([]int64, nsrc)
				}
				copy(c.rows, g.rows)
				copy(c.rowids, g.rowids)
				c.aggVals = vals
				if having != nil {
					hv := having.fn(c)
					if !hv.Bool() {
						continue
					}
				}
				if !addBase() {
					break
				}
			}
		} else {
			plan.run(c, func() bool {
				return addBase()
			})
		}
		if hasWin {
			n := len(bases)
			wvals := make([][]Value, n)
			for i := range wvals {
				wvals[i] = make([]Value, len(wins))
			}
			setRow := func(i int) {
				b := bases[i]
				copy(c.rows, b.rows)
				copy(c.rowids, b.rowids)
				c.aggVals = b.aggVals
				c.winVals = wvals[i]
			}
			outOrder := computeWindows(c, wins, n, setRow, wvals)
			for _, i := range outOrder {
				setRow(i)
				vals, keys := computeOut(c)
				if !sink.add(vals, keys) {
					break
				}
			}
		}
		sink.finish()
		return !sink.stopped
	}
	return res
}

func splitAnd(e *Expr) []*Expr {
	if e.Op == EBinary && e.Name == "AND" {
		return append(splitAnd(e.L), splitAnd(e.R)...)
	}
	return []*Expr{e}
}

func (cp *compiler) columnDisplayName(e *Expr, sc *scope) string {
	if e.srcHint > 0 {
		return e.Column
	}
	// find declared column name
	for _, s := range sc.srcs {
		if e.Table != "" && !strings.EqualFold(s.name, e.Table) {
			continue
		}
		for _, cn := range s.cols {
			if strings.EqualFold(cn, e.Column) {
				return cn
			}
		}
		if s.hasRowid && isRowidName(e.Column) {
			return e.Column
		}
	}
	return e.Column
}

// compileWithDeps compiles e and returns the bitmask of sources (in sc) it references.
func (cp *compiler) compileWithDeps(e *Expr, sc *scope) (cexpr, uint64) {
	saved := cp.refTrack
	cp.refTrack = &refTracker{sc: sc}
	x := cp.compileExpr(e, sc)
	deps := cp.refTrack.mask
	if cp.refTrack.unknown {
		deps = ^uint64(0) >> 1
	}
	cp.refTrack = saved
	if saved != nil {
		saved.mask |= 0
	}
	return x, deps
}

type refTracker struct {
	sc      *scope
	mask    uint64
	unknown bool
}

func (cp *compiler) compileValues(sel *Select, parent *scope, ctes *cteScope, orderBy []*OrderTerm, limit, offset *Expr) *compiledSelect {
	lvl := &level{}
	sc := &scope{parent: parent, lvl: lvl, ctes: ctes}
	n := len(sel.Values[0])
	rows := make([][]cexpr, len(sel.Values))
	for i, r := range sel.Values {
		if len(r) != n {
			throwPos(-1, "all VALUES must have the same number of terms")
		}
		rows[i] = make([]cexpr, n)
		for j, e := range r {
			rows[i][j] = cp.compileExpr(e, sc)
		}
	}
	res := &compiledSelect{colNames: make([]string, n), colAff: make([]Affinity, n), colHasAff: make([]bool, n), colColl: make([]string, n), colDeclType: make([]string, n), colOrigin: make([]*colOrigin, n)}
	for i := 0; i < n; i++ {
		res.colNames[i] = "column" + itoa(i+1)
	}
	res.correlated = lvl.correlated
	var obs []int
	var specs []orderSpec
	for ti, ot := range orderBy {
		e := ot.E
		idx := -1
		if e.Op == ELit && e.Val.K == KInt {
			idx = int(e.Val.I) - 1
			if idx < 0 || idx >= n {
				throwPos(-1, "%s ORDER BY term out of range - should be between 1 and %d", ordinal(ti+1), n)
			}
		} else if e.Op == EColumn {
			for i, nm := range res.colNames {
				if strings.EqualFold(nm, e.Column) {
					idx = i
				}
			}
		}
		if idx < 0 {
			throwPos(-1, "%s ORDER BY term does not match any column in the result set", ordinal(ti+1))
		}
		obs = append(obs, idx)
		specs = append(specs, orderSpec{desc: ot.Desc, nulls: ot.Nulls})
	}
	lim, off := cp.compileLimit(limit, offset, parent)
	res.run = func(pc *Ctx, emit func([]Value) bool) bool {
		c := &Ctx{conn: cp.conn, parent: pc}
		sink := newSink(c, emit, false, nil, specs, lim, off)
		for _, r := range rows {
			if sink.stopped {
				break
			}
			vals := make([]Value, n)
			for j := range r {
				vals[j] = r[j].fn(c)
			}
			var keys []Value
			if specs != nil {
				keys = make([]Value, len(obs))
				for k, ix := range obs {
					keys[k] = vals[ix]
				}
			}
			if !sink.add(vals, keys) {
				break
			}
		}
		sink.finish()
		return !sink.stopped
	}
	return res
}

func itoa(i int) string {
	return strings.TrimSpace(strings.Replace(string(rune('0')), "0", "", 1)) + intToStr(i)
}

func intToStr(i int) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var b [20]byte
	p := len(b)
	for i > 0 {
		p--
		b[p] = byte('0' + i%10)
		i /= 10
	}
	if neg {
		p--
		b[p] = '-'
	}
	return string(b[p:])
}
EOF
echo ok

