{"command":"cd /workspace/src && cat > from.go <<'EOF'
package main

import (
	"strings"
)

func flattenFrom(items []*FromItem) []*FromItem {
	var out []*FromItem
	for _, it := range items {
		if it.Paren != nil {
			inner := flattenFrom(it.Paren)
			if len(inner) > 0 {
				first := *inner[0]
				first.Join = it.Join
				if it.On != nil {
					// attach outer ON to last inner item
				}
				inner[0] = &first
				out = append(out, inner...)
				if it.On != nil || it.Using != nil {
					last := *out[len(out)-1]
					if it.On != nil {
						if last.On != nil {
							last.On = &Expr{Op: EBinary, Name: "AND", L: last.On, R: it.On}
						} else {
							last.On = it.On
						}
					}
					if it.Using != nil {
						last.Using = append(last.Using, it.Using...)
					}
					out[len(out)-1] = &last
				}
			}
			continue
		}
		out = append(out, it)
	}
	return out
}

func (cp *compiler) compileFrom(items []*FromItem, sc *scope) []*fromSrc {
	items = flattenFrom(items)
	var srcs []*fromSrc
	for i, it := range items {
		s := cp.compileFromItem(it, sc, i)
		s.info.idx = i
		s.join = it.Join
		s.onExpr = it.On
		s.using = it.Using
		s.item = it
		s.order = i
		s.indexedBy = it.Indexed
		s.notIndexed = it.NotIndexed
		srcs = append(srcs, s)
		sc.srcs = append(sc.srcs, s.info)
	}
	// USING / NATURAL
	for i, s := range srcs {
		if i == 0 {
			continue
		}
		var usingCols []string
		if s.join&JNatural != 0 {
			for _, cn := range s.info.cols {
				for j := 0; j < i; j++ {
					if hasCol(srcs[j].info, cn) {
						usingCols = append(usingCols, cn)
						break
					}
				}
			}
		} else if s.using != nil {
			usingCols = s.using
		}
		for _, cn := range usingCols {
			rc := colIdxOf(s.info, cn)
			if rc < 0 {
				throwPos(-1, "cannot join using column %s - column not present in both tables", cn)
			}
			lj := -1
			for j := 0; j < i; j++ {
				if colIdxOf(srcs[j].info, cn) >= 0 {
					lj = j
					break
				}
			}
			if lj < 0 {
				throwPos(-1, "cannot join using column %s - column not present in both tables", cn)
			}
			cond := &Expr{Op: EBinary, Name: "=",
				L: &Expr{Op: EColumn, Column: cn, srcHint: srcs[lj].info.idx + 1, colHint: colIdxOf(srcs[lj].info, cn) + 1, Pos: -1},
				R: &Expr{Op: EColumn, Column: cn, srcHint: s.info.idx + 1, colHint: rc + 1, Pos: -1}}
			if s.onExpr == nil {
				s.onExpr = cond
			} else {
				s.onExpr = &Expr{Op: EBinary, Name: "AND", L: s.onExpr, R: cond}
			}
			if s.info.hiddenCol == nil {
				s.info.hiddenCol = make([]bool, len(s.info.cols))
			}
			if s.join&JRight != 0 && s.join&JLeft == 0 {
				// right join: left column hidden instead
				li := srcs[lj].info
				if li.hiddenCol == nil {
					li.hiddenCol = make([]bool, len(li.cols))
				}
				li.hiddenCol[colIdxOf(li, cn)] = true
			} else {
				s.info.hiddenCol[rc] = true
			}
			if s.info.usingCol == nil {
				s.info.usingCol = map[string]bool{}
			}
			s.info.usingCol[strings.ToLower(cn)] = true
		}
	}
	return srcs
}

func hasCol(si *srcInfo, name string) bool { return colIdxOf(si, name) >= 0 }

func colIdxOf(si *srcInfo, name string) int {
	for i, c := range si.cols {
		if strings.EqualFold(c, name) {
			return i
		}
	}
	return -1
}

func tableSrcInfo(t *Table, name string) *srcInfo {
	n := len(t.Cols)
	si := &srcInfo{name: name, table: t, hasRowid: !t.WithoutRowid, cols: make([]string, n), aff: make([]Affinity, n), hasAff: make([]bool, n), coll: make([]string, n)}
	for i, c := range t.Cols {
		si.cols[i] = c.Name
		si.aff[i] = c.Aff
		si.hasAff[i] = true
		si.coll[i] = strings.ToUpper(c.Collate)
		if si.coll[i] == "BINARY" {
			si.coll[i] = ""
		}
	}
	return si
}

func subSrcInfo(cs *compiledSelect, name string, colNames []string) *srcInfo {
	n := len(cs.colNames)
	if colNames == nil {
		colNames = uniqueColNames(cs.colNames)
	}
	si := &srcInfo{name: name, cols: colNames, aff: make([]Affinity, n), hasAff: make([]bool, n), coll: make([]string, n)}
	copy(si.aff, cs.colAff)
	copy(si.hasAff, cs.colHasAff)
	copy(si.coll, cs.colColl)
	return si
}

func (cp *compiler) compileFromItem(it *FromItem, sc *scope, pos int) *fromSrc {
	alias := it.Alias
	if it.Sel != nil {
		cs := cp.compileSelect(it.Sel, sc.parent, sc.ctes)
		if cs.correlated {
			sc.lvl.correlated = true
		}
		name := alias
		if name == "" {
			name = "(subquery-" + intToStr(pos+1) + ")"
		}
		return &fromSrc{kind: srcSub, sub: cs, info: subSrcInfo(cs, name, nil)}
	}
	if it.IsFunc {
		return cp.compileTVF(it, sc)
	}
	name := it.Name
	if alias == "" {
		alias = name
	}
	if it.Schema == "" && sc.ctes != nil {
		if d := sc.ctes.find(name); d != nil {
			if d.compiling {
				// recursive reference
				if !d.recursive {
					throwPos(-1, "circular reference: %s", d.cte.Name)
				}
				si := &srcInfo{name: alias, cols: d.recNames, aff: d.recAff, hasAff: d.recHasAff, coll: d.recColl}
				return &fromSrc{kind: srcRecCTE, cte: d, info: si}
			}
			cs := cp.compileCTE(d)
			if cs.correlated {
				sc.lvl.correlated = true
			}
			var names []string
			if d.cte.Cols != nil {
				names = d.cte.Cols
			}
			return &fromSrc{kind: srcCTE, cte: d, sub: cs, info: subSrcInfo(cs, alias, names)}
		}
	}
	if it.Schema != "" && cp.conn.schemaByName(it.Schema) == nil {
		throwPos(it.Pos, "no such table: %s.%s", it.Schema, name)
	}
	if t := cp.conn.findTable(it.Schema, name); t != nil {
		if t.isVirtual {
			return cp.compileVTabSource(t, alias)
		}
		return &fromSrc{kind: srcTable, table: t, info: tableSrcInfo(t, alias)}
	}
	if strings.EqualFold(name, "sqlite_master") || strings.EqualFold(name, "sqlite_schema") || strings.EqualFold(name, "sqlite_temp_master") || strings.EqualFold(name, "sqlite_temp_schema") {
		return cp.compileSchemaSource(it, alias)
	}
	if v := cp.conn.findView(it.Schema, name); v != nil {
		cs := cp.compileView(v)
		return &fromSrc{kind: srcSub, sub: cs, info: subSrcInfo(cs, alias, viewColNames(v, cs))}
	}
	if it.Schema != "" {
		throwPos(it.Pos, "no such table: %s.%s", it.Schema, name)
	}
	throwPos(it.Pos, "no such table: %s", name)
	return nil
}

func viewColNames(v *View, cs *compiledSelect) []string {
	if v.Cols != nil {
		return v.Cols
	}
	return uniqueColNames(cs.colNames)
}

func (cp *compiler) compileView(v *View) *compiledSelect {
	if cp.viewDepth > 50 {
		throwPos(-1, "view %s is circularly defined", v.Name)
	}
	for _, x := range cp.viewStack {
		if x == v {
			throwPos(-1, "view %s is circularly defined", v.Name)
		}
	}
	cp.viewStack = append(cp.viewStack, v)
	cp.viewDepth++
	defer func() {
		cp.viewStack = cp.viewStack[:len(cp.viewStack)-1]
		cp.viewDepth--
	}()
	cs := cp.compileSelect(v.Sel, nil, nil)
	if v.Cols != nil && len(v.Cols) != len(cs.colNames) {
		throwPos(-1, "expected %d columns for '%s' but got %d", len(v.Cols), v.Name, len(cs.colNames))
	}
	return cs
}

func (cp *compiler) compileCTE(d *cteDef) *compiledSelect {
	if d.compiled != nil {
		return d.compiled
	}
	var cs *compiledSelect
	if d.recursive {
		cs = cp.compileRecursiveCTE(d)
	} else {
		d.compiling = true
		cs = cp.compileSelect(d.cte.Sel, d.scope, d.ctes.parentFor(d))
		d.compiling = false
	}
	if d.cte.Cols != nil && len(d.cte.Cols) != len(cs.colNames) {
		throwPos(-1, "table %s has %d values for %d columns", d.cte.Name, len(cs.colNames), len(d.cte.Cols))
	}
	// wrap to materialize once per statement
	inner := cs
	wrapped := &compiledSelect{colNames: inner.colNames, colAff: inner.colAff, colHasAff: inner.colHasAff, colColl: inner.colColl, colDeclType: inner.colDeclType, colOrigin: inner.colOrigin, correlated: inner.correlated}
	if d.recursive || inner.correlated {
		wrapped.run = inner.run
	} else {
		wrapped.run = func(pc *Ctx, emit func([]Value) bool) bool {
			if d.cacheGen != pc.conn.stmtGen || d.cache == nil {
				var rows [][]Value
				inner.run(pc, func(r []Value) bool {
					rows = append(rows, append([]Value(nil), r...))
					return true
				})
				if rows == nil {
					rows = [][]Value{}
				}
				d.cache = rows
				d.cacheGen = pc.conn.stmtGen
			}
			for _, r := range d.cache {
				if !emit(r) {
					return false
				}
			}
			return true
		}
	}
	d.compiled = wrapped
	return wrapped
}

// CTEs defined in the same WITH are visible to later ones (and to itself if recursive)
func (cs *cteScope) parentFor(d *cteDef) *cteScope {
	return cs
}

func (cp *compiler) compileRecursiveCTE(d *cteDef) *compiledSelect {
	sel := d.cte.Sel
	var parts []*Select
	for s := sel; s != nil; s = s.Prior {
		parts = append([]*Select{s}, parts...)
	}
	k := -1
	for i, p := range parts {
		if fromReferences(p.From, d.cte.Name) {
			k = i
			break
		}
	}
	if k <= 0 {
		if k == 0 {
			throwPos(-1, "recursive reference in a subquery: %s", d.cte.Name)
		}
		d.recursive = false
		d.compiling = true
		cs := cp.compileSelect(sel, d.scope, d.ctes)
		d.compiling = false
		return cs
	}
	op := parts[k].CompoundOp
	if op != "UNION" && op != "UNION ALL" {
		throwPos(-1, "recursive reference in a subquery: %s", d.cte.Name)
	}
	// build initial select chain
	var initSel *Select
	for i := 0; i < k; i++ {
		cp2 := *parts[i]
		cp2.OrderBy = nil
		cp2.Limit = nil
		cp2.Offset = nil
		cp2.With = nil
		if i == 0 {
			cp2.Prior = nil
			cp2.CompoundOp = ""
		} else {
			cp2.Prior = initSel
		}
		initSel = &cp2
	}
	initSel.With = nil
	init := cp.compileSelect(initSel, d.scope, d.ctes)
	n := len(init.colNames)
	names := init.colNames
	if d.cte.Cols != nil {
		if len(d.cte.Cols) != n {
			throwPos(-1, "table %s has %d values for %d columns", d.cte.Name, n, len(d.cte.Cols))
		}
		names = d.cte.Cols
	}
	d.recNames = uniqueColNames(names)
	d.recAff = make([]Affinity, n)
	d.recHasAff = make([]bool, n)
	d.recColl = make([]string, n)
	copy(d.recColl, init.colColl)
	d.compiling = true
	var recs []*compiledSelect
	for i := k; i < len(parts); i++ {
		p := *parts[i]
		p.OrderBy = nil
		p.Limit = nil
		p.Offset = nil
		p.Prior = nil
		p.CompoundOp = ""
		rc := cp.compileCore(&p, d.scope, d.ctes, nil, nil, nil)
		if len(rc.colNames) != n {
			throwPos(-1, "SELECTs to the left and right of %s do not have the same number of result columns", op)
		}
		recs = append(recs, rc)
	}
	d.compiling = false
	// order by / limit from last part (sel)
	var specs []orderSpec
	var obIdx []int
	for ti, ot := range sel.OrderBy {
		e := ot.E
		coll := ""
		if e.Op == ECollate {
			coll = strings.ToUpper(e.Name)
			e = e.L
		}
		idx := -1
		if e.Op == ELit && e.Val.K == KInt {
			idx = int(e.Val.I) - 1
		} else if e.Op == EColumn {
			for i, nm := range d.recNames {
				if strings.EqualFold(nm, e.Column) {
					idx = i
				}
			}
			if idx < 0 {
				for i, nm := range init.colNames {
					if strings.EqualFold(nm, e.Column) {
						idx = i
					}
				}
			}
		}
		if idx < 0 || idx >= n {
			throwPos(-1, "%s ORDER BY term does not match any column in the result set", ordinal(ti+1))
		}
		if coll == "" {
			coll = d.recColl[idx]
		}
		specs = append(specs, orderSpec{desc: ot.Desc, nulls: ot.Nulls, coll: getCollation(coll)})
		obIdx = append(obIdx, idx)
	}
	lim, off := cp.compileLimit(sel.Limit, sel.Offset, d.scope)
	union := op == "UNION"
	res := &compiledSelect{colNames: init.colNames, colAff: d.recAff, colHasAff: d.recHasAff, colColl: d.recColl, colDeclType: make([]string, n), colOrigin: make([]*colOrigin, n)}
	res.colNames = d.recNames
	res.correlated = init.correlated
	for _, r := range recs {
		if r.correlated {
			res.correlated = true
		}
	}
	res.run = func(pc *Ctx, emit func([]Value) bool) bool {
		c := &Ctx{conn: cp.conn, parent: pc}
		limit := evalLimit(c, lim)
		offset := int64(0)
		if off != nil {
			offset = evalLimit(c, off)
		}
		var queue [][]Value
		seen := map[string]bool{}
		push := func(r []Value) bool {
			row := append([]Value(nil), r...)
			if union {
				k := rowKey(row, d.recColl)
				if seen[k] {
					return true
				}
				seen[k] = true
			}
			if specs != nil {
				// insert into sorted position (stable: after equal keys)
				keys := make([]Value, len(obIdx))
				for i, ix := range obIdx {
					keys[i] = row[ix]
				}
				lo, hi := 0, len(queue)
				for lo < hi {
					mid := (lo + hi) / 2
					mk := make([]Value, len(obIdx))
					for i, ix := range obIdx {
						mk[i] = queue[mid][ix]
					}
