				queue = append(queue, nil)
				copy(queue[lo+1:], queue[lo:])
				queue[lo] = row
			} else {
				queue = append(queue, row)
			}
			return true
		}
		init.run(pc, push)
		count := int64(0)
		for len(queue) > 0 {
			row := queue[0]
			queue = queue[1:]
			if limit >= 0 && count >= limit {
				return true
			}
			if offset > 0 {
				offset--
			} else {
				count++
				if !emit(row) {
					return false
				}
			}
			saved := d.recCurrent
			d.recCurrent = [][]Value{row}
			for _, r := range recs {
