cd /workspace/src && cat > planner.go <<'EOF'
package main

import (
	"math"
	"sort"
	"strings"
)

const (
	apFull = iota
	apRowidEq
	apRowidIn
	apRowidRange
	apIndexEq
	apIndexIn
	apIndexRange
	apIndexScan
	apAutoIndex
)

type accessPath struct {
	kind    int
	index   *Index
	eq      []cexpr
	eqAff   []Affinity
	in      []cexpr
	inSel   *compiledSelect
	inAff   Affinity
	lo, hi  *cexpr
	loIncl  bool
	hiIncl  bool
	loAff   Affinity
	hiAff   Affinity
	cost    float64
	nOut    float64
	desc    bool
	autoCol int
	autoAff Affinity
	autoColl string
	autoProbe *cexpr
	nEq     int
}

// a constraint on a single column of a source
type colConstraint struct {
	term   *termInfo
	col    int // -1 rowid
	op     string // =, <, <=, >, >=, IN
	other  *Expr
	otherC cexpr
	deps   uint64
	aff    Affinity
	coll   string
	inList []*Expr
	inSel  *Select
}

type joinPlan struct {
	order  []*fromSrc
	levels [][]cexpr // terms at each level (in join order)
	nsrc   int
	allTerms []cexpr // terms with no deps evaluated first
	run    func(c *Ctx, f func() bool)
}

func (cp *compiler) analyzeConstraints(s *fromSrc, terms []*termInfo, sc *scope) []*colConstraint {
	var out []*colConstraint
	bit := uint64(1) << uint(s.info.idx)
	for _, t := range terms {
		if t.isOn && t.srcIdx != s.order {
			continue
		}
		if t.deps&bit == 0 {
			continue
		}
		e := t.e
		for e.Paren && false {
		}
		switch e.Op {
		case EBinary:
			op := e.Name
			if op != "=" && op != "<" && op != "<=" && op != ">" && op != ">=" && op != "IS" {
				continue
			}
			if e.L.Op == EVector || e.R.Op == EVector {
				continue
			}
			for side := 0; side < 2; side++ {
				colE, othE := e.L, e.R
				o := op
				if side == 1 {
					colE, othE = e.R, e.L
					o = flipOp(op)
				}
				col, ok := cp.isSrcColumn(colE, s, sc)
				if !ok {
					continue
				}
				oc, od := cp.compileWithDeps(othE, sc)
				if od&bit != 0 {
					continue
				}
				cc, _ := cp.compileWithDeps(colE, sc)
				cst := &colConstraint{term: t, col: col, op: o, other: othE, otherC: oc, deps: od}
				cst.aff = cmpAffinity(cc, oc)
				if side == 1 {
					cst.aff = cmpAffinity(oc, cc)
					cst.coll = cmpCollation(oc, cc)
				} else {
					cst.coll = cmpCollation(cc, oc)
				}
				if o == "IS" {
					cst.op = "="
					if oc.isConst && oc.val.K == KNull {
						continue
					}
				}
				out = append(out, cst)
			}
		case EBetween:
			if e.Not {
				continue
			}
			col, ok := cp.isSrcColumn(e.L, s, sc)
			if !ok {
				continue
			}
			cc, _ := cp.compileWithDeps(e.L, sc)
			for i, b := range e.List {
				oc, od := cp.compileWithDeps(b, sc)
				if od&bit != 0 {
					continue
				}
				o := ">="
				if i == 1 {
					o = "<="
				}
				out = append(out, &colConstraint{term: t, col: col, op: o, other: b, otherC: oc, deps: od, aff: cmpAffinity(cc, oc), coll: cmpCollation(cc, oc)})
			}
		case EIn:
			if e.Not || e.Name != "" {
				continue
			}
			if e.L.Op == EVector {
				continue
			}
			col, ok := cp.isSrcColumn(e.L, s, sc)
			if !ok {
				continue
			}
			cc, _ := cp.compileWithDeps(e.L, sc)
			if e.Sel != nil {
				continue
			}
			var deps uint64
			okAll := true
			aff := AffNone
			coll := cc.coll
			for _, it := range e.List {
				oc, od := cp.compileWithDeps(it, sc)
				if od&bit != 0 {
					okAll = false
					break
				}
				deps |= od
				aff = cmpAffinity(cc, oc)
				coll = cmpCollation(cc, oc)
			}
			if !okAll || len(e.List) == 0 {
				continue
			}
			out = append(out, &colConstraint{term: t, col: col, op: "IN", inList: e.List, deps: deps, aff: aff, coll: coll})
		}
	}
	// OR of equalities on same column -> IN
	for _, t := range terms {
		if t.isOn && t.srcIdx != s.order {
			continue
		}
		if t.deps != bit {
			continue
		}
		if t.e.Op == EBinary && t.e.Name == "OR" {
			disj := splitOr(t.e)
			col := -2
			var list []*Expr
			ok := true
			var aff Affinity
			var coll string
			for _, d := range disj {
				if d.Op != EBinary || d.Name != "=" {
					ok = false
					break
				}
				c1, ok1 := cp.isSrcColumn(d.L, s, sc)
				other := d.R
				if !ok1 {
					c1, ok1 = cp.isSrcColumn(d.R, s, sc)
					other = d.L
				}
				if !ok1 || (col != -2 && c1 != col) {
					ok = false
					break
				}
				oc, od := cp.compileWithDeps(other, sc)
				if od != 0 {
					ok = false
					break
				}
				cc, _ := cp.compileWithDeps(d.L, sc)
				aff = cmpAffinity(cc, oc)
				coll = cmpCollation(cc, oc)
				col = c1
				list = append(list, other)
			}
			if ok && col != -2 {
				out = append(out, &colConstraint{term: t, col: col, op: "IN", inList: list, aff: aff, coll: coll})
			}
		}
	}
	return out
}

func splitOr(e *Expr) []*Expr {
	if e.Op == EBinary && e.Name == "OR" {
		return append(splitOr(e.L), splitOr(e.R)...)
	}
	return []*Expr{e}
}

func flipOp(op string) string {
	switch op {
	case "<":
		return ">"
	case "<=":
		return ">="
	case ">":
		return "<"
	case ">=":
		return "<="
	}
	return op
}

// isSrcColumn: is e a direct column reference to source s? returns column index (-1 rowid)
func (cp *compiler) isSrcColumn(e *Expr, s *fromSrc, sc *scope) (int, bool) {
	if e.Op != EColumn {
		return 0, false
	}
	if s.kind != srcTable && s.kind != srcSub && s.kind != srcCTE {
		return 0, false
	}
	x, deps := cp.compileWithDeps(e, sc)
	if !x.isColumn || x.depth != 0 || x.srcIdx != s.info.idx || deps != uint64(1)<<uint(s.info.idx) {
		return 0, false
	}
	if x.colIdx == -1 {
		return -1, true
	}
	if s.table != nil && s.table.IPK == x.colIdx {
		return -1, true
	}
	return x.colIdx, true
}

const estRows = 1048576.0

func idxCovers(ix *Index, needed map[int]bool, t *Table) bool {
	for c := range needed {
		if c == -1 {
			continue
		}
		if t.IPK == c {
			continue
		}
		found := false
		for _, ic := range ix.Cols {
			if ic.Col == c {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

// choose best access path for table source given bound sources mask
func (cp *compiler) bestPath(s *fromSrc, cons []*colConstraint, bound uint64, needed map[int]bool, sc *scope) *accessPath {
	full := &accessPath{kind: apFull, cost: estRows * 3, nOut: estRows}
	if s.kind != srcTable {
		// subquery/cte: possibly automatic index on equality
		best := full
		for _, c := range cons {
			if c.op == "=" && c.deps&^bound == 0 && c.deps != 0 {
				ap := &accessPath{kind: apAutoIndex, autoCol: c.col, autoAff: c.aff, autoColl: c.coll, cost: 40, nOut: 10}
				oc := c.otherC
				ap.autoProbe = &oc
				ap.cost = 40
				if best.kind == apFull {
					best = ap
				}
			}
		}
		return best
	}
	t := s.table
	usable := func(c *colConstraint) bool { return c.deps&^bound == 0 }
	if s.notIndexed {
		return full
	}
	// rowid equality
	if !t.WithoutRowid && s.indexedBy == "" {
		for _, c := range cons {
			if c.col == -1 && usable(c) {
				if c.op == "=" {
					return &accessPath{kind: apRowidEq, eq: []cexpr{c.otherC}, eqAff: []Affinity{AffInteger}, cost: 20, nOut: 1}
				}
			}
		}
		for _, c := range cons {
			if c.col == -1 && usable(c) && c.op == "IN" {
				ap := &accessPath{kind: apRowidIn, inAff: AffInteger, cost: 20 * float64(len(c.inList)), nOut: float64(len(c.inList))}
				for _, it := range c.inList {
					x := cp.compileExpr(it, sc)
					ap.in = append(ap.in, x)
				}
				return ap
			}
		}
	}
	var best *accessPath
	betterThan := func(a, b *accessPath) bool {
		if b == nil {
			return true
		}
		return a.cost <= b.cost
	}
	// indexes in creation order; later ones win ties
	idxs := t.Indexes
	for _, ix := range idxs {
		if s.indexedBy != "" && !strings.EqualFold(ix.Name, s.indexedBy) {
			continue
		}
		if ix.Where != nil {
			// partial index: only usable if WHERE implies; skip for simplicity
			if !cp.partialUsable(ix, cons) {
				continue
			}
		}
		var eqs []cexpr
		var affs []Affinity
		nEq := 0
		var inC *colConstraint
		for k, ic := range ix.Cols {
			var found *colConstraint
			for _, c := range cons {
				if c.col == ic.Col && ic.Col >= 0 && c.op == "=" && usable(c) && collMatches(c, ic) {
					found = c
					break
				}
			}
			if found == nil {
				if k == nEq && inC == nil {
					for _, c := range cons {
						if c.col == ic.Col && ic.Col >= 0 && c.op == "IN" && usable(c) && collMatches(c, ic) {
							inC = c
							break
						}
					}
				}
				break
			}
			eqs = append(eqs, found.otherC)
			affs = append(affs, ixColAff(t, ic, found.aff))
			nEq++
		}
		covering := idxCovers(ix, needed, t)
		lookupCost := 20.0
		if !covering {
			lookupCost = 40
		}
		if nEq > 0 {
			nOut := 10.0
			if ix.Unique && nEq == len(ix.Cols) {
				nOut = 1
			} else {
				for k := 1; k < nEq; k++ {
					nOut = math.Max(1, nOut*0.9)
				}
			}
			ap := &accessPath{kind: apIndexEq, index: ix, eq: eqs, eqAff: affs, nEq: nEq, cost: lookupCost + nOut*lookupCost/2 - float64(nEq), nOut: nOut}
			// range on next column?
			if nEq < len(ix.Cols) {
				cp.addRange(ap, ix.Cols[nEq], cons, usable, t)
			}
			if betterThan(ap, best) {
				best = ap
			}
			continue
		}
		if inC != nil {
			ap := &accessPath{kind: apIndexIn, index: ix, inAff: ixColAff(t, ix.Cols[0], inC.aff), cost: float64(len(inC.inList)) * (lookupCost + 10), nOut: float64(len(inC.inList)) * 10}
			for _, it := range inC.inList {
				ap.in = append(ap.in, cp.compileExpr(it, sc))
			}
			if betterThan(ap, best) {
				best = ap
			}
			continue
		}
		// range on first column
		ap := &accessPath{kind: apIndexRange, index: ix}
		if cp.addRange(ap, ix.Cols[0], cons, usable, t) {
			nOut := estRows / 4
			if ap.lo != nil && ap.hi != nil {
				nOut = estRows / 64
			}
			ap.nOut = nOut
			ap.cost = nOut * lookupCost / 10
			if betterThan(ap, best) {
				best = ap
			}
		}
	}
	// rowid range
	if !t.WithoutRowid && s.indexedBy == "" {
		ap := &accessPath{kind: apRowidRange}
		if cp.addRange(ap, IdxCol{Col: -1}, cons, usable, t) {
			nOut := estRows / 4
			if ap.lo != nil && ap.hi != nil {
				nOut = estRows / 64
			}
			ap.nOut = nOut
			ap.cost = nOut * 1.5
			if best == nil || ap.cost < best.cost {
				best = ap
			}
		}
	}
	if best != nil {
		return best
	}
	// automatic index for joins
	for _, c := range cons {
		if c.op == "=" && usable(c) && c.deps != 0 && c.col >= 0 {
			oc := c.otherC
			return &accessPath{kind: apAutoIndex, autoCol: c.col, autoAff: c.aff, autoColl: c.coll, autoProbe: &oc, cost: 45, nOut: 10}
		}
	}
	// covering index scan
	if s.indexedBy != "" {
		for _, ix := range t.Indexes {
			if strings.EqualFold(ix.Name, s.indexedBy) {
				return &accessPath{kind: apIndexScan, index: ix, cost: estRows * 2, nOut: estRows}
			}
		}
	}
	if !t.WithoutRowid {
		var bestIx *Index
		for _, ix := range t.Indexes {
			if ix.Where != nil {
				continue
			}
			if idxCovers(ix, needed, t) {
				if bestIx == nil || len(ix.Cols) < len(bestIx.Cols) || (len(ix.Cols) == len(bestIx.Cols)) {
					bestIx = ix
				}
			}
		}
		if bestIx != nil && len(bestIx.Cols) < len(t.Cols) {
			return &accessPath{kind: apIndexScan, index: bestIx, cost: estRows * 2, nOut: estRows}
		}
	} else if t.pkIndex != nil {
		return &accessPath{kind: apIndexScan, index: t.pkIndex, cost: estRows * 3, nOut: estRows}
	}
	return full
}

func (cp *compiler) partialUsable(ix *Index, cons []*colConstraint) bool {
	w := ix.Where
	for _, c := range cons {
		if exprEqual(c.term.e, w) {
			return true
		}
	}
	// simple: "col IS NOT NULL" / "col NOT NULL" implied by any constraint on col
	if w.Op == EIsNull && w.Not && w.L.Op == EColumn {
		ci := ix.Table.colIndex(w.L.Column)
		for _, c := range cons {
			if c.col == ci && c.op != "IN" {
				return true
			}
		}
	}
	return false
}

func collMatches(c *colConstraint, ic IdxCol) bool {
	a := strings.ToUpper(c.coll)
	b := strings.ToUpper(ic.CollName)
	if a == "BINARY" {
		a = ""
	}
	if b == "BINARY" {
		b = ""
	}
	return a == b
}

func ixColAff(t *Table, ic IdxCol, aff Affinity) Affinity {
	return aff
}

func (cp *compiler) addRange(ap *accessPath, ic IdxCol, cons []*colConstraint, usable func(*colConstraint) bool, t *Table) bool {
	found := false
	for _, c := range cons {
		if c.col != ic.Col || !usable(c) {
			continue
		}
		if ic.Col >= 0 && !collMatches(c, ic) {
			continue
		}
		oc := c.otherC
		switch c.op {
		case ">", ">=":
			if ap.lo == nil {
				ap.lo = &oc
				ap.loIncl = c.op == ">="
				ap.loAff = c.aff
				found = true
			}
		case "<", "<=":
			if ap.hi == nil {
				ap.hi = &oc
				ap.hiIncl = c.op == "<="
				ap.hiAff = c.aff
				found = true
			}
		}
	}
	if found && ic.Desc {
		// swap semantics for descending index: handled at run time
	}
	return found
}

// neededColumns: which columns of source s are referenced anywhere (approx: by name scan of select AST)
func neededColumns(s *fromSrc, sel *Select, cols []*ResultCol, multi bool) map[int]bool {
	need := map[int]bool{}
	if s.table == nil {
		return need
	}
	t := s.table
	var walk func(e *Expr)
	walk = func(e *Expr) {
		if e == nil {
			return
		}
		if e.Op == EColumn {
			if e.srcHint > 0 {
				if e.srcHint-1 == s.info.idx {
					need[e.colHint-1] = true
				}
			} else if e.Table == "" || strings.EqualFold(e.Table, s.info.name) {
				ci := t.colIndex(e.Column)
				if ci >= 0 {
					need[ci] = true
				} else if isRowidName(e.Column) {
					need[-1] = true
				}
			}
		}
		walk(e.L)
		walk(e.R)
		walk(e.Escape)
		walk(e.Filter)
		for _, x := range e.List {
			walk(x)
		}
		for _, x := range e.TblArgs {
			walk(x)
		}
		for _, o := range e.OrderBy {
			walk(o.E)
		}
		if e.Over != nil {
			for _, x := range e.Over.Partition {
				walk(x)
			}
			for _, o := range e.Over.OrderBy {
				walk(o.E)
			}
		}
		if e.Sel != nil {
			walkSelect(e.Sel, walk)
		}
	}
	for _, rc := range cols {
		walk(rc.E)
	}
	if sel != nil {
		walk(sel.Where)
		for _, g := range sel.GroupBy {
			walk(g)
		}
		walk(sel.Having)
		for _, o := range sel.OrderBy {
			walk(o.E)
		}
		for _, f := range flattenFrom(sel.From) {
			walk(f.On)
			for _, u := range f.Using {
				if ci := t.colIndex(u); ci >= 0 {
					need[ci] = true
				}
			}
			if f.Join&JNatural != 0 {
				for i := range t.Cols {
					need[i] = true
				}
			}
		}
	}
	return need
}

func walkSelect(sel *Select, walk func(*Expr)) {
	for s := sel; s != nil; s = s.Prior {
		for _, rc := range s.Cols {
			walk(rc.E)
		}
		walk(s.Where)
		for _, g := range s.GroupBy {
			walk(g)
		}
		walk(s.Having)
		for _, o := range s.OrderBy {
			walk(o.E)
		}
		for _, f := range s.From {
			walk(f.On)
			if f.Sel != nil {
				walkSelect(f.Sel, walk)
			}
		}
		for _, r := range s.Values {
			for _, x := range r {
				walk(x)
			}
		}
	}
}

func (cp *compiler) planJoins(srcs []*fromSrc, terms []*termInfo, sc *scope, cols []*ResultCol, sel *Select, isAgg bool) *joinPlan {
	n := len(srcs)
	jp := &joinPlan{nsrc: n}
	// constraints per source
	cons := make([][]*colConstraint, n)
	needed := make([]map[int]bool, n)
	for i, s := range srcs {
		cons[i] = cp.analyzeConstraints(s, terms, sc)
		needed[i] = neededColumns(s, sel, cols, n > 1)
		if sel != nil && sel.Cols != nil {
			for _, rc := range sel.Cols {
				if rc.Star && (rc.Table == "" || strings.EqualFold(rc.Table, s.info.name)) && s.table != nil {
					for ci := range s.table.Cols {
						needed[i][ci] = true
					}
				}
			}
		}
	}
	// determine join order
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	canReorder := n > 1 && n <= 6
	for _, s := range srcs {
		if s.join&(JLeft|JRight|JCross) != 0 {
			canReorder = false
		}
	}
	paths := make([]*accessPath, n)
	if canReorder {
		bestCost := math.Inf(1)
		var bestOrder []int
		var bestPaths []*accessPath
		perm := make([]int, n)
		used := make([]bool, n)
		var rec func(k int, bound uint64, rows float64, cost float64, ps []*accessPath)
		rec = func(k int, bound uint64, rows float64, cost float64, ps []*accessPath) {
			if cost >= bestCost {
				return
			}
			if k == n {
				bestCost = cost
				bestOrder = append([]int(nil), perm...)
				bestPaths = append([]*accessPath(nil), ps...)
				return
			}
			for i := 0; i < n; i++ {
				if used[i] {
					continue
				}
				ap := cp.bestPath(srcs[i], cons[i], bound, needed[i], sc)
				c := rows * ap.cost
				if ap.kind == apAutoIndex {
					c += estRows * 20
				}
				nrows := rows * ap.nOut
				// filter factor of terms bound now
				used[i] = true
				perm[k] = i
				rec(k+1, bound|uint64(1)<<uint(srcs[i].info.idx), nrows, cost+c, append(ps, ap))
				used[i] = false
			}
		}
		rec(0, 0, 1, 0, nil)
		order = bestOrder
		for k, i := range order {
			paths[i] = bestPaths[k]
		}
	} else {
		var bound uint64
		for _, i := range order {
			paths[i] = cp.bestPath(srcs[i], cons[i], bound, needed[i], sc)
			bound |= uint64(1) << uint(srcs[i].info.idx)
		}
	}
	jp.order = make([]*fromSrc, n)
	for k, i := range order {
		jp.order[k] = srcs[i]
		srcs[i].path = paths[i]
	}
	// assign terms to levels
	posOf := make([]int, n) // srcIdx -> level
	for k, s := range jp.order {
		posOf[s.info.idx] = k
	}
	jp.levels = make([][]cexpr, n)
	onLevels := make([][]cexpr, n)
	for _, t := range terms {
		if t.isOn {
			lv := posOf[srcs[t.srcIdx].info.idx]
			onLevels[lv] = append(onLevels[lv], t.c)
			continue
		}
		lv := -1
		for i := 0; i < n; i++ {
			if t.deps&(uint64(1)<<uint(i)) != 0 {
				if posOf[i] > lv {
					lv = posOf[i]
				}
			}
		}
		// terms must be evaluated no earlier than any left-joined source they reference
		if lv < 0 {
			jp.allTerms = append(jp.allTerms, t.c)
			continue
		}
		jp.levels[lv] = append(jp.levels[lv], t.c)
	}
	for k, s := range jp.order {
		if len(onLevels[k]) > 0 {
			ons := onLevels[k]
			x := cexpr{fn: func(c *Ctx) Value {
				for _, o := range ons {
					v := o.fn(c)
					if !v.Bool() {
						return IntValue(0)
					}
				}
				return IntValue(1)
			}}
			s.on = &x
		}
	}
	hasRight := false
	for _, s := range jp.order {
		if s.join&JRight != 0 {
			hasRight = true
		}
	}
	levels := jp.levels
	orderSrcs := jp.order
	pre := jp.allTerms
	jp.run = func(c *Ctx, f func() bool) {
		for _, t := range pre {
			if !t.fn(c).Bool() {
				return
			}
		}
		if n == 0 {
			f()
			return
		}
		for _, s := range orderSrcs {
			if s.join&JRight != 0 {
				s.matched = map[int]bool{}
			}
		}
		var loop func(k int) bool
		loop = func(k int) bool {
			if k == n {
				return f()
			}
			s := orderSrcs[k]
			lt := levels[k]
			matched := false
			cont := true
			idx := s.info.idx
			trackRight := s.join&JRight != 0
			s.iterate(c, func(row []Value, rowid int64, pos int) bool {
				c.rows[idx] = row
				c.rowids[idx] = rowid
				if s.on != nil && !s.on.fn(c).Bool() {
					return true
				}
				matched = true
				if trackRight {
					s.matched[pos] = true
				}
				for _, t := range lt {
					if !t.fn(c).Bool() {
						return true
					}
				}
				if !loop(k + 1) {
					cont = false
					return false
				}
				return true
			})
			if !cont {
				return false
			}
			if !matched && s.join&JLeft != 0 {
				c.rows[idx] = nil
				c.rowids[idx] = 0
				for _, t := range lt {
					if !t.fn(c).Bool() {
						return true
					}
				}
				return loop(k + 1)
			}
			return true
		}
		if !loop(0) {
			return
		}
		if hasRight {
			for k, s := range orderSrcs {
				if s.join&JRight == 0 {
					continue
				}
				idx := s.info.idx
				stop := false
				s.iterate(c, func(row []Value, rowid int64, pos int) bool {
					if s.matched[pos] {
						return true
					}
					for j := 0; j < k; j++ {
						c.rows[orderSrcs[j].info.idx] = nil
					}
					c.rows[idx] = row
					c.rowids[idx] = rowid
					for j := 0; j <= k; j++ {
						for _, t := range levels[j] {
							if !t.fn(c).Bool() {
								return true
							}
						}
					}
					if !loop(k + 1) {
						stop = true
						return false
					}
					return true
				})
				if stop {
					return
				}
			}
		}
	}
	return jp
}

// iterate over a source's rows according to its access path
func (s *fromSrc) iterate(c *Ctx, f func(row []Value, rowid int64, pos int) bool) {
	switch s.kind {
	case srcTable:
		s.iterateTable(c, f)
	case srcSub, srcCTE:
		rows := s.materialize(c)
		if s.path != nil && s.path.kind == apAutoIndex {
			s.iterateAuto(c, rows, f)
			return
		}
		for i, r := range rows {
			if !f(r, int64(i+1), i) {
				return
			}
		}
	case srcRecCTE:
		rows := s.cte.recCurrent
		for i, r := range rows {
			if !f(r, int64(i+1), i) {
				return
			}
		}
	case srcTVF:
		rows := s.tvfRows(c)
		for i, r := range rows {
			if !f(r, int64(i+1), i) {
				return
			}
		}
	case srcSingle:
		f([]Value{}, 0, 0)
	}
}

func (s *fromSrc) materialize(c *Ctx) [][]Value {
	if !s.sub.correlated && s.subGen == c.conn.stmtGen && s.subCache != nil {
		return s.subCache
	}
	var rows [][]Value
	s.sub.run(c.parent, func(r []Value) bool {
		rows = append(rows, append([]Value(nil), r...))
		return true
	})
	if rows == nil {
		rows = [][]Value{}
	}
	s.subCache = rows
	s.subGen = c.conn.stmtGen
	s.autoIdx = nil
	return rows
}

func (s *fromSrc) iterateAuto(c *Ctx, rows [][]Value, f func(row []Value, rowid int64, pos int) bool) {
	ap := s.path
	if s.autoIdx == nil || s.autoGen != c.conn.stmtGen {
		m := map[string][]int{}
		for i, r := range rows {
			v := r[ap.autoCol]
			if v.K == KNull {
				continue
			}
			v = applyCmpAff(v, ap.autoAff)
			k := string(appendValueKey(nil, v, strings.ToUpper(ap.autoColl)))
			m[k] = append(m[k], i)
		}
		s.autoIdx = m
		s.autoGen = c.conn.stmtGen
	}
	pv := ap.autoProbe.fn(c)
	if pv.K == KNull {
		return
	}
	pv = applyCmpAff(pv, ap.autoAff)
	k := string(appendValueKey(nil, pv, strings.ToUpper(ap.autoColl)))
	for _, i := range s.autoIdx[k] {
		if !f(rows[i], int64(i+1), i) {
			return
		}
	}
}

func probeRowid(v Value) (int64, bool) {
	v = applyNumericAffinityCmp(v)
	switch v.K {
	case KInt:
		return v.I, true
	case KReal:
		if v.F == math.Trunc(v.F) && v.F >= -9.2233720368547758e18 && v.F < 9.2233720368547758e18 {
			return int64(v.F), true
		}
	}
	return 0, false
}

func (s *fromSrc) iterateTable(c *Ctx, f func(row []Value, rowid int64, pos int) bool) {
	t := s.table
	ap := s.path
	if ap == nil {
		ap = &accessPath{kind: apFull}
	}
	switch ap.kind {
	case apRowidEq:
		v := ap.eq[0].fn(c)
		if v.K == KNull {
			return
		}
		id, ok := probeRowid(v)
		if !ok {
			return
		}
		if r := t.getRow(id); r != nil {
			f(r.Vals, r.Rowid, int(r.Rowid))
		}
		return
	case apRowidIn:
		var ids []int64
		seen := map[int64]bool{}
		for _, x := range ap.in {
			v := x.fn(c)
			if v.K == KNull {
				continue
			}
			id, ok := probeRowid(v)
			if ok && !seen[id] {
				seen[id] = true
				ids = append(ids, id)
			}
		}
		sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
		for _, id := range ids {
			if r := t.getRow(id); r != nil {
				if !f(r.Vals, r.Rowid, int(r.Rowid)) {
					return
				}
			}
		}
		return
	case apRowidRange:
		start := 0
		end := len(t.rows)
		if ap.lo != nil {
			v := ap.lo.fn(c)
			if v.K == KNull {
				return
			}
			v = applyNumericAffinityCmp(v)
			if v.K == KText || v.K == KBlob {
				return
			}
			fl := v.Float()
			var lo int64
			if v.K == KInt {
				lo = v.I
				if !ap.loIncl {
					if lo == math.MaxInt64 {
						return
					}
					lo++
				}
			} else {
				if fl > 9.2e18 {
					return
				}
				if fl < -9.2e18 {
					lo = math.MinInt64
				} else {
					lo = int64(math.Ceil(fl))
					if !ap.loIncl && float64(lo) == fl {
						lo++
					}
				}
			}
			start = sort.Search(len(t.rows), func(i int) bool { return t.rows[i].Rowid >= lo })
		}
		if ap.hi != nil {
			v := ap.hi.fn(c)
			if v.K == KNull {
				return
			}
			v = applyNumericAffinityCmp(v)
			if v.K == KInt || v.K == KReal {
				fl := v.Float()
				var hi int64
				if v.K == KInt {
					hi = v.I
					if !ap.hiIncl {
						if hi == math.MinInt64 {
							return
						}
						hi--
					}
				} else {
					if fl < -9.2e18 {
						return
					}
					if fl > 9.2e18 {
						hi = math.MaxInt64
					} else {
						hi = int64(math.Floor(fl))
						if !ap.hiIncl && float64(hi) == fl {
							hi--
						}
					}
				}
				end = sort.Search(len(t.rows), func(i int) bool { return t.rows[i].Rowid > hi })
			}
		}
		rows := t.rows
		for i := start; i < end && i < len(rows); i++ {
			r := rows[i]
			if !f(r.Vals, r.Rowid, int(r.Rowid)) {
				return
			}
		}
		return
	case apIndexEq, apIndexRange, apIndexIn, apIndexScan:
		s.iterateIndex(c, ap, f)
		return
	case apAutoIndex:
		s.iterateTableAuto(c, ap, f)
		return
	}
	// full scan: snapshot rows slice
	rows := t.rows
	for _, r := range rows {
		if !f(r.Vals, r.Rowid, int(r.Rowid)) {
			return
		}
	}
}

func (s *fromSrc) iterateTableAuto(c *Ctx, ap *accessPath, f func(row []Value, rowid int64, pos int) bool) {
	t := s.table
	if s.autoIdx == nil || s.autoGen != c.conn.stmtGen || s.autoVer != t.version {
		m := map[string][]int{}
		for i, r := range t.rows {
			v := r.Vals[ap.autoCol]
			if v.K == KNull {
				continue
			}
			v = applyCmpAff(v, ap.autoAff)
			k := string(appendValueKey(nil, v, strings.ToUpper(ap.autoColl)))
			m[k] = append(m[k], i)
		}
		s.autoIdx = m
		s.autoGen = c.conn.stmtGen
		s.autoVer = t.version
		s.autoRows = t.rows
	}
	pv := ap.autoProbe.fn(c)
	if pv.K == KNull {
		return
	}
	pv = applyCmpAff(pv, ap.autoAff)
	k := string(appendValueKey(nil, pv, strings.ToUpper(ap.autoColl)))
	rows := s.autoRows
	for _, i := range s.autoIdx[k] {
		r := rows[i]
		if !f(r.Vals, r.Rowid, int(r.Rowid)) {
			return
		}
	}
}

func (s *fromSrc) iterateIndex(c *Ctx, ap *accessPath, f func(row []Value, rowid int64, pos int) bool) {
	ix := ap.index
	t := s.table
	entries := ix.entries
	emitRange := func(lo, hi int) bool {
		for i := lo; i < hi && i < len(entries); i++ {
			r := t.getRow(entries[i].rowid)
			if r == nil {
				continue
			}
			if !f(r.Vals, r.Rowid, int(r.Rowid)) {
				return false
			}
		}
		return true
	}
	switch ap.kind {
	case apIndexScan:
		emitRange(0, len(entries))
		return
	case apIndexEq:
		key := make([]Value, len(ap.eq))
		for i, e := range ap.eq {
			v := e.fn(c)
			if v.K == KNull {
				return
			}
			key[i] = applyCmpAff(v, ap.eqAff[i])
		}
		lo := ix.lowerBound(key)
		hi := ix.upperBound(key)
		if ap.lo != nil || ap.hi != nil {
			// filter by range on next column via callback (terms recheck)
		}
		emitRange(lo, hi)
		return
	case apIndexIn:
		var keys []Value
		seen := map[string]bool{}
		coll := ix.Cols[0].CollName
		for _, x := range ap.in {
			v := x.fn(c)
			if v.K == KNull {
				continue
			}
			v = applyCmpAff(v, ap.inAff)
			k := string(appendValueKey(nil, v, strings.ToUpper(coll)))
			if !seen[k] {
				seen[k] = true
				keys = append(keys, v)
			}
		}
		cl := ix.Cols[0].Coll
		desc := ix.Cols[0].Desc
		sort.SliceStable(keys, func(i, j int) bool {
			r := compareValues(keys[i], keys[j], cl)
			if desc {
				return r > 0
			}
			return r < 0
		})
		for _, k := range keys {
			lo := ix.lowerBound([]Value{k})
			hi := ix.upperBound([]Value{k})
			if !emitRange(lo, hi) {
				return
			}
		}
		return
	case apIndexRange:
		lo := 0
		hi := len(entries)
		desc := ix.Cols[0].Desc
		if ap.lo != nil {
			v := ap.lo.fn(c)
			if v.K == KNull {
				return
			}
			v = applyCmpAff(v, ap.loAff)
			if !desc {
				if ap.loIncl {
					lo = ix.lowerBound([]Value{v})
				} else {
					lo = ix.upperBound([]Value{v})
				}
			} else {
				if ap.loIncl {
					hi = ix.upperBound([]Value{v})
				} else {
					hi = ix.lowerBound([]Value{v})
				}
			}
		}
		if ap.hi != nil {
			v := ap.hi.fn(c)
			if v.K == KNull {
				return
			}
			v = applyCmpAff(v, ap.hiAff)
			if !desc {
				if ap.hiIncl {
					hi = ix.upperBound([]Value{v})
				} else {
					hi = ix.lowerBound([]Value{v})
				}
			} else {
				if ap.hiIncl {
					lo = ix.lowerBound([]Value{v})
				} else {
					lo = ix.upperBound([]Value{v})
				}
			}
		}
		// skip NULLs at the start for ascending scans with only upper bound
		if ap.lo == nil && !desc {
			for lo < hi && entries[lo].key[0].K == KNull {
				lo++
			}
		}
		if ap.hi == nil && desc {
			for hi > lo && entries[hi-1].key[0].K == KNull {
				hi--
			}
		}
		emitRange(lo, hi)
		return
	}
}
EOF
echo ok

