	if v.K == KNull {
		return false
	}
	sep := ","
	if len(args) > 1 {
		if args[1].K == KNull {
			sep = ""
		} else {
			sep = args[1].Text()
		}
	}
	s.items = append(s.items, concatItem{val: v.Text(), sep: sep, keys: okeys})
	return false
}

