	s.keys = append(s.keys, okeys)
	return false
}

func (s *jsonArrState) final() Value {
	idx := make([]int, len(s.items))
	for i := range idx {
		idx[i] = i
	}
	if s.specs != nil {
		sort.SliceStable(idx, func(a, b int) bool { return cmpOrderKeys(s.keys[idx[a]], s.keys[idx[b]], s.specs) < 0 })
	}
	var b strings.Builder
	b.WriteByte('[')
	for k, i := range idx {
		if k > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonValueText(s.items[i]))
	}
	b.WriteByte(']')
	if s.binary {
		return jsonToBlob(b.String())
	}
	return jsonTextValue(b.String())
}

type jsonObjState struct {
	names  []string
	vals   []Value
	keys   [][]Value
	specs  []orderSpec
	binary bool
}

func (s *jsonObjState) step(args []Value, okeys []Value) bool {
	if args[0].K == KNull {
		return false
	}
	s.names = append(s.names, args[0].Text())
	s.vals = append(s.vals, args[1])
	s.keys = append(s.keys, okeys)
	return false
}

func (s *jsonObjState) final() Value {
	idx := make([]int, len(s.vals))
	for i := range idx {
		idx[i] = i
	}
	if s.specs != nil {
		sort.SliceStable(idx, func(a, b int) bool { return cmpOrderKeys(s.keys[idx[a]], s.keys[idx[b]], s.specs) < 0 })
	}
	var b strings.Builder
	b.WriteByte('{')
	for k, i := range idx {
		if k > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonQuoteString(s.names[i]))
		b.WriteByte(':')
		b.WriteString(jsonValueText(s.vals[i]))
	}
	b.WriteByte('}')
	if s.binary {
		return jsonToBlob(b.String())
	}
	return jsonTextValue(b.String())
}

type pctState struct {
	kind  int
	fixed float64
	vals  []float64
	p     float64
	pSet  bool
}

func (s *pctState) step(args []Value, _ []Value) bool {
	if len(args) > 1 {
		pv := args[1]
		var p float64
		switch pv.K {
		case KInt, KReal:
			p = pv.Float()
		default:
			p = -1
		}
		if s.kind == 1 {
			if p < 0 || p > 100 {
				throw("the fraction argument to percentile() is not between 0.0 and 100.0")
			}
			p = p / 100
		} else {
			if p < 0 || p > 1 {
				throw("the fraction argument to %s() is not between 0.0 and 1.0", map[int]string{2: "percentile_cont", 3: "percentile_disc"}[s.kind])
			}
		}
		if s.pSet && p != s.p {
			throw("the fraction argument to %s() is not the same for all input rows", map[int]string{1: "percentile", 2: "percentile_cont", 3: "percentile_disc"}[s.kind])
		}
		s.p = p
		s.pSet = true
	}
	v := args[0]
	if v.K == KNull {
		return false
	}
	if v.K != KInt && v.K != KReal {
		n := applyNumericAffinityCmp(v)
		if n.K != KInt && n.K != KReal {
			throw("input to %s() is not numeric", map[int]string{0: "median", 1: "percentile", 2: "percentile_cont", 3: "percentile_disc"}[s.kind])
		}
		v = n
	}
	s.vals = append(s.vals, v.Float())
	return false
}

func (s *pctState) final() Value {
	if len(s.vals) == 0 {
		return NullValue
	}
	vals := append([]float64(nil), s.vals...)
	sort.Float64s(vals)
	p := s.p
	if s.kind == 0 {
		p = 0.5
	}
	if s.kind == 3 {
		i := int(math.Ceil(p*float64(len(vals)))) - 1
		if i < 0 {
			i = 0
		}
		_ = i
		ix := p * float64(len(vals)-1)
		i2 := int(ix)
		if ix > float64(i2) {
			// round down per percentile_disc
		}
		return RealValue(vals[i2])
	}
	ix := p * float64(len(vals)-1)
	i1 := int(math.Floor(ix))
	i2 := int(math.Ceil(ix))
	r := vals[i1]
	if i2 != i1 {
		r = vals[i1] + (vals[i2]-vals[i1])*(ix-float64(i1))
	}
	return RealValue(r)
}
