		"percentile_disc":   {name: "percentile_disc", minArg: 2, maxArg: 2, newState: func(a *aggCall) aggState { return &pctState{kind: 3} }},
	}
}

type countState struct {
	star bool
	n    int64
}

func (s *countState) step(args []Value, _ []Value) bool {
	if s.star || len(args) == 0 || args[0].K != KNull {
		s.n++
	}
	return false
}
func (s *countState) final() Value { return IntValue(s.n) }

type sumState struct {
	kind   int // 0 sum, 1 total, 2 avg
	cnt    int64
	iSum   int64
	rSum   float64
	rErr   float64
	approx bool
	ovrfl  bool
}

func (p *sumState) kbnStep(r float64) {
	s := p.rSum
	t := s + r
	if math.Abs(s) > math.Abs(r) {
		p.rErr += (s - t) + r
	} else {
		p.rErr += (r - t) + s
	}
	p.rSum = t
}

func (p *sumState) kbnStepInt(iVal int64) {
	if iVal <= -4503599627370496 || iVal >= 4503599627370496 {
		iSm := iVal % 16384
		iBig := iVal - iSm
		p.kbnStep(float64(iBig))
		p.kbnStep(float64(iSm))
	} else {
		p.kbnStep(float64(iVal))
	}
}

func (p *sumState) kbnInit(iVal int64) {
	if iVal <= -4503599627370496 || iVal >= 4503599627370496 {
		iSm := iVal % 16384
		p.rSum = float64(iVal - iSm)
		p.rErr = float64(iSm)
	} else {
		p.rSum = float64(iVal)
		p.rErr = 0
	}
}

func numericType(v Value) Value {
	if v.K == KText {
		n := applyNumericAffinityCmp(v)
		return n
	}
	return v
}

func (p *sumState) step(args []Value, _ []Value) bool {
	v := numericType(args[0])
	if v.K == KNull {
		return false
	}
	p.cnt++
	if !p.approx {
		if v.K != KInt {
			p.kbnInit(p.iSum)
			p.approx = true
			p.kbnStep(v.Float())
		} else {
			x := p.iSum + v.I
			if (p.iSum >= 0) == (v.I >= 0) && (x >= 0) != (p.iSum >= 0) {
				p.ovrfl = true
				p.kbnInit(p.iSum)
				p.approx = true
				p.kbnStepInt(v.I)
			} else {
				p.iSum = x
			}
		}
	} else {
		if v.K == KInt {
			p.kbnStepInt(v.I)
		} else {
			p.ovrfl = false
			p.kbnStep(v.Float())
		}
	}
	return false
}

func (p *sumState) final() Value {
	switch p.kind {
	case 0:
		if p.cnt == 0 {
			return NullValue
		}
		if p.approx {
			if p.ovrfl {
				panic(&SQLError{Msg: "integer overflow", Code: SQLITE_ERROR, Pos: -1})
			}
			if !math.IsInf(p.rSum, 0) {
				return RealValue(p.rSum + p.rErr)
			}
			return RealValue(p.rSum)
		}
		return IntValue(p.iSum)
	case 1:
		if p.approx {
			if !math.IsInf(p.rSum, 0) {
				return RealValue(p.rSum + p.rErr)
			}
			return RealValue(p.rSum)
		}
		return RealValue(float64(p.iSum))
	default:
		if p.cnt == 0 {
			return NullValue
		}
		var r float64
		if p.approx {
			r = p.rSum
			if !math.IsInf(r, 0) {
				r += p.rErr
			}
		} else {
			r = float64(p.iSum)
		}
		return RealValue(r / float64(p.cnt))
	}
}

type minMaxState struct {
	max  bool
	coll Collation
	val  Value
	has  bool
}

func (s *minMaxState) step(args []Value, _ []Value) bool {
	v := args[0]
	if v.K == KNull {
		return false
	}
	if !s.has {
		s.val = v
		s.has = true
		return true
	}
	c := compareValues(v, s.val, s.coll)
	if (s.max && c > 0) || (!s.max && c < 0) {
		s.val = v
		return true
	}
	return false
}
func (s *minMaxState) final() Value {
	if !s.has {
		return NullValue
	}
	return s.val
}

type concatItem struct {
	val  string
	sep  string
	keys []Value
}

type concatState struct {
	items []concatItem
	specs []orderSpec
	n     int
}

func (s *concatState) step(args []Value, okeys []Value) bool {
	v := args[0]
	if v.K == KNull {
		return false
	}
	sep := ","
	if len(args) > 1 {
		if args[1].K == KNull {
			sep = ""
		} else {
			sep = args[1].Text()
		}
	}
	s.items = append(s.items, concatItem{val: v.Text(), sep: sep, keys: okeys})
	return false
}

func (s *concatState) final() Value {
	if len(s.items) == 0 {
		return NullValue
	}
	items := s.items
	if s.specs != nil {
		items = append([]concatItem(nil), items...)
		sort.SliceStable(items, func(i, j int) bool { return cmpOrderKeys(items[i].keys, items[j].keys, s.specs) < 0 })
	}
	var b strings.Builder
	for i, it := range items {
		if i > 0 {
			b.WriteString(it.sep)
		}
		b.WriteString(it.val)
	}
	return TextValue(b.String())
}

type jsonArrState struct {
	items  []Value
	keys   [][]Value
	specs  []orderSpec
	binary bool
}

func (s *jsonArrState) step(args []Value, okeys []Value) bool {
	s.items = append(s.items, args[0])
	s.keys = append(s.keys, okeys)
	return false
}

func (s *jsonArrState) final() Value {
	idx := make([]int, len(s.items))
	for i := range idx {
		idx[i] = i
	}
	if s.specs != nil {
		sort.SliceStable(idx, func(a, b int) bool { return cmpOrderKeys(s.keys[idx[a]], s.keys[idx[b]], s.specs) < 0 })
	}
	var b strings.Builder
	b.WriteByte('[')
	for k, i := range idx {
		if k > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonValueText(s.items[i]))
	}
	b.WriteByte(']')
	if s.binary {
		return jsonToBlob(b.String())
	}
	return jsonTextValue(b.String())
}

type jsonObjState struct {
	names  []string
	vals   []Value
	keys   [][]Value
	specs  []orderSpec
	binary bool
}

func (s *jsonObjState) step(args []Value, okeys []Value) bool {
	if args[0].K == KNull {
		return false
	}
	s.names = append(s.names, args[0].Text())
	s.vals = append(s.vals, args[1])
	s.keys = append(s.keys, okeys)
	return false
}

func (s *jsonObjState) final() Value {
	idx := make([]int, len(s.vals))
	for i := range idx {
		idx[i] = i
	}
	if s.specs != nil {
		sort.SliceStable(idx, func(a, b int) bool { return cmpOrderKeys(s.keys[idx[a]], s.keys[idx[b]], s.specs) < 0 })
	}
	var b strings.Builder
	b.WriteByte('{')
	for k, i := range idx {
		if k > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonQuoteString(s.names[i]))
		b.WriteByte(':')
		b.WriteString(jsonValueText(s.vals[i]))
	}
	b.WriteByte('}')
	if s.binary {
		return jsonToBlob(b.String())
	}
	return jsonTextValue(b.String())
}

type pctState struct {
	kind  int
	fixed float64
	vals  []float64
	p     float64
	pSet  bool
}

func (s *pctState) step(args []Value, _ []Value) bool {
	if len(args) > 1 {
		pv := args[1]
		var p float64
		switch pv.K {
		case KInt, KReal:
			p = pv.Float()
		default:
			p = -1
		}
		if s.kind == 1 {
			if p < 0 || p > 100 {
				throw("the fraction argument to percentile() is not between 0.0 and 100.0")
			}
			p = p / 100
		} else {
			if p < 0 || p > 1 {
				throw("the fraction argument to %s() is not between 0.0 and 1.0", map[int]string{2: "percentile_cont", 3: "percentile_disc"}[s.kind])
			}
		}
		if s.pSet && p != s.p {
			throw("the fraction argument to %s() is not the same for all input rows", map[int]string{1: "percentile", 2: "percentile_cont", 3: "percentile_disc"}[s.kind])
		}
		s.p = p
		s.pSet = true
	}
	v := args[0]
	if v.K == KNull {
		return false
	}
	if v.K != KInt && v.K != KReal {
		n := applyNumericAffinityCmp(v)
		if n.K != KInt && n.K != KReal {
			throw("input to %s() is not numeric", map[int]string{0: "median", 1: "percentile", 2: "percentile_cont", 3: "percentile_disc"}[s.kind])
		}
		v = n
	}
	s.vals = append(s.vals, v.Float())
	return false
}

func (s *pctState) final() Value {
	if len(s.vals) == 0 {
		return NullValue
	}
	vals := append([]float64(nil), s.vals...)
	sort.Float64s(vals)
	p := s.p
	if s.kind == 0 {
		p = 0.5
	}
	if s.kind == 3 {
		i := int(math.Ceil(p*float64(len(vals)))) - 1
		if i < 0 {
			i = 0
		}
		_ = i
		ix := p * float64(len(vals)-1)
		i2 := int(ix)
		if ix > float64(i2) {
			// round down per percentile_disc
		}
		return RealValue(vals[i2])
	}
	ix := p * float64(len(vals)-1)
	i1 := int(math.Floor(ix))
	i2 := int(math.Ceil(ix))
	r := vals[i1]
	if i2 != i1 {
		r = vals[i1] + (vals[i2]-vals[i1])*(ix-float64(i1))
	}
	return RealValue(r)
}
