cd /workspace/src && cat > window.go <<'EOF'
package main

import (
	"sort"
)

type winCall struct {
	name       string
	agg        *aggDef
	aggc       *aggCall
	args       []cexpr
	partition  []cexpr
	partColl   []string
	order      []cexpr
	orderSpecs []orderSpec
	frame      *FrameSpec
	startOff   *cexpr
	endOff     *cexpr
	filter     *cexpr
	distinct   bool
	slot       int
	argColls   []string
}

var winOnlyFuncs = map[string][2]int{
	"row_number":   {0, 0},
	"rank":         {0, 0},
	"dense_rank":   {0, 0},
	"percent_rank": {0, 0},
	"cume_dist":    {0, 0},
	"ntile":        {1, 1},
	"lag":          {1, 3},
	"lead":         {1, 3},
	"first_value":  {1, 1},
	"last_value":   {1, 1},
	"nth_value":    {2, 2},
}

func computeWindows(c *Ctx, wins []*winCall, n int, setRow func(int), wvals [][]Value) []int {
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	// evaluate keys per window
	for wi := len(wins) - 1; wi >= 0; wi-- {
		w := wins[wi]
		np := len(w.partition)
		no := len(w.order)
		pkeys := make([][]Value, n)
		okeys := make([][]Value, n)
		args := make([][]Value, n)
		filt := make([]bool, n)
		for i := 0; i < n; i++ {
			setRow(i)
			if np > 0 {
				pk := make([]Value, np)
				for j, p := range w.partition {
					pk[j] = p.fn(c)
				}
				pkeys[i] = pk
			}
			if no > 0 {
				ok := make([]Value, no)
				for j, o := range w.order {
					ok[j] = o.fn(c)
				}
				okeys[i] = ok
			}
			if len(w.args) > 0 {
				a := make([]Value, len(w.args))
				for j, x := range w.args {
					a[j] = x.fn(c)
				}
				args[i] = a
			}
			filt[i] = true
			if w.filter != nil {
				filt[i] = w.filter.fn(c).Bool()
			}
		}
		pspecs := make([]orderSpec, np)
		for j := range pspecs {
			pspecs[j] = orderSpec{coll: getCollation(w.partColl[j])}
		}
		if np > 0 || no > 0 {
			sort.SliceStable(order, func(a, b int) bool {
				x, y := order[a], order[b]
				if np > 0 {
					cmp := cmpOrderKeys(pkeys[x], pkeys[y], pspecs)
					if cmp != 0 {
						return cmp < 0
					}
				}
				if no > 0 {
					return cmpOrderKeys(okeys[x], okeys[y], w.orderSpecs) < 0
				}
				return false
			})
		}
		// partitions
		start := 0
		for start < n {
			end := start + 1
			for end < n && (np == 0 || cmpOrderKeys(pkeys[order[start]], pkeys[order[end]], pspecs) == 0) {
				end++
			}
			part := order[start:end]
			computePartition(c, w, part, okeys, args, filt, wvals, setRow)
			start = end
		}
	}
	return order
}

func computePartition(c *Ctx, w *winCall, part []int, okeys [][]Value, args [][]Value, filt []bool, wvals [][]Value, setRow func(int)) {
	m := len(part)
	slot := w.slot
	// peer groups
	peerStart := make([]int, m)
	peerEnd := make([]int, m) // exclusive
	groupNo := make([]int, m)
	{
		g := 0
		i := 0
		for i < m {
			j := i + 1
			for j < m && (len(w.order) == 0 || cmpOrderKeys(okeys[part[i]], okeys[part[j]], w.orderSpecs) == 0) {
				j++
			}
			for k := i; k < j; k++ {
				peerStart[k] = i
				peerEnd[k] = j
				groupNo[k] = g
			}
			g++
			i = j
		}
	}
	switch w.name {
	case "row_number":
		for i := 0; i < m; i++ {
			wvals[part[i]][slot] = IntValue(int64(i + 1))
		}
		return
	case "rank":
		for i := 0; i < m; i++ {
			wvals[part[i]][slot] = IntValue(int64(peerStart[i] + 1))
		}
		return
	case "dense_rank":
		for i := 0; i < m; i++ {
			wvals[part[i]][slot] = IntValue(int64(groupNo[i] + 1))
		}
		return
	case "percent_rank":
		for i := 0; i < m; i++ {
			if m <= 1 {
				wvals[part[i]][slot] = RealValue(0)
			} else {
				wvals[part[i]][slot] = RealValue(float64(peerStart[i]) / float64(m-1))
			}
		}
		return
	case "cume_dist":
		for i := 0; i < m; i++ {
			wvals[part[i]][slot] = RealValue(float64(peerEnd[i]) / float64(m))
		}
		return
	case "ntile":
		for i := 0; i < m; i++ {
			nv := args[part[i]][0]
			nt := nv.Int()
			if nv.K == KNull || nt <= 0 {
				throw("argument of ntile must be a positive integer")
			}
			N := int64(m)
			size := N / nt
			rem := N % nt
			var bucket int64
			ii := int64(i)
			if size == 0 {
				bucket = ii + 1
			} else {
				big := rem * (size + 1)
				if ii < big {
					bucket = ii/(size+1) + 1
				} else {
					bucket = rem + (ii-big)/size + 1
				}
			}
			wvals[part[i]][slot] = IntValue(bucket)
		}
		return
	case "lag", "lead":
		for i := 0; i < m; i++ {
			a := args[part[i]]
			off := int64(1)
			if len(a) > 1 {
				if a[1].K == KNull {
					wvals[part[i]][slot] = NullValue
					continue
				}
				off = a[1].Int()
				if off < 0 {
					throw("argument of %s must be a non-negative integer", w.name)
				}
			}
			var j int64
			if w.name == "lag" {
				j = int64(i) - off
			} else {
				j = int64(i) + off
			}
			if j >= 0 && j < int64(m) {
				wvals[part[i]][slot] = args[part[j]][0]
			} else if len(a) > 2 {
				wvals[part[i]][slot] = a[2]
			} else {
				wvals[part[i]][slot] = NullValue
			}
		}
		return
	}
	// frame-based functions
	fr := w.frame
	ftype := "RANGE"
	startK := "UNBOUNDED PRECEDING"
	endK := "CURRENT ROW"
	exclude := ""
	if fr != nil {
		ftype = fr.Type
		startK = fr.Start.Kind
		endK = fr.End.Kind
		exclude = fr.Exclude
	} else if len(w.order) == 0 {
		endK = "UNBOUNDED FOLLOWING"
	}
	var startOff, endOff Value
	if w.startOff != nil {
		startOff = w.startOff.fn(c)
	}
	if w.endOff != nil {
		endOff = w.endOff.fn(c)
	}
	checkOff := func(v Value) {
		if ftype == "RANGE" {
			if v.K == KNull || (v.K != KInt && v.K != KReal) || v.Float() < 0 {
				throw("frame starting offset must be a non-negative number")
			}
		} else {
			if v.K != KInt || v.I < 0 {
				if v.K == KReal && v.F == float64(int64(v.F)) && v.F >= 0 {
					return
				}
				throw("frame starting offset must be a non-negative integer")
			}
		}
	}
	if w.startOff != nil {
		checkOff(startOff)
	}
	if w.endOff != nil {
		if ftype == "RANGE" {
			if endOff.K == KNull || (endOff.K != KInt && endOff.K != KReal) || endOff.Float() < 0 {
				throw("frame ending offset must be a non-negative number")
			}
		} else if endOff.K != KInt || endOff.I < 0 {
			throw("frame ending offset must be a non-negative integer")
		}
	}
	nGroups := 0
	if m > 0 {
		nGroups = groupNo[m-1] + 1
	}
	groupFirst := make([]int, nGroups)
	groupLast := make([]int, nGroups)
	for i := m - 1; i >= 0; i-- {
		groupFirst[groupNo[i]] = i
	}
	for i := 0; i < m; i++ {
		groupLast[groupNo[i]] = i
	}
	rangeBound := func(i int, kind string, off Value, isStart bool) int {
		// RANGE with offset: find rows whose order key within key +- off
		key := okeys[part[i]]
		if len(key) == 0 {
			if isStart {
				return 0
			}
			return m - 1
		}
		kv := key[0]
		desc := w.orderSpecs[0].desc
		if kv.K == KNull {
			// nulls are peers
			if isStart {
				return peerStart[i]
			}
			return peerEnd[i] - 1
		}
		if kv.K != KInt && kv.K != KReal {
			if isStart {
				return peerStart[i]
			}
			return peerEnd[i] - 1
		}
		o := off.Float()
		var target float64
		if (kind == "PRECEDING") != desc {
			target = kv.Float() - o
		} else {
			target = kv.Float() + o
		}
		if isStart {
			// first row j with key >= target (asc) or <= target (desc)
			for j := 0; j < m; j++ {
				kj := okeys[part[j]][0]
				if kj.K == KNull {
					continue
				}
				if kj.K != KInt && kj.K != KReal {
					continue
				}
				if (!desc && kj.Float() >= target) || (desc && kj.Float() <= target) {
					return j
				}
			}
			return m
		}
		last := -1
		for j := 0; j < m; j++ {
			kj := okeys[part[j]][0]
			if kj.K == KNull {
				if !desc {
					last = j
				}
				continue
			}
			if kj.K != KInt && kj.K != KReal {
				continue
			}
			if (!desc && kj.Float() <= target) || (desc && kj.Float() >= target) {
				last = j
			}
		}
		return last
	}
	frameOf := func(i int) (int, int) {
		var s, e int
		switch startK {
		case "UNBOUNDED PRECEDING":
			s = 0
		case "CURRENT ROW":
			if ftype == "ROWS" {
				s = i
			} else {
				s = peerStart[i]
			}
		case "PRECEDING":
			switch ftype {
			case "ROWS":
				s = i - int(startOff.Int())
			case "GROUPS":
				g := groupNo[i] - int(startOff.Int())
				if g < 0 {
					s = 0
				} else {
					s = groupFirst[g]
				}
			default:
				s = rangeBound(i, "PRECEDING", startOff, true)
			}
		case "FOLLOWING":
			switch ftype {
			case "ROWS":
				s = i + int(startOff.Int())
			case "GROUPS":
				g := groupNo[i] + int(startOff.Int())
				if g >= nGroups {
					s = m
				} else {
					s = groupFirst[g]
				}
			default:
				s = rangeBound(i, "FOLLOWING", startOff, true)
			}
		case "UNBOUNDED FOLLOWING":
			s = m
		}
		switch endK {
		case "UNBOUNDED FOLLOWING":
			e = m - 1
		case "CURRENT ROW":
			if ftype == "ROWS" {
				e = i
			} else {
				e = peerEnd[i] - 1
			}
		case "FOLLOWING":
			switch ftype {
			case "ROWS":
				e = i + int(endOff.Int())
			case "GROUPS":
				g := groupNo[i] + int(endOff.Int())
				if g >= nGroups {
					e = m - 1
				} else {
					e = groupLast[g]
				}
			default:
				e = rangeBound(i, "FOLLOWING", endOff, false)
			}
		case "PRECEDING":
			switch ftype {
			case "ROWS":
				e = i - int(endOff.Int())
			case "GROUPS":
				g := groupNo[i] - int(endOff.Int())
				if g < 0 {
					e = -1
				} else {
					e = groupLast[g]
				}
			default:
				e = rangeBound(i, "PRECEDING", endOff, false)
			}
		case "UNBOUNDED PRECEDING":
			e = -1
		}
		if s < 0 {
			s = 0
		}
		if e >= m {
			e = m - 1
		}
		return s, e
	}
	excluded := func(i, j int) bool {
		switch exclude {
		case "CURRENT ROW":
			return i == j
		case "GROUP":
			return groupNo[i] == groupNo[j]
		case "TIES":
			return groupNo[i] == groupNo[j] && i != j
		}
		return false
	}
	switch w.name {
	case "first_value", "last_value", "nth_value":
		for i := 0; i < m; i++ {
			s, e := frameOf(i)
			var res Value
			switch w.name {
			case "first_value":
				for j := s; j <= e; j++ {
					if excluded(i, j) {
						continue
					}
					res = args[part[j]][0]
					break
				}
			case "last_value":
				for j := e; j >= s; j-- {
					if excluded(i, j) {
						continue
					}
					res = args[part[j]][0]
					break
				}
			case "nth_value":
				nv := args[part[i]][1]
				nn := nv.Int()
				if nv.K == KNull || nn <= 0 || (nv.K == KReal && nv.F != float64(int64(nv.F))) {
					throw("second argument to nth_value must be a positive integer")
				}
				cnt := int64(0)
				for j := s; j <= e; j++ {
					if excluded(i, j) {
						continue
					}
					cnt++
					if cnt == nn {
						res = args[part[j]][0]
						break
					}
				}
			}
			wvals[part[i]][slot] = res
		}
		return
	}
	// aggregate window function
	incremental := startK == "UNBOUNDED PRECEDING" && exclude == "" && !w.distinct
	if incremental {
		st := w.agg.newState(w.aggc)
		done := -1
		for i := 0; i < m; i++ {
			_, e := frameOf(i)
			for done < e {
				done++
				j := part[done]
				if filt[j] {
					var ok []Value
					if len(w.aggc.orderBy) > 0 {
						setRow(j)
						ok = make([]Value, len(w.aggc.orderBy))
						for k, oe := range w.aggc.orderBy {
							ok[k] = oe.fn(c)
						}
					}
					st.step(args[j], ok)
				}
			}
			wvals[part[i]][slot] = st.final()
		}
		return
	}
	for i := 0; i < m; i++ {
		s, e := frameOf(i)
		st := w.agg.newState(w.aggc)
		var seen map[string]bool
		if w.distinct {
			seen = map[string]bool{}
		}
		for j := s; j <= e; j++ {
			if excluded(i, j) {
				continue
			}
			r := part[j]
			if !filt[r] {
				continue
			}
			if seen != nil {
				k := rowKey(args[r], w.argColls)
				if seen[k] {
					continue
				}
				seen[k] = true
			}
			st.step(args[r], nil)
		}
		wvals[part[i]][slot] = st.final()
	}
}
