package main

import (
	"strings"
)

type scalarFunc struct {
	minArg int
	maxArg int // -1 unlimited
	fn     func(c *Ctx, args []Value) Value
	lazy   func(cp *compiler, e *Expr, args []cexpr) cexpr
	// result affinity / collation propagation
	passColl bool
}

var scalarFuncs = map[string]*scalarFunc{}

func regFunc(name string, minA, maxA int, fn func(c *Ctx, args []Value) Value) {
	scalarFuncs[name] = &scalarFunc{minArg: minA, maxArg: maxA, fn: fn}
}

func (cp *compiler) compileFunc(e *Expr, sc *scope) cexpr {
	name := e.Name
	nargs := len(e.List)
	lvl := sc.lvl
	if e.Over != nil {
		return cp.compileWindowFunc(e, sc)
	}
	if _, ok := winOnlyFuncs[name]; ok {
