func (cp *compiler) resolveWindowDef(w *WindowDef, sc *scope, pos int) *WindowDef {
	if w.Base == "" {
		return w
	}
	var base *WindowDef
	if sc.lvl != nil {
		for _, d := range sc.lvl.windows {
			if strings.EqualFold(d.Name, w.Base) {
				base = d
				break
			}
		}
	}
	if base == nil {
		throwPos(pos, "no such window: %s", w.Base)
	}
	base = cp.resolveWindowDef(base, sc, pos)
	nw := &WindowDef{Partition: base.Partition, OrderBy: base.OrderBy, Frame: base.Frame}
	if w.Partition != nil {
		throwPos(pos, "cannot override PARTITION clause of window %s", w.Base)
	}
	if w.OrderBy != nil {
		if base.OrderBy != nil {
			throwPos(pos, "cannot override ORDER BY clause of window %s", w.Base)
		}
		nw.OrderBy = w.OrderBy
	}
	if w.Frame != nil {
		nw.Frame = w.Frame
	} else if w.Partition == nil && w.OrderBy == nil {
		nw.Frame = base.Frame
	}
	if base.Frame != nil && (w.OrderBy != nil || w.Frame != nil) {
		throwPos(pos, "cannot override frame specification of window %s", w.Base)
	}
	return nw
}

func (cp *compiler) compileWindowFunc(e *Expr, sc *scope) cexpr {
	name := e.Name
	lvl := sc.lvl
	if lvl == nil || !lvl.allowWin {
		throwPos(e.Pos, "misuse of window function %s()", name)
	}
	w := &winCall{name: name, distinct: e.Distinct}
	nargs := len(e.List)
	if rng, ok := winOnlyFuncs[name]; ok {
		if nargs < rng[0] || nargs > rng[1] {
			throwPos(e.Pos, "wrong number of arguments to function %s()", name)
		}
