		if nargs < ad.minArg || nargs > ad.maxArg {
			if !(name == "count" && e.Star) {
				throwPos(e.Pos, "wrong number of arguments to function %s()", name)
			}
		}
		w.agg = ad
	} else if _, ok := scalarFuncs[name]; ok {
		throwPos(e.Pos, "%s() may not be used as a window function", name)
	} else {
		throwPos(e.Pos, "no such function: %s", e.Name)
	}
	def := cp.resolveWindowDef(e.Over, sc, e.Pos)
	saveWin := lvl.allowWin
	lvl.allowWin = false
	for _, x := range e.List {
		ax := cp.compileExpr(x, sc)
		w.args = append(w.args, ax)
		w.argColls = append(w.argColls, ax.coll)
	}
	if e.Filter != nil {
		f := cp.compileExpr(e.Filter, sc)
		w.filter = &f
	}
	for _, p := range def.Partition {
		x := cp.compileExpr(p, sc)
		w.partition = append(w.partition, x)
		w.partColl = append(w.partColl, x.coll)
	}
	for _, o := range def.OrderBy {
		x := cp.compileExpr(o.E, sc)
		w.order = append(w.order, x)
		w.orderSpecs = append(w.orderSpecs, orderSpec{desc: o.Desc, nulls: o.Nulls, coll: getCollation(x.coll)})
	}
	if def.Frame != nil {
		w.frame = def.Frame
		if def.Frame.Start.Expr != nil {
			x := cp.compileExpr(def.Frame.Start.Expr, sc)
			w.startOff = &x
		}
		if def.Frame.End.Expr != nil {
			x := cp.compileExpr(def.Frame.End.Expr, sc)
			w.endOff = &x
		}
		if def.Frame.Type == "RANGE" && (def.Frame.Start.Expr != nil || def.Frame.End.Expr != nil) && len(def.OrderBy) != 1 {
			throwPos(e.Pos, "RANGE with offset PRECEDING/FOLLOWING requires exactly one ORDER BY term")
		}
		if def.Frame.Start.Kind == "UNBOUNDED FOLLOWING" {
			throwPos(e.Pos, "near \"FOLLOWING\": syntax error")
		}
	}
	lvl.allowWin = saveWin
	if w.agg != nil {
		ac := &aggCall{name: name, def: w.agg, args: w.args, argColls: w.argColls, distinct: w.distinct}
		if len(w.args) > 0 {
			ac.coll = getCollation(w.args[0].coll)
		}
		for _, ot := range e.OrderBy {
			oc := cp.compileExpr(ot.E, sc)
			ac.orderBy = append(ac.orderBy, oc)
			ac.orderSpecs = append(ac.orderSpecs, orderSpec{desc: ot.Desc, nulls: ot.Nulls, coll: getCollation(oc.coll)})
		}
		w.aggc = ac
	}
