	lvl.wins = append(lvl.wins, w)
	slot := w.slot
	return cexpr{fn: func(c *Ctx) Value {
		if c.winVals == nil || slot >= len(c.winVals) {
			return NullValue
		}
		return c.winVals[slot]
	}}
}

func init() {
	scalarFuncs["coalesce"] = &scalarFunc{minArg: 2, maxArg: -1, lazy: lazyCoalesce}
	scalarFuncs["ifnull"] = &scalarFunc{minArg: 2, maxArg: 2, lazy: lazyCoalesce}
	scalarFuncs["iif"] = &scalarFunc{minArg: 2, maxArg: -1, lazy: lazyIif}
	scalarFuncs["if"] = &scalarFunc{minArg: 2, maxArg: -1, lazy: lazyIif}
	scalarFuncs["likely"] = &scalarFunc{minArg: 1, maxArg: 1, lazy: lazyPass}
	scalarFuncs["unlikely"] = &scalarFunc{minArg: 1, maxArg: 1, lazy: lazyPass}
	scalarFuncs["likelihood"] = &scalarFunc{minArg: 2, maxArg: 2, lazy: lazyLikelihood}
}

func lazyCoalesce(cp *compiler, e *Expr, args []cexpr) cexpr {
	r := cexpr{fn: func(c *Ctx) Value {
		for _, a := range args {
			v := a.fn(c)
			if v.K != KNull {
				return v
			}
		}
		return NullValue
	}}
	for _, a := range args {
		if a.coll != "" {
			r.coll = a.coll
			break
		}
	}
	return r
}

func lazyIif(cp *compiler, e *Expr, args []cexpr) cexpr {
	return cexpr{fn: func(c *Ctx) Value {
		n := len(args)
		i := 0
		for ; i+1 < n; i += 2 {
			v := args[i].fn(c)
			if v.Bool() {
				return args[i+1].fn(c)
			}
		}
		if i < n {
			return args[i].fn(c)
		}
		return NullValue
	}}
}

func lazyPass(cp *compiler, e *Expr, args []cexpr) cexpr {
	r := args[0]
	r.isConst = false
	return r
}

func lazyLikelihood(cp *compiler, e *Expr, args []cexpr) cexpr {
	p := args[1]
	if !p.isConst || (p.val.K != KReal && p.val.K != KInt) || p.val.Float() < 0 || p.val.Float() > 1 {
		throwPos(e.Pos, "second argument to likelihood() must be a constant between 0.0 and 1.0")
	}
	r := args[0]
	r.isConst = false
	return r
}
