func substrRange(n, p1, p2 int64, hasLen bool) (int64, int64) {
	if !hasLen {
		p2 = math.MaxInt32
	}
	if p1 < 0 {
		p1 += n
		if p1 < 0 {
			if p2 < 0 {
				p2 = 0
			}
			p2 += p1
			if p2 < 0 {
				p2 = 0
			}
			p1 = 0
		}
	} else if p1 > 0 {
		p1--
	} else if p2 > 0 {
		p2--
	}
	if p2 < 0 {
		if p2 < -p1 {
			p2 = p1
			p1 = 0
		} else {
			p1 += p2
			p2 = -p2
		}
	}
	if p1 > n {
		p1 = n
	}
	e := p1 + p2
	if e > n || e < p1 {
		e = n
	}
	return p1, e
}

func (c *Conn) randU64() uint64 {
	if !c.randInit {
		c.randState = uint64(nowNanos()) | 1
		c.randInit = true
	}
	// xorshift64*
	x := c.randState
	x ^= x >> 12
	x ^= x << 25
	x ^= x >> 27
	c.randState = x
	return x * 2685821657736338717
}
