func (cp *compiler) compileTVF(it *FromItem, sc *scope) *fromSrc {
	name := strings.ToLower(it.Name)
	alias := it.Alias
	if alias == "" {
		alias = it.Name
	}
	var def *tvfDef
	if d, ok := tvfDefs[name]; ok {
		def = d
	} else if strings.HasPrefix(name, "pragma_") {
		def = cp.pragmaTVF(name[7:], it)
	}
	if def == nil {
		throwPos(it.Pos, "no such table: %s", it.Name)
	}
	if len(it.FuncArgs) > def.nArgs {
		throwPos(it.Pos, "too many arguments on %s() - max %d", it.Name, def.nArgs)
	}
	// args are evaluated in the enclosing scope (they may reference earlier FROM items)
	var args []cexpr
	for _, a := range it.FuncArgs {
		x, _ := cp.compileWithDeps(a, sc)
		args = append(args, x)
	}
	n := len(def.cols)
	si := &srcInfo{name: alias, cols: def.cols, aff: make([]Affinity, n), hasAff: make([]bool, n), coll: make([]string, n), hiddenCol: nil}
	s := &fromSrc{kind: srcTVF, tvf: def, tvfArgs: args, info: si}
	s.tvfHidden = def.hidden
	return s
}

func (s *fromSrc) tvfRows(c *Ctx) [][]Value {
	args := make([]Value, len(s.tvfArgs))
	for i, a := range s.tvfArgs {
		args[i] = a.fn(c)
	}
	return s.tvf.rows(c, args, len(args))
}

func (cp *compiler) compileSchemaSource(it *FromItem, alias string) *fromSrc {
	name := strings.ToLower(it.Name)
	var sch *Schema
	if strings.HasPrefix(name, "sqlite_temp") {
		sch = cp.conn.temp
	} else if it.Schema != "" {
		sch = cp.conn.schemaByName(it.Schema)
	} else {
		sch = cp.conn.main
	}
	conn := cp.conn
	def := &tvfDef{name: name, cols: []string{"type", "name", "tbl_name", "rootpage", "sql"}, hidden: []bool{false, false, false, false, false},
		rows: func(c *Ctx, args []Value, nargs int) [][]Value {
			return schemaRows(conn, sch)
		}}
	si := &srcInfo{name: alias, cols: def.cols, aff: []Affinity{AffText, AffText, AffText, AffInteger, AffText}, hasAff: []bool{true, true, true, true, true}, coll: make([]string, 5), hasRowid: true}
	return &fromSrc{kind: srcTVF, tvf: def, info: si}
}

func schemaRows(conn *Conn, sch *Schema) [][]Value {
	var rows [][]Value
	for _, e := range sch.entries {
		rows = append(rows, []Value{TextValue(e.Type), TextValue(e.Name), TextValue(e.TblName), IntValue(sch.entryRootPage(e)), sch.entrySQL(e)})
	}
	return rows
}

func (cp *compiler) compileVTabSource(t *Table, alias string) *fromSrc {
	return &fromSrc{kind: srcTable, table: t, info: tableSrcInfo(t, alias)}
}
