type jsonErr struct{ pos int }

// ---------- text parser ----------

type jparser struct {
	s   string
	i   int
	err int
}

func jsonParse(s string) (*jnode, int) {
	p := &jparser{s: s}
	p.skipWS()
	n := p.parseValue(0)
	if n == nil {
		if p.err < 0 {
			p.err = p.i
		}
		return nil, p.err + 1
	}
	p.skipWS()
	if p.i < len(p.s) {
		return nil, p.i + 1
	}
	return n, 0
}

func (p *jparser) fail() *jnode {
	if p.err < 0 || p.err == 0 {
		p.err = p.i
	}
	return nil
}

func isJSONWS(s string, i int) int {
	c := s[i]
	switch c {
	case ' ', '\t', '\n', '\r':
		return 1
	case '\v', '\f':
		return 1
	case '/':
		if i+1 < len(s) && s[i+1] == '*' {
			j := strings.Index(s[i+2:], "*/")
			if j < 0 {
				return -1
			}
			return j + 4
		}
		if i+1 < len(s) && s[i+1] == '/' {
			j := strings.IndexByte(s[i+2:], '\n')
			if j < 0 {
				return len(s) - i
			}
			return j + 3
		}
	case 0xc2:
		if i+1 < len(s) && s[i+1] == 0xa0 {
			return 2
		}
	case 0xe2:
		if i+2 < len(s) && s[i+1] == 0x80 && (s[i+2] == 0xa8 || s[i+2] == 0xa9 || (s[i+2] >= 0x80 && s[i+2] <= 0x8a) || s[i+2] == 0xaf) {
			return 3
		}
		if i+2 < len(s) && s[i+1] == 0x81 && s[i+2] == 0x9f {
			return 3
		}
	case 0xe3:
		if i+2 < len(s) && s[i+1] == 0x80 && s[i+2] == 0x80 {
			return 3
		}
	case 0xef:
		if i+2 < len(s) && s[i+1] == 0xbb && s[i+2] == 0xbf {
			return 3
		}
	}
	return 0
}

func (p *jparser) skipWS() {
	for p.i < len(p.s) {
		k := isJSONWS(p.s, p.i)
		if k <= 0 {
			return
		}
		p.i += k
	}
}

func (p *jparser) parseValue(depth int) *jnode {
	if depth > 1000 {
		return p.fail()
	}
	if p.i >= len(p.s) {
		return p.fail()
	}
	c := p.s[p.i]
	switch {
	case c == '{':
		p.i++
		n := &jnode{typ: jObject}
		for {
			p.skipWS()
			if p.i >= len(p.s) {
				return p.fail()
			}
			if p.s[p.i] == '}' {
				p.i++
				return n
			}
			var key *jnode
			if p.s[p.i] == '"' || p.s[p.i] == '\'' {
