			p.i += 5
			return &jnode{typ: jFalse}
		}
	case c == 'n':
		if strings.HasPrefix(p.s[p.i:], "null") && !p.identAfter(4) {
			p.i += 4
			return &jnode{typ: jNull}
		}
	case c == 'N':
		if strings.HasPrefix(p.s[p.i:], "NaN") && !p.identAfter(3) {
			p.i += 3
