			return &jnode{typ: jFloat5, text: "9e999"}
		}
	case c == '-' || c == '+' || c == '.' || (c >= '0' && c <= '9'):
		return p.parseNumber()
	}
	return p.fail()
}

func (p *jparser) identAfter(k int) bool {
	j := p.i + k
	if j < len(p.s) {
		ch := p.s[j]
		return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '_'
	}
	return false
}

func (p *jparser) parseNumber() *jnode {
	st := p.i
	s := p.s
	five := false
	neg := false
	if s[p.i] == '+' {
		five = true
		p.i++
	} else if s[p.i] == '-' {
		neg = true
		p.i++
	}
	if p.i < len(s) && s[p.i] == 'I' && strings.HasPrefix(s[p.i:], "Infinity") {
		p.i += 8
		if neg {
			return &jnode{typ: jFloat5, text: "-9e999"}
		}
		return &jnode{typ: jFloat5, text: "9e999"}
	}
	if p.i+1 < len(s) && s[p.i] == '0' && (s[p.i+1] == 'x' || s[p.i+1] == 'X') {
		p.i += 2
		h := p.i
		for p.i < len(s) && isHex(s[p.i]) {
			p.i++
		}
		if p.i == h {
			return p.fail()
		}
		return &jnode{typ: jInt5, text: s[st:p.i]}
	}
	isFloat := false
	d0 := p.i
	for p.i < len(s) && isDigit(s[p.i]) {
		p.i++
	}
	nInt := p.i - d0
	if nInt > 1 && s[d0] == '0' {
		return p.fail()
	}
	if p.i < len(s) && s[p.i] == '.' {
		isFloat = true
		p.i++
		f0 := p.i
		for p.i < len(s) && isDigit(s[p.i]) {
			p.i++
		}
		if p.i == f0 {
			five = true
		}
		if nInt == 0 {
			five = true
		}
		if nInt == 0 && p.i == f0 {
			return p.fail()
		}
	} else if nInt == 0 {
		return p.fail()
	}
	if p.i < len(s) && (s[p.i] == 'e' || s[p.i] == 'E') {
		isFloat = true
		p.i++
		if p.i < len(s) && (s[p.i] == '+' || s[p.i] == '-') {
			p.i++
		}
		e0 := p.i
		for p.i < len(s) && isDigit(s[p.i]) {
			p.i++
		}
		if p.i == e0 {
			return p.fail()
		}
	}
	t := s[st:p.i]
	if isFloat {
		if five {
			return &jnode{typ: jFloat5, text: t}
		}
		return &jnode{typ: jFloat, text: t}
	}
	if five {
		return &jnode{typ: jInt5, text: t}
	}
	return &jnode{typ: jInt, text: t}
}

func (p *jparser) parseString() *jnode {
	q := p.s[p.i]
	p.i++
	st := p.i
	typ := byte(jText)
	if q == '\'' {
		typ = jText
	}
	s := p.s
	for p.i < len(s) {
		c := s[p.i]
		if c == q {
			t := s[st:p.i]
			p.i++
			if q == '\'' && strings.IndexByte(t, '"') >= 0 {
				typ = jText5
			}
			return &jnode{typ: typ, text: t}
		}
		if c < 0x20 {
			if c == 0 {
				return p.fail()
			}
			return p.fail()
		}
		if c == '\\' {
			p.i++
			if p.i >= len(s) {
				return p.fail()
			}
			e := s[p.i]
			switch e {
			case '"', '\\', '/', 'b', 'f', 'n', 'r', 't':
				if typ == jText {
					typ = jTextJ
				}
				p.i++
			case 'u':
				if p.i+4 >= len(s) {
					return p.fail()
				}
				for k := 1; k <= 4; k++ {
					if !isHex(s[p.i+k]) {
						return p.fail()
					}
				}
				if typ == jText {
					typ = jTextJ
				}
				p.i += 5
			case '\'', 'v', '0', '\n':
				typ = jText5
				p.i++
			case '\r':
				typ = jText5
				p.i++
				if p.i < len(s) && s[p.i] == '\n' {
					p.i++
				}
			case 'x':
				if p.i+2 >= len(s) || !isHex(s[p.i+1]) || !isHex(s[p.i+2]) {
					return p.fail()
				}
				typ = jText5
				p.i += 3
			case 0xe2:
				if p.i+2 < len(s) && s[p.i+1] == 0x80 && (s[p.i+2] == 0xa8 || s[p.i+2] == 0xa9) {
					typ = jText5
					p.i += 3
				} else {
					return p.fail()
				}
			default:
				return p.fail()
			}
			continue
		}
		p.i++
	}
	return p.fail()
}

// ---------- output ----------

func jsonEscapeRaw(b *strings.Builder, s string) {
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		case '\b':
			b.WriteString("\\b")
		case '\f':
			b.WriteString("\\f")
		default:
			if c < 0x20 {
				b.WriteString("\\u00")
				b.WriteByte(hexdigits[c>>4])
				b.WriteByte(hexdigits[c&15])
			} else {
				b.WriteByte(c)
			}
		}
	}
	b.WriteByte('"')
}

func jsonQuoteString(s string) string {
	var b strings.Builder
	jsonEscapeRaw(&b, s)
	return b.String()
}

// decode a string payload (any text type) to its actual value
func jsonUnescape(n *jnode) string {
	switch n.typ {
	case jText, jTextRaw:
		return n.text
	}
	s := n.text
	if strings.IndexByte(s, '\\') < 0 {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' {
			b.WriteByte(c)
			continue
		}
		i++
		if i >= len(s) {
			break
		}
		switch s[i] {
		case 'b':
			b.WriteByte('\b')
		case 'f':
			b.WriteByte('\f')
		case 'n':
			b.WriteByte('\n')
		case 'r':
			if i+1 < len(s) && s[i+1] == '\n' && n.typ == jText5 && false {
			}
			b.WriteByte('\r')
		case 't':
			b.WriteByte('\t')
		case 'v':
			b.WriteByte('\v')
		case '0':
			b.WriteByte(0)
		case 'x':
			x, _ := strconv.ParseUint(s[i+1:i+3], 16, 8)
			b.WriteRune(rune(x))
			i += 2
		case 'u':
			x, _ := strconv.ParseUint(s[i+1:i+5], 16, 32)
			i += 4
			r := rune(x)
			if r >= 0xd800 && r < 0xdc00 && i+6 < len(s)+0 && i+2 < len(s) && s[i+1] == '\\' && s[i+2] == 'u' {
				y, err := strconv.ParseUint(s[i+3:i+7], 16, 32)
				if err == nil && y >= 0xdc00 && y < 0xe000 {
					r = 0x10000 + (r-0xd800)<<10 + (rune(y) - 0xdc00)
					i += 6
				}
			}
			b.WriteRune(r)
		case '\n':
			// line continuation
		case '\r':
			if i+1 < len(s) && s[i+1] == '\n' {
				i++
			}
		case 0xe2:
			i += 2
		default:
			b.WriteByte(s[i])
		}
	}
	return b.String()
}

func jsonNumText(n *jnode) string {
	switch n.typ {
	case jInt:
		return n.text
	case jFloat:
		return n.text
	case jInt5:
		t := n.text
		neg := false
		if t[0] == '-' || t[0] == '+' {
			neg = t[0] == '-'
			t = t[1:]
		}
		if len(t) > 1 && (t[1] == 'x' || t[1] == 'X') {
			bi := new(big.Int)
			bi.SetString(t[2:], 16)
			if neg {
				bi.Neg(bi)
			}
			if bi.IsInt64() {
				return bi.String()
			}
			f, _ := new(big.Float).SetInt(bi).Float64()
			return FormatReal(f)
		}
		if neg {
			return "-" + t
		}
		return t
	case jFloat5:
		t := n.text
		if t == "9e999" || t == "-9e999" {
			return t
		}
		neg := false
		if t[0] == '-' || t[0] == '+' {
			neg = t[0] == '-'
			t = t[1:]
		}
		if strings.HasPrefix(t, ".") {
			t = "0" + t
		}
		if i := strings.IndexByte(t, '.'); i >= 0 && (i+1 == len(t) || !isDigit(t[i+1])) {
			t = t[:i+1] + "0" + t[i+1:]
		}
		if neg {
			t = "-" + t
		}
		return t
	}
	return n.text
}

func jsonRender(b *strings.Builder, n *jnode) {
	switch n.typ {
	case jNull:
		b.WriteString("null")
	case jTrue:
		b.WriteString("true")
	case jFalse:
		b.WriteString("false")
	case jInt, jFloat, jInt5, jFloat5:
		b.WriteString(jsonNumText(n))
	case jText:
		b.WriteByte('"')
		b.WriteString(n.text)
		b.WriteByte('"')
	case jTextJ:
		b.WriteByte('"')
		b.WriteString(n.text)
		b.WriteByte('"')
	case jText5:
		jsonEscapeRaw(b, jsonUnescape(n))
	case jTextRaw:
		jsonEscapeRaw(b, n.text)
	case jArray:
		b.WriteByte('[')
		for i, k := range n.kids {
			if i > 0 {
				b.WriteByte(',')
			}
			jsonRender(b, k)
		}
		b.WriteByte(']')
	case jObject:
		b.WriteByte('{')
		for i := 0; i+1 < len(n.kids); i += 2 {
			if i > 0 {
				b.WriteByte(',')
			}
			jsonRender(b, n.kids[i])
			b.WriteByte(':')
			jsonRender(b, n.kids[i+1])
		}
		b.WriteByte('}')
	}
}

func jsonString(n *jnode) string {
	var b strings.Builder
	jsonRender(&b, n)
	return b.String()
}

func jsonPretty(b *strings.Builder, n *jnode, indent string, level int) {
	switch n.typ {
	case jArray:
		if len(n.kids) == 0 {
			b.WriteString("[]")
			return
		}
		b.WriteString("[\n")
		for i, k := range n.kids {
			b.WriteString(strings.Repeat(indent, level+1))
			jsonPretty(b, k, indent, level+1)
			if i < len(n.kids)-1 {
				b.WriteByte(',')
			}
			b.WriteByte('\n')
		}
		b.WriteString(strings.Repeat(indent, level))
		b.WriteByte(']')
	case jObject:
		if len(n.kids) == 0 {
			b.WriteString("{}")
			return
		}
		b.WriteString("{\n")
		for i := 0; i+1 < len(n.kids); i += 2 {
			b.WriteString(strings.Repeat(indent, level+1))
			jsonRender(b, n.kids[i])
			b.WriteString(": ")
			jsonPretty(b, n.kids[i+1], indent, level+1)
			if i+2 < len(n.kids) {
				b.WriteByte(',')
			}
			b.WriteByte('\n')
		}
		b.WriteString(strings.Repeat(indent, level))
		b.WriteByte('}')
	default:
		jsonRender(b, n)
	}
}

// ---------- JSONB ----------

func jsonbPayloadSize(n *jnode) int {
	switch n.typ {
	case jNull, jTrue, jFalse:
		return 0
	case jArray, jObject:
		t := 0
		for _, k := range n.kids {
			t += jsonbSize(k)
		}
		return t
	}
	return len(n.text)
}

func jsonbHdrSize(p int) int {
	switch {
	case p <= 11:
		return 1
	case p <= 0xff:
		return 2
	case p <= 0xffff:
		return 3
	case p <= 0xffffffff:
		return 5
	}
	return 9
}

func jsonbSize(n *jnode) int {
	p := jsonbPayloadSize(n)
	return jsonbHdrSize(p) + p
}

func jsonbEncode(b []byte, n *jnode) []byte {
	p := jsonbPayloadSize(n)
	switch {
	case p <= 11:
		b = append(b, byte(p<<4)|n.typ)
	case p <= 0xff:
		b = append(b, 0xc0|n.typ, byte(p))
	case p <= 0xffff:
		b = append(b, 0xd0|n.typ, byte(p>>8), byte(p))
	default:
		b = append(b, 0xe0|n.typ, byte(p>>24), byte(p>>16), byte(p>>8), byte(p))
	}
	switch n.typ {
	case jArray, jObject:
		for _, k := range n.kids {
			b = jsonbEncode(b, k)
		}
	case jNull, jTrue, jFalse:
	default:
		b = append(b, n.text...)
	}
	return b
}

func jsonbDecode(s string) (*jnode, bool) {
	n, used, ok := jsonbDecodeAt(s, 0, 0)
	if !ok || used != len(s) {
		return nil, false
	}
	return n, true
}

func jsonbDecodeAt(s string, i int, depth int) (*jnode, int, bool) {
	if i >= len(s) || depth > 1000 {
		return nil, 0, false
	}
	h := s[i]
	typ := h & 0x0f
	sz := int(h >> 4)
	hl := 1
	switch sz {
	case 12:
		if i+1 >= len(s) {
			return nil, 0, false
		}
		sz = int(s[i+1])
		hl = 2
	case 13:
		if i+2 >= len(s) {
			return nil, 0, false
		}
		sz = int(s[i+1])<<8 | int(s[i+2])
		hl = 3
	case 14:
		if i+4 >= len(s) {
			return nil, 0, false
		}
		sz = int(s[i+1])<<24 | int(s[i+2])<<16 | int(s[i+3])<<8 | int(s[i+4])
		hl = 5
	case 15:
		return nil, 0, false
	}
	if typ > 12 {
		return nil, 0, false
	}
	end := i + hl + sz
	if end > len(s) {
		return nil, 0, false
	}
	n := &jnode{typ: typ}
	switch typ {
	case jNull, jTrue, jFalse:
		if sz != 0 {
			return nil, 0, false
		}
	case jArray, jObject:
		j := i + hl
		for j < end {
			k, u, ok := jsonbDecodeAt(s, j, depth+1)
			if !ok {
				return nil, 0, false
			}
			n.kids = append(n.kids, k)
			j += u
		}
		if j != end {
			return nil, 0, false
		}
		if typ == jObject && len(n.kids)%2 != 0 {
			return nil, 0, false
		}
	default:
		n.text = s[i+hl : end]
		if typ == jInt || typ == jFloat {
			if sz == 0 {
				return nil, 0, false
			}
		}
	}
	return n, end - i, true
}

// ---------- SQL value conversions ----------

func jsonTextValue(s string) Value {
	return Value{K: KText, S: s, Sub: subJSON}
}

func jsonToBlob(s string) Value {
	n, e := jsonParse(s)
	if e != 0 {
		throw("malformed JSON")
	}
	return BlobValue(string(jsonbEncode(nil, n)))
}

// parse a SQL value that is a JSON document argument
func jsonArgNode(v Value) *jnode {
	switch v.K {
	case KNull:
		return nil
	case KBlob:
		if n, ok := jsonbDecode(v.S); ok {
			return n
		}
		throw("malformed JSON")
	case KInt, KReal:
		n, e := jsonParse(v.Text())
		if e != 0 {
			throw("malformed JSON")
		}
		return n
	}
	n, e := jsonParse(v.S)
	if e != 0 {
		throw("malformed JSON")
	}
	return n
}

func realToJSONText(f float64) string {
	if math.IsInf(f, 1) {
		return "9.0e+999"
	}
	if math.IsInf(f, -1) {
		return "-9.0e+999"
	}
	return formatFloatSQL(f, 'g', 15, 0, fmtFlags{alt2: true})
}

// SQL value -> JSON node (for json_array etc.)
func valueToJNode(v Value) *jnode {
	switch v.K {
	case KNull:
		return &jnode{typ: jNull}
	case KInt:
		return &jnode{typ: jInt, text: strconv.FormatInt(v.I, 10)}
	case KReal:
		if math.IsNaN(v.F) {
			return &jnode{typ: jNull}
		}
		return &jnode{typ: jFloat, text: realToJSONText(v.F)}
	case KText:
		if v.Sub == subJSON {
			n, e := jsonParse(v.S)
			if e == 0 {
				return n
			}
		}
		return &jnode{typ: jTextRaw, text: v.S}
	case KBlob:
		if n, ok := jsonbDecode(v.S); ok {
			return n
		}
		throw("JSON cannot hold BLOB values")
	}
	return &jnode{typ: jNull}
}

func jsonValueText(v Value) string {
	return jsonString(valueToJNode(v))
}

// JSON node -> SQL value (json_extract semantics)
func jnodeToValue(n *jnode) Value {
	switch n.typ {
	case jNull:
		return NullValue
	case jTrue:
		return IntValue(1)
	case jFalse:
		return IntValue(0)
	case jInt, jInt5:
		t := jsonNumText(n)
		if i, err := strconv.ParseInt(t, 10, 64); err == nil {
			return IntValue(i)
		}
		f, _ := strconv.ParseFloat(t, 64)
		return RealValue(f)
	case jFloat, jFloat5:
		t := jsonNumText(n)
		if t == "9e999" {
			return RealValue(math.Inf(1))
		}
		if t == "-9e999" {
			return RealValue(math.Inf(-1))
		}
		f, _ := strconv.ParseFloat(t, 64)
		return RealValue(f)
	case jText, jTextJ, jText5, jTextRaw:
		return TextValue(jsonUnescape(n))
	}
	return jsonTextValue(jsonString(n))
}

func jsonTypeName(n *jnode) string {
	switch n.typ {
	case jNull:
		return "null"
	case jTrue:
		return "true"
	case jFalse:
		return "false"
	case jInt, jInt5:
		return "integer"
	case jFloat, jFloat5:
		return "real"
	case jArray:
		return "array"
	case jObject:
		return "object"
	}
	return "text"
}

// ---------- paths ----------

type jpathSeg struct {
	isIdx   bool
	key     string
	idx     int64
	fromEnd bool // #-N
	append  bool // [#]
}

func parseJSONPath(p string) ([]jpathSeg, bool) {
	if !strings.HasPrefix(p, "$") {
		return nil, false
	}
	var segs []jpathSeg
	i := 1
	for i < len(p) {
		c := p[i]
		if c == '.' {
			i++
			if i < len(p) && p[i] == '"' {
				j := strings.IndexByte(p[i+1:], '"')
				if j < 0 {
					return nil, false
				}
				segs = append(segs, jpathSeg{key: p[i+1 : i+1+j]})
				i = i + j + 2
				continue
			}
			st := i
			for i < len(p) && p[i] != '.' && p[i] != '[' {
				i++
			}
			if i == st {
				return nil, false
			}
			segs = append(segs, jpathSeg{key: p[st:i]})
			continue
		}
		if c == '[' {
			i++
			if i < len(p) && p[i] == '#' {
				i++
				if i < len(p) && p[i] == ']' {
					segs = append(segs, jpathSeg{isIdx: true, append: true})
					i++
					continue
				}
				if i < len(p) && p[i] == '-' {
					i++
					st := i
					for i < len(p) && isDigit(p[i]) {
						i++
					}
					if i == st || i >= len(p) || p[i] != ']' {
						return nil, false
					}
					n, _ := strconv.ParseInt(p[st:i], 10, 64)
					segs = append(segs, jpathSeg{isIdx: true, fromEnd: true, idx: n})
					i++
					continue
				}
				return nil, false
			}
			st := i
			for i < len(p) && isDigit(p[i]) {
				i++
			}
			if i == st || i >= len(p) || p[i] != ']' {
				return nil, false
			}
			n, _ := strconv.ParseInt(p[st:i], 10, 64)
			segs = append(segs, jpathSeg{isIdx: true, idx: n})
			i++
			continue
		}
		return nil, false
	}
	return segs, true
}

func jsonPathArg(v Value) []jpathSeg {
	p := v.Text()
	segs, ok := parseJSONPath(p)
	if !ok {
		throw("bad JSON path: '%s'", p)
	}
	return segs
}

func objLookup(n *jnode, key string) int {
	for i := 0; i+1 < len(n.kids); i += 2 {
		if jsonUnescape(n.kids[i]) == key {
			return i + 1
		}
	}
	return -1
}

func jsonLookup(n *jnode, segs []jpathSeg) *jnode {
	cur := n
	for _, s := range segs {
		if s.isIdx {
			if cur.typ != jArray {
				return nil
			}
			if s.append {
				return nil
			}
			idx := s.idx
			if s.fromEnd {
				idx = int64(len(cur.kids)) - s.idx
			}
			if idx < 0 || idx >= int64(len(cur.kids)) {
				return nil
			}
			cur = cur.kids[idx]
		} else {
			if cur.typ != jObject {
				return nil
			}
			k := objLookup(cur, s.key)
			if k < 0 {
				return nil
			}
			cur = cur.kids[k]
		}
	}
	return cur
}

// jsonEdit: mode 'i' insert, 'r' replace, 's' set, 'd' delete
func jsonEdit(root *jnode, segs []jpathSeg, val *jnode, mode byte) *jnode {
	if len(segs) == 0 {
		switch mode {
		case 'r', 's':
			return val
		case 'd':
			return nil
		}
		return root
	}
	cur := root
	for k, s := range segs {
		last := k == len(segs)-1
		if s.isIdx {
			if cur.typ != jArray {
				return root
			}
			idx := s.idx
			if s.fromEnd {
				idx = int64(len(cur.kids)) - s.idx
			}
			if s.append {
				idx = int64(len(cur.kids))
			}
			if idx < 0 {
				return root
			}
			if idx < int64(len(cur.kids)) {
				if last {
					switch mode {
					case 'r', 's':
						cur.kids[idx] = val
					case 'd':
						cur.kids = append(cur.kids[:idx], cur.kids[idx+1:]...)
					}
					return root
				}
				cur = cur.kids[idx]
				continue
			}
			if idx == int64(len(cur.kids)) && (mode == 'i' || mode == 's') {
				nn := buildPath(segs[k+1:], val)
				cur.kids = append(cur.kids, nn)
			}
			return root
		}
		if cur.typ != jObject {
			return root
		}
		ki := objLookup(cur, s.key)
		if ki >= 0 {
			if last {
				switch mode {
				case 'r', 's':
					cur.kids[ki] = val
				case 'd':
					cur.kids = append(cur.kids[:ki-1], cur.kids[ki+1:]...)
				}
				return root
			}
			cur = cur.kids[ki]
			continue
		}
		if mode == 'i' || mode == 's' {
			nn := buildPath(segs[k+1:], val)
			if nn == nil {
				return root
			}
			cur.kids = append(cur.kids, &jnode{typ: jTextRaw, text: s.key}, nn)
		}
		return root
	}
	return root
}

func buildPath(segs []jpathSeg, val *jnode) *jnode {
	if len(segs) == 0 {
		return val
	}
	s := segs[0]
	inner := buildPath(segs[1:], val)
	if inner == nil {
		return nil
	}
	if s.isIdx {
		if s.idx != 0 && !s.append {
			return nil
		}
		if s.fromEnd {
			return nil
		}
		return &jnode{typ: jArray, kids: []*jnode{inner}}
	}
	return &jnode{typ: jObject, kids: []*jnode{{typ: jTextRaw, text: s.key}, inner}}
}

func jsonPatch(target, patch *jnode) *jnode {
	if patch.typ != jObject {
		return patch
	}
	if target == nil || target.typ != jObject {
		target = &jnode{typ: jObject}
	} else {
		cp := *target
		cp.kids = append([]*jnode(nil), target.kids...)
		target = &cp
	}
	for i := 0; i+1 < len(patch.kids); i += 2 {
		key := jsonUnescape(patch.kids[i])
		pv := patch.kids[i+1]
		ki := objLookup(target, key)
		if pv.typ == jNull {
			if ki >= 0 {
				target.kids = append(target.kids[:ki-1], target.kids[ki+1:]...)
			}
			continue
		}
		if ki >= 0 {
			target.kids[ki] = jsonPatch(target.kids[ki], pv)
		} else {
			target.kids = append(target.kids, patch.kids[i], jsonPatch(nil, pv))
		}
	}
	return target
}

func cloneJ(n *jnode) *jnode {
	if n == nil {
		return nil
	}
	c := &jnode{typ: n.typ, text: n.text}
	if n.kids != nil {
		c.kids = make([]*jnode, len(n.kids))
		for i, k := range n.kids {
			c.kids[i] = cloneJ(k)
		}
	}
	return c
}

func jsonArrow(l, r Value, asText bool) Value {
	if l.K == KNull || r.K == KNull {
		return NullValue
	}
	n := jsonArgNode(l)
	var segs []jpathSeg
	switch r.K {
	case KInt:
		if r.I < 0 {
			segs = []jpathSeg{{isIdx: true, fromEnd: true, idx: -r.I}}
		} else {
			segs = []jpathSeg{{isIdx: true, idx: r.I}}
		}
	default:
		p := r.Text()
		if strings.HasPrefix(p, "$") {
			segs = jsonPathArg(r)
		} else {
			segs = []jpathSeg{{key: p}}
		}
	}
	res := jsonLookup(n, segs)
	if res == nil {
		return NullValue
	}
	if asText {
		return jnodeToValue(res)
	}
	return jsonTextValue(jsonString(res))
}

func keyNeedsQuote(k string) bool {
	if k == "" {
		return true
	}
	for i := 0; i < len(k); i++ {
		c := k[i]
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || (i > 0 && c >= '0' && c <= '9') || c >= 0x80) {
			return true
		}
	}
	return false
}

func fullkeyAppend(base string, key string) string {
	if keyNeedsQuote(key) {
		return base + ".\"" + key + "\""
	}
	return base + "." + key
}

func jsonEachRows(args []Value, nargs int, tree bool, binary bool) [][]Value {
	if nargs == 0 || args[0].K == KNull {
		return nil
	}
	root := jsonArgNode(args[0])
	path := "$"
	var segs []jpathSeg
	if nargs > 1 {
		if args[1].K == KNull {
			return nil
		}
		path = args[1].Text()
		segs = jsonPathArg(args[1])
	}
	// compute offsets
	offsets := map[*jnode]int{}
	var assign func(n *jnode, off int)
	assign = func(n *jnode, off int) {
		offsets[n] = off
		p := jsonbPayloadSize(n)
		o := off + jsonbHdrSize(p)
		for _, k := range n.kids {
			assign(k, o)
			o += jsonbSize(k)
		}
	}
	assign(root, 0)
	// locate target and its key
	target := root
	var targetKey Value = NullValue
	targetID := 0
	cur := root
	curID := 0
	for _, s := range segs {
		var next *jnode
		if s.isIdx {
			if cur.typ != jArray {
				return nil
			}
			idx := s.idx
			if s.fromEnd {
				idx = int64(len(cur.kids)) - s.idx
			}
			if idx < 0 || idx >= int64(len(cur.kids)) {
				return nil
			}
			next = cur.kids[idx]
			targetKey = IntValue(idx)
			curID = offsets[next]
		} else {
			if cur.typ != jObject {
				return nil
			}
			k := objLookup(cur, s.key)
			if k < 0 {
				return nil
			}
			next = cur.kids[k]
			targetKey = TextValue(s.key)
			curID = offsets[cur.kids[k-1]]
		}
		cur = next
	}
	target = cur
	targetID = curID
	jsonCol := args[0]
	var rows [][]Value
	valOf := func(n *jnode) Value {
		if n.typ == jArray || n.typ == jObject {
			if binary {
				return BlobValue(string(jsonbEncode(nil, n)))
			}
			return jsonTextValue(jsonString(n))
		}
		return jnodeToValue(n)
	}
	atomOf := func(n *jnode) Value {
		if n.typ == jArray || n.typ == jObject {
			return NullValue
		}
		return jnodeToValue(n)
	}
	mkRow := func(key Value, n *jnode, id int, parent Value, fullkey, p string) []Value {
		return []Value{key, valOf(n), TextValue(jsonTypeName(n)), atomOf(n), IntValue(int64(id)), parent, TextValue(fullkey), TextValue(p), jsonCol, TextValue(path)}
	}
	if tree {
		var walk func(n *jnode, key Value, id int, parent Value, fullkey, p string)
		walk = func(n *jnode, key Value, id int, parent Value, fullkey, p string) {
			rows = append(rows, mkRow(key, n, id, parent, fullkey, p))
			switch n.typ {
			case jArray:
				for i, k := range n.kids {
					walk(k, IntValue(int64(i)), offsets[k], IntValue(int64(id)), fullkey+"["+strconv.Itoa(i)+"]", fullkey)
				}
			case jObject:
				for i := 0; i+1 < len(n.kids); i += 2 {
					kn := jsonUnescape(n.kids[i])
					walk(n.kids[i+1], TextValue(kn), offsets[n.kids[i]], IntValue(int64(id)), fullkeyAppend(fullkey, kn), fullkey)
				}
			}
		}
		parentPath := "$"
		if len(segs) > 0 {
			parentPath = pathPrefix(path)
		}
		walk(target, targetKey, targetID, NullValue, path, parentPath)
		return rows
	}
	switch target.typ {
	case jArray:
		for i, k := range target.kids {
			rows = append(rows, mkRow(IntValue(int64(i)), k, offsets[k], NullValue, path+"["+strconv.Itoa(i)+"]", path))
		}
	case jObject:
		for i := 0; i+1 < len(target.kids); i += 2 {
			kn := jsonUnescape(target.kids[i])
			rows = append(rows, mkRow(TextValue(kn), target.kids[i+1], offsets[target.kids[i]], NullValue, fullkeyAppend(path, kn), path))
		}
	default:
		parentPath := "$"
		if len(segs) > 0 {
			parentPath = pathPrefix(path)
		}
		rows = append(rows, mkRow(targetKey, target, targetID, NullValue, path, parentPath))
	}
	return rows
}

func pathPrefix(p string) string {
	// strip last segment
	if strings.HasSuffix(p, "]") {
		i := strings.LastIndexByte(p, '[')
		if i > 0 {
			return p[:i]
		}
	}
	if strings.HasSuffix(p, "\"") {
		j := strings.LastIndex(p[:len(p)-1], ".\"")
		if j > 0 {
			return p[:j]
		}
	}
	i := strings.LastIndexByte(p, '.')
	if i > 0 {
		return p[:i]
	}
	return "$"
}

func init() {
	regFunc("json", 1, 1, func(c *Ctx, a []Value) Value {
		if a[0].K == KNull {
			return NullValue
		}
		n := jsonArgNode(a[0])
		return jsonTextValue(jsonString(n))
	})
	regFunc("jsonb", 1, 1, func(c *Ctx, a []Value) Value {
		if a[0].K == KNull {
			return NullValue
		}
		n := jsonArgNode(a[0])
		return BlobValue(string(jsonbEncode(nil, n)))
	})
	regFunc("json_valid", 1, 2, func(c *Ctx, a []Value) Value {
		if a[0].K == KNull {
			return NullValue
		}
		flags := int64(1)
		if len(a) > 1 {
			flags = a[1].Int()
			if flags < 1 || flags > 15 {
				throw("FLAGS parameter to json_valid() must be between 1 and 15")
			}
		}
		v := a[0]
		if v.K == KBlob {
			if flags&12 != 0 {
				if _, ok := jsonbDecode(v.S); ok {
					return IntValue(1)
				}
			}
			return IntValue(0)
		}
		s := v.Text()
		n, e := jsonParse(s)
		if e != 0 {
			return IntValue(0)
		}
		if flags&2 != 0 {
			return IntValue(1)
		}
		if flags&1 != 0 && isStrictJSON(n, s) {
			return IntValue(1)
		}
		return IntValue(0)
	})
	regFunc("json_error_position", 1, 1, func(c *Ctx, a []Value) Value {
		if a[0].K == KNull {
			return NullValue
		}
		if a[0].K == KBlob {
			if _, ok := jsonbDecode(a[0].S); ok {
				return IntValue(0)
			}
			return IntValue(1)
		}
		s := a[0].Text()
		_, e := jsonParse(s)
		if e == 0 {
			return IntValue(0)
		}
		// convert byte offset to character offset
		if e-1 <= len(s) {
			return IntValue(int64(utf8.RuneCountInString(s[:e-1]) + 1))
		}
		return IntValue(int64(e))
	})
	extract := func(binary bool) func(c *Ctx, a []Value) Value {
		return func(c *Ctx, a []Value) Value {
			if a[0].K == KNull {
				return NullValue
			}
			n := jsonArgNode(a[0])
			if len(a) == 2 {
				if a[1].K == KNull {
					return NullValue
				}
				r := jsonLookup(n, jsonPathArg(a[1]))
				if r == nil {
					return NullValue
				}
				if binary {
					return BlobValue(string(jsonbEncode(nil, r)))
				}
				return jnodeToValue(r)
			}
			arr := &jnode{typ: jArray}
			for _, p := range a[1:] {
				if p.K == KNull {
					return NullValue
				}
				r := jsonLookup(n, jsonPathArg(p))
				if r == nil {
					arr.kids = append(arr.kids, &jnode{typ: jNull})
				} else {
					arr.kids = append(arr.kids, r)
				}
			}
			if binary {
				return BlobValue(string(jsonbEncode(nil, arr)))
			}
			return jsonTextValue(jsonString(arr))
		}
	}
	regFunc("json_extract", 2, -1, extract(false))
	regFunc("jsonb_extract", 2, -1, extract(true))
	mkArray := func(binary bool) func(c *Ctx, a []Value) Value {
		return func(c *Ctx, a []Value) Value {
			arr := &jnode{typ: jArray}
			for _, v := range a {
				arr.kids = append(arr.kids, valueToJNode(v))
			}
			if binary {
				return BlobValue(string(jsonbEncode(nil, arr)))
			}
			return jsonTextValue(jsonString(arr))
		}
	}
	regFunc("json_array", 0, -1, mkArray(false))
	regFunc("jsonb_array", 0, -1, mkArray(true))
	mkObject := func(binary bool) func(c *Ctx, a []Value) Value {
		return func(c *Ctx, a []Value) Value {
			if len(a)%2 != 0 {
				throw("json_object() requires an even number of arguments")
			}
			obj := &jnode{typ: jObject}
			for i := 0; i < len(a); i += 2 {
				if a[i].K != KText {
					throw("json_object() labels must be TEXT")
				}
				obj.kids = append(obj.kids, &jnode{typ: jTextRaw, text: a[i].S}, valueToJNode(a[i+1]))
			}
			if binary {
				return BlobValue(string(jsonbEncode(nil, obj)))
			}
			return jsonTextValue(jsonString(obj))
		}
	}
	regFunc("json_object", 0, -1, mkObject(false))
	regFunc("jsonb_object", 0, -1, mkObject(true))
	regFunc("json_array_length", 1, 2, func(c *Ctx, a []Value) Value {
		if a[0].K == KNull {
			return NullValue
		}
		n := jsonArgNode(a[0])
		if len(a) > 1 {
			if a[1].K == KNull {
				return NullValue
			}
			n = jsonLookup(n, jsonPathArg(a[1]))
			if n == nil {
				return NullValue
			}
		}
		if n.typ != jArray {
			return IntValue(0)
		}
		return IntValue(int64(len(n.kids)))
	})
	regFunc("json_type", 1, 2, func(c *Ctx, a []Value) Value {
		if a[0].K == KNull {
			return NullValue
		}
		n := jsonArgNode(a[0])
		if len(a) > 1 {
			if a[1].K == KNull {
				return NullValue
			}
			n = jsonLookup(n, jsonPathArg(a[1]))
			if n == nil {
				return NullValue
			}
		}
		return TextValue(jsonTypeName(n))
	})
	regFunc("json_quote", 1, 1, func(c *Ctx, a []Value) Value {
		return jsonTextValue(jsonValueText(a[0]))
	})
	edit := func(mode byte, binary bool, name string) func(c *Ctx, a []Value) Value {
		return func(c *Ctx, a []Value) Value {
			if a[0].K == KNull {
				return NullValue
			}
			if mode != 'd' && len(a)%2 != 1 {
				throw("json_%s() needs an odd number of arguments", name)
			}
			n := cloneJ(jsonArgNode(a[0]))
			if mode == 'd' {
				for _, p := range a[1:] {
					if p.K == KNull {
						return NullValue
					}
					segs := jsonPathArg(p)
					n = jsonEdit(n, segs, nil, 'd')
					if n == nil {
						return NullValue
					}
				}
			} else {
				for i := 1; i+1 < len(a); i += 2 {
					if a[i].K == KNull {
						return NullValue
					}
					segs := jsonPathArg(a[i])
					v := valueToJNode(a[i+1])
					n = jsonEdit(n, segs, v, mode)
				}
			}
			if binary {
				return BlobValue(string(jsonbEncode(nil, n)))
			}
			return jsonTextValue(jsonString(n))
		}
	}
	regFunc("json_insert", 1, -1, edit('i', false, "insert"))
	regFunc("json_replace", 1, -1, edit('r', false, "replace"))
	regFunc("json_set", 1, -1, edit('s', false, "set"))
	regFunc("json_remove", 1, -1, edit('d', false, "remove"))
	regFunc("jsonb_insert", 1, -1, edit('i', true, "insert"))
	regFunc("jsonb_replace", 1, -1, edit('r', true, "replace"))
	regFunc("jsonb_set", 1, -1, edit('s', true, "set"))
	regFunc("jsonb_remove", 1, -1, edit('d', true, "remove"))
	patch := func(binary bool) func(c *Ctx, a []Value) Value {
		return func(c *Ctx, a []Value) Value {
			if a[0].K == KNull || a[1].K == KNull {
				return NullValue
			}
			t := jsonArgNode(a[0])
			p := jsonArgNode(a[1])
			r := jsonPatch(t, p)
			if binary {
				return BlobValue(string(jsonbEncode(nil, r)))
			}
			return jsonTextValue(jsonString(r))
		}
	}
	regFunc("json_patch", 2, 2, patch(false))
	regFunc("jsonb_patch", 2, 2, patch(true))
	regFunc("json_pretty", 1, 2, func(c *Ctx, a []Value) Value {
		if a[0].K == KNull {
			return NullValue
		}
		n := jsonArgNode(a[0])
		indent := "    "
		if len(a) > 1 && a[1].K != KNull {
			indent = a[1].Text()
		}
		var b strings.Builder
		jsonPretty(&b, n, indent, 0)
		return jsonTextValue(b.String())
	})
}

func isStrictJSON(n *jnode, s string) bool {
	switch n.typ {
	case jInt5, jFloat5, jText5:
		return false
	case jArray, jObject:
		for _, k := range n.kids {
			if !isStrictJSON(k, s) {
				return false
			}
		}
	}
	// detect JSON5 syntax features in source text (comments, single quotes, trailing commas, unquoted keys)
	return !hasJSON5Syntax(s)
}

func hasJSON5Syntax(s string) bool {
	inStr := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inStr {
			if c == '\\' {
				i++
			} else if c == '"' {
				inStr = false
			}
			continue
		}
		switch c {
		case '"':
			inStr = true
		case '\'', '/':
			return true
		case ',':
			j := i + 1
			for j < len(s) && (s[j] == ' ' || s[j] == '\t' || s[j] == '\n' || s[j] == '\r') {
				j++
			}
			if j < len(s) && (s[j] == ']' || s[j] == '}') {
				return true
			}
		case '{':
			j := i + 1
			for j < len(s) && (s[j] == ' ' || s[j] == '\t' || s[j] == '\n' || s[j] == '\r') {
				j++
			}
			if j < len(s) && s[j] != '"' && s[j] != '}' {
				return true
			}
		case '\v', '\f':
			return true
		}
	}
	return false
}
