	p.validJD = true
	if p.validHMS {
		p.iJD += int64(p.h)*3600000 + int64(p.m)*60000 + int64(p.s*1000+0.5)
		if p.validTZ {
			p.iJD -= int64(p.tz) * 60000
			p.validYMD = false
			p.validHMS = false
			p.validTZ = false
		}
	}
}

func validJulianDay(iJD int64) bool {
	return iJD >= 0 && iJD <= 464269060799999
}

func (p *dateTime) computeYMD() {
	if p.validYMD {
		return
	}
	if !p.validJD {
		p.Y, p.M, p.D = 2000, 1, 1
	} else if !validJulianDay(p.iJD) {
		p.isError = true
		return
	} else {
		Z := int((p.iJD + 43200000) / 86400000)
		A := int((float64(Z) - 1867216.25) / 36524.25)
		A = Z + 1 + A - (A / 4)
		B := A + 1524
		C := int((float64(B) - 122.1) / 365.25)
		D := (36525 * (C & 32767)) / 100
		E := int(float64(B-D) / 30.6001)
		X1 := int(30.6001 * float64(E))
		p.D = B - D - X1
		if E < 14 {
			p.M = E - 1
		} else {
			p.M = E - 13
		}
		if p.M > 2 {
			p.Y = C - 4716
		} else {
			p.Y = C - 4715
		}
	}
	p.validYMD = true
}

func (p *dateTime) computeHMS() {
	if p.validHMS {
		return
	}
	p.computeJD()
	dayMs := int((p.iJD + 43200000) % 86400000)
	p.s = float64(dayMs%60000) / 1000.0
	dayMin := dayMs / 60000
	p.m = dayMin % 60
	p.h = dayMin / 60
	p.rawS = false
	p.validHMS = true
}

func (p *dateTime) computeYMDHMS() {
	p.computeYMD()
	p.computeHMS()
}

func (p *dateTime) clearYMDHMSTZ() {
	p.validYMD = false
	p.validHMS = false
	p.validTZ = false
}

func getDigits(s string, i *int, n int, min, max int) (int, bool) {
	if *i+n > len(s) {
		return 0, false
	}
	v := 0
	for k := 0; k < n; k++ {
		c := s[*i+k]
		if c < '0' || c > '9' {
			return 0, false
		}
		v = v*10 + int(c-'0')
	}
	if v < min || v > max {
		return 0, false
	}
	*i += n
	return v, true
}

func parseTimezone(s string, i int, p *dateTime) bool {
	for i < len(s) && isSpaceByte(s[i]) {
		i++
	}
	p.tz = 0
	if i >= len(s) {
		return true
	}
	c := s[i]
	sgn := 0
	if c == '-' {
		sgn = -1
	} else if c == '+' {
		sgn = 1
	} else if c == 'Z' || c == 'z' {
		i++
		p.isUtc = true
		p.validTZ = true
		for i < len(s) && isSpaceByte(s[i]) {
			i++
		}
		return i == len(s)
	} else {
		return false
	}
	i++
	nHr, ok := getDigits(s, &i, 2, 0, 14)
	if !ok {
		return false
	}
	if i >= len(s) || s[i] != ':' {
		return false
	}
	i++
	nMn, ok := getDigits(s, &i, 2, 0, 59)
	if !ok {
		return false
	}
	p.tz = sgn * (nMn + nHr*60)
	for i < len(s) && isSpaceByte(s[i]) {
		i++
	}
	p.validTZ = true
	return i == len(s)
}

func parseHhMmSs(s string, i int, p *dateTime) bool {
	h, ok := getDigits(s, &i, 2, 0, 24)
	if !ok {
		return false
	}
	if i >= len(s) || s[i] != ':' {
		return false
	}
	i++
	m, ok := getDigits(s, &i, 2, 0, 59)
	if !ok {
		return false
	}
	var sec float64
	if i < len(s) && s[i] == ':' {
		i++
		sv, ok := getDigits(s, &i, 2, 0, 59)
		if !ok {
			return false
		}
		sec = float64(sv)
		if i+1 < len(s) && s[i] == '.' && isDigit(s[i+1]) {
			i++
			scale := 1.0
			frac := 0.0
			for i < len(s) && isDigit(s[i]) {
				if scale < 1e15 {
					frac = frac*10 + float64(s[i]-'0')
					scale *= 10
				}
				i++
			}
			sec += frac / scale
		}
	}
	p.validJD = false
	p.rawS = false
	p.validHMS = true
	p.h = h
	p.m = m
	p.s = sec
	if !parseTimezone(s, i, p) {
		return false
	}
	return true
}

func parseYyyyMmDd(s string, p *dateTime) bool {
	i := 0
	neg := false
	if i < len(s) && s[i] == '-' {
		neg = true
		i++
	}
	Y, ok := getDigits(s, &i, 4, 0, 9999)
	if !ok {
		return false
	}
	if i >= len(s) || s[i] != '-' {
		return false
	}
	i++
	M, ok := getDigits(s, &i, 2, 1, 12)
	if !ok {
		return false
	}
	if i >= len(s) || s[i] != '-' {
		return false
	}
	i++
	D, ok := getDigits(s, &i, 2, 1, 31)
	if !ok {
		return false
	}
	for i < len(s) && (isSpaceByte(s[i]) || s[i] == 'T') {
		i++
	}
	if i < len(s) {
		if !parseHhMmSs(s, i, p) {
			// maybe only timezone
			if !parseTimezone(s, i, p) {
				return false
			}
		}
	} else {
		p.validHMS = false
	}
	p.validJD = false
	p.validYMD = true
	if neg {
		p.Y = -Y
	} else {
		p.Y = Y
	}
	p.M = M
	p.D = D
	if p.validTZ {
		p.computeJD()
	}
	return true
}

func (c *Conn) stmtNow() int64 {
	if !c.stmtTimeSet {
		t := time.Now()
		ms := t.UnixNano() / 1000000
		c.stmtTime = float64(ms)
		c.stmtTimeSet = true
	}
	return int64(c.stmtTime) + 210866760000000
}

func parseDateOrTime(c *Ctx, s string, p *dateTime) bool {
	if parseYyyyMmDd(s, p) {
		return true
	}
	if parseHhMmSs(s, 0, p) {
		return true
	}
	if strings.EqualFold(s, "now") {
		p.iJD = c.conn.stmtNow()
		p.validJD = true
		return true
	}
	np := parseNumber(s)
	if np.ok && np.full {
		r := np.f
		p.rawNum = r
		p.hasRaw = true
		p.setRawDateNumber(r)
		return true
	}
	if strings.EqualFold(s, "subsec") || strings.EqualFold(s, "subsecond") {
		p.useSubsec = true
		p.iJD = c.conn.stmtNow()
		p.validJD = true
		return true
	}
	return false
}

func (p *dateTime) setRawDateNumber(r float64) {
	p.s = r
	p.rawS = true
	if r >= 0.0 && r < 5373484.5 {
		p.iJD = int64(r*86400000.0 + 0.5)
		p.validJD = true
	}
}

func dateArgs(c *Ctx, args []Value, p *dateTime) bool {
	if len(args) == 0 {
		p.iJD = c.conn.stmtNow()
		p.validJD = true
		return true
	}
	v := args[0]
	switch v.K {
	case KNull:
		return false
	case KInt, KReal:
		r := v.Float()
		p.rawNum = r
		p.hasRaw = true
		p.setRawDateNumber(r)
	default:
		if !parseDateOrTime(c, v.Text(), p) {
			return false
		}
	}
	for i := 1; i < len(args); i++ {
		if args[i].K == KNull {
			return false
		}
		if !parseModifier(c, args[i].Text(), p, i) {
			return false
		}
	}
	p.computeJD()
	if p.isError || !validJulianDay(p.iJD) {
		return false
	}
	if len(args) == 1 && p.validYMD && p.D > 28 {
		// validate day of month
		p.validYMD = false
	}
	return true
}

func daysInMonth(y, m int) int {
	switch m {
	case 2:
		if (y%4 == 0 && y%100 != 0) || y%400 == 0 {
			return 29
		}
		return 28
	case 4, 6, 9, 11:
		return 30
	}
	return 31
}

func localOffsetMs(iJD int64) int64 {
	secs := (iJD - 210866760000000) / 1000
	t := time.Unix(secs, 0)
	_, off := t.Zone()
	return int64(off) * 1000
}

func autoAdjustDate(p *dateTime) {
	if !p.rawS || p.validJD {
		p.rawS = false
		return
	}
	if p.s >= -21086676*10000.0 && p.s <= (25340230*10000.0)+799 {
		r := p.s*1000.0 + 210866760000000.0
		p.clearYMDHMSTZ()
		p.iJD = int64(r + 0.5)
		p.validJD = true
		p.rawS = false
	}
}

func parseModifier(c *Ctx, z string, p *dateTime, idx int) bool {
	lz := strings.ToLower(strings.TrimSpace(z))
	switch {
	case lz == "auto":
		if idx > 1 {
			return false
		}
		autoAdjustDate(p)
		return true
	case lz == "ceiling":
		p.computeJD()
		p.nFloor = 0
		return true
	case lz == "floor":
		p.computeJD()
		p.nFloor = 1
		return true
	case lz == "julianday":
		if idx > 1 {
			return false
		}
		if p.validJD && p.rawS {
			p.rawS = false
			return true
		}
		return false
	case lz == "localtime":
		p.computeJD()
		p.iJD += localOffsetMs(p.iJD)
		p.clearYMDHMSTZ()
		p.isLocal = true
		return true
	case lz == "unixepoch":
		if idx > 1 {
			return false
		}
		if p.rawS {
			r := p.s*1000.0 + 210866760000000.0
			if r >= 0.0 && r < 464269060800000.0 {
				p.clearYMDHMSTZ()
				p.iJD = int64(r + 0.5)
				p.validJD = true
				p.rawS = false
				return true
			}
		}
		return false
	case lz == "utc":
		if !p.isUtc {
			p.computeJD()
			off := localOffsetMs(p.iJD)
			p.iJD -= off
			p.clearYMDHMSTZ()
			p.isUtc = true
			p.isLocal = false
		}
		return true
	case lz == "subsec" || lz == "subsecond":
		p.useSubsec = true
		return true
	case strings.HasPrefix(lz, "weekday "):
		np := parseNumber(lz[8:])
		if !np.ok || !np.full {
			return false
		}
		n := int64(np.f)
		if float64(n) != np.f || n < 0 || n >= 7 {
			return false
		}
		p.computeYMDHMS()
		p.validTZ = false
		p.validJD = false
		p.computeJD()
		Z := ((p.iJD + 129600000) / 86400000) % 7
		if Z > n {
			Z -= 7
		}
		p.iJD += (n - Z) * 86400000
		p.clearYMDHMSTZ()
		return true
	case strings.HasPrefix(lz, "start of "):
		if !p.validJD && !p.validYMD && !p.validHMS {
			return false
		}
		rest := strings.TrimSpace(lz[9:])
		p.computeYMD()
		p.validHMS = true
		p.h, p.m = 0, 0
		p.s = 0
		p.rawS = false
		p.validTZ = false
		p.validJD = false
		switch rest {
		case "month":
			p.D = 1
		case "year":
			p.M = 1
			p.D = 1
		case "day":
		default:
			return false
		}
		return true
	}
	// numeric modifiers
	s := strings.TrimSpace(z)
	if s == "" {
		return false
	}
	if s[0] == '+' || s[0] == '-' || isDigit(s[0]) || s[0] == '.' {
		// +-YYYY-MM-DD or +-HH:MM[:SS]
		return parseNumericModifier(p, s)
	}
	return false
}

func parseNumericModifier(p *dateTime, s string) bool {
	// try "+-HH:MM[:SS[.SSS]]" or "+-YYYY-MM-DD [HH:MM[:SS]]"
	sign := 1
	body := s
	if s[0] == '-' || s[0] == '+' {
		if s[0] == '-' {
			sign = -1
		}
		body = s[1:]
	}
	// YYYY-MM-DD form
	if len(body) >= 10 && body[4] == '-' && body[7] == '-' {
		i := 0
		Y, ok1 := getDigits(body, &i, 4, 0, 9999)
		i++
		M, ok2 := getDigits(body, &i, 2, 0, 11)
		i++
		D, ok3 := getDigits(body, &i, 2, 0, 30)
		if ok1 && ok2 && ok3 && (s[0] == '+' || s[0] == '-') {
			p.computeYMDHMS()
			p.validJD = false
			if sign < 0 {
				Y, M, D = -Y, -M, -D
			}
			p.Y += Y
			p.M += M
			x := 0
			if p.M > 0 {
				x = (p.M - 1) / 12
			} else {
				x = (p.M - 12) / 12
			}
			p.Y += x
			p.M -= x * 12
			p.computeJD()
			p.validHMS = false
			p.validYMD = false
			p.iJD += int64(D) * 86400000
			rest := strings.TrimSpace(body[10:])
			if rest == "" {
				return true
			}
			var tx dateTime
			if !parseHhMmSs(rest, 0, &tx) {
				return false
			}
			ms := int64(tx.h)*3600000 + int64(tx.m)*60000 + int64(tx.s*1000+0.5)
			if sign < 0 {
				ms = -ms
			}
			p.iJD += ms
			p.clearYMDHMSTZ()
			return true
		}
	}
	if strings.IndexByte(body, ':') >= 0 && (s[0] == '+' || s[0] == '-' || isDigit(s[0])) {
		var tx dateTime
		if parseHhMmSs(body, 0, &tx) && !tx.validTZ {
			p.computeJD()
			p.clearYMDHMSTZ()
			ms := int64(tx.h)*3600000 + int64(tx.m)*60000 + int64(tx.s*1000+0.5)
			if sign < 0 {
				ms = -ms
			}
			p.iJD += ms
			return true
		}
	}
	// NNN units
	j := 0
	if j < len(s) && (s[j] == '+' || s[j] == '-') {
		j++
	}
	for j < len(s) && (isDigit(s[j]) || s[j] == '.' || s[j] == 'e' || s[j] == 'E') {
		if (s[j] == 'e' || s[j] == 'E') && !(j+1 < len(s) && (isDigit(s[j+1]) || s[j+1] == '-' || s[j+1] == '+')) {
			break
		}
		j++
	}
	numStr := s[:j]
	r, err := strconv.ParseFloat(numStr, 64)
	if err != nil {
		return false
	}
	unit := strings.ToLower(strings.TrimSpace(s[j:]))
	if j < len(s) && !isSpaceByte(s[j]) {
		return false
	}
	unit = strings.TrimSuffix(unit, "s")
	p.computeJD()
	var ms float64
	switch unit {
	case "second":
		ms = 1000
	case "minute":
		ms = 60000
	case "hour":
		ms = 3600000
	case "day":
		ms = 86400000
	case "month":
		p.computeYMDHMS()
		x := int(r)
		p.M += x
		var y int
		if p.M > 0 {
			y = (p.M - 1) / 12
		} else {
			y = (p.M - 12) / 12
		}
		p.Y += y
		p.M -= y * 12
		p.validJD = false
		r -= float64(x)
		p.computeJD()
		if r != 0 {
			p.iJD += int64(r * 30.0 * 86400000.0)
		}
		p.clearYMDHMSTZ()
		return true
	case "year":
		p.computeYMDHMS()
		x := int(r)
		p.Y += x
		p.validJD = false
		r -= float64(x)
		p.computeJD()
		if r != 0 {
			p.iJD += int64(r * 365.0 * 86400000.0)
		}
		p.clearYMDHMSTZ()
		return true
	default:
		return false
	}
	rounder := 0.5
	if r < 0 {
		rounder = -0.5
	}
	p.iJD += int64(r*ms + rounder)
	p.clearYMDHMSTZ()
	return true
}

func fmtYear(y int) string {
	if y < 0 {
		return fmt.Sprintf("-%04d", -y)
	}
	return fmt.Sprintf("%04d", y)
}

func (p *dateTime) dateStr() string {
	p.computeYMD()
	return fmt.Sprintf("%s-%02d-%02d", fmtYear(p.Y), p.M, p.D)
}

func (p *dateTime) timeStr() string {
	p.computeHMS()
	if p.useSubsec {
		s := p.s
		return fmt.Sprintf("%02d:%02d:%06.3f", p.h, p.m, s)
	}
	return fmt.Sprintf("%02d:%02d:%02d", p.h, p.m, int(p.s))
}

func init() {
	regFunc("date", 0, -1, func(c *Ctx, a []Value) Value {
		var p dateTime
		if !dateArgs(c, a, &p) {
			return NullValue
		}
		p.validYMD = false
		p.validHMS = false
		p.computeYMD()
		if p.isError {
			return NullValue
		}
		return TextValue(p.dateStr())
	})
	regFunc("time", 0, -1, func(c *Ctx, a []Value) Value {
		var p dateTime
		if !dateArgs(c, a, &p) {
			return NullValue
		}
		p.validHMS = false
		return TextValue(p.timeStr())
	})
	regFunc("datetime", 0, -1, func(c *Ctx, a []Value) Value {
		var p dateTime
		if !dateArgs(c, a, &p) {
			return NullValue
		}
		p.validYMD = false
		p.validHMS = false
		p.computeYMD()
		if p.isError {
			return NullValue
		}
		return TextValue(p.dateStr() + " " + p.timeStr())
	})
	regFunc("julianday", 0, -1, func(c *Ctx, a []Value) Value {
		var p dateTime
		if !dateArgs(c, a, &p) {
			return NullValue
		}
		return RealValue(float64(p.iJD) / 86400000.0)
	})
	regFunc("unixepoch", 0, -1, func(c *Ctx, a []Value) Value {
		var p dateTime
		if !dateArgs(c, a, &p) {
			return NullValue
		}
		if p.useSubsec {
			return RealValue(float64(p.iJD-210866760000000) / 1000.0)
		}
		v := p.iJD - 210866760000000
		if v < 0 && v%1000 != 0 {
			return IntValue(v/1000 - 1)
		}
		return IntValue(v / 1000)
	})
	regFunc("strftime", 1, -1, func(c *Ctx, a []Value) Value {
		if a[0].K == KNull {
			return NullValue
		}
		var p dateTime
		if !dateArgs(c, a[1:], &p) {
			return NullValue
		}
		return strftimeImpl(a[0].Text(), &p)
	})
	regFunc("current_date", 0, 0, func(c *Ctx, a []Value) Value {
		p := dateTime{iJD: c.conn.stmtNow(), validJD: true}
		return TextValue(p.dateStr())
	})
	regFunc("current_time", 0, 0, func(c *Ctx, a []Value) Value {
		p := dateTime{iJD: c.conn.stmtNow(), validJD: true}
		return TextValue(p.timeStr())
	})
	regFunc("current_timestamp", 0, 0, func(c *Ctx, a []Value) Value {
		p := dateTime{iJD: c.conn.stmtNow(), validJD: true}
		return TextValue(p.dateStr() + " " + p.timeStr())
	})
	regFunc("timediff", 2, 2, func(c *Ctx, a []Value) Value {
		var d1, d2 dateTime
		if !dateArgs(c, a[0:1], &d1) {
			return NullValue
		}
		if !dateArgs(c, a[1:2], &d2) {
			return NullValue
		}
		d1.computeYMDHMS()
		d2.computeYMDHMS()
		sign := byte('+')
		if d1.iJD < d2.iJD {
			sign = '-'
			d1, d2 = d2, d1
		}
		Y := d1.Y - d2.Y
		M := d1.M - d2.M
		if M < 0 {
			Y--
			M += 12
		}
		// compute day difference by moving d2 forward Y years and M months
		t := d2
		t.Y += Y
		t.M += M
		for t.M > 12 {
			t.M -= 12
			t.Y++
		}
		t.validJD = false
		t.computeJD()
		for t.iJD > d1.iJD {
			M--
			if M < 0 {
				M += 12
				Y--
			}
			t = d2
			t.Y += Y
			t.M += M
			for t.M > 12 {
				t.M -= 12
				t.Y++
			}
			t.validJD = false
			t.computeJD()
		}
		diff := d1.iJD - t.iJD
		days := diff / 86400000
		rem := diff % 86400000
		h := rem / 3600000
		rem %= 3600000
		mi := rem / 60000
		rem %= 60000
		sec := float64(rem) / 1000.0
		return TextValue(fmt.Sprintf("%c%04d-%02d-%02d %02d:%02d:%06.3f", sign, Y, M, days, h, mi, sec))
	})
}

func strftimeImpl(f string, p *dateTime) Value {
	var b strings.Builder
	p.computeYMDHMS()
	if p.isError {
		return NullValue
	}
	for i := 0; i < len(f); i++ {
		ch := f[i]
		if ch != '%' {
			b.WriteByte(ch)
			continue
		}
		i++
		if i >= len(f) {
			return NullValue
		}
		switch f[i] {
		case 'd':
			fmt.Fprintf(&b, "%02d", p.D)
		case 'e':
			fmt.Fprintf(&b, "%2d", p.D)
		case 'f':
			s := p.s
			if s > 59.999 {
				s = 59.999
			}
			fmt.Fprintf(&b, "%06.3f", s)
		case 'F':
			fmt.Fprintf(&b, "%s-%02d-%02d", fmtYear(p.Y), p.M, p.D)
		case 'G', 'g', 'V':
			// ISO 8601 week-based year
			y := *p
			y.validJD = false
			y.computeJD()
			dow := int((y.iJD + 129600000) / 86400000 % 7) // 0=Sunday
			isoDow := dow
			if isoDow == 0 {
				isoDow = 7
			}
			// Thursday of this week
			thu := y.iJD + int64(4-isoDow)*86400000
			t := dateTime{iJD: thu, validJD: true}
			t.computeYMD()
			isoYear := t.Y
			if f[i] == 'G' {
				fmt.Fprintf(&b, "%04d", isoYear)
			} else if f[i] == 'g' {
				fmt.Fprintf(&b, "%02d", isoYear%100)
			} else {
				jan1 := dateTime{Y: isoYear, M: 1, D: 1, validYMD: true}
				jan1.computeJD()
				week := int((thu-jan1.iJD)/86400000)/7 + 1
				fmt.Fprintf(&b, "%02d", week)
			}
		case 'H':
			fmt.Fprintf(&b, "%02d", p.h)
		case 'I':
			h := p.h % 12
			if h == 0 {
				h = 12
			}
			fmt.Fprintf(&b, "%02d", h)
		case 'k':
			fmt.Fprintf(&b, "%2d", p.h)
		case 'l':
			h := p.h % 12
			if h == 0 {
				h = 12
			}
			fmt.Fprintf(&b, "%2d", h)
		case 'p':
			if p.h >= 12 {
				b.WriteString("PM")
			} else {
				b.WriteString("AM")
			}
		case 'P':
			if p.h >= 12 {
				b.WriteString("pm")
			} else {
				b.WriteString("am")
			}
		case 'j':
			jan1 := dateTime{Y: p.Y, M: 1, D: 1, validYMD: true}
			jan1.computeJD()
			y := *p
			y.validJD = false
			y.validHMS = false
			y.computeJD()
			fmt.Fprintf(&b, "%03d", int((y.iJD-jan1.iJD+43200000)/86400000)+1)
		case 'J':
			s := formatFloatSQL(float64(p.iJD)/86400000.0, 'g', 16, 0, fmtFlags{alt2: true})
			b.WriteString(s)
		case 'm':
			fmt.Fprintf(&b, "%02d", p.M)
		case 'M':
			fmt.Fprintf(&b, "%02d", p.m)
		case 's':
			if p.useSubsec {
				b.WriteString(FormatReal(float64(p.iJD-210866760000000) / 1000.0))
			} else {
				v := p.iJD/1000 - 21086676*10000
				b.WriteString(strconv.FormatInt(v, 10))
			}
		case 'S':
			fmt.Fprintf(&b, "%02d", int(p.s))
		case 'T':
			fmt.Fprintf(&b, "%02d:%02d:%02d", p.h, p.m, int(p.s))
		case 'R':
			fmt.Fprintf(&b, "%02d:%02d", p.h, p.m)
		case 'u':
			dow := int((p.iJD + 129600000) / 86400000 % 7)
			if dow == 0 {
				dow = 7
			}
			fmt.Fprintf(&b, "%d", dow)
		case 'w':
			dow := int((p.iJD + 129600000) / 86400000 % 7)
			fmt.Fprintf(&b, "%d", dow)
		case 'U', 'W':
			jan1 := dateTime{Y: p.Y, M: 1, D: 1, validYMD: true}
			jan1.computeJD()
			y := *p
			y.validJD = false
			y.validHMS = false
			y.computeJD()
			doy := int((y.iJD - jan1.iJD + 43200000) / 86400000)
			wd := int((y.iJD + 129600000) / 86400000 % 7) // 0 = sunday
			var wk int
			if f[i] == 'U' {
				wk = (doy + 7 - wd) / 7
			} else {
				wk = (doy + 7 - ((wd + 6) % 7)) / 7
			}
			fmt.Fprintf(&b, "%02d", wk)
		case 'Y':
			if p.Y < 0 {
				fmt.Fprintf(&b, "-%04d", -p.Y)
			} else {
				fmt.Fprintf(&b, "%04d", p.Y)
			}
		case 'y':
			fmt.Fprintf(&b, "%02d", ((p.Y%100)+100)%100)
		case 'C':
			fmt.Fprintf(&b, "%02d", p.Y/100)
		case '%':
			b.WriteByte('%')
		default:
			return NullValue
		}
	}
	return TextValue(b.String())
}

