// Prepare compiles a statement. Errors are returned as *SQLError.
func (c *Conn) Prepare(stmt Stmt) (p *Prepared, err error) {
	defer catch(&err)
	cp := &compiler{conn: c}
	p = cp.prepareStmt(stmt, nil)
	return p, nil
}

func (cp *compiler) prepareStmt(stmt Stmt, trig *scope) *Prepared {
	switch s := stmt.(type) {
	case *SelectStmt:
		cs := cp.compileSelect(s.Sel, trig, nil)
		return &Prepared{colNames: cs.colNames, declTypes: cs.colDeclType, isQuery: true, readOnly: true, run: func(parent *Ctx, emit func([]Value) bool) {
			cs.run(parent, emit)
		}}
	case *InsertStmt:
		return cp.compileInsert(s, trig)
	case *UpdateStmt:
		return cp.compileUpdate(s, trig)
	case *DeleteStmt:
		return cp.compileDelete(s, trig)
	case *CreateTableStmt:
		return cp.prepCreateTable(s)
	case *CreateIndexStmt:
		return cp.prepCreateIndex(s)
	case *CreateViewStmt:
		return cp.prepCreateView(s)
	case *CreateTriggerStmt:
		return cp.prepCreateTrigger(s)
	case *CreateVirtualStmt:
		return cp.prepCreateVirtual(s)
	case *DropStmt:
		return cp.prepDrop(s)
	case *AlterStmt:
		return cp.prepAlter(s)
	case *TxnStmt:
		return cp.prepTxn(s)
	case *PragmaStmt:
		return cp.prepPragma(s)
	case *ExplainStmt:
		return cp.prepExplain(s)
	case *AttachStmt:
		return cp.prepAttach(s)
	case *DetachStmt:
		return cp.prepDetach(s)
	case *VacuumStmt, *AnalyzeStmt, *ReindexStmt:
		return &Prepared{run: func(parent *Ctx, emit func([]Value) bool) {}}
	}
	throw("unsupported statement")
	return nil
}

// Execute runs a prepared statement with statement-level atomicity.
func (c *Conn) Execute(p *Prepared, emit func([]Value) bool) (err error) {
	c.stmtGen++
	c.stmtTimeSet = false
	mark := len(c.undo)
	autoCommit := !c.inTxn
	defer func() {
		if r := recover(); r != nil {
			e, ok := r.(*SQLError)
			if !ok {
				if pe, ok2 := r.(*ParseError); ok2 {
					e = &SQLError{Msg: pe.Msg, Code: SQLITE_ERROR, Pos: pe.Pos}
				} else {
					panic(r)
				}
			}
			if e.rollback {
				c.rollbackTo(0)
				c.inTxn = false
				c.savepoints = nil
			} else if e.fail {
				// keep changes
				if autoCommit {
					c.commit()
				}
			} else {
				c.rollbackTo(mark)
			}
			err = e
			return
		}
		if autoCommit && !c.inTxn {
			c.commitPersist()
		}
	}()
	if p.isDML {
		c.changes = 0
	}
	p.run(nil, emit)
	return nil
}

func (c *Conn) commitPersist() {
	if len(c.undo) > 0 || c.dirty {
		c.commit()
		c.persist()
	}
	c.dirty = false
}

// ------------- transactions --------------

func (cp *compiler) prepTxn(s *TxnStmt) *Prepared {
	c := cp.conn
	return &Prepared{run: func(parent *Ctx, emit func([]Value) bool) {
		switch s.Kind {
		case "BEGIN":
			if c.inTxn {
				throw("cannot start a transaction within a transaction")
			}
			c.inTxn = true
			c.undo = c.undo[:0]
		case "COMMIT":
			if !c.inTxn {
				throw("cannot commit - no transaction is active")
			}
			c.inTxn = false
			c.commit()
			c.persist()
		case "ROLLBACK":
			if s.Name != "" {
				idx := -1
				for i := len(c.savepoints) - 1; i >= 0; i-- {
					if strings.EqualFold(c.savepoints[i].name, s.Name) {
						idx = i
						break
					}
				}
				if idx < 0 {
					throw("no such savepoint: %s", s.Name)
				}
				c.rollbackTo(c.savepoints[idx].undoPos)
				c.savepoints = c.savepoints[:idx+1]
				return
			}
			if !c.inTxn {
				throw("cannot rollback - no transaction is active")
			}
			c.rollbackTo(0)
			c.inTxn = false
			c.savepoints = nil
		case "SAVEPOINT":
			if !c.inTxn {
				c.inTxn = true
				c.undo = c.undo[:0]
				c.savepoints = append(c.savepoints, savepoint{name: s.Name, undoPos: 0, isTxn: true})
				return
			}
			c.savepoints = append(c.savepoints, savepoint{name: s.Name, undoPos: len(c.undo)})
		case "RELEASE":
			idx := -1
			for i := len(c.savepoints) - 1; i >= 0; i-- {
				if strings.EqualFold(c.savepoints[i].name, s.Name) {
					idx = i
					break
				}
			}
			if idx < 0 {
				throw("no such savepoint: %s", s.Name)
			}
			isTxn := c.savepoints[idx].isTxn
			c.savepoints = c.savepoints[:idx]
			if isTxn {
				c.inTxn = false
				c.commit()
				c.persist()
			}
		}
	}}
}

// ------------- triggers --------------

type trigCtx struct {
	old, new []Value
	oldRowid int64
	newRowid int64
}

func (c *Conn) triggersFor(t *Table, event, time string, changedCols map[int]bool) []*Trigger {
	var res []*Trigger
	for _, s := range c.allSchemas() {
		for _, e := range s.entries {
			tr, ok := e.obj.(*Trigger)
			if !ok {
				continue
			}
			if !strings.EqualFold(tr.Table, t.Name) || tr.Event != event || tr.Time != time {
				continue
			}
			if event == "UPDATE" && len(tr.UpdateCols) > 0 && changedCols != nil {
				hit := false
				for _, cn := range tr.UpdateCols {
					ci := t.colIndex(cn)
					if ci >= 0 && changedCols[ci] {
						hit = true
					}
				}
				if !hit {
					continue
				}
			}
			res = append(res, tr)
		}
	}
	return res
}

type compiledTrigger struct {
	when  *cexpr
	stmts []*Prepared
	gen   int
}

func (c *Conn) fireTriggers(t *Table, trigs []*Trigger, old, new []Value, oldRowid, newRowid int64) {
	for _, tr := range trigs {
		c.fireTrigger(t, tr, old, new, oldRowid, newRowid)
	}
}

func (c *Conn) trigScope(t *Table) *scope {
	oldSrc := tableSrcInfo(t, "old")
	oldSrc.idx = 0
	newSrc := tableSrcInfo(t, "new")
	newSrc.idx = 1
	return &scope{srcs: []*srcInfo{oldSrc, newSrc}, lvl: &level{}}
}

func (c *Conn) fireTrigger(t *Table, tr *Trigger, old, new []Value, oldRowid, newRowid int64) {
	if c.activeTriggers == nil {
		c.activeTriggers = map[*Trigger]int{}
	}
	if c.activeTriggers[tr] > 0 && !c.recursiveTriggers {
		return
	}
	if c.triggerDepth >= 1000 {
		throw("too many levels of trigger recursion")
	}
	ct := c.trigCache[tr]
	if ct == nil || ct.gen != c.schemaGen {
		cp := &compiler{conn: c}
		sc := c.trigScope(t)
		ct = &compiledTrigger{gen: c.schemaGen}
		saved := c.inTriggerCompile
		c.inTriggerCompile = true
		func() {
			defer func() { c.inTriggerCompile = saved }()
			if tr.When != nil {
				w := cp.compileExpr(tr.When, sc)
				ct.when = &w
			}
			for _, st := range tr.Body {
				ct.stmts = append(ct.stmts, cp.prepareStmt(st, sc))
			}
		}()
		if c.trigCache == nil {
			c.trigCache = map[*Trigger]*compiledTrigger{}
		}
