	if ct.when != nil {
		if !ct.when.fn(ctx).Bool() {
			return
		}
	}
	c.activeTriggers[tr]++
	c.triggerDepth++
	savedChanges := c.changes
	defer func() {
		c.activeTriggers[tr]--
		c.triggerDepth--
		c.changes = savedChanges
	}()
	func() {
		defer func() {
			if r := recover(); r != nil {
				if e, ok := r.(*SQLError); ok && e.ignore {
					panic(r)
				}
				panic(r)
			}
		}()
		for _, p := range ct.stmts {
			c.stmtGen++
			p.run(ctx, func(v []Value) bool { return true })
		}
	}()
}
