cd /workspace/src && cat > dml.go <<'EOF'
package main

import (
	"math"
	"strings"
)

// conflict resolution codes
func resolveConflict(stmtOr, constraintOr string) string {
	if stmtOr != "" {
		return stmtOr
	}
	if constraintOr != "" {
		return constraintOr
	}
	return "ABORT"
}

type rowWriter struct {
	c      *Conn
	t      *Table
	checks []cexpr
	gens   []cexpr // generated column exprs indexed by column (nil if not generated)
	defs   []*cexpr
	orc    string
}

func (cp *compiler) newRowWriter(t *Table, orc string) *rowWriter {
	w := &rowWriter{c: cp.conn, t: t, orc: orc}
	sc := &scope{srcs: []*srcInfo{tableSrcInfo(t, t.Name)}, lvl: &level{}}
	sc.srcs[0].idx = 0
	for _, ck := range t.Checks {
		w.checks = append(w.checks, cp.compileExpr(ck.E, sc))
	}
	w.gens = make([]cexpr, len(t.Cols))
	w.defs = make([]*cexpr, len(t.Cols))
	for i, col := range t.Cols {
		if col.Generated != nil {
			w.gens[i] = cp.compileExpr(col.Generated, sc)
		}
		if col.Default != nil {
			d := cp.compileExpr(col.Default, &scope{lvl: &level{}})
			w.defs[i] = &d
		}
	}
	return w
}

func (w *rowWriter) defaultValue(c *Ctx, i int) Value {
	if w.defs[i] == nil {
		return NullValue
	}
	v := w.defs[i].fn(c)
	return v
}

func strictTypeOK(col *Column, v Value) (Value, bool) {
	if v.K == KNull {
		return v, true
	}
	t := strings.ToUpper(col.Type)
	switch t {
	case "ANY":
		return v, true
	case "INT", "INTEGER":
		v = applyAffinity(v, AffInteger)
		if v.K == KReal && v.F == math.Trunc(v.F) && math.Abs(v.F) < 9.2e18 {
			v = IntValue(int64(v.F))
		}
		return v, v.K == KInt
	case "REAL":
		v = applyAffinity(v, AffReal)
		return v, v.K == KReal
	case "TEXT":
		v = applyAffinity(v, AffText)
		return v, v.K == KText
	case "BLOB":
		return v, v.K == KBlob
	}
	return v, true
}

func typeNameUpper(v Value) string {
	return strings.ToUpper(v.TypeName())
}

// prepareRow applies affinity, computes generated columns
func (w *rowWriter) prepareRow(c *Ctx, row []Value, rowid int64) {
	t := w.t
	for i, col := range t.Cols {
		if col.Generated != nil {
			continue
		}
		if i == t.IPK {
			row[i] = NullValue
			continue
		}
		if t.Strict {
			nv, ok := strictTypeOK(col, row[i])
			if !ok {
				panic(&SQLError{Msg: "cannot store " + typeNameUpper(row[i]) + " value in " + strings.ToUpper(col.Type) + " column " + t.Name + "." + col.Name, Code: SQLITE_CONSTRAINT, Pos: -1})
			}
			row[i] = nv
		} else {
			row[i] = applyAffinity(row[i], col.Aff)
		}
	}
	w.computeGenerated(c, row, rowid)
}

func (w *rowWriter) computeGenerated(c *Ctx, row []Value, rowid int64) {
	t := w.t
	has := false
	for _, col := range t.Cols {
		if col.Generated != nil {
			has = true
		}
	}
	if !has {
		return
	}
	ctx := &Ctx{conn: w.c, rows: [][]Value{row}, rowids: []int64{rowid}}
	if t.IPK >= 0 {
		row[t.IPK] = IntValue(rowid)
	}
	for pass := 0; pass < 2; pass++ {
		for i, col := range t.Cols {
			if col.Generated != nil {
				v := w.gens[i].fn(ctx)
				row[i] = applyAffinity(v, col.Aff)
			}
		}
	}
	if t.IPK >= 0 {
		row[t.IPK] = NullValue
	}
}

// returns false if row should be skipped (IGNORE)
func (w *rowWriter) checkNotNull(c *Ctx, row []Value, orc string) bool {
	t := w.t
	for i, col := range t.Cols {
		if i == t.IPK {
			continue
		}
		isNN := col.NotNull || (t.WithoutRowid && col.PK > 0)
		if !isNN || row[i].K != KNull {
			continue
		}
		action := resolveConflict(orc, col.NNConflict)
		switch action {
		case "IGNORE":
			return false
		case "REPLACE":
			if w.defs[i] != nil {
				dv := applyAffinity(w.defaultValue(c, i), col.Aff)
				if dv.K != KNull {
					row[i] = dv
					continue
				}
			}
		}
		e := constraintErr("NOT NULL constraint failed: " + t.Name + "." + col.Name)
		if action == "ROLLBACK" {
			e.rollback = true
		} else if action == "FAIL" {
			e.fail = true
		}
		panic(e)
	}
	return true
}

func (w *rowWriter) checkChecks(row []Value, rowid int64, orc string) bool {
	t := w.t
	if len(w.checks) == 0 {
		return true
	}
	vals := row
	if t.IPK >= 0 {
		vals = append([]Value(nil), row...)
		vals[t.IPK] = IntValue(rowid)
	}
	ctx := &Ctx{conn: w.c, rows: [][]Value{vals}, rowids: []int64{rowid}}
	for i, ck := range w.checks {
		v := ck.fn(ctx)
		if v.K != KNull && !v.Bool() {
			if orc == "IGNORE" {
				return false
			}
			name := t.Checks[i].Name
			if name == "" {
				name = t.Checks[i].Text
			}
			e := constraintErr("CHECK constraint failed: " + name)
			if orc == "ROLLBACK" {
				e.rollback = true
			} else if orc == "FAIL" {
				e.fail = true
			}
			panic(e)
		}
	}
	return true
}

// find conflicting rowid in unique index (excluding selfRowid); -1 if none
func (w *rowWriter) findConflict(ix *Index, row []Value, rowid int64, selfRowid int64, hasSelf bool) (int64, bool) {
	c := w.c
	t := w.t
	vals := row
	if t.IPK >= 0 {
		vals = append([]Value(nil), row...)
		vals[t.IPK] = IntValue(rowid)
	}
	if !c.indexIncludes(ix, t, vals, rowid) {
		return 0, false
	}
	key := c.indexKey(ix, t, vals, rowid)
	for _, k := range key {
		if k.K == KNull {
			return 0, false
		}
	}
	lo := ix.lowerBound(key)
	hi := ix.upperBound(key)
	for i := lo; i < hi; i++ {
		r := ix.entries[i].rowid
		if hasSelf && r == selfRowid {
			continue
		}
		return r, true
	}
	return 0, false
}

func uniqueErrMsg(t *Table, ix *Index) string {
	var parts []string
	for _, ic := range ix.Cols {
		if ic.Col >= 0 {
			parts = append(parts, t.Name+"."+t.Cols[ic.Col].Name)
		} else if ic.Col == -2 {
			parts = append(parts, t.Name+".rowid")
		} else {
			parts = append(parts, "index '"+ix.Name+"'")
			return "UNIQUE constraint failed: index '" + ix.Name + "'"
		}
	}
	return "UNIQUE constraint failed: " + strings.Join(parts, ", ")
}

// unique index check order (SQLite checks newer indexes first, REPLACE last)
func (t *Table) uniqueIndexes() []*Index {
	var res []*Index
	for i := len(t.Indexes) - 1; i >= 0; i-- {
		ix := t.Indexes[i]
		if ix.Unique {
			res = append(res, ix)
		}
	}
	return res
}

func toRowid(v Value) (int64, bool) {
	switch v.K {
	case KInt:
		return v.I, true
	case KReal:
		if v.F == math.Trunc(v.F) && v.F >= -9.2233720368547758e18 && v.F < 9.2233720368547758e18 {
			return int64(v.F), true
		}
		return 0, false
	case KText:
		n := textToNumericAff(v)
		if n.K == KInt {
			return n.I, true
		}
		if n.K == KReal {
			return toRowid(n)
		}
		return 0, false
	case KBlob:
		return toRowid(TextValue(v.S))
	}
	return 0, false
}

// ---------------- INSERT ----------------

func (cp *compiler) findTargetTable(schema, name string, forWhat string) *Table {
	c := cp.conn
	if schema != "" && c.schemaByName(schema) == nil {
		throw("no such table: %s.%s", schema, name)
	}
	t := c.findTable(schema, name)
	if t == nil {
		if v := c.findView(schema, name); v != nil {
			throw("cannot modify %s because it is a view", v.Name)
		}
		if schema != "" {
			throw("no such table: %s.%s", schema, name)
		}
		throw("no such table: %s", name)
	}
	if strings.HasPrefix(strings.ToLower(t.Name), "sqlite_") && !strings.EqualFold(t.Name, "sqlite_sequence") && !strings.HasPrefix(strings.ToLower(t.Name), "sqlite_stat") {
		throw("table %s may not be modified", t.Name)
	}
	if t.isVirtual {
		throw("table %s may not be modified", t.Name)
	}
	return t
}

func (cp *compiler) compileReturning(rcs []*ResultCol, t *Table, alias string, parent *scope) (*scope, []cexpr, []string) {
	if rcs == nil {
		return nil, nil, nil
	}
	si := tableSrcInfo(t, alias)
	si.idx = 0
	sc := &scope{srcs: []*srcInfo{si}, parent: parent, lvl: &level{}}
	var fns []cexpr
	var names []string
	for _, rc := range rcs {
		if rc.Star {
			for ci, col := range t.Cols {
				if col.Hidden != 0 {
					continue
				}
				fns = append(fns, cexpr{fn: makeColReader(0, 0, ci)})
				names = append(names, col.Name)
			}
			continue
		}
		x := cp.compileExpr(rc.E, sc)
		fns = append(fns, x)
		name := rc.Alias
		if name == "" {
			if rc.E.Op == EColumn {
				name = cp.columnDisplayName(rc.E, sc)
			} else {
				name = rc.Span
			}
		}
		names = append(names, name)
	}
	return sc, fns, names
}

func fullRow(t *Table, row []Value, rowid int64) []Value {
	if t.IPK < 0 {
		return row
	}
	r := append([]Value(nil), row...)
	r[t.IPK] = IntValue(rowid)
	return r
}

type upsertC struct {
	u       *Upsert
	index   *Index // nil => rowid/PK or any
	isRowid bool
	anyTgt  bool
	set     []struct {
		cols []int
		e    cexpr
		isRowid bool
	}
	where *cexpr
}

func (cp *compiler) compileInsert(s *InsertStmt, parent *scope) *Prepared {
	c := cp.conn
	if s.With != nil {
		// CTEs for the source select
		if s.Sel != nil {
			if s.Sel.With == nil {
				s.Sel.With = s.With
			} else {
				s.Sel.With = &With{Recursive: s.With.Recursive || s.Sel.With.Recursive, CTEs: append(append([]*CTE(nil), s.With.CTEs...), s.Sel.With.CTEs...)}
			}
		}
	}
	t := cp.findTargetTable(s.Schema, s.Table, "insert")
	ncol := len(t.Cols)
	// column mapping
	var colMap []int // -1 => rowid
	if s.Cols != nil {
		seen := map[int]bool{}
		for _, cn := range s.Cols {
			ci := t.colIndex(cn)
			if ci < 0 {
				if isRowidName(cn) && !t.WithoutRowid {
					colMap = append(colMap, -1)
					continue
				}
				throw("table %s has no column named %s", t.Name, cn)
			}
			if t.Cols[ci].Generated != nil {
				throw("cannot INSERT into generated column \"%s\"", t.Cols[ci].Name)
			}
			_ = seen
			colMap = append(colMap, ci)
		}
	} else {
		for i, col := range t.Cols {
			if col.Generated != nil {
				continue
			}
			colMap = append(colMap, i)
		}
	}
	var src *compiledSelect
	if !s.Default {
		src = cp.compileSelect(s.Sel, parent, nil)
		if len(src.colNames) != len(colMap) {
			if s.Cols != nil {
				throw("%d values for %d columns", len(src.colNames), len(colMap))
			}
			throw("table %s has %d columns but %d values were supplied", t.Name, len(colMap), len(src.colNames))
		}
	}
	orc := s.OrConflict
	w := cp.newRowWriter(t, orc)
	alias := s.Alias
	if alias == "" {
		alias = t.Name
	}
	// upserts
	var ups []*upsertC
	for i, u := range s.Upserts {
		uc := &upsertC{u: u}
		if u.Target == nil {
			if i != len(s.Upserts)-1 {
				throw("ON CONFLICT clause does not match any PRIMARY KEY or UNIQUE constraint")
			}
			uc.anyTgt = true
		} else {
			// match target to index
			var cols []int
			for _, ic := range u.Target {
				if ic.E.Op != EColumn {
					cols = append(cols, -99)
					continue
				}
				ci := t.colIndex(ic.E.Column)
				if ci < 0 {
					if isRowidName(ic.E.Column) {
						cols = append(cols, -1)
						continue
					}
					throw("no such column: %s", ic.E.Column)
				}
				if ci == t.IPK {
					ci = -1
				}
				cols = append(cols, ci)
			}
			if len(cols) == 1 && cols[0] == -1 {
				uc.isRowid = true
			} else {
				for _, ix := range t.Indexes {
					if !ix.Unique || len(ix.Cols) != len(cols) {
						continue
					}
					match := true
					for _, ic := range ix.Cols {
						found := false
						for _, cc := range cols {
							if cc == ic.Col {
								found = true
							}
						}
						if !found {
							match = false
						}
					}
					if match {
						uc.index = ix
						break
					}
				}
				if uc.index == nil {
					throw("ON CONFLICT clause does not match any PRIMARY KEY or UNIQUE constraint")
				}
			}
		}
		if !u.DoNothing {
			si := tableSrcInfo(t, alias)
			si.idx = 0
			ex := tableSrcInfo(t, "excluded")
			ex.idx = 1
			sc := &scope{srcs: []*srcInfo{si, ex}, parent: parent, lvl: &level{}}
			for _, sc2 := range u.Set {
				var cols []int
				isRowid := false
				for _, cn := range sc2.Cols {
					ci := t.colIndex(cn)
					if ci < 0 {
						if isRowidName(cn) {
							isRowid = true
							cols = append(cols, -1)
							continue
						}
						throw("no such column: %s", cn)
					}
					cols = append(cols, ci)
				}
				x := cp.compileExpr(sc2.E, sc)
				uc.set = append(uc.set, struct {
					cols    []int
					e       cexpr
					isRowid bool
				}{cols, x, isRowid})
			}
			if u.Where != nil {
				x := cp.compileExpr(u.Where, sc)
				uc.where = &x
			}
		}
		ups = append(ups, uc)
	}
	_, retFns, retNames := cp.compileReturning(s.Returning, t, alias, parent)
	upW := cp.newRowWriter(t, "")
	p := &Prepared{isDML: true, colNames: retNames, isQuery: retFns != nil}
	p.run = func(pc *Ctx, emit func([]Value) bool) {
		ctx := &Ctx{conn: c, parent: pc}
		// materialize source rows
		var srcRows [][]Value
		if s.Default {
			srcRows = [][]Value{{}}
		} else {
			src.run(pc, func(r []Value) bool {
				srcRows = append(srcRows, append([]Value(nil), r...))
				return true
			})
		}
		var retRows [][]Value
		befTrig := c.triggersFor(t, "INSERT", "BEFORE", nil)
		aftTrig := c.triggersFor(t, "INSERT", "AFTER", nil)
		for _, sv := range srcRows {
			row := make([]Value, ncol)
			set := make([]bool, ncol)
			var rowidVal Value
			hasRowidVal := false
			if !s.Default {
				for i, ci := range colMap {
					if ci == -1 {
						rowidVal = sv[i]
						hasRowidVal = true
						continue
					}
					row[ci] = sv[i]
					set[ci] = true
				}
			}
			for i := range t.Cols {
				if !set[i] && t.Cols[i].Generated == nil {
					row[i] = w.defaultValue(ctx, i)
				}
			}
			var rowid int64
			autoRowid := true
			if t.IPK >= 0 && row[t.IPK].K != KNull {
				rowidVal = row[t.IPK]
				hasRowidVal = true
			}
			if hasRowidVal && rowidVal.K != KNull {
				id, ok := toRowid(rowidVal)
				if !ok {
					panic(&SQLError{Msg: "datatype mismatch", Code: SQLITE_MISMATCH, Pos: -1})
				}
				rowid = id
				autoRowid = false
			}
			if autoRowid {
				rowid = c.newRowid(t)
			}
			w.prepareRow(ctx, row, rowid)
			if len(befTrig) > 0 {
				nr := fullRow(t, row, rowid)
				c.fireTriggers(t, befTrig, nil, nr, 0, rowid)
			}
			if !w.checkNotNull(ctx, row, orc) {
				continue
			}
			if !w.checkChecks(row, rowid, orc) {
				continue
			}
			// uniqueness
			skip := false
			didUpsert := false
			if !t.WithoutRowid {
				if existing := t.getRow(rowid); existing != nil && !autoRowid {
					// rowid conflict
					handled := false
					for _, uc := range ups {
						if uc.anyTgt || uc.isRowid {
							if uc.u.DoNothing {
								skip = true
							} else {
								cp.doUpsertUpdate(ctx, uc, upW, t, existing, row, rowid, &retRows, retFns)
								didUpsert = true
							}
							handled = true
							break
						}
					}
					if !handled {
						action := resolveConflict(orc, t.PKConflict)
						switch action {
						case "IGNORE":
							skip = true
						case "REPLACE":
							c.replaceDelete(t, rowid)
						default:
							col := "rowid"
							if t.IPK >= 0 {
								col = t.Cols[t.IPK].Name
							}
							e := constraintErr("UNIQUE constraint failed: " + t.Name + "." + col)
							if action == "ROLLBACK" {
								e.rollback = true
							} else if action == "FAIL" {
								e.fail = true
							}
							panic(e)
						}
					}
				}
			}
			if skip || didUpsert {
				continue
			}
			for _, ix := range t.uniqueIndexes() {
				confRowid, conflict := w.findConflict(ix, row, rowid, 0, false)
				if !conflict {
					continue
				}
				handled := false
				for _, uc := range ups {
					if uc.anyTgt || uc.index == ix {
						existing := t.getRow(confRowid)
						if uc.u.DoNothing {
							skip = true
						} else {
							cp.doUpsertUpdate(ctx, uc, upW, t, existing, row, rowid, &retRows, retFns)
							didUpsert = true
						}
						handled = true
						break
					}
				}
				if handled {
					break
				}
				action := resolveConflict(orc, ix.Conflict)
				switch action {
				case "IGNORE":
					skip = true
				case "REPLACE":
					c.replaceDelete(t, confRowid)
					continue
				default:
					e := constraintErr(uniqueErrMsg(t, ix))
					if ix.Origin == "pk" {
						e = constraintErr(uniqueErrMsg(t, ix))
					}
					if action == "ROLLBACK" {
						e.rollback = true
					} else if action == "FAIL" {
						e.fail = true
					}
					panic(e)
				}
				if skip {
					break
				}
			}
			if skip || didUpsert {
				continue
			}
			if c.foreignKeys {
				c.fkCheckChild(t, row, rowid)
			}
			c.insertRow(t, rowid, row)
			if t.AutoInc {
				c.updateSequence(t, rowid)
			}
			c.changes++
			c.totalChanges++
			c.lastRowid = rowid
			if len(aftTrig) > 0 {
				c.fireTriggers(t, aftTrig, nil, fullRow(t, row, rowid), 0, rowid)
			}
			if retFns != nil {
				rctx := &Ctx{conn: c, parent: pc, rows: [][]Value{fullRow(t, row, rowid)}, rowids: []int64{rowid}}
				rr := make([]Value, len(retFns))
				for i, f := range retFns {
					rr[i] = f.fn(rctx)
				}
				retRows = append(retRows, rr)
			}
		}
		for _, r := range retRows {
			if !emit(r) {
				break
			}
		}
	}
	return p
}

func (c *Conn) replaceDelete(t *Table, rowid int64) {
	old := t.getRow(rowid)
	if old == nil {
		return
	}
	var bef, aft []*Trigger
	if c.recursiveTriggers {
		bef = c.triggersFor(t, "DELETE", "BEFORE", nil)
		aft = c.triggersFor(t, "DELETE", "AFTER", nil)
	}
	ov := fullRow(t, old.Vals, rowid)
	if len(bef) > 0 {
		c.fireTriggers(t, bef, ov, nil, rowid, 0)
	}
	if c.foreignKeys {
		c.fkParentDelete(t, old.Vals, rowid)
	}
	c.deleteRow(t, rowid)
	if len(aft) > 0 {
		c.fireTriggers(t, aft, ov, nil, rowid, 0)
	}
}

func (cp *compiler) doUpsertUpdate(ctx *Ctx, uc *upsertC, w *rowWriter, t *Table, existing *Row, excluded []Value, exRowid int64, retRows *[][]Value, retFns []cexpr) {
	c := cp.conn
	if existing == nil {
		return
	}
	old := fullRow(t, existing.Vals, existing.Rowid)
	ex := fullRow(t, excluded, exRowid)
	uctx := &Ctx{conn: c, parent: ctx.parent, rows: [][]Value{old, ex}, rowids: []int64{existing.Rowid, exRowid}}
	if uc.where != nil && !uc.where.fn(uctx).Bool() {
		return
	}
	newRow := append([]Value(nil), existing.Vals...)
	newRowid := existing.Rowid
	changed := map[int]bool{}
	for _, sc := range uc.set {
		v := sc.e.fn(uctx)
		if len(sc.cols) > 1 {
			throw("row value misused")
		}
		ci := sc.cols[0]
		if ci == -1 || ci == t.IPK {
			id, ok := toRowid(v)
			if !ok {
				panic(&SQLError{Msg: "datatype mismatch", Code: SQLITE_MISMATCH, Pos: -1})
			}
			newRowid = id
			continue
		}
		newRow[ci] = v
		changed[ci] = true
	}
	cp.applyUpdate(ctx, w, t, existing, newRow, newRowid, changed, "", retRows, retFns, nil)
}

// applyUpdate performs constraint checks and the update of a single row
func (cp *compiler) applyUpdate(ctx *Ctx, w *rowWriter, t *Table, old *Row, newRow []Value, newRowid int64, changed map[int]bool, orc string, retRows *[][]Value, retFns []cexpr, extra func(rctx *Ctx)) bool {
	c := cp.conn
	oldRowid := old.Rowid
	oldFull := fullRow(t, old.Vals, oldRowid)
	w.prepareRow(ctx, newRow, newRowid)
	bef := c.triggersFor(t, "UPDATE", "BEFORE", changed)
	if len(bef) > 0 {
		c.fireTriggers(t, bef, oldFull, fullRow(t, newRow, newRowid), oldRowid, newRowid)
		// row may have been modified/deleted by trigger
		if t.getRow(oldRowid) == nil {
			return false
		}
	}
	if !w.checkNotNull(ctx, newRow, orc) {
		return false
	}
	if !w.checkChecks(newRow, newRowid, orc) {
		return false
	}
	if newRowid != oldRowid {
		if t.getRow(newRowid) != nil {
			action := resolveConflict(orc, t.PKConflict)
			switch action {
			case "IGNORE":
				return false
			case "REPLACE":
				c.replaceDelete(t, newRowid)
			default:
				col := "rowid"
				if t.IPK >= 0 {
					col = t.Cols[t.IPK].Name
				}
				e := constraintErr("UNIQUE constraint failed: " + t.Name + "." + col)
				if action == "ROLLBACK" {
					e.rollback = true
				} else if action == "FAIL" {
					e.fail = true
				}
				panic(e)
			}
		}
	}
	for _, ix := range t.uniqueIndexes() {
		confRowid, conflict := w.findConflict(ix, newRow, newRowid, oldRowid, true)
		if !conflict {
			continue
		}
		action := resolveConflict(orc, ix.Conflict)
		switch action {
		case "IGNORE":
			return false
		case "REPLACE":
			c.replaceDelete(t, confRowid)
			continue
		default:
			e := constraintErr(uniqueErrMsg(t, ix))
			if action == "ROLLBACK" {
				e.rollback = true
			} else if action == "FAIL" {
				e.fail = true
			}
			panic(e)
		}
	}
	if c.foreignKeys {
		c.fkCheckChild(t, newRow, newRowid)
		c.fkParentUpdate(t, old.Vals, oldRowid, newRow, newRowid)
	}
	c.updateRow(t, oldRowid, newRowid, newRow)
	c.changes++
	c.totalChanges++
	aft := c.triggersFor(t, "UPDATE", "AFTER", changed)
	if len(aft) > 0 {
		c.fireTriggers(t, aft, oldFull, fullRow(t, newRow, newRowid), oldRowid, newRowid)
	}
	if retFns != nil {
		rctx := &Ctx{conn: c, parent: ctx.parent, rows: [][]Value{fullRow(t, newRow, newRowid)}, rowids: []int64{newRowid}}
		if extra != nil {
			extra(rctx)
		}
		rr := make([]Value, len(retFns))
		for i, f := range retFns {
			rr[i] = f.fn(rctx)
		}
		*retRows = append(*retRows, rr)
	}
	return true
}

// ---------------- UPDATE ----------------

func (cp *compiler) compileUpdate(s *UpdateStmt, parent *scope) *Prepared {
	c := cp.conn
	t := cp.findTargetTable(s.Schema, s.Table, "update")
	alias := s.Alias
	if alias == "" {
		alias = t.Name
	}
	// Build a select over target (+ FROM) to find rows
	items := []*FromItem{{Name: t.Name, Schema: s.Schema, Alias: alias, Indexed: s.Indexed}}
	for i, f := range s.From {
		f2 := *f
		if i == 0 {
			f2.Join = JInner
		}
		items = append(items, &f2)
	}
	var ctes *cteScope
	if s.With != nil {
		ns := &cteScope{defs: map[string]*cteDef{}}
		for _, cte := range s.With.CTEs {
			ns.defs[strings.ToLower(cte.Name)] = &cteDef{cte: cte, scope: parent, ctes: ns, recursive: s.With.Recursive && selectReferences(cte.Sel, cte.Name)}
		}
		ctes = ns
	}
	lvl := &level{}
	sc := &scope{parent: parent, lvl: lvl, ctes: ctes}
	srcs := cp.compileFrom(items, sc)
	type setC struct {
		cols    []int
		e       cexpr
		isRowid bool
	}
	var sets []setC
	changed := map[int]bool{}
	for _, st := range s.Set {
		var cols []int
		for _, cn := range st.Cols {
			ci := t.colIndex(cn)
			if ci < 0 {
				if isRowidName(cn) && !t.WithoutRowid {
					cols = append(cols, -1)
					continue
				}
				throw("no such column: %s", cn)
			}
			if t.Cols[ci].Generated != nil {
				throw("cannot UPDATE generated column \"%s\"", t.Cols[ci].Name)
			}
			cols = append(cols, ci)
			changed[ci] = true
		}
		var x cexpr
		if len(cols) > 1 {
			parts, pf := cp.vectorParts(st.E, sc)
			if len(parts) != len(cols) {
				throw("%d columns assigned %d values", len(cols), len(parts))
			}
			x = cexpr{fn: func(c *Ctx) Value { return Value{K: KNull, S: "", Sub: 0} }, sub: []cexpr{{fn: nil}}}
			x.nCols = len(cols)
			vf := pf
			sets = append(sets, setC{cols: cols, e: cexpr{fn: nil, nCols: len(cols), sub: []cexpr{{fn: func(c *Ctx) Value { return NullValue }}}}})
			sets[len(sets)-1].e.vecFn = vf
			continue
		}
		x = cp.compileExpr(st.E, sc)
		sets = append(sets, setC{cols: cols, e: x})
	}
	var terms []*termInfo
	if s.Where != nil {
		for _, tm := range splitAnd(s.Where) {
			ti := &termInfo{e: tm}
			ti.c, ti.deps = cp.compileWithDeps(tm, sc)
			terms = append(terms, ti)
		}
	}
	for i, src := range srcs {
		if src.onExpr == nil {
			continue
		}
		for _, tm := range splitAnd(src.onExpr) {
			ti := &termInfo{e: tm, isOn: src.join&(JLeft|JRight) != 0, srcIdx: i}
			ti.c, ti.deps = cp.compileWithDeps(tm, sc)
			terms = append(terms, ti)
		}
	}
	// order by / limit
	var obs []cexpr
	var specs []orderSpec
	for _, ot := range s.OrderBy {
		x := cp.compileExpr(ot.E, sc)
		obs = append(obs, x)
		specs = append(specs, orderSpec{desc: ot.Desc, nulls: ot.Nulls, coll: getCollation(x.coll)})
	}
	lim, off := cp.compileLimit(s.Limit, s.Offset, parent)
	plan := cp.planJoins(srcs, terms, sc, nil, &Select{Where: s.Where, From: items}, false)
	_ = plan
	// for UPDATE, target must be outer loop to keep rowid order semantics; use FROM order
	w := cp.newRowWriter(t, s.OrConflict)
	_, retFns, retNames := cp.compileReturning(s.Returning, t, alias, parent)
	nsrc := len(srcs)
	p := &Prepared{isDML: true, colNames: retNames, isQuery: retFns != nil}
	p.run = func(pc *Ctx, emit func([]Value) bool) {
		ctx := &Ctx{conn: c, parent: pc, rows: make([][]Value, nsrc), rowids: make([]int64, nsrc)}
		type cand struct {
			rowid int64
			rows  [][]Value
			rids  []int64
			keys  []Value
		}
		var cands []cand
		seen := map[int64]bool{}
		plan.run(ctx, func() bool {
			rid := ctx.rowids[0]
			if seen[rid] {
				return true
			}
			seen[rid] = true
			cd := cand{rowid: rid, rows: append([][]Value(nil), ctx.rows...), rids: append([]int64(nil), ctx.rowids...)}
			if obs != nil {
				cd.keys = make([]Value, len(obs))
				for i, o := range obs {
					cd.keys[i] = o.fn(ctx)
				}
			}
			cands = append(cands, cd)
			return true
		})
		if obs != nil {
			rows := make([]outRow, len(cands))
			for i := range cands {
				rows[i] = outRow{keys: cands[i].keys, vals: []Value{IntValue(int64(i))}}
			}
			sortRows(rows, specs)
			nc := make([]cand, len(cands))
			for i, r := range rows {
				nc[i] = cands[r.vals[0].I]
			}
			cands = nc
		}
		if lim != nil || off != nil {
			limit := evalLimit(ctx, lim)
			offset := int64(0)
			if off != nil {
				offset = evalLimit(ctx, off)
			}
			if offset > int64(len(cands)) {
				offset = int64(len(cands))
			}
			if offset > 0 {
				cands = cands[offset:]
			}
			if limit >= 0 && limit < int64(len(cands)) {
				cands = cands[:limit]
			}
		}
		var retRows [][]Value
		for _, cd := range cands {
			cur := t.getRow(cd.rowid)
			if cur == nil {
				continue
			}
			copy(ctx.rows, cd.rows)
			copy(ctx.rowids, cd.rids)
			ctx.rows[0] = fullRow(t, cur.Vals, cur.Rowid)
			newRow := append([]Value(nil), cur.Vals...)
			newRowid := cur.Rowid
			for _, st := range sets {
				if st.e.vecFn != nil {
					vals := st.e.vecFn(ctx)
					for k, ci := range st.cols {
						if ci == -1 || ci == t.IPK {
							id, ok := toRowid(vals[k])
							if !ok {
								panic(&SQLError{Msg: "datatype mismatch", Code: SQLITE_MISMATCH, Pos: -1})
							}
							newRowid = id
							if ci == t.IPK {
								continue
							}
							continue
						}
						newRow[ci] = vals[k]
					}
					continue
				}
				v := st.e.fn(ctx)
				ci := st.cols[0]
				if ci == -1 || ci == t.IPK {
					if v.K == KNull && ci == t.IPK {
						// setting IPK to NULL -> new rowid? sqlite: datatype mismatch? assigns new rowid
						newRowid = c.newRowid(t)
						continue
					}
					id, ok := toRowid(v)
					if !ok {
						panic(&SQLError{Msg: "datatype mismatch", Code: SQLITE_MISMATCH, Pos: -1})
					}
					newRowid = id
					continue
				}
				newRow[ci] = v
			}
			rowsCopy := append([][]Value(nil), ctx.rows...)
			cp.applyUpdate(ctx, w, t, cur, newRow, newRowid, changed, s.OrConflict, &retRows, retFns, func(rctx *Ctx) {
				_ = rowsCopy
			})
		}
		for _, r := range retRows {
			if !emit(r) {
				break
			}
		}
	}
	return p
}

// ---------------- DELETE ----------------

func (cp *compiler) compileDelete(s *DeleteStmt, parent *scope) *Prepared {
	c := cp.conn
	t := cp.findTargetTable(s.Schema, s.Table, "delete")
	alias := s.Alias
	if alias == "" {
		alias = t.Name
	}
	items := []*FromItem{{Name: t.Name, Schema: s.Schema, Alias: alias}}
	var ctes *cteScope
	if s.With != nil {
		ns := &cteScope{defs: map[string]*cteDef{}}
		for _, cte := range s.With.CTEs {
			ns.defs[strings.ToLower(cte.Name)] = &cteDef{cte: cte, scope: parent, ctes: ns, recursive: s.With.Recursive && selectReferences(cte.Sel, cte.Name)}
		}
		ctes = ns
	}
	lvl := &level{}
	sc := &scope{parent: parent, lvl: lvl, ctes: ctes}
	srcs := cp.compileFrom(items, sc)
	var terms []*termInfo
	if s.Where != nil {
		for _, tm := range splitAnd(s.Where) {
			ti := &termInfo{e: tm}
			ti.c, ti.deps = cp.compileWithDeps(tm, sc)
			terms = append(terms, ti)
		}
	}
	var obs []cexpr
	var specs []orderSpec
	for _, ot := range s.OrderBy {
		x := cp.compileExpr(ot.E, sc)
		obs = append(obs, x)
		specs = append(specs, orderSpec{desc: ot.Desc, nulls: ot.Nulls, coll: getCollation(x.coll)})
	}
	lim, off := cp.compileLimit(s.Limit, s.Offset, parent)
	plan := cp.planJoins(srcs, terms, sc, nil, &Select{Where: s.Where, From: items}, false)
	_, retFns, retNames := cp.compileReturning(s.Returning, t, alias, parent)
	p := &Prepared{isDML: true, colNames: retNames, isQuery: retFns != nil}
	p.run = func(pc *Ctx, emit func([]Value) bool) {
		ctx := &Ctx{conn: c, parent: pc, rows: make([][]Value, 1), rowids: make([]int64, 1)}
		var ids []int64
		var keys [][]Value
		plan.run(ctx, func() bool {
			ids = append(ids, ctx.rowids[0])
			if obs != nil {
				k := make([]Value, len(obs))
				for i, o := range obs {
					k[i] = o.fn(ctx)
				}
				keys = append(keys, k)
			}
			return true
		})
		if obs != nil {
			rows := make([]outRow, len(ids))
			for i := range ids {
				rows[i] = outRow{keys: keys[i], vals: []Value{IntValue(ids[i])}}
			}
			sortRows(rows, specs)
			for i, r := range rows {
				ids[i] = r.vals[0].I
			}
		}
		if lim != nil || off != nil {
			limit := evalLimit(ctx, lim)
			offset := int64(0)
			if off != nil {
				offset = evalLimit(ctx, off)
			}
			if offset > int64(len(ids)) {
				offset = int64(len(ids))
			}
			if offset > 0 {
				ids = ids[offset:]
			}
			if limit >= 0 && limit < int64(len(ids)) {
				ids = ids[:limit]
			}
		}
		bef := c.triggersFor(t, "DELETE", "BEFORE", nil)
		aft := c.triggersFor(t, "DELETE", "AFTER", nil)
		var retRows [][]Value
		for _, id := range ids {
			r := t.getRow(id)
			if r == nil {
				continue
			}
			ov := fullRow(t, r.Vals, id)
			if len(bef) > 0 {
				c.fireTriggers(t, bef, ov, nil, id, 0)
				r = t.getRow(id)
				if r == nil {
					continue
				}
				ov = fullRow(t, r.Vals, id)
			}
			if retFns != nil {
				rctx := &Ctx{conn: c, parent: pc, rows: [][]Value{ov}, rowids: []int64{id}}
				rr := make([]Value, len(retFns))
				for i, f := range retFns {
					rr[i] = f.fn(rctx)
				}
				retRows = append(retRows, rr)
			}
			if c.foreignKeys {
				c.fkParentDelete(t, r.Vals, id)
			}
			c.deleteRow(t, id)
			c.changes++
			c.totalChanges++
			if len(aft) > 0 {
