package main

import (
	"strings"
)

func needsQuote(id string) bool {
	if id == "" {
		return true
	}
	if id[0] >= '0' && id[0] <= '9' {
		return true
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') {
			return true
		}
	}
	if keywords[strings.ToUpper(id)] {
		return true
	}
	return false
}

func quoteIdent(id string) string {
	if needsQuote(id) {
		return "\"" + strings.ReplaceAll(id, "\"", "\"\"") + "\""
	}
	return id
}

func (c *Conn) objectExists(s *Schema, name string) string {
	l := strings.ToLower(name)
	if _, ok := s.Tables[l]; ok {
		return "table"
	}
	if _, ok := s.Views[l]; ok {
		return "view"
	}
	if _, ok := s.Indexes[l]; ok {
		return "index"
	}
	return ""
}

func (cp *compiler) targetSchema(schema string, temp bool) *Schema {
	c := cp.conn
	if temp {
		if schema != "" && !strings.EqualFold(schema, "temp") {
			throw("temporary table name must be unqualified")
		}
		return c.temp
	}
	if schema != "" {
		s := c.schemaByName(schema)
		if s == nil {
			throw("unknown database %s", schema)
		}
		return s
	}
	return c.main
}

func (c *Conn) addSchemaUndo(s *Schema) {
	c.schemaGen++
	saved := append([]*schemaEntry(nil), s.entries...)
	savedPage := s.nextPage
	c.addUndo(func() {
		s.entries = saved
		s.nextPage = savedPage
		c.schemaGen++
	})
}

func (cp *compiler) buildTable(s *CreateTableStmt, sch *Schema) *Table {
	t := &Table{Name: s.Name, Schema: sch, IPK: -1, WithoutRowid: s.WithoutRowid, Strict: s.Strict, SQL: s.SQL}
	seen := map[string]bool{}
	var pkCols []IndexedCol
	pkConflict := ""
	pkAutoInc := false
	nPK := 0
	pkDescCol := false
	for _, cd := range s.Cols {
		l := strings.ToLower(cd.Name)
		if seen[l] {
			throw("duplicate column name: %s", cd.Name)
		}
		seen[l] = true
		col := &Column{Name: cd.Name, Type: cd.Type, Aff: affinityOfType(cd.Type), NotNull: cd.NotNull, NNConflict: cd.NNConflict, Default: cd.Default, DefaultText: cd.DefaultText, Collate: cd.Collate, Generated: cd.Generated, GenStored: cd.GenStored}
		if cd.Collate != "" && getCollation(cd.Collate) == nil {
			throw("no such collation sequence: %s", cd.Collate)
		}
		if s.Strict {
			u := strings.ToUpper(cd.Type)
			switch u {
			case "INT", "INTEGER", "REAL", "TEXT", "BLOB", "ANY":
			case "":
				throw("missing datatype for %s.%s", s.Name, cd.Name)
			default:
				throw("unknown datatype for %s.%s: \"%s\"", s.Name, cd.Name, cd.Type)
			}
			if u == "ANY" {
				col.Aff = AffNone
			}
		}
		if cd.Generated != nil {
			col.Hidden = 0
			if cd.Default != nil {
				throw("cannot use DEFAULT on a generated column")
			}
		}
		t.Cols = append(t.Cols, col)
		if cd.PrimaryKey {
			nPK++
			pkCols = []IndexedCol{{Name: cd.Name, Desc: cd.PKDesc}}
			pkConflict = cd.PKConflict
			pkAutoInc = cd.AutoInc
			pkDescCol = cd.PKDesc
		}
		for i, ck := range cd.Check {
			t.Checks = append(t.Checks, CheckDef{E: ck, Text: cd.CheckText[i]})
		}
		if cd.FK != nil {
			t.FKs = append(t.FKs, cd.FK)
		}
	}
	for _, tc := range s.Constraints {
		switch tc.Kind {
		case "PRIMARY":
			nPK++
			pkCols = tc.Cols
			pkConflict = tc.Conflict
			pkAutoInc = tc.AutoInc
			pkDescCol = false
		case "CHECK":
			t.Checks = append(t.Checks, CheckDef{E: tc.Check, Text: tc.CheckText, Name: tc.Name})
		case "FOREIGN":
			t.FKs = append(t.FKs, tc.FK)
		}
	}
	if nPK > 1 {
		throw("table \"%s\" has more than one primary key", s.Name)
	}
	t.PKConflict = pkConflict
	t.rebuildColMap()
	if len(pkCols) > 0 {
		for i, pc := range pkCols {
			ci := -1
			if pc.Name != "" {
				ci = t.colIndex(pc.Name)
			}
			if ci < 0 {
				nm := pc.Name
				if nm == "" && pc.E != nil {
					nm = pc.E.Column
				}
				throw("expressions prohibited in PRIMARY KEY and UNIQUE constraints")
			}
			t.Cols[ci].PK = i + 1
			t.PKCols = append(t.PKCols, ci)
		}
		if len(t.PKCols) == 1 && strings.EqualFold(t.Cols[t.PKCols[0]].Type, "INTEGER") && !s.WithoutRowid && !pkDescCol {
			t.IPK = t.PKCols[0]
		}
	}
	if pkAutoInc {
		if t.IPK < 0 {
			throw("AUTOINCREMENT is only allowed on an INTEGER PRIMARY KEY")
		}
		t.AutoInc = true
	}
	if s.WithoutRowid && len(t.PKCols) == 0 {
		throw("PRIMARY KEY missing on table %s", s.Name)
	}
	return t
}

func (cp *compiler) addAutoIndexes(t *Table, s *CreateTableStmt, sch *Schema) []*Index {
	var created []*Index
	mk := func(cols []IndexedCol, origin, conflict string) {
		ix := &Index{Table: t, Unique: true, Origin: origin, Conflict: conflict, Schema: sch}
		for _, ic := range cols {
			ci := t.colIndex(ic.Name)
			if ci < 0 {
				throw("expressions prohibited in PRIMARY KEY and UNIQUE constraints")
			}
			coll := ic.Collate
			if coll == "" {
				coll = t.Cols[ci].Collate
			}
			ix.Cols = append(ix.Cols, IdxCol{Col: ci, CollName: strings.ToUpper(coll), Coll: getCollation(coll), Desc: ic.Desc, Name: t.Cols[ci].Name})
		}
		// skip if identical unique index exists
		for _, ex := range t.Indexes {
			if len(ex.Cols) == len(ix.Cols) {
				same := true
				for i := range ex.Cols {
					if ex.Cols[i].Col != ix.Cols[i].Col || ex.Cols[i].CollName != ix.Cols[i].CollName {
						same = false
					}
				}
				if same {
					if ex.Conflict == "" {
						ex.Conflict = conflict
					}
					return
				}
			}
		}
		t.nAutoIdx++
		ix.Name = "sqlite_autoindex_" + t.Name + "_" + intToStr(t.nAutoIdx)
		t.Indexes = append(t.Indexes, ix)
		created = append(created, ix)
	}
	// order: column constraints in column order (PK/UNIQUE), then table constraints
	for _, cd := range s.Cols {
		if cd.PrimaryKey && t.IPK < 0 {
			mk([]IndexedCol{{Name: cd.Name, Desc: cd.PKDesc}}, "pk", cd.PKConflict)
		}
		if cd.Unique {
			mk([]IndexedCol{{Name: cd.Name}}, "u", cd.UQConflict)
		}
	}
	for _, tc := range s.Constraints {
		if tc.Kind == "PRIMARY" && t.IPK < 0 {
			mk(tc.Cols, "pk", tc.Conflict)
		}
		if tc.Kind == "UNIQUE" {
			mk(tc.Cols, "u", tc.Conflict)
		}
	}
	for _, ix := range t.Indexes {
		if ix.Origin == "pk" {
			t.pkIndex = ix
		}
	}
	return created
}

func (c *Conn) registerTable(sch *Schema, t *Table, created []*Index) {
	c.addSchemaUndo(sch)
	if !t.WithoutRowid || true {
		t.RootPage = sch.allocPage()
	}
	sch.Tables[strings.ToLower(t.Name)] = t
	sch.addEntry("table", t.Name, t.Name, t)
	for _, ix := range created {
		if t.WithoutRowid && ix.Origin == "pk" {
			continue
		}
		ix.RootPage = sch.allocPage()
		sch.Indexes[strings.ToLower(ix.Name)] = ix
		sch.addEntry("index", ix.Name, t.Name, ix)
	}
	name := strings.ToLower(t.Name)
	c.addUndo(func() {
		delete(sch.Tables, name)
		for _, ix := range created {
			delete(sch.Indexes, strings.ToLower(ix.Name))
		}
	})
	if t.AutoInc {
		if _, ok := sch.Tables["sqlite_sequence"]; !ok {
			sq := &Table{Name: "sqlite_sequence", Schema: sch, IPK: -1, SQL: "CREATE TABLE sqlite_sequence(name,seq)"}
			sq.Cols = []*Column{{Name: "name", Aff: AffNone}, {Name: "seq", Aff: AffNone}}
			sq.rebuildColMap()
			sq.RootPage = sch.allocPage()
			sch.Tables["sqlite_sequence"] = sq
			sch.addEntry("table", "sqlite_sequence", "sqlite_sequence", sq)
			c.addUndo(func() { delete(sch.Tables, "sqlite_sequence") })
		}
	}
}

func (cp *compiler) prepCreateTable(s *CreateTableStmt) *Prepared {
	c := cp.conn
	sch := cp.targetSchema(s.Schema, s.Temp)
	if kind := c.objectExists(sch, s.Name); kind != "" {
		if s.IfNotExists {
			return &Prepared{run: func(*Ctx, func([]Value) bool) {}}
		}
		if kind == "index" {
			throw("there is already an index named %s", s.Name)
		}
		throwPos(-2, "%s %s already exists", kind, s.Name)
	}
	if strings.HasPrefix(strings.ToLower(s.Name), "sqlite_") {
		throw("object name reserved for internal use: %s", s.Name)
	}
	if s.AsSelect != nil {
		cs := cp.compileSelect(s.AsSelect, nil, nil)
		names := uniqueColNames(cs.colNames)
		t := &Table{Name: s.Name, Schema: sch, IPK: -1}
		var b strings.Builder
		n := 0
		for _, nm := range names {
			n += len(nm) + strings.Count(nm, "\"") + 2 + 5
		}
		n += len(s.Name) + 2
		sep, sep2, end := "", ",", ")"
		if n >= 50 {
			sep, sep2, end = "\n  ", ",\n  ", "\n)"
		}
		b.WriteString("CREATE TABLE ")
		b.WriteString(quoteIdent(s.Name))
		b.WriteString("(")
		b.WriteString(sep)
		for i, nm := range names {
			if i > 0 {
				b.WriteString(sep2)
			}
			b.WriteString(quoteIdent(nm))
			aff := cs.colAff[i]
			if !cs.colHasAff[i] {
				aff = AffNone
			}
			typ := ""
			switch aff {
			case AffText:
				typ = "TEXT"
			case AffNumeric:
				typ = "NUM"
			case AffInteger:
				typ = "INT"
			case AffReal:
				typ = "REAL"
			}
			if typ != "" {
				b.WriteString(" " + typ)
			}
			t.Cols = append(t.Cols, &Column{Name: nm, Type: typ, Aff: affinityOfType(typ)})
		}
		b.WriteString(end)
		t.SQL = b.String()
		t.rebuildColMap()
		return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
			c.registerTable(sch, t, nil)
			var rows [][]Value
			cs.run(pc, func(r []Value) bool {
				rows = append(rows, append([]Value(nil), r...))
				return true
			})
			for _, r := range rows {
				vals := make([]Value, len(r))
				for i, v := range r {
					vals[i] = applyAffinity(v, t.Cols[i].Aff)
				}
				c.insertRow(t, c.newRowid(t), vals)
			}
		}}
	}
	t := cp.buildTable(s, sch)
	created := cp.addAutoIndexes(t, s, sch)
	// validate CHECK / default / generated expressions compile
	func() {
		sc := &scope{srcs: []*srcInfo{tableSrcInfo(t, t.Name)}, lvl: &level{}}
		for _, ck := range t.Checks {
			cp.compileExpr(ck.E, sc)
		}
		for _, col := range t.Cols {
			if col.Generated != nil {
				cp.compileExpr(col.Generated, sc)
			}
		}
	}()
	return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
		c.registerTable(sch, t, created)
	}}
}

func (cp *compiler) buildIndex(s *CreateIndexStmt, t *Table, sch *Schema) *Index {
	ix := &Index{Name: s.Name, Table: t, Unique: s.Unique, Where: s.Where, Origin: "c", SQL: s.SQL, Schema: sch}
	sc := &scope{srcs: []*srcInfo{tableSrcInfo(t, t.Name)}, lvl: &level{}}
	for _, ic := range s.Cols {
		var col IdxCol
		e := ic.E
		if e.Op == EColumn && e.Table == "" {
			ci := t.colIndex(e.Column)
			if ci < 0 {
				if isRowidName(e.Column) && !t.WithoutRowid {
					col.Col = -2
				} else {
					if e.ColQuot {
						// string literal: expression index on constant? treat as error
					}
					throw("no such column: %s", e.Column)
				}
			} else {
				col.Col = ci
				col.Name = t.Cols[ci].Name
			}
		} else {
			col.Col = -1
			col.E = e
		}
		coll := ic.Collate
		if coll == "" && col.Col >= 0 {
			coll = t.Cols[col.Col].Collate
		}
		if coll != "" && getCollation(coll) == nil {
			throw("no such collation sequence: %s", coll)
		}
		col.CollName = strings.ToUpper(coll)
		if col.CollName == "BINARY" {
			col.CollName = ""
		}
		col.Coll = getCollation(coll)
		col.Desc = ic.Desc
		ix.Cols = append(ix.Cols, col)
		if col.Col == -1 {
			x := cp.compileExpr(e, sc)
			ix.ExprFns = append(ix.ExprFns, x.fn)
		} else {
			ix.ExprFns = append(ix.ExprFns, nil)
		}
	}
	if s.Where != nil {
		x := cp.compileExpr(s.Where, sc)
		ix.WhereFn = x.fn
	}
	return ix
}

func (c *Conn) populateIndex(ix *Index) {
	t := ix.Table
	ix.entries = nil
	for _, r := range t.rows {
		if !c.indexIncludes(ix, t, r.Vals, r.Rowid) {
			continue
		}
		key := c.indexKey(ix, t, r.Vals, r.Rowid)
		if ix.Unique {
			hasNull := false
			for _, k := range key {
				if k.K == KNull {
					hasNull = true
				}
			}
			if !hasNull {
				lo := ix.lowerBound(key)
				hi := ix.upperBound(key)
				if hi > lo {
					ix.entries = nil
					panic(constraintErr(uniqueErrMsg(t, ix)))
				}
			}
		}
		ix.insertEntry(key, r.Rowid)
	}
}

func (cp *compiler) prepCreateIndex(s *CreateIndexStmt) *Prepared {
	c := cp.conn
	var sch *Schema
	var t *Table
	if s.Schema != "" {
		sch = c.schemaByName(s.Schema)
		if sch == nil {
			throw("unknown database %s", s.Schema)
		}
		t = sch.Tables[strings.ToLower(s.Table)]
	} else {
		t = c.findTable("", s.Table)
		if t != nil {
			sch = t.Schema
		}
	}
	if t == nil {
		if c.findView(s.Schema, s.Table) != nil {
			throw("views may not be indexed")
		}
		schName := "main"
		if s.Schema != "" {
			schName = s.Schema
		}
		throw("no such table: %s.%s", schName, s.Table)
	}
	if strings.HasPrefix(strings.ToLower(t.Name), "sqlite_") {
		throw("table %s may not be indexed", t.Name)
	}
	if kind := c.objectExists(sch, s.Name); kind != "" {
		if s.IfNotExists {
			return &Prepared{run: func(*Ctx, func([]Value) bool) {}}
		}
		if kind == "index" {
			throw("index %s already exists", s.Name)
		}
		throw("there is already a %s named %s", kind, s.Name)
	}
	if strings.HasPrefix(strings.ToLower(s.Name), "sqlite_") {
		throw("object name reserved for internal use: %s", s.Name)
	}
	ix := cp.buildIndex(s, t, sch)
	return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
		c.populateIndex(ix)
		c.addSchemaUndo(sch)
		ix.RootPage = sch.allocPage()
		t.Indexes = append(t.Indexes, ix)
		sch.Indexes[strings.ToLower(ix.Name)] = ix
		sch.addEntry("index", ix.Name, t.Name, ix)
		c.addUndo(func() {
			delete(sch.Indexes, strings.ToLower(ix.Name))
			for i, x := range t.Indexes {
				if x == ix {
					t.Indexes = append(t.Indexes[:i:i], t.Indexes[i+1:]...)
					break
				}
			}
		})
	}}
}

func (cp *compiler) prepCreateView(s *CreateViewStmt) *Prepared {
	c := cp.conn
	sch := cp.targetSchema(s.Schema, s.Temp)
	if kind := c.objectExists(sch, s.Name); kind != "" {
		if s.IfNotExists {
			return &Prepared{run: func(*Ctx, func([]Value) bool) {}}
		}
		throw("%s %s already exists", kind, s.Name)
	}
	if strings.HasPrefix(strings.ToLower(s.Name), "sqlite_") {
		throw("object name reserved for internal use: %s", s.Name)
	}
	v := &View{Name: s.Name, Schema: sch, Cols: s.Cols, Sel: s.Sel, SQL: s.SQL}
	// validate
	cs := cp.compileView(v)
	_ = cs
	return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
		c.addSchemaUndo(sch)
		sch.Views[strings.ToLower(v.Name)] = v
		sch.addEntry("view", v.Name, v.Name, v)
		c.addUndo(func() { delete(sch.Views, strings.ToLower(v.Name)) })
	}}
}

func (cp *compiler) prepCreateTrigger(s *CreateTriggerStmt) *Prepared {
	c := cp.conn
	sch := cp.targetSchema(s.Schema, s.Temp)
	if c.findTrigger(s.Schema, s.Name) != nil {
		if s.IfNotExists {
			return &Prepared{run: func(*Ctx, func([]Value) bool) {}}
		}
		throw("trigger %s already exists", s.Name)
	}
	t := c.findTable("", s.Table)
	v := c.findView("", s.Table)
	if t == nil && v == nil {
		throw("no such table: main.%s", s.Table)
	}
	if v != nil && s.Time != "INSTEAD OF" {
		throw("cannot create %s trigger on view: %s", s.Time, v.Name)
	}
	if t != nil && s.Time == "INSTEAD OF" {
		throw("cannot create INSTEAD OF trigger on table: %s", t.Name)
	}
	if t != nil && strings.HasPrefix(strings.ToLower(t.Name), "sqlite_") {
		throw("cannot create trigger on system table")
	}
	tblName := s.Table
	if t != nil {
		tblName = t.Name
	} else {
		tblName = v.Name
	}
	tr := &Trigger{Name: s.Name, Schema: sch, Table: tblName, Time: s.Time, Event: s.Event, UpdateCols: s.UpdateCols, When: s.When, Body: s.Body, SQL: s.SQL}
	return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
		c.addSchemaUndo(sch)
		sch.Triggers[strings.ToLower(tr.Name)] = tr
		sch.addEntry("trigger", tr.Name, tblName, tr)
		c.addUndo(func() { delete(sch.Triggers, strings.ToLower(tr.Name)) })
	}}
}

func (cp *compiler) prepCreateVirtual(s *CreateVirtualStmt) *Prepared {
	throw("no such module: %s", s.Module)
	return nil
}

func (cp *compiler) prepDrop(s *DropStmt) *Prepared {
	c := cp.conn
	switch s.Kind {
	case "TABLE":
		t := c.findTable(s.Schema, s.Name)
		if t == nil {
			if s.IfExists {
				return &Prepared{run: func(*Ctx, func([]Value) bool) {}}
			}
			if c.findView(s.Schema, s.Name) != nil {
				throw("use DROP VIEW to delete view %s", s.Name)
			}
			if s.Schema != "" {
				throw("no such table: %s.%s", s.Schema, s.Name)
			}
			throw("no such table: %s", s.Name)
		}
		if strings.HasPrefix(strings.ToLower(t.Name), "sqlite_") && !strings.EqualFold(t.Name, "sqlite_sequence") && !strings.HasPrefix(strings.ToLower(t.Name), "sqlite_stat") {
			throw("table %s may not be dropped", t.Name)
		}
		return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
			if c.foreignKeys {
				// deleting all rows checks FKs
				for _, ref := range c.fkReferencing(t) {
					if ref.child != t && len(ref.child.rows) > 0 {
						for _, r := range t.rows {
							c.fkParentDelete(t, r.Vals, r.Rowid)
						}
						break
					}
				}
			}
			c.dropTable(t)
		}}
	case "VIEW":
		v := c.findView(s.Schema, s.Name)
		if v == nil {
			if s.IfExists {
				return &Prepared{run: func(*Ctx, func([]Value) bool) {}}
			}
			if c.findTable(s.Schema, s.Name) != nil {
				throw("use DROP TABLE to delete table %s", s.Name)
			}
			throw("no such view: %s", s.Name)
		}
		return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
			sch := v.Schema
			c.addSchemaUndo(sch)
			delete(sch.Views, strings.ToLower(v.Name))
			sch.removeEntry("view", v.Name)
			// drop triggers on view
			for name, tr := range sch.Triggers {
				if strings.EqualFold(tr.Table, v.Name) {
					delete(sch.Triggers, name)
					sch.removeEntry("trigger", tr.Name)
					tr2 := tr
					n2 := name
					c.addUndo(func() { sch.Triggers[n2] = tr2 })
				}
			}
			c.addUndo(func() { sch.Views[strings.ToLower(v.Name)] = v })
		}}
	case "INDEX":
		ix := c.findIndex(s.Schema, s.Name)
		if ix == nil {
			if s.IfExists {
				return &Prepared{run: func(*Ctx, func([]Value) bool) {}}
			}
			throw("no such index: %s", s.Name)
		}
		if ix.Origin != "c" {
			throw("index associated with UNIQUE or PRIMARY KEY constraint cannot be dropped")
		}
		return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
			sch := ix.Schema
			t := ix.Table
			c.addSchemaUndo(sch)
			delete(sch.Indexes, strings.ToLower(ix.Name))
			sch.removeEntry("index", ix.Name)
			saved := append([]*Index(nil), t.Indexes...)
			for i, x := range t.Indexes {
				if x == ix {
					t.Indexes = append(t.Indexes[:i:i], t.Indexes[i+1:]...)
					break
				}
			}
			c.addUndo(func() {
				sch.Indexes[strings.ToLower(ix.Name)] = ix
				t.Indexes = saved
			})
		}}
	case "TRIGGER":
		tr := c.findTrigger(s.Schema, s.Name)
		if tr == nil {
			if s.IfExists {
				return &Prepared{run: func(*Ctx, func([]Value) bool) {}}
			}
			throw("no such trigger: %s", s.Name)
		}
		return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
			sch := tr.Schema
			c.addSchemaUndo(sch)
			delete(sch.Triggers, strings.ToLower(tr.Name))
			sch.removeEntry("trigger", tr.Name)
			c.addUndo(func() { sch.Triggers[strings.ToLower(tr.Name)] = tr })
		}}
	}
	return nil
}

func (c *Conn) dropTable(t *Table) {
	sch := t.Schema
	c.addSchemaUndo(sch)
	name := strings.ToLower(t.Name)
	delete(sch.Tables, name)
	sch.removeEntry("table", t.Name)
	for _, ix := range t.Indexes {
		delete(sch.Indexes, strings.ToLower(ix.Name))
		sch.removeEntry("index", ix.Name)
	}
	var droppedTrigs []*Trigger
	for _, s := range c.allSchemas() {
		for tn, tr := range s.Triggers {
			if strings.EqualFold(tr.Table, t.Name) {
				delete(s.Triggers, tn)
				s.removeEntry("trigger", tr.Name)
				droppedTrigs = append(droppedTrigs, tr)
			}
		}
	}
	// remove from sqlite_sequence
	if t.AutoInc {
		if sq := sch.Tables["sqlite_sequence"]; sq != nil {
			for _, r := range append([]*Row(nil), sq.rows...) {
				if strings.EqualFold(r.Vals[0].Text(), t.Name) {
					c.deleteRow(sq, r.Rowid)
				}
			}
		}
	}
	c.addUndo(func() {
		sch.Tables[name] = t
		for _, ix := range t.Indexes {
			sch.Indexes[strings.ToLower(ix.Name)] = ix
		}
		for _, tr := range droppedTrigs {
			tr.Schema.Triggers[strings.ToLower(tr.Name)] = tr
		}
	})
}
