cd /workspace/src && cat > alter.go <<'EOF'
package main

import (
	"strings"
)

// rewriteIdents replaces identifier tokens equal to old (case-insensitive) with repl.
// filter decides per token index whether to replace.
func rewriteIdents(sql, old, repl string, filter func(toks []Token, i int) bool) string {
	toks, _ := tokenize(sql)
	var b strings.Builder
	last := 0
	for i, t := range toks {
		if t.T == TEOF {
			break
		}
		if (t.T == TIdent || (t.T == TKeyword && !reservedWords[t.V]) || t.T == TString) && strings.EqualFold(nameOf(t), old) {
			if t.T == TString {
				// only replace string tokens used as names (rare): skip
				continue
			}
			if filter != nil && !filter(toks, i) {
				continue
			}
			b.WriteString(sql[last:t.Pos])
			b.WriteString(repl)
			last = t.Pos + len(t.S)
		}
	}
	b.WriteString(sql[last:])
	return b.String()
}

func notFuncCall(toks []Token, i int) bool {
	if i+1 < len(toks) && toks[i+1].T == TOp && toks[i+1].S == "(" {
		// could be table name in CREATE TABLE t(...) or index ON t(...)
		if i > 0 {
			p := toks[i-1]
			if p.T == TKeyword && (p.V == "TABLE" || p.V == "ON" || p.V == "INTO" || p.V == "EXISTS") {
				return true
			}
			if p.T == TOp && p.S == "." {
				return true
			}
		}
		return false
	}
	return true
}

func (cp *compiler) prepAlter(s *AlterStmt) *Prepared {
	c := cp.conn
	t := c.findTable(s.Schema, s.Table)
	if t == nil {
		if s.Schema != "" {
			throw("no such table: %s.%s", s.Schema, s.Table)
		}
		throw("no such table: %s", s.Table)
	}
	if strings.HasPrefix(strings.ToLower(t.Name), "sqlite_") {
		throw("table %s may not be altered", t.Name)
	}
	sch := t.Schema
	switch s.Kind {
	case "RENAME":
		if k := c.objectExists(sch, s.NewName); k != "" {
			throw("there is already another table or index with this name: %s", s.NewName)
		}
		if strings.HasPrefix(strings.ToLower(s.NewName), "sqlite_") {
			throw("object name reserved for internal use: %s", s.NewName)
		}
		return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
			c.snapshotSchema(sch)
			oldName := t.Name
			newQ := "\"" + strings.ReplaceAll(s.NewName, "\"", "\"\"") + "\""
			t.SQL = rewriteIdents(t.SQL, oldName, newQ, notFuncCall)
			delete(sch.Tables, strings.ToLower(oldName))
			t.Name = s.NewName
			sch.Tables[strings.ToLower(t.Name)] = t
			for _, e := range sch.entries {
				if e.Type == "table" && e.obj == t {
					e.Name = t.Name
					e.TblName = t.Name
				}
			}
			for _, ix := range t.Indexes {
				if ix.SQL != "" {
					ix.SQL = rewriteIdents(ix.SQL, oldName, newQ, notFuncCall)
				}
				if strings.HasPrefix(ix.Name, "sqlite_autoindex_"+oldName+"_") {
					old := ix.Name
					ix.Name = "sqlite_autoindex_" + t.Name + ix.Name[len("sqlite_autoindex_"+oldName):]
					delete(sch.Indexes, strings.ToLower(old))
					sch.Indexes[strings.ToLower(ix.Name)] = ix
					for _, e := range sch.entries {
						if e.obj == ix {
							e.Name = ix.Name
						}
					}
				}
				for _, e := range sch.entries {
					if e.obj == ix {
						e.TblName = t.Name
					}
				}
			}
			for _, s2 := range c.allSchemas() {
				for _, e := range s2.entries {
					switch o := e.obj.(type) {
					case *Trigger:
						if strings.EqualFold(o.Table, oldName) {
							o.Table = t.Name
							e.TblName = t.Name
						}
						if sqlMentions(o.SQL, oldName) {
							o.SQL = rewriteIdents(o.SQL, oldName, newQ, notFuncCall)
							reparseTrigger(o)
						}
					case *View:
						if sqlMentions(o.SQL, oldName) {
							o.SQL = rewriteIdents(o.SQL, oldName, newQ, notFuncCall)
							reparseView(o)
						}
					case *Table:
						for _, fk := range o.FKs {
							if strings.EqualFold(fk.Table, oldName) {
								fk.Table = t.Name
								o.SQL = rewriteIdents(o.SQL, oldName, newQ, func(toks []Token, i int) bool {
									return i > 0 && toks[i-1].T == TKeyword && toks[i-1].V == "REFERENCES"
								})
							}
						}
					}
				}
			}
			c.schemaGen++
		}}
	case "RENAMECOL":
		ci := t.colIndex(s.OldCol)
		if ci < 0 {
			throw("no such column: \"%s\"", s.OldCol)
		}
		if t.colIndex(s.NewName) >= 0 && !strings.EqualFold(s.OldCol, s.NewName) {
			throw("duplicate column name: %s", s.NewName)
		}
		return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
			c.snapshotSchema(sch)
			oldCol := t.Cols[ci].Name
			repl := quoteIdent(s.NewName)
			t.SQL = rewriteIdents(t.SQL, oldCol, repl, notFuncCall)
			t.Cols[ci].Name = s.NewName
			t.rebuildColMap()
			for _, ix := range t.Indexes {
				if ix.SQL != "" {
					ix.SQL = rewriteIdents(ix.SQL, oldCol, repl, func(toks []Token, i int) bool {
						// skip the index name and table name tokens
						return i > 0 && notFuncCall(toks, i) && !(toks[i-1].T == TKeyword && (toks[i-1].V == "INDEX" || toks[i-1].V == "ON" || toks[i-1].V == "EXISTS"))
					})
				}
				for k := range ix.Cols {
					if ix.Cols[k].Col == ci {
						ix.Cols[k].Name = s.NewName
					}
				}
			}
			for _, s2 := range c.allSchemas() {
				for _, e := range s2.entries {
					switch o := e.obj.(type) {
					case *Trigger:
						if strings.EqualFold(o.Table, t.Name) || sqlMentions(o.SQL, t.Name) {
							o.SQL = rewriteIdents(o.SQL, oldCol, repl, func(toks []Token, i int) bool {
								return i > 0 && notFuncCall(toks, i) && !(toks[i-1].T == TKeyword && (toks[i-1].V == "TRIGGER" || toks[i-1].V == "EXISTS"))
							})
							reparseTrigger(o)
						}
					case *View:
						if sqlMentions(o.SQL, t.Name) {
							o.SQL = rewriteIdents(o.SQL, oldCol, repl, func(toks []Token, i int) bool {
								return i > 0 && notFuncCall(toks, i) && !(toks[i-1].T == TKeyword && (toks[i-1].V == "VIEW" || toks[i-1].V == "AS" && i == 3))
							})
							reparseView(o)
						}
					case *Table:
						if o != t {
							for _, fk := range o.FKs {
								if strings.EqualFold(fk.Table, t.Name) {
									for k, rc := range fk.RefCols {
										if strings.EqualFold(rc, oldCol) {
											fk.RefCols[k] = s.NewName
										}
									}
								}
							}
						} else {
							for _, fk := range o.FKs {
								for k, cc := range fk.Cols {
									if strings.EqualFold(cc, oldCol) {
										fk.Cols[k] = s.NewName
									}
								}
							}
						}
					}
				}
			}
			// re-parse table to refresh check expressions
			reparseTableChecks(t)
			c.schemaGen++
		}}
	case "ADD":
		cd := s.Col
		if cd.PrimaryKey {
			throw("Cannot add a PRIMARY KEY column")
		}
		if cd.Unique {
			throw("Cannot add a UNIQUE column")
		}
		if t.colIndex(cd.Name) >= 0 {
			throw("duplicate column name: %s", cd.Name)
		}
		if cd.Default != nil && cd.Default.Op != ELit && !(cd.Default.Op == EUnary) {
			if cd.Default.Op == EFunc {
				throw("Cannot add a column with non-constant default")
			}
		}
		if cd.Generated != nil && cd.GenStored {
			throw("cannot add a STORED column")
		}
		return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
			if cd.NotNull && (cd.Default == nil || (cd.Default.Op == ELit && cd.Default.Val.K == KNull)) && len(t.rows) > 0 && cd.Generated == nil {
				throw("Cannot add a NOT NULL column with default value NULL")
			}
			c.snapshotSchema(sch)
			c.snapshotRows(t)
			col := &Column{Name: cd.Name, Type: cd.Type, Aff: affinityOfType(cd.Type), NotNull: cd.NotNull, NNConflict: cd.NNConflict, Default: cd.Default, DefaultText: cd.DefaultText, Collate: cd.Collate, Generated: cd.Generated}
			t.Cols = append(t.Cols, col)
			t.rebuildColMap()
			for i, ck := range cd.Check {
				t.Checks = append(t.Checks, CheckDef{E: ck, Text: cd.CheckText[i]})
			}
			if cd.FK != nil {
				t.FKs = append(t.FKs, cd.FK)
			}
			// default value for existing rows
			dv := NullValue
			if cd.Default != nil {
				cp2 := &compiler{conn: c}
				x := cp2.compileExpr(cd.Default, &scope{lvl: &level{}})
				dv = applyAffinity(x.fn(&Ctx{conn: c}), col.Aff)
			}
			for _, r := range t.rows {
				r.Vals = append(append([]Value(nil), r.Vals...), dv)
			}
			if cd.Generated != nil {
				cp2 := &compiler{conn: c}
				w := cp2.newRowWriter(t, "")
				for _, r := range t.rows {
					w.computeGenerated(&Ctx{conn: c}, r.Vals, r.Rowid)
				}
			}
			// update SQL text
			sql := t.SQL
			i := strings.LastIndexByte(sql, ')')
			if i > 0 {
				t.SQL = sql[:i] + ", " + s.ColSQL + sql[i:]
			}
			c.schemaGen++
		}}
	case "DROP":
		ci := t.colIndex(s.OldCol)
		if ci < 0 {
			throw("no such column: \"%s\"", s.OldCol)
		}
		col := t.Cols[ci]
		if col.PK > 0 {
			throw("cannot drop PRIMARY KEY column: \"%s\"", col.Name)
		}
		for _, ix := range t.Indexes {
			if ix.Origin == "u" {
				for _, ic := range ix.Cols {
					if ic.Col == ci {
						throw("cannot drop UNIQUE column: \"%s\"", col.Name)
					}
				}
			}
		}
		if len(t.Cols) == 1 {
			throw("cannot drop column \"%s\": no other columns exist", col.Name)
		}
		for _, ix := range t.Indexes {
			if ix.Origin == "c" {
				for _, ic := range ix.Cols {
					if ic.Col == ci || (ic.E != nil && exprMentions(ic.E, col.Name)) {
						throw("error in index %s after drop column: no such column: %s", ix.Name, col.Name)
					}
				}
				if ix.Where != nil && exprMentions(ix.Where, col.Name) {
					throw("error in index %s after drop column: no such column: %s", ix.Name, col.Name)
				}
			}
		}
		for _, ck := range t.Checks {
			if exprMentions(ck.E, col.Name) {
				throw("error in table %s after drop column: no such column: %s", t.Name, col.Name)
			}
		}
		for _, fk := range t.FKs {
			for _, fc := range fk.Cols {
				if strings.EqualFold(fc, col.Name) {
					throw("error in table %s after drop column: unknown column \"%s\" in foreign key definition", t.Name, col.Name)
				}
			}
		}
		for _, s2 := range c.allSchemas() {
			for _, e := range s2.entries {
				if v, ok := e.obj.(*View); ok && sqlMentions(v.SQL, t.Name) && sqlMentions(v.SQL, col.Name) {
					throw("error in view %s after drop column: no such column: %s", v.Name, col.Name)
				}
				if tr, ok := e.obj.(*Trigger); ok && (strings.EqualFold(tr.Table, t.Name) || sqlMentions(tr.SQL, t.Name)) && sqlMentions(tr.SQL, col.Name) {
					throw("error in trigger %s after drop column: no such column: %s", tr.Name, col.Name)
				}
			}
		}
		return &Prepared{run: func(pc *Ctx, emit func([]Value) bool) {
			c.snapshotSchema(sch)
			c.snapshotRows(t)
			t.SQL = removeColumnDef(t.SQL, col.Name)
			t.Cols = append(t.Cols[:ci:ci], t.Cols[ci+1:]...)
			if t.IPK > ci {
				t.IPK--
			}
			for k, pc := range t.PKCols {
				if pc > ci {
					t.PKCols[k]--
				}
			}
			t.rebuildColMap()
			for _, r := range t.rows {
				nv := make([]Value, 0, len(r.Vals)-1)
				nv = append(nv, r.Vals[:ci]...)
				nv = append(nv, r.Vals[ci+1:]...)
				r.Vals = nv
			}
			for _, ix := range t.Indexes {
				for k := range ix.Cols {
					if ix.Cols[k].Col > ci {
						ix.Cols[k].Col--
					}
				}
				c.populateIndex(ix)
			}
			reparseTableChecks(t)
			c.schemaGen++
		}}
	}
	return nil
}

func exprMentions(e *Expr, name string) bool {
	found := false
	var walk func(e *Expr)
	walk = func(e *Expr) {
		if e == nil || found {
			return
		}
		if e.Op == EColumn && strings.EqualFold(e.Column, name) {
			found = true
			return
		}
		walk(e.L)
		walk(e.R)
		for _, x := range e.List {
			walk(x)
		}
	}
	walk(e)
	return found
}

func sqlMentions(sql, name string) bool {
	toks, _ := tokenize(sql)
	for _, t := range toks {
		if (t.T == TIdent || t.T == TKeyword) && strings.EqualFold(nameOf(t), name) {
			return true
		}
	}
	return false
}

func removeColumnDef(sql, col string) string {
	toks, _ := tokenize(sql)
	// find opening paren
	depth := 0
	start := -1
	var defStarts []int // token index of each column def start at depth 1
	var defEnds []int
	for i, t := range toks {
		if t.T == TOp && t.S == "(" {
			depth++
			if depth == 1 {
				start = i
				defStarts = append(defStarts, i+1)
			}
			continue
		}
		if t.T == TOp && t.S == ")" {
			if depth == 1 {
				defEnds = append(defEnds, i)
			}
			depth--
			continue
		}
		if depth == 1 && t.T == TOp && t.S == "," {
			defEnds = append(defEnds, i)
			defStarts = append(defStarts, i+1)
		}
	}
	_ = start
	for k, ds := range defStarts {
		if ds >= len(toks) {
			break
		}
		t := toks[ds]
		if strings.EqualFold(nameOf(t), col) && (t.T == TIdent || t.T == TKeyword || t.T == TString) {
			end := defEnds[k]
			// remove from previous comma to end (exclusive)
			if k > 0 {
				prevComma := toks[defEnds[k-1]]
				return sql[:prevComma.Pos] + sql[toks[end].Pos:]
			}
			// first column: remove through following comma and spaces
			if end < len(toks) && toks[end].S == "," {
				nxt := toks[end+1]
				return sql[:t.Pos] + sql[nxt.Pos:]
			}
			return sql[:t.Pos] + sql[toks[end].Pos:]
		}
	}
	return sql
}

func reparseView(v *View) {
	st, _, err := ParseStatement(v.SQL, 0)
	if err != nil {
		return
	}
	if cv, ok := st.(*CreateViewStmt); ok {
		v.Sel = cv.Sel
		v.Cols = cv.Cols
	}
}

func reparseTrigger(tr *Trigger) {
	st, _, err := ParseStatement(tr.SQL, 0)
	if err != nil {
		return
	}
	if ct, ok := st.(*CreateTriggerStmt); ok {
		tr.Body = ct.Body
		tr.When = ct.When
		tr.UpdateCols = ct.UpdateCols
	}
}

func reparseTableChecks(t *Table) {
	st, _, err := ParseStatement(t.SQL, 0)
	if err != nil {
		return
	}
	ct, ok := st.(*CreateTableStmt)
	if !ok {
		return
	}
	var checks []CheckDef
	for _, cd := range ct.Cols {
		for i, ck := range cd.Check {
			checks = append(checks, CheckDef{E: ck, Text: cd.CheckText[i]})
		}
		ci := t.colIndex(cd.Name)
		if ci >= 0 {
			t.Cols[ci].Default = cd.Default
			t.Cols[ci].Generated = cd.Generated
		}
	}
	for _, tc := range ct.Constraints {
		if tc.Kind == "CHECK" {
			checks = append(checks, CheckDef{E: tc.Check, Text: tc.CheckText, Name: tc.Name})
		}
	}
	t.Checks = checks
}

// snapshotSchema saves enough state to undo DDL that mutates objects in place
func (c *Conn) snapshotSchema(sch *Schema) {
	type tblSnap struct {
		t     *Table
		name  string
		sql   string
		cols  []*Column
		colCopies []Column
		ipk   int
		pk    []int
		checks []CheckDef
		fks   []*ForeignKey
		idx   []*Index
	}
	var snaps []tblSnap
	for _, s := range c.allSchemas() {
		for _, t := range s.Tables {
			sn := tblSnap{t: t, name: t.Name, sql: t.SQL, cols: append([]*Column(nil), t.Cols...), ipk: t.IPK, pk: append([]int(nil), t.PKCols...), checks: append([]CheckDef(nil), t.Checks...), fks: append([]*ForeignKey(nil), t.FKs...), idx: append([]*Index(nil), t.Indexes...)}
			for _, col := range t.Cols {
				sn.colCopies = append(sn.colCopies, *col)
			}
			snaps = append(snaps, sn)
		}
	}
	type objSnap struct {
		e       *schemaEntry
		name    string
		tbl     string
		sql     string
		v       *View
		vsel    *Select
		tr      *Trigger
		trBody  []Stmt
		trTable string
		ix      *Index
		ixCols  []IdxCol
		ixName  string
	}
	var objs []objSnap
	maps := map[*Schema][4]map[string]interface{}{}
	for _, s := range c.allSchemas() {
		for _, e := range s.entries {
			o := objSnap{e: e, name: e.Name, tbl: e.TblName}
			switch x := e.obj.(type) {
			case *View:
				o.v = x
				o.sql = x.SQL
				o.vsel = x.Sel
			case *Trigger:
				o.tr = x
				o.sql = x.SQL
				o.trBody = x.Body
				o.trTable = x.Table
			case *Index:
				o.ix = x
				o.sql = x.SQL
				o.ixCols = append([]IdxCol(nil), x.Cols...)
				o.ixName = x.Name
			}
			objs = append(objs, o)
		}
		var m [4]map[string]interface{}
		for i := range m {
			m[i] = map[string]interface{}{}
		}
		for k, v := range s.Tables {
			m[0][k] = v
		}
		for k, v := range s.Indexes {
			m[1][k] = v
		}
		for k, v := range s.Views {
			m[2][k] = v
		}
		for k, v := range s.Triggers {
			m[3][k] = v
		}
		maps[s] = m
	}
	c.addUndo(func() {
		for _, sn := range snaps {
			t := sn.t
			t.Name = sn.name
			t.SQL = sn.sql
			t.Cols = sn.cols
			for i, col := range t.Cols {
				*col = sn.colCopies[i]
			}
			t.IPK = sn.ipk
			t.PKCols = sn.pk
			t.Checks = sn.checks
			t.FKs = sn.fks
			t.Indexes = sn.idx
			t.rebuildColMap()
		}
		for _, o := range objs {
			o.e.Name = o.name
			o.e.TblName = o.tbl
			if o.v != nil {
				o.v.SQL = o.sql
				o.v.Sel = o.vsel
			}
			if o.tr != nil {
				o.tr.SQL = o.sql
				o.tr.Body = o.trBody
				o.tr.Table = o.trTable
			}
			if o.ix != nil {
				o.ix.SQL = o.sql
				o.ix.Cols = o.ixCols
				o.ix.Name = o.ixName
			}
		}
		for s, m := range maps {
			s.Tables = map[string]*Table{}
			for k, v := range m[0] {
				s.Tables[k] = v.(*Table)
			}
			s.Indexes = map[string]*Index{}
			for k, v := range m[1] {
				s.Indexes[k] = v.(*Index)
			}
			s.Views = map[string]*View{}
			for k, v := range m[2] {
				s.Views[k] = v.(*View)
			}
			s.Triggers = map[string]*Trigger{}
			for k, v := range m[3] {
				s.Triggers[k] = v.(*Trigger)
			}
		}
		c.schemaGen++
	})
}

func (c *Conn) snapshotRows(t *Table) {
	saved := make([]*Row, len(t.rows))
	for i, r := range t.rows {
		saved[i] = &Row{Rowid: r.Rowid, Vals: append([]Value(nil), r.Vals...)}
	}
	savedIdx := make([][]idxEntry, len(t.Indexes))
	idxs := append([]*Index(nil), t.Indexes...)
	for i, ix := range idxs {
		savedIdx[i] = append([]idxEntry(nil), ix.entries...)
	}
	c.addUndo(func() {
		t.rows = saved
		for i, ix := range idxs {
			ix.entries = savedIdx[i]
		}
	})
}
