func collDisplayName(ix *Index, i int, t *Table) string {
	// show collation as written in index definition
	if ix.SQL != "" {
		st, _, err := ParseStatement(ix.SQL, 0)
		if err == nil {
			if ci, ok := st.(*CreateIndexStmt); ok && i < len(ci.Cols) && ci.Cols[i].Collate != "" {
				return ci.Cols[i].Collate
			}
		}
	}
	col := ix.Cols[i]
	if col.Col >= 0 && t.Cols[col.Col].Collate != "" {
		return t.Cols[col.Col].Collate
	}
	return col.CollName
}

func (c *Conn) schemaVersion() int {
	return c.schemaVer
}

func (c *Conn) fkCheckAll() [][]Value {
	var rows [][]Value
	for _, s := range c.allSchemas() {
		for _, e := range s.entries {
			t, ok := e.obj.(*Table)
			if !ok {
				continue
			}
			for k, fk := range t.FKs {
				parent := c.findTable("", fk.Table)
				for _, r := range t.rows {
					vals := make([]Value, len(fk.Cols))
					hasNull := false
					for i, cn := range fk.Cols {
						ci := t.colIndex(cn)
						if ci < 0 {
							continue
						}
						v := r.Vals[ci]
						if ci == t.IPK {
							v = IntValue(r.Rowid)
						}
						if v.K == KNull {
							hasNull = true
						}
						vals[i] = v
					}
					if hasNull {
						continue
					}
					ok := parent != nil && c.parentHasRow(parent, c.fkParentCols(fk, parent), vals)
					if !ok {
						rows = append(rows, []Value{TextValue(t.Name), IntValue(r.Rowid), TextValue(fk.Table), IntValue(int64(len(t.FKs) - 1 - k))})
					}
				}
			}
		}
	}
	return rows
}

func (cp *compiler) prepPragma(s *PragmaStmt) *Prepared {
	c := cp.conn
	var arg *Value
	if s.HasVal && s.Value != nil {
		x := cp.compileExpr(s.Value, &scope{lvl: &level{}})
		v := x.fn(&Ctx{conn: c})
		arg = &v
	}
	name := strings.ToLower(s.Name)
	// determine column names at prepare time
	var cols []string
	if res := c.peekPragmaCols(name, arg); res != nil {
		cols = res
	}
	p := &Prepared{isQuery: true, colNames: cols}
	p.run = func(pc *Ctx, emit func([]Value) bool) {
		res := c.runPragma(name, arg, s.Schema)
		if res == nil {
			return
		}
		for _, r := range res.rows {
			if !emit(r) {
				return
			}
		}
	}
	return p
}

func (c *Conn) peekPragmaCols(name string, arg *Value) []string {
	switch name {
	case "foreign_keys", "user_version", "recursive_triggers", "application_id", "page_size", "cache_size", "journal_mode", "query_only":
		if arg != nil && name != "journal_mode" {
			return nil
		}
	}
	// evaluate on a dry basis to get columns (pragmas without side effects for column discovery)
	switch name {
	case "table_info":
		return []string{"cid", "name", "type", "notnull", "dflt_value", "pk"}
	case "table_xinfo":
		return []string{"cid", "name", "type", "notnull", "dflt_value", "pk", "hidden"}
	case "index_list":
		return []string{"seq", "name", "unique", "origin", "partial"}
	case "index_info":
		return []string{"seqno", "cid", "name"}
	case "index_xinfo":
		return []string{"seqno", "cid", "name", "desc", "coll", "key"}
	case "foreign_key_list":
		return []string{"id", "seq", "table", "from", "to", "on_update", "on_delete", "match"}
	case "database_list":
		return []string{"seq", "name", "file"}
	case "table_list":
		return []string{"schema", "name", "type", "ncol", "wr", "strict"}
	case "collation_list":
		return []string{"seq", "name"}
	case "foreign_key_check":
		return []string{"table", "rowid", "parent", "fkid"}
	case "busy_timeout":
		return []string{"timeout"}
	case "wal_checkpoint":
		return []string{"busy", "log", "checkpointed"}
	case "function_list":
		return []string{"name", "builtin", "type", "enc", "narg", "flags"}
	}
	return []string{name}
}

func (cp *compiler) pragmaTVF(name string, it *FromItem) *tvfDef {
	c := cp.conn
	cols := c.peekPragmaCols(name, nil)
	switch name {
	case "table_info", "table_xinfo", "index_list", "index_info", "index_xinfo", "foreign_key_list", "database_list", "table_list", "collation_list", "compile_options", "function_list", "foreign_key_check":
	default:
		return nil
	}
	allCols := append(append([]string(nil), cols...), "arg", "schema")
	hidden := make([]bool, len(allCols))
	hidden[len(cols)] = true
	hidden[len(cols)+1] = true
	return &tvfDef{name: "pragma_" + name, cols: allCols, hidden: hidden, nArgs: 2, rows: func(ctx *Ctx, args []Value, nargs int) [][]Value {
		var arg *Value
		if nargs > 0 {
			arg = &args[0]
		}
		schema := ""
		if nargs > 1 {
			schema = args[1].Text()
		}
		res := c.runPragma(name, arg, schema)
		if res == nil {
			return nil
		}
		var out [][]Value
		for _, r := range res.rows {
			row := append(append([]Value(nil), r...), NullValue, NullValue)
			if arg != nil {
				row[len(cols)] = *arg
			}
			out = append(out, row)
		}
		return out
	}}
}
