// runArg executes a command-line argument (SQL or dot command). returns false on error.
func (sh *Shell) runArg(a string, idx int, isCmd bool) bool {
	t := strings.TrimLeft(a, " \t")
	if strings.HasPrefix(t, ".") {
		rc := sh.doMetaCommand(t)
		if rc != 0 {
			return false
		}
		return true
	}
	ok := sh.runSQL(a, 0, fmt.Sprintf("in %s command line argument", ordinal(idx)))
	sh.out.Flush()
	return ok
}

func (sh *Shell) processFile(name string) bool {
	f, err := os.Open(name)
	if err != nil {
		sh.errf("Error: cannot open \"%s\"\n", name)
		return false
	}
	defer f.Close()
	sh.nesting++
	saved := sh.inFile
	sh.inFile = name
	sh.processInput(bufio.NewReader(f), name)
	sh.inFile = saved
	sh.nesting--
	return true
}

func isAllWhitespace(s string) bool {
	i := 0
	for i < len(s) {
		c := s[i]
		if isSpaceByte(c) {
			i++
			continue
		}
		if c == '/' && i+1 < len(s) && s[i+1] == '*' {
			j := strings.Index(s[i+2:], "*/")
			if j < 0 {
				return false
			}
			i += j + 4
			continue
		}
		if c == '-' && i+1 < len(s) && s[i+1] == '-' {
			j := strings.IndexByte(s[i:], '\n')
			if j < 0 {
				return true
			}
			i += j + 1
			continue
		}
		return false
	}
	return true
}

func (sh *Shell) processInput(rd *bufio.Reader, fname string) {
	var buf strings.Builder
	inSQL := false
	startLine := 0
	lineno := 0
	for {
		line, err := rd.ReadString('\n')
		if err != nil && line == "" {
			break
		}
		lineno++
		line = strings.TrimSuffix(line, "\n")
		line = strings.TrimSuffix(line, "\r")
		if !inSQL {
			tl := strings.TrimLeft(line, " \t")
			if strings.HasPrefix(tl, ".") {
				sh.out.Flush()
				rc := sh.doMetaCommandLine(tl, lineno)
				sh.out.Flush()
				if rc == 2 || sh.quitFlag {
					return
				}
				if rc != 0 {
					sh.errOccurred = true
					if sh.bail {
						sh.quitFlag = true
						sh.exitCode = 1
						return
					}
				}
				continue
			}
			if strings.HasPrefix(tl, "#") {
				continue
			}
			if isAllWhitespace(line) {
				continue
			}
			buf.Reset()
			buf.WriteString(line)
			inSQL = true
			startLine = lineno
		} else {
			buf.WriteByte('\n')
			buf.WriteString(line)
		}
		s := buf.String()
		if sqliteComplete(s) {
			ok := sh.runSQL(s, startLine, "")
			sh.out.Flush()
			inSQL = false
			buf.Reset()
			if !ok {
				sh.errOccurred = true
				if sh.bail {
					sh.quitFlag = true
					sh.exitCode = 1
					return
				}
			}
			if sh.quitFlag {
				return
			}
		}
		if err != nil {
			break
		}
	}
	if inSQL {
		s := buf.String()
		if !isAllWhitespace(s) {
			ok := sh.runSQL(s, startLine, "")
			if !ok {
				sh.errOccurred = true
				if sh.bail {
					sh.quitFlag = true
					sh.exitCode = 1
				}
			}
		}
	}
}

func errorContext(sql string, pos int) string {
	if pos < 0 || pos >= len(sql) {
		return ""
	}
	iOffset := pos
	z := sql
	for iOffset > 50 {
		iOffset--
		z = z[1:]
		for len(z) > 0 && (z[0]&0xc0) == 0x80 {
			z = z[1:]
			iOffset--
		}
	}
	n := len(z)
	if n > 78 {
		n = 78
		for n > 0 && (z[n]&0xc0) == 0x80 {
			n--
		}
	}
	code := []byte(z[:n])
	for i := range code {
		if isSpaceByte(code[i]) {
			code[i] = ' '
		}
	}
	if iOffset < 25 {
		return fmt.Sprintf("\n  %s\n  %s^--- error here", string(code), strings.Repeat(" ", iOffset))
	}
	return fmt.Sprintf("\n  %s\n  %serror here ---^", string(code), strings.Repeat(" ", iOffset-14))
}

// runSQL executes all statements in sql. lineNo is the starting line (0 for args).
func (sh *Shell) runSQL(sql string, lineNo int, where string) bool {
	pos := 0
	for {
		// skip leading whitespace
		for pos < len(sql) && isSpaceByte(sql[pos]) {
			pos++
		}
		if pos >= len(sql) {
			return true
		}
		stmt, end, perr := ParseStatement(sql, pos)
		loc := where
		if loc == "" {
			loc = fmt.Sprintf("near line %d", lineNo)
		}
		if perr != nil {
			ctx := ""
			if perr.Pos >= 0 {
				ctx = errorContext(sql[pos:], perr.Pos-pos)
			}
			sh.errf("Parse error %s: %s%s\n", loc, perr.Msg, ctx)
			return false
		}
		if stmt == nil {
			return true
		}
		stmtText := strings.TrimRight(sql[pos:end], " \t\n\r;")
		if sh.echo {
			fmt.Fprintf(sh.out, "%s\n", strings.TrimSpace(sql[pos:end]))
		}
		ok := sh.execStmt(stmt, sql[pos:], stmtText, loc)
		if !ok {
			return false
		}
		pos = end
		if sh.quitFlag {
			return true
		}
	}
}

func (sh *Shell) execStmt(stmt Stmt, rest string, text string, loc string) bool {
	c := sh.conn
	if c.openErr != "" {
		sh.errf("Error %s: %s\n", loc, c.openErr)
		return false
	}
	p, err := c.Prepare(stmt)
	if err != nil {
		e := err.(*SQLError)
		ctx := ""
		if e.Pos >= 0 {
			ctx = errorContext(rest, e.Pos-(len(rest)-len(rest)))
		}
		_ = ctx
		ctxs := ""
		if e.Pos >= 0 {
			base := sh.stmtBase(rest)
			ctxs = errorContext(rest, e.Pos-base)
		}
		sh.errf("Parse error %s: %s%s\n", loc, e.Msg, ctxs)
		return false
	}
	if ex, ok := stmt.(*ExplainStmt); ok && ex.QueryPlan {
		return sh.runEQP(p, loc)
	}
	if sh.eqp > 0 {
		if _, ok := stmt.(*SelectStmt); ok {
			sh.showEQP(stmt)
		}
	}
	r := sh.newRenderer(p.colNames, p.declTypes)
	err = c.Execute(p, func(row []Value) bool {
		r.row(row)
		return true
	})
	r.finish()
	if err != nil {
		e := err.(*SQLError)
		sh.errf("Error %s: %s\n", loc, e.Msg)
		return false
	}
	if sh.changesOn && p.isDML {
		fmt.Fprintf(sh.out, "changes: %d   total_changes: %d\n", c.changes, c.totalChanges)
	}
	return true
}

// stmtBase returns the absolute offset base for error positions within rest.
func (sh *Shell) stmtBase(rest string) int {
	return sh.curBase
}

func (sh *Shell) printUsage(argv0 string, w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [OPTIONS] [FILENAME [SQL...]]\n", argv0)
	fmt.Fprint(w, usageText)
}

const usageText = `FILENAME is the name of an SQLite database. A new database is created
if the file does not previously exist. Defaults to :memory:.
OPTIONS include:
   --                   treat no subsequent arguments as options
   -A ARGS...           run ".archive ARGS" and exit
   -append              append the database to the end of the file
   -ascii               set output mode to 'ascii'
   -bail                stop after hitting an error
   -batch               force batch I/O
   -box                 set output mode to 'box'
   -cmd COMMAND         run "COMMAND" before reading stdin
   -column              set output mode to 'column'
   -csv                 set output mode to 'csv'
   -deserialize         open the database using sqlite3_deserialize()
   -echo                print inputs before execution
   -escape T            ctrl-char escape; T is one of: symbol, ascii, off
   -init FILENAME       read/process named file
   -[no]header          turn headers on or off
   -help                show this message
   -html                set output mode to HTML
   -ifexists            only open if database already exists
   -interactive         force interactive I/O
   -json                set output mode to 'json'
   -line                set output mode to 'line'
   -list                set output mode to 'list'
   -lookaside SIZE N    use N entries of SZ bytes for lookaside memory
   -markdown            set output mode to 'markdown'
   -maxsize N           maximum size for a --deserialize database
   -memtrace            trace all memory allocations and deallocations
   -mmap N              default mmap size set to N
   -newline SEP         set output row separator. Default: '\n'
   -nofollow            refuse to open symbolic links to database files
   -noinit              Do not read the ~/.sqliterc file at startup
   -nonce STRING        set the safe-mode escape nonce
   -no-rowid-in-view    Disable rowid-in-view using sqlite3_config()
   -nullvalue TEXT      set text string for NULL values. Default ''
   -pagecache SIZE N    use N slots of SZ bytes each for page cache memory
   -pcachetrace         trace all page cache operations
   -quote               set output mode to 'quote'
   -readonly            open the database read-only
   -safe                enable safe-mode
   -screenwidth N       use N as the default screenwidth 
   -separator SEP       set output column separator. Default: '|'
   -stats               print memory stats before each finalize
   -table               set output mode to 'table'
   -tabs                set output mode to 'tabs'
   -unsafe-testing      allow unsafe commands and modes for testing
   -version             show SQLite version
   -vfs NAME            use NAME as the default VFS
   -vfstrace            enable tracing of all VFS calls
   -zip                 open the file as a ZIP Archive
`
EOF
echo ok"}

