			case "noinit":
				noInit = true
			case "bail":
				sh.bail = true
			case "batch":
			case "interactive":
				sh.interactive = true
			case "echo":
				sh.echo = true
			case "header", "headers":
				sh.headers = true
				sh.headerSet = true
			case "noheader", "noheaders":
				sh.headers = false
				sh.headerSet = true
			case "list":
				sh.setMode(modeList)
			case "csv":
				sh.setMode(modeCsv)
			case "column":
				sh.setMode(modeColumn)
			case "table":
				sh.setMode(modeTable)
			case "box":
				sh.setMode(modeBox)
			case "markdown":
				sh.setMode(modeMarkdown)
			case "json":
				sh.setMode(modeJson)
			case "line":
				sh.setMode(modeLine)
			case "html":
				sh.setMode(modeHtml)
			case "quote":
				sh.setMode(modeQuote)
			case "tabs":
				sh.setMode(modeTabs)
			case "ascii":
				sh.setMode(modeAscii)
			case "insert":
				sh.setMode(modeInsert)
			case "separator":
				i++
				if i < len(args) {
					sh.colSep = unescapeArg(args[i])
				}
			case "newline":
				i++
				if i < len(args) {
					sh.rowSep = unescapeArg(args[i])
				}
			case "nullvalue":
				i++
				if i < len(args) {
					sh.nullValue = unescapeArg(args[i])
				}
			case "escape":
				i++
				if i < len(args) {
					switch args[i] {
					case "symbol":
						sh.escMode = 1
					case "ascii":
						sh.escMode = 0
					case "off":
						sh.escMode = 2
					}
				}
			case "version":
				fmt.Fprintf(sh.stdout, "%s %s (64-bit)\n", sqliteVersion, sqliteSourceID)
				sh.stdout.Flush()
				return 0
			case "help":
				sh.printUsage(args[0], os.Stdout)
				return 0
			case "readonly":
				readonly = true
			case "safe":
				sh.safeMode = true
			case "nofollow", "append", "deserialize", "memtrace", "pcachetrace", "stats", "vfstrace", "unsafe-testing", "no-rowid-in-view", "zip", "ifexists":
			case "lookaside", "pagecache":
				i += 2
			case "maxsize", "mmap", "vfs", "nonce", "screenwidth", "heap":
				i++
			case "A":
				// archive: not supported
				fmt.Fprintf(os.Stderr, "Error: .archive not supported\n")
				return 1
			default:
				fmt.Fprintf(os.Stderr, "%s: Error: unknown option: %s\nUse -help for a list of options.\n", args[0], a)
				return 1
			}
			continue
		}
		filename = a
		haveFile = true
	}
	_ = noInit
	sh.readOnly = readonly
	if filename == "" {
		filename = ":memory:"
	}
	sh.openDB(filename, false)
	defer sh.closeDB()
	if initFile != "" {
		sh.processFile(initFile)
	}
	for k, cmd := range cmds {
		sh.runArg(cmd, cmdIdx[k], true)
		if sh.quitFlag {
			sh.flushAll()
			return sh.exitCode
		}
	}
	if len(sqlArgs) > 0 {
		for k, a := range sqlArgs {
			ok := sh.runArg(a, sqlArgIdx[k], false)
			if sh.quitFlag {
				break
			}
			if !ok {
				sh.flushAll()
				if sh.exitCode != 0 {
					return sh.exitCode
				}
				return 1
			}
		}
		sh.flushAll()
		return sh.exitCode
	}
	rd := bufio.NewReaderSize(os.Stdin, 65536)
	sh.processInput(rd, "")
	sh.flushAll()
	if sh.quitFlag {
		return sh.exitCode
	}
	if sh.errOccurred {
		return 1
	}
	return 0
}

func (sh *Shell) flushAll() {
	sh.out.Flush()
	sh.stdout.Flush()
}

func unescapeArg(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '\\':
				b.WriteByte('\\')
			case '"':
				b.WriteByte('"')
			case '\'':
				b.WriteByte('\'')
			case 'a':
				b.WriteByte(7)
			case 'b':
				b.WriteByte(8)
			case 'f':
				b.WriteByte(12)
			case 'v':
				b.WriteByte(11)
			case '0', '1', '2', '3', '4', '5', '6', '7':
				v := 0
				k := 0
				for k < 3 && i < len(s) && s[i] >= '0' && s[i] <= '7' {
					v = v*8 + int(s[i]-'0')
					i++
					k++
				}
				i--
				b.WriteByte(byte(v))
			case 'x':
				v := 0
				k := 0
				i++
				for k < 2 && i < len(s) && isHex(s[i]) {
					v = v*16 + hexVal(s[i])
					i++
					k++
				}
				i--
				b.WriteByte(byte(v))
			default:
				b.WriteByte('\\')
				b.WriteByte(s[i])
			}
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}

func hexVal(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return 0
}

func (sh *Shell) setMode(m int) {
	sh.mode = m
	switch m {
	case modeList:
		sh.colSep = "|"
		sh.rowSep = "\n"
	case modeCsv:
		sh.colSep = ","
		sh.rowSep = "\r\n"
	case modeTabs:
		sh.colSep = "\t"
		sh.rowSep = "\n"
	case modeAscii:
		sh.colSep = "\x1f"
		sh.rowSep = "\x1e"
	case modeColumn, modeTable, modeBox, modeMarkdown:
		if !sh.headerSet {
		}
	}
}

// runArg executes a command-line argument (SQL or dot command). returns false on error.
func (sh *Shell) runArg(a string, idx int, isCmd bool) bool {
	t := strings.TrimLeft(a, " \t")
	if strings.HasPrefix(t, ".") {
		rc := sh.doMetaCommand(t)
		if rc != 0 {
			return false
		}
		return true
	}
	ok := sh.runSQL(a, 0, fmt.Sprintf("in %s command line argument", ordinal(idx)))
	sh.out.Flush()
	return ok
}

func (sh *Shell) processFile(name string) bool {
	f, err := os.Open(name)
	if err != nil {
		sh.errf("Error: cannot open \"%s\"\n", name)
		return false
	}
	defer f.Close()
	sh.nesting++
	saved := sh.inFile
	sh.inFile = name
	sh.processInput(bufio.NewReader(f), name)
	sh.inFile = saved
	sh.nesting--
	return true
}

func isAllWhitespace(s string) bool {
	i := 0
	for i < len(s) {
		c := s[i]
		if isSpaceByte(c) {
			i++
			continue
		}
		if c == '/' && i+1 < len(s) && s[i+1] == '*' {
			j := strings.Index(s[i+2:], "*/")
			if j < 0 {
				return false
			}
			i += j + 4
			continue
		}
		if c == '-' && i+1 < len(s) && s[i+1] == '-' {
			j := strings.IndexByte(s[i:], '\n')
			if j < 0 {
				return true
			}
			i += j + 1
			continue
		}
		return false
	}
	return true
}

func (sh *Shell) processInput(rd *bufio.Reader, fname string) {
	var buf strings.Builder
	inSQL := false
	startLine := 0
	lineno := 0
	for {
		line, err := rd.ReadString('\n')
		if err != nil && line == "" {
			break
		}
		lineno++
		line = strings.TrimSuffix(line, "\n")
		line = strings.TrimSuffix(line, "\r")
		if !inSQL {
			tl := strings.TrimLeft(line, " \t")
			if strings.HasPrefix(tl, ".") {
				sh.out.Flush()
				rc := sh.doMetaCommandLine(tl, lineno)
				sh.out.Flush()
				if rc == 2 || sh.quitFlag {
					return
				}
				if rc != 0 {
					sh.errOccurred = true
					if sh.bail {
						sh.quitFlag = true
						sh.exitCode = 1
						return
					}
				}
				continue
			}
			if strings.HasPrefix(tl, "#") {
				continue
			}
			if isAllWhitespace(line) {
				continue
			}
			buf.Reset()
			buf.WriteString(line)
			inSQL = true
			startLine = lineno
		} else {
			buf.WriteByte('\n')
			buf.WriteString(line)
		}
		s := buf.String()
		if sqliteComplete(s) {
			ok := sh.runSQL(s, startLine, "")
			sh.out.Flush()
			inSQL = false
			buf.Reset()
			if !ok {
				sh.errOccurred = true
				if sh.bail {
					sh.quitFlag = true
					sh.exitCode = 1
					return
				}
			}
			if sh.quitFlag {
				return
			}
		}
		if err != nil {
			break
		}
	}
	if inSQL {
		s := buf.String()
		if !isAllWhitespace(s) {
			ok := sh.runSQL(s, startLine, "")
			if !ok {
				sh.errOccurred = true
				if sh.bail {
					sh.quitFlag = true
					sh.exitCode = 1
				}
			}
		}
	}
}

func errorContext(sql string, pos int) string {
	if pos < 0 || pos >= len(sql) {
		return ""
	}
	iOffset := pos
	z := sql
	for iOffset > 50 {
		iOffset--
		z = z[1:]
		for len(z) > 0 && (z[0]&0xc0) == 0x80 {
			z = z[1:]
			iOffset--
		}
	}
	n := len(z)
	if n > 78 {
		n = 78
		for n > 0 && (z[n]&0xc0) == 0x80 {
			n--
		}
	}
	code := []byte(z[:n])
	for i := range code {
		if isSpaceByte(code[i]) {
			code[i] = ' '
		}
	}
	if iOffset < 25 {
		return fmt.Sprintf("\n  %s\n  %s^--- error here", string(code), strings.Repeat(" ", iOffset))
	}
	return fmt.Sprintf("\n  %s\n  %serror here ---^", string(code), strings.Repeat(" ", iOffset-14))
}

// runSQL executes all statements in sql. lineNo is the starting line (0 for args).
func (sh *Shell) runSQL(sql string, lineNo int, where string) bool {
	pos := 0
	for {
		// skip leading whitespace
		for pos < len(sql) && isSpaceByte(sql[pos]) {
			pos++
		}
		if pos >= len(sql) {
			return true
		}
		stmt, end, perr := ParseStatement(sql, pos)
		loc := where
		if loc == "" {
			loc = fmt.Sprintf("near line %d", lineNo)
		}
		if perr != nil {
			ctx := ""
			if perr.Pos >= 0 {
				ctx = errorContext(sql[pos:], perr.Pos-pos)
			}
			sh.errf("Parse error %s: %s%s\n", loc, perr.Msg, ctx)
			return false
		}
		if stmt == nil {
			return true
		}
		stmtText := strings.TrimRight(sql[pos:end], " \t\n\r;")
		if sh.echo {
			fmt.Fprintf(sh.out, "%s\n", strings.TrimSpace(sql[pos:end]))
		}
		ok := sh.execStmt(stmt, sql[pos:], stmtText, loc)
		if !ok {
			return false
		}
		pos = end
		if sh.quitFlag {
			return true
		}
	}
}

func (sh *Shell) execStmt(stmt Stmt, rest string, text string, loc string) bool {
	c := sh.conn
	if c.openErr != "" {
		sh.errf("Error %s: %s\n", loc, c.openErr)
		return false
	}
	p, err := c.Prepare(stmt)
	if err != nil {
		e := err.(*SQLError)
		ctx := ""
		if e.Pos >= 0 {
			ctx = errorContext(rest, e.Pos-(len(rest)-len(rest)))
		}
		_ = ctx
		ctxs := ""
		if e.Pos >= 0 {
			base := sh.stmtBase(rest)
			ctxs = errorContext(rest, e.Pos-base)
		}
		sh.errf("Parse error %s: %s%s\n", loc, e.Msg, ctxs)
		return false
	}
	if ex, ok := stmt.(*ExplainStmt); ok && ex.QueryPlan {
		return sh.runEQP(p, loc)
	}
	if sh.eqp > 0 {
		if _, ok := stmt.(*SelectStmt); ok {
			sh.showEQP(stmt)
		}
	}
	r := sh.newRenderer(p.colNames, p.declTypes)
	err = c.Execute(p, func(row []Value) bool {
		r.row(row)
		return true
	})
	r.finish()
	if err != nil {
		e := err.(*SQLError)
		sh.errf("Error %s: %s\n", loc, e.Msg)
		return false
	}
	if sh.changesOn && p.isDML {
		fmt.Fprintf(sh.out, "changes: %d   total_changes: %d\n", c.changes, c.totalChanges)
	}
	return true
}

// stmtBase returns the absolute offset base for error positions within rest.
func (sh *Shell) stmtBase(rest string) int {
	return sh.curBase
}

func (sh *Shell) printUsage(argv0 string, w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [OPTIONS] [FILENAME [SQL...]]\n", argv0)
	fmt.Fprint(w, usageText)
}

