			}
			w.WriteString("\n")
		}
		for i, v := range vals {
			if i > 0 {
				w.WriteString(" ")
			}
			if v.K == KNull {
				w.WriteString(tclEsc(sh.nullValue))
			} else {
				w.WriteString(tclEsc(v.Text()))
			}
		}
		w.WriteString("\n")
	case modeExplain:
		for i, v := range vals {
			if i > 0 {
				w.WriteString("  ")
			}
			w.WriteString(sh.displayText(v))
		}
		w.WriteString("\n")
	}
}

func (r *streamRenderer) finish() {
	if r.sh.mode == modeJson && r.n > 0 {
		r.sh.out.WriteString("]\n")
	}
}

func (sh *Shell) csvField(s string) string {
	if csvNeedsQuote(s, sh.colSep) {
		return csvQuote(s)
	}
	return s
}

func quoteIdentIfNeeded(s string) string {
	if needsQuote(s) {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	return s
}

// ---------- grid modes (column, table, box, markdown) ----------

type gridRenderer struct {
	sh   *Shell
	cols []string
	rows [][]Value
}

func (r *gridRenderer) row(vals []Value) {
	r.rows = append(r.rows, append([]Value(nil), vals...))
}

type cell struct {
	text  string
	right bool
}

func (r *gridRenderer) finish() {
	sh := r.sh
	if len(r.rows) == 0 {
		return
	}
	n := len(r.cols)
	widths := make([]int, n)
	cells := make([][]cell, len(r.rows))
	for i, c := range r.cols {
		widths[i] = strWidth(c)
	}
	for ri, row := range r.rows {
		cells[ri] = make([]cell, n)
		for i, v := range row {
			var t string
			right := false
			switch v.K {
			case KNull:
				t = sh.nullValue
			case KInt, KReal:
				t = v.Text()
				right = true
			default:
				t = escCtrl(v.S, sh.escMode)
			}
			cells[ri][i] = cell{text: t, right: right}
		}
	}
	// explicit widths
	fixed := make([]int, n)
	for i := 0; i < n && i < len(sh.widths); i++ {
		fixed[i] = sh.widths[i]
	}
	wrap := sh.modeOpts.wrap
	// split cells into lines
	type mcell struct {
		lines []string
		right bool
	}
	mcells := make([][]mcell, len(cells))
	for ri := range cells {
		mcells[ri] = make([]mcell, n)
		for i, c := range cells[ri] {
			lines := strings.Split(c.text, "\n")
			lim := 0
			if fixed[i] != 0 {
				lim = abs(fixed[i])
			} else if wrap > 0 {
				lim = wrap
			}
			if lim > 0 {
				var nl []string
				for _, l := range lines {
					nl = append(nl, wrapLine(l, lim, sh.modeOpts.wordwrap)...)
				}
				lines = nl
			}
			mcells[ri][i] = mcell{lines: lines, right: c.right}
			for _, l := range lines {
				if w := strWidth(l); w > widths[i] {
					widths[i] = w
				}
			}
		}
	}
	for i := 0; i < n; i++ {
		if fixed[i] != 0 {
			widths[i] = abs(fixed[i])
		} else if wrap > 0 && widths[i] > wrap {
			widths[i] = wrap
		}
	}
	w := sh.out
	pad := func(s string, width int, right bool) string {
		sw := strWidth(s)
		if sw >= width {
			return s
		}
		if right {
			return strings.Repeat(" ", width-sw) + s
		}
		return s + strings.Repeat(" ", width-sw)
	}
	center := func(s string, width int) string {
		sw := strWidth(s)
		if sw >= width {
			return s
		}
		l := (width - sw) / 2
		return strings.Repeat(" ", l) + s + strings.Repeat(" ", width-sw-l)
	}
	switch sh.mode {
	case modeColumn:
		var lines []string
		if sh.headers || !sh.headerSet {
			var b strings.Builder
			for i, c := range r.cols {
				if i > 0 {
					b.WriteString("  ")
				}
				if wrap > 0 {
					b.WriteString(center(c, widths[i]))
				} else {
					right := fixed[i] < 0
					b.WriteString(pad(c, widths[i], right))
				}
			}
			lines = append(lines, strings.TrimRight(b.String(), " "))
			b.Reset()
			for i := range r.cols {
				if i > 0 {
					b.WriteString("  ")
				}
				b.WriteString(strings.Repeat("-", widths[i]))
			}
			lines = append(lines, b.String())
		}
		for ri := range mcells {
			nl := 1
			for _, mc := range mcells[ri] {
				if len(mc.lines) > nl {
					nl = len(mc.lines)
				}
			}
			for li := 0; li < nl; li++ {
				var b strings.Builder
				for i, mc := range mcells[ri] {
					if i > 0 {
						b.WriteString("  ")
					}
					t := ""
					if li < len(mc.lines) {
						t = mc.lines[li]
					}
					right := mc.right
					if fixed[i] < 0 {
						right = true
					}
					b.WriteString(pad(t, widths[i], right))
				}
				lines = append(lines, strings.TrimRight(b.String(), " "))
			}
		}
		for _, l := range lines {
			w.WriteString(l)
			w.WriteString("\n")
		}
	case modeTable, modeMarkdown, modeBox:
		var h, v, tl, tm, tr, ml, mm, mr, bl, bm, br string
		var hh, hl, hm, hr string
		if sh.mode == modeBox {
			h, v = "─", "│"
			tl, tm, tr = "╭", "┬", "╮"
			ml, mm, mr = "├", "┼", "┤"
			bl, bm, br = "╰", "┴", "╯"
			hh, hl, hm, hr = "═", "╞", "╪", "╡"
		} else {
			h, v = "-", "|"
			tl, tm, tr = "+", "+", "+"
			ml, mm, mr = "+", "+", "+"
			bl, bm, br = "+", "+", "+"
			hh, hl, hm, hr = "-", "+", "+", "+"
		}
		_ = ml
		_ = mm
		_ = mr
		sep := func(l, m, r, fill string) string {
			var b strings.Builder
			b.WriteString(l)
			for i := range r2(n) {
				if i > 0 {
					b.WriteString(m)
				}
				b.WriteString(strings.Repeat(fill, widths[i]+2))
			}
			b.WriteString(r)
			return b.String()
		}
		if sh.mode != modeMarkdown {
			w.WriteString(sep(tl, tm, tr, h))
			w.WriteString("\n")
		}
		// header
		if sh.headers || !sh.headerSet || true {
			w.WriteString(v)
			for i, c := range r.cols {
				w.WriteString(" ")
				w.WriteString(center(c, widths[i]))
				w.WriteString(" ")
				w.WriteString(v)
			}
			w.WriteString("\n")
			if sh.mode == modeMarkdown {
				w.WriteString("|")
				for i := range r.cols {
					w.WriteString(strings.Repeat("-", widths[i]+2))
					w.WriteString("|")
				}
				w.WriteString("\n")
			} else if sh.mode == modeBox {
				w.WriteString(sep(hl, hm, hr, hh))
				w.WriteString("\n")
			} else {
				w.WriteString(sep(tl, tm, tr, h))
				w.WriteString("\n")
			}
		}
		for ri := range mcells {
			nl := 1
			for _, mc := range mcells[ri] {
				if len(mc.lines) > nl {
					nl = len(mc.lines)
				}
			}
			for li := 0; li < nl; li++ {
				w.WriteString(v)
				for i, mc := range mcells[ri] {
					t := ""
					if li < len(mc.lines) {
						t = mc.lines[li]
					}
					w.WriteString(" ")
					w.WriteString(pad(t, widths[i], mc.right))
					w.WriteString(" ")
					w.WriteString(v)
				}
				w.WriteString("\n")
			}
		}
		if sh.mode != modeMarkdown {
			w.WriteString(sep(bl, bm, br, h))
			w.WriteString("\n")
		}
	}
}

func r2(n int) []struct{} { return make([]struct{}, n) }

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func wrapLine(s string, lim int, word bool) []string {
	if strWidth(s) <= lim {
		return []string{s}
	}
	var out []string
	runes := []rune(s)
	for len(runes) > 0 {
		w := 0
		i := 0
		for i < len(runes) && w+runeWidth(runes[i]) <= lim {
			w += runeWidth(runes[i])
			i++
		}
		if i == 0 {
			i = 1
		}
		if word && i < len(runes) {
			// break at last space
			j := i
			for j > 0 && runes[j-1] != ' ' && runes[j] != ' ' {
				j--
			}
			if j > 0 {
				seg := strings.TrimRight(string(runes[:j]), " ")
				out = append(out, seg)
				k := j
				for k < len(runes) && runes[k] == ' ' {
					k++
				}
				runes = runes[k:]
				continue
			}
		}
		out = append(out, string(runes[:i]))
		runes = runes[i:]
	}
	return out
}
