		_ = mr
		sep := func(l, m, r, fill string) string {
			var b strings.Builder
			b.WriteString(l)
			for i := range r2(n) {
				if i > 0 {
					b.WriteString(m)
				}
				b.WriteString(strings.Repeat(fill, widths[i]+2))
			}
			b.WriteString(r)
			return b.String()
		}
		if sh.mode != modeMarkdown {
			w.WriteString(sep(tl, tm, tr, h))
			w.WriteString("\n")
		}
		// header
		if sh.headers || !sh.headerSet || true {
			w.WriteString(v)
			for i, c := range r.cols {
				w.WriteString(" ")
				w.WriteString(center(c, widths[i]))
				w.WriteString(" ")
				w.WriteString(v)
			}
			w.WriteString("\n")
			if sh.mode == modeMarkdown {
				w.WriteString("|")
				for i := range r.cols {
					w.WriteString(strings.Repeat("-", widths[i]+2))
					w.WriteString("|")
				}
				w.WriteString("\n")
			} else if sh.mode == modeBox {
				w.WriteString(sep(hl, hm, hr, hh))
				w.WriteString("\n")
			} else {
				w.WriteString(sep(tl, tm, tr, h))
				w.WriteString("\n")
			}
		}
		for ri := range mcells {
			nl := 1
			for _, mc := range mcells[ri] {
				if len(mc.lines) > nl {
					nl = len(mc.lines)
				}
			}
			for li := 0; li < nl; li++ {
				w.WriteString(v)
				for i, mc := range mcells[ri] {
					t := ""
					if li < len(mc.lines) {
						t = mc.lines[li]
					}
					w.WriteString(" ")
					w.WriteString(pad(t, widths[i], mc.right))
					w.WriteString(" ")
					w.WriteString(v)
				}
				w.WriteString("\n")
			}
		}
		if sh.mode != modeMarkdown {
			w.WriteString(sep(bl, bm, br, h))
			w.WriteString("\n")
		}
	}
}

func r2(n int) []struct{} { return make([]struct{}, n) }

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func wrapLine(s string, lim int, word bool) []string {
	if strWidth(s) <= lim {
		return []string{s}
	}
	var out []string
	runes := []rune(s)
	for len(runes) > 0 {
		w := 0
		i := 0
		for i < len(runes) && w+runeWidth(runes[i]) <= lim {
			w += runeWidth(runes[i])
			i++
		}
		if i == 0 {
			i = 1
		}
		if word && i < len(runes) {
			// break at last space
			j := i
			for j > 0 && runes[j-1] != ' ' && runes[j] != ' ' {
				j--
			}
			if j > 0 {
				seg := strings.TrimRight(string(runes[:j]), " ")
				out = append(out, seg)
				k := j
				for k < len(runes) && runes[k] == ' ' {
					k++
				}
				runes = runes[k:]
				continue
			}
		}
		out = append(out, string(runes[:i]))
		runes = runes[i:]
	}
	return out
}
