// parse dot-command arguments like the sqlite shell
func parseDotArgs(line string) []string {
	var args []string
	i := 0
	n := len(line)
	for i < n {
		for i < n && isSpaceByte(line[i]) {
			i++
		}
		if i >= n {
			break
		}
		c := line[i]
		if c == '"' || c == '\'' {
			q := c
			i++
			var b strings.Builder
			for i < n && line[i] != q {
				if line[i] == '\\' && q == '"' && i+1 < n {
					b.WriteByte(line[i])
					i++
				}
				b.WriteByte(line[i])
				i++
			}
			if i < n {
				i++
			}
			s := b.String()
			if q == '"' {
				s = unescapeArg(s)
			}
			args = append(args, s)
			continue
		}
		st := i
		for i < n && !isSpaceByte(line[i]) {
			i++
		}
		args = append(args, line[st:i])
	}
	return args
}

func (sh *Shell) doMetaCommandLine(line string, lineno int) int {
