// ---------------- .tables / .indexes / .schema ----------------

func likeMatchCI(pat, s string) bool {
	return likeMatch(pat, s, 0, true)
}

func (sh *Shell) printColumns(names []string) {
	if len(names) == 0 {
		return
	}
	const screen = 80
	n := len(names)
	for rows := 1; rows <= n; rows++ {
		cols := (n + rows - 1) / rows
		widths := make([]int, cols)
		for i, nm := range names {
			c := i / rows
			if w := strWidth(nm); w > widths[c] {
				widths[c] = w
			}
		}
		total := 0
		for _, w := range widths {
			total += w
		}
		total += 2 * (cols - 1)
		if total <= screen || rows == n {
			gap := 2
			if cols > 1 {
				gap = 2 + (screen-total)/(cols-1)
				if gap > 5 {
					gap = 5
				}
				if gap < 2 {
					gap = 2
				}
			}
			for r := 0; r < rows; r++ {
				var b strings.Builder
				for c := 0; c < cols; c++ {
					i := c*rows + r
					if i >= n {
						break
					}
					if c > 0 {
						b.WriteString(strings.Repeat(" ", gap))
					}
					nm := names[i]
					b.WriteString(nm)
					if c < cols-1 && (c+1)*rows+r < n {
						b.WriteString(strings.Repeat(" ", widths[c]-strWidth(nm)))
					}
				}
				fmt.Fprintf(sh.out, "%s\n", strings.TrimRight(b.String(), " "))
			}
			return
		}
	}
}

func (sh *Shell) doTables(args []string) {
	c := sh.conn
	var names []string
	pat := ""
	if len(args) > 0 {
		pat = args[0]
	}
	add := func(s *Schema, prefix string) {
		for _, e := range s.entries {
			if e.Type != "table" && e.Type != "view" {
				continue
			}
			if strings.HasPrefix(strings.ToLower(e.Name), "sqlite_") {
				continue
			}
			if pat != "" && !likeMatchCI(pat, e.Name) {
				continue
			}
			names = append(names, prefix+e.Name)
		}
	}
	add(c.main, "")
	for _, s := range c.attached {
		add(s, s.Name+".")
	}
	add(c.temp, "temp.")
	sort.Strings(names)
	sh.printColumns(names)
}

func (sh *Shell) doIndexes(args []string) {
	c := sh.conn
	var names []string
	add := func(s *Schema, prefix string) {
		for _, e := range s.entries {
			if e.Type != "index" {
				continue
			}
			if len(args) > 0 && !likeMatchCI(args[0], e.TblName) {
				continue
			}
			names = append(names, prefix+e.Name)
		}
	}
	add(c.main, "")
	add(c.temp, "temp.")
	sort.Strings(names)
	sh.printColumns(names)
}

func (sh *Shell) doSchemaCmd(args []string) int {
	var pat []string
	indent := false
	for _, a := range args {
		if a == "--indent" {
			indent = true
			continue
		}
		if a == "--nosys" {
			continue
		}
		pat = append(pat, a)
	}
	sh.doSchema(pat, indent)
	return 0
}

func (sh *Shell) doSchema(pat []string, indent bool) {
	c := sh.conn
	out := func(s *Schema, e *schemaEntry, sqlv Value) {
		if sqlv.K == KNull {
			return
		}
		sql := sqlv.S
		if s == c.temp && e.Type == "table" {
			sql = strings.Replace(sql, "CREATE TABLE ", "CREATE TABLE temp.", 1)
		}
		if indent {
			sql = indentSQL(sql)
		}
		fmt.Fprintf(sh.out, "%s;\n", sql)
		if e.Type == "view" {
			if v, ok := e.obj.(*View); ok {
				cp := &compiler{conn: c}
				var names []string
				func() {
					defer func() { recover() }()
					cs := cp.compileView(v)
					names = viewColNames(v, cs)
				}()
				_ = names
			}
		}
	}
	match := func(e *schemaEntry) bool {
		if len(pat) == 0 {
			return true
		}
		for _, p := range pat {
			if likeMatchCI(p, e.Name) || likeMatchCI(p, e.TblName) {
				return true
			}
		}
		return false
	}
	for _, s := range []*Schema{c.main, c.temp} {
		for _, e := range s.entries {
			if !match(e) {
				continue
			}
			sqlv := s.entrySQL(e)
			if e.Type == "view" && sqlv.K != KNull {
				v := e.obj.(*View)
				cp := &compiler{conn: c}
				var names []string
				func() {
					defer func() { recover() }()
					cs := cp.compileView(v)
					names = viewColNames(v, cs)
				}()
				sql := sqlv.S
				if indent {
					sql = indentSQL(sql)
				}
				if names != nil {
					fmt.Fprintf(sh.out, "%s\n/* %s(%s) */;\n", sql, v.Name, strings.Join(names, ","))
				} else {
					fmt.Fprintf(sh.out, "%s;\n", sql)
				}
				continue
			}
			out(s, e, sqlv)
		}
	}
}

func indentSQL(sql string) string {
	return sql
}

// ---------------- .dump ----------------

func (sh *Shell) doDump(args []string) {
	c := sh.conn
	w := sh.out
	var pats []string
	for _, a := range args {
		if strings.HasPrefix(a, "-") {
			continue
		}
		pats = append(pats, a)
	}
	match := func(name string) bool {
		if len(pats) == 0 {
			return true
		}
		for _, p := range pats {
			if likeMatchCI(p, name) {
				return true
			}
		}
		return false
	}
	fmt.Fprintf(w, "PRAGMA foreign_keys=OFF;\n")
	fmt.Fprintf(w, "BEGIN TRANSACTION;\n")
	s := c.main
	seqDone := false
	for _, e := range s.entries {
		if e.Type != "table" {
			continue
		}
		t := e.obj.(*Table)
		if !match(t.Name) {
			continue
		}
		if strings.EqualFold(t.Name, "sqlite_sequence") {
			seqDone = true
			fmt.Fprintf(w, "DELETE FROM sqlite_sequence;\n")
		} else if strings.HasPrefix(strings.ToLower(t.Name), "sqlite_stat") {
			fmt.Fprintf(w, "ANALYZE sqlite_schema;\n")
		} else if strings.HasPrefix(strings.ToLower(t.Name), "sqlite_") {
			continue
		} else {
			fmt.Fprintf(w, "%s;\n", t.SQL)
		}
		_ = seqDone
		// rows
		tn := quoteIdentIfNeeded(t.Name)
		var colList string
		hasGen := false
		for _, col := range t.Cols {
			if col.Generated != nil {
				hasGen = true
			}
		}
		if hasGen {
			var names []string
			for _, col := range t.Cols {
				if col.Generated == nil {
					names = append(names, quoteIdentIfNeeded(col.Name))
				}
			}
			colList = "(" + strings.Join(names, ",") + ")"
		}
		rows := t.rows
		if t.WithoutRowid && t.pkIndex != nil {
			rows = nil
			for _, en := range t.pkIndex.entries {
				if r := t.getRow(en.rowid); r != nil {
					rows = append(rows, r)
				}
			}
		}
		for _, r := range rows {
			var vals []string
			for i, col := range t.Cols {
				if col.Generated != nil {
					continue
				}
				v := r.Vals[i]
				if i == t.IPK {
					v = IntValue(r.Rowid)
				}
				vals = append(vals, quoteLiteral(v))
			}
			fmt.Fprintf(w, "INSERT INTO %s%s VALUES(%s);\n", tn, colList, strings.Join(vals, ","))
		}
	}
	for _, e := range s.entries {
		if e.Type == "table" {
			continue
		}
		if !match(e.TblName) && !match(e.Name) {
			continue
		}
		sqlv := s.entrySQL(e)
		if sqlv.K == KNull {
			continue
		}
		fmt.Fprintf(w, "%s;\n", sqlv.S)
	}
	fmt.Fprintf(w, "COMMIT;\n")
}

// ---------------- .open ----------------

func (sh *Shell) doOpen(args []string) int {
	file := ""
	for _, a := range args {
		if strings.HasPrefix(a, "-") {
			continue
		}
		file = a
	}
	sh.closeDB()
	if file == "" {
		file = ":memory:"
	}
	sh.openDB(file, true)
	return 0
}

// ---------------- .import ----------------

func (sh *Shell) doImport(args []string) int {
	var file, table string
	csv := sh.mode == modeCsv
	skip := 0
	sep := sh.colSep
	rowSep := sh.rowSep
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch a {
		case "--csv":
			csv = true
		case "--ascii":
			csv = false
			sep = "\x1f"
			rowSep = "\x1e"
		case "--skip":
			i++
			if i < len(args) {
				skip, _ = strconv.Atoi(args[i])
			}
		case "--schema":
			i++
		case "-v":
		default:
			if file == "" {
				file = a
			} else {
				table = a
			}
		}
	}
	if file == "" || table == "" {
		sh.errf("Usage: .import FILE TABLE\n")
		return 1
	}
	data, err := os.ReadFile(file)
	if err != nil {
		sh.errf("Error: cannot open \"%s\"\n", file)
		return 1
	}
	if csv {
		sep = ","
		if sh.mode == modeCsv {
			sep = sh.colSep
		}
	}
	if sh.mode == modeAscii && !csv {
		sep = "\x1f"
		rowSep = "\x1e"
	}
	if sep == "\t" || sh.mode == modeTabs {
		csv = true
	}
	records := parseImport(string(data), sep, rowSep, csv)
	if skip > 0 && skip <= len(records) {
		records = records[skip:]
	}
	c := sh.conn
	t := c.findTable("", table)
	lineNo := skip
	if t == nil {
		if len(records) == 0 {
			return 0
		}
		hdr := records[0]
		records = records[1:]
		lineNo++
		var cols []string
		for _, h := range hdr {
			cols = append(cols, quoteIdent(h)+" TEXT")
		}
		sql := "CREATE TABLE " + quoteIdent(table) + "(" + strings.Join(cols, ",") + ")"
		if !sh.runSQL(sql, 0, "") {
			return 1
		}
		t = c.findTable("", table)
		if t == nil {
			return 1
		}
	}
	ncol := len(t.Cols)
	ok := true
	ph := make([]string, ncol)
	for i := range ph {
		ph[i] = "?"
	}
	ins := "INSERT INTO " + quoteIdent(table) + " VALUES(" + strings.Join(ph, ",") + ")"
	st, _, perr := ParseStatement(ins, 0)
	if perr != nil {
		return 1
	}
	p, err2 := c.Prepare(st)
	if err2 != nil {
		sh.errf("Error: %s\n", err2.Error())
		return 1
	}
	wasTxn := c.inTxn
	if !wasTxn {
		c.inTxn = true
	}
	for _, rec := range records {
		lineNo++
		if len(rec) == 1 && rec[0] == "" {
			continue
		}
		if len(rec) < ncol {
			sh.errf("%s:%d: expected %d columns but found %d - filling the rest with NULL\n", file, lineNo, ncol, len(rec))
		} else if len(rec) > ncol {
			sh.errf("%s:%d: expected %d columns but found %d - extras ignored\n", file, lineNo, ncol, len(rec))
		}
		for i := 0; i < ncol; i++ {
			name := "?" + strconv.Itoa(i+1)
			if i < len(rec) {
				c.params[name] = TextValue(rec[i])
			} else {
				c.params[name] = NullValue
			}
		}
		if err := c.Execute(p, func([]Value) bool { return true }); err != nil {
			sh.errf("%s:%d: INSERT failed: %s\n", file, lineNo, err.Error())
			ok = false
		}
	}
	for i := 0; i < ncol; i++ {
		delete(c.params, "?"+strconv.Itoa(i+1))
	}
	if !wasTxn {
		c.inTxn = false
		c.commitPersist()
	}
	if !ok {
		return 0
	}
	return 0
}

func parseImport(data, sep, rowSep string, csv bool) [][]string {
	var recs [][]string
	if !csv {
		lines := strings.Split(data, rowSep)
		if len(lines) > 0 && lines[len(lines)-1] == "" {
			lines = lines[:len(lines)-1]
		}
		for _, l := range lines {
			l = strings.TrimSuffix(l, "\r")
			recs = append(recs, strings.Split(l, sep))
		}
		return recs
	}
	i := 0
	n := len(data)
	var rec []string
	var field strings.Builder
	for i < n {
		if data[i] == '"' {
			i++
			for i < n {
				if data[i] == '"' {
					if i+1 < n && data[i+1] == '"' {
						field.WriteByte('"')
						i += 2
						continue
					}
					i++
					break
				}
				field.WriteByte(data[i])
				i++
			}
			continue
		}
		if strings.HasPrefix(data[i:], sep) {
			rec = append(rec, field.String())
			field.Reset()
			i += len(sep)
			continue
		}
		if data[i] == '\n' || (data[i] == '\r' && i+1 < n && data[i+1] == '\n') {
			rec = append(rec, field.String())
			field.Reset()
			recs = append(recs, rec)
			rec = nil
			if data[i] == '\r' {
				i++
			}
			i++
			continue
		}
		field.WriteByte(data[i])
		i++
	}
	if field.Len() > 0 || rec != nil {
		rec = append(rec, field.String())
		recs = append(recs, rec)
	}
	return recs
}
