		if c == '"' || c == '\'' {
			q := c
			i++
			var b strings.Builder
			for i < n && line[i] != q {
				if line[i] == '\\' && q == '"' && i+1 < n {
					b.WriteByte(line[i])
					i++
				}
				b.WriteByte(line[i])
				i++
			}
			if i < n {
				i++
			}
			s := b.String()
			if q == '"' {
				s = unescapeArg(s)
			}
			args = append(args, s)
			continue
		}
		st := i
		for i < n && !isSpaceByte(line[i]) {
			i++
		}
		args = append(args, line[st:i])
	}
	return args
}

func (sh *Shell) doMetaCommandLine(line string, lineno int) int {
	sh.curLine = lineno
	return sh.doMetaCommand(line)
}

func booleanValue(s string) (bool, bool) {
	switch strings.ToLower(s) {
	case "on", "yes", "true", "1":
		return true, true
	case "off", "no", "false", "0":
		return false, true
	}
	if n, err := strconv.Atoi(s); err == nil {
		return n != 0, true
	}
	return false, false
}

func (sh *Shell) boolArg(s string) bool {
	b, ok := booleanValue(s)
	if !ok {
		sh.errf("ERROR: Not a boolean value: \"%s\". Assuming \"no\".\n", s)
		return false
	}
	return b
}

func (sh *Shell) doMetaCommand(line string) int {
	if sh.echo {
		fmt.Fprintf(sh.out, "%s\n", line)
	}
	l := strings.TrimRight(line, " \t\r\n")
	if strings.HasSuffix(l, ";") {
		l = strings.TrimRight(strings.TrimSuffix(l, ";"), " \t")
	}
	args := parseDotArgs(l[1:])
	if len(args) == 0 {
		return 0
	}
	cmd := args[0]
	n := len(cmd)
	is := func(full string, minLen int) bool {
		return n >= minLen && n <= len(full) && strings.HasPrefix(full, cmd)
	}
	switch {
	case is("bail", 2):
		if len(args) != 2 {
			sh.errf("Usage: .bail on|off\n")
			return 1
		}
		sh.bail = sh.boolArg(args[1])
	case is("changes", 3):
		if len(args) != 2 {
			sh.errf("Usage: .changes on|off\n")
			return 1
		}
		sh.changesOn = sh.boolArg(args[1])
	case is("crlf", 2):
		fmt.Fprintf(sh.out, "crlf is OFF\n")
	case is("databases", 2):
		fmt.Fprintf(sh.out, "main: \"%s\" r/w\n", sh.conn.mainFileDisplay())
		if len(sh.conn.temp.entries) > 0 || true {
			fmt.Fprintf(sh.out, "temp: \"\" r/w\n")
		}
		for _, s := range sh.conn.attached {
			fmt.Fprintf(sh.out, "%s: \"%s\" r/w\n", s.Name, s.File)
		}
	case is("dump", 2):
		sh.doDump(args[1:])
	case is("echo", 2):
		if len(args) != 2 {
			sh.errf("Usage: .echo on|off\n")
			return 1
		}
		sh.echo = sh.boolArg(args[1])
	case is("eqp", 2):
		if len(args) == 2 {
			switch strings.ToLower(args[1]) {
			case "full":
				sh.eqp = 2
			case "trigger":
				sh.eqp = 3
			default:
				if sh.boolArg(args[1]) {
					sh.eqp = 1
				} else {
					sh.eqp = 0
				}
			}
		} else {
			sh.errf("Usage: .eqp off|on|trace|trigger|full\n")
			return 1
		}
	case is("exit", 2) || is("quit", 1):
		code := 0
		if len(args) > 1 && is("exit", 2) {
			code, _ = strconv.Atoi(args[1])
		}
		sh.quitFlag = true
		sh.exitCode = code
		return 2
	case is("explain", 3):
		if len(args) > 1 {
			sh.explain = strings.ToLower(args[1])
		} else {
			sh.explain = "on"
		}
	case is("fullschema", 2):
		sh.doSchema(nil, false)
		fmt.Fprintf(sh.out, "/* No STAT tables available */\n")
	case is("headers", 2):
		if len(args) != 2 {
			sh.errf("Usage: .headers on|off\n")
			return 1
		}
		sh.headers = sh.boolArg(args[1])
		sh.headerSet = true
	case is("help", 2):
		sh.doHelp(args[1:])
	case is("import", 2):
		return sh.doImport(args[1:])
	case is("indexes", 3) || is("indices", 3):
		sh.doIndexes(args[1:])
	case is("limit", 2):
		sh.doLimit(args[1:])
	case is("mode", 3):
		return sh.doMode(args[1:])
	case is("nullvalue", 2):
		if len(args) != 2 {
			sh.errf("Usage: .nullvalue STRING\n")
			return 1
		}
		sh.nullValue = args[1]
	case is("once", 2):
		return sh.doOutput(args[1:], true)
	case is("open", 2):
		return sh.doOpen(args[1:])
	case is("output", 2):
		return sh.doOutput(args[1:], false)
	case is("parameter", 2):
		return sh.doParameter(args[1:])
	case is("print", 2):
		fmt.Fprintf(sh.out, "%s\n", strings.Join(args[1:], " "))
	case is("prompt", 2):
		if len(args) > 1 {
			sh.prompt1 = args[1]
		}
		if len(args) > 2 {
			sh.prompt2 = args[2]
		}
	case is("read", 2):
		if len(args) != 2 {
			sh.errf("Usage: .read FILE\n")
			return 1
		}
		if strings.HasPrefix(args[1], "|") {
			out, err := exec.Command("sh", "-c", args[1][1:]).Output()
			if err != nil && len(out) == 0 {
				sh.errf("Error: cannot open \"%s\"\n", args[1])
				return 1
			}
			sh.processInput(bufio.NewReader(strings.NewReader(string(out))), args[1])
			return 0
		}
		f, err := os.Open(args[1])
		if err != nil {
			sh.errf("Error: cannot open \"%s\"\n", args[1])
			return 1
		}
		sh.nesting++
		sh.processInput(bufio.NewReader(f), args[1])
		sh.nesting--
		f.Close()
		if sh.quitFlag {
			return 2
		}
	case is("schema", 2):
		return sh.doSchemaCmd(args[1:])
	case is("separator", 3):
		if len(args) < 2 || len(args) > 3 {
			sh.errf("Usage: .separator COL ?ROW?\n")
			return 1
		}
		sh.colSep = unescapeArg(args[1])
		if len(args) > 2 {
			sh.rowSep = unescapeArg(args[2])
		}
	case is("shell", 2) || is("system", 2):
		if len(args) < 2 {
			sh.errf("Usage: .system COMMAND\n")
			return 1
		}
		sh.out.Flush()
		cmdline := strings.Join(args[1:], " ")
		c := exec.Command("sh", "-c", cmdline)
		c.Stdout = os.Stdout
		c.Stderr = os.Stderr
		c.Run()
	case is("show", 2):
		sh.doShow()
	case is("stats", 2):
		if len(args) > 1 {
			sh.statsOn = sh.boolArg(args[1])
		}
	case is("tables", 2):
		sh.doTables(args[1:])
	case is("timeout", 2):
	case is("timer", 2):
		if len(args) > 1 {
			sh.timer = sh.boolArg(args[1])
		}
	case is("trace", 2):
	case is("version", 2):
		fmt.Fprintf(sh.out, "SQLite %s %s\n", sqliteVersion, sqliteSourceID)
		fmt.Fprintf(sh.out, "zlib version 1.2.11\n")
		fmt.Fprintf(sh.out, "gcc-11.4.0 (64-bit)\n")
	case is("width", 2):
		sh.widths = nil
		for _, a := range args[1:] {
			v, _ := strconv.Atoi(a)
			sh.widths = append(sh.widths, v)
		}
	case is("cd", 2):
		if len(args) != 2 {
			sh.errf("Usage: .cd DIRECTORY\n")
			return 1
		}
		if err := os.Chdir(args[1]); err != nil {
			sh.errf("Cannot change to directory \"%s\"\n", args[1])
			return 1
		}
	case is("testcase", 2), is("check", 2), is("log", 2), is("progress", 3), is("auth", 2), is("vfsinfo", 4), is("vfslist", 4), is("vfsname", 4), is("dbconfig", 3), is("filectrl", 2), is("lint", 2), is("scanstats", 2), is("intck", 2), is("imposter", 2), is("expert", 2), is("unmodule", 2), is("nonce", 2), is("load", 2), is("recover", 2), is("selftest", 2), is("sha3sum", 2), is("save", 2), is("backup", 2), is("restore", 2), is("clone", 2), is("dbinfo", 2), is("dbtotxt", 2), is("excel", 2), is("www", 2), is("connection", 2), is("archive", 2), is("binary", 2):
		return sh.doMisc(cmd, args)
	default:
		sh.errf("Error: unknown command or invalid arguments:  \"%s\". Enter \".help\" for help\n", cmd)
		return 1
	}
	return 0
}

func (sh *Shell) doMisc(cmd string, args []string) int {
	switch {
	case strings.HasPrefix("dbinfo", cmd):
		return 0
	case strings.HasPrefix("save", cmd), strings.HasPrefix("backup", cmd):
		if len(args) < 2 {
			sh.errf("Usage: .save FILE\n")
			return 1
		}
		file := args[len(args)-1]
		if err := sh.conn.saveTo(file); err != nil {
			sh.errf("Error: %s\n", err.Error())
			return 1
		}
	case strings.HasPrefix("restore", cmd):
		if len(args) < 2 {
			return 1
		}
		file := args[len(args)-1]
		nc, err := loadDatabase(file)
		if err != nil {
			sh.errf("Error: %s\n", err.Error())
			return 1
		}
		fn := sh.conn.filename
		*sh.conn = *nc
		sh.conn.filename = fn
		sh.conn.dirty = true
	case strings.HasPrefix("load", cmd):
		if len(args) < 2 {
			sh.errf("Usage: .load FILE ?ENTRYPOINT?\n")
			return 1
		}
		sh.errf("Error: %s.so: cannot open shared object file: No such file or directory\n", args[1])
		return 1
	case strings.HasPrefix("sha3sum", cmd):
		return 0
	}
	return 0
}

func (sh *Shell) doShow() {
	w := sh.out
	onoff := func(b bool) string {
		if b {
			return "on"
		}
		return "off"
	}
	fmt.Fprintf(w, "%12s: %s\n", "echo", onoff(sh.echo))
	eqp := "off"
	switch sh.eqp {
	case 1:
		eqp = "on"
	case 2:
		eqp = "full"
	case 3:
		eqp = "trigger"
	}
	fmt.Fprintf(w, "%12s: %s\n", "eqp", eqp)
	fmt.Fprintf(w, "%12s: %s\n", "explain", sh.explain)
	fmt.Fprintf(w, "%12s: %s\n", "headers", onoff(sh.headers))
	fmt.Fprintf(w, "%12s: %s\n", "mode", modeNames[sh.mode])
	fmt.Fprintf(w, "%12s: %s\n", "nullvalue", showQuoted(sh.nullValue))
	outName := "stdout"
	if sh.outName != "" {
		outName = sh.outName
	}
	fmt.Fprintf(w, "%12s: %s\n", "output", outName)
	fmt.Fprintf(w, "%12s: %s\n", "colseparator", showQuoted(sh.colSep))
	fmt.Fprintf(w, "%12s: %s\n", "rowseparator", showQuoted(sh.rowSep))
	fmt.Fprintf(w, "%12s: %s\n", "stats", onoff(sh.statsOn))
	var ws []string
	for _, x := range sh.widths {
		ws = append(ws, strconv.Itoa(x))
	}
	fmt.Fprintf(w, "%12s: %s\n", "width", strings.Join(ws, " "))
	fmt.Fprintf(w, "%12s: %s\n", "filename", sh.filename)
}

func showQuoted(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		default:
			if c < 0x20 || c == 0x7f {
				fmt.Fprintf(&b, "\\%03o", c)
			} else {
				b.WriteByte(c)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func (sh *Shell) doMode(args []string) int {
	if len(args) == 0 {
		sh.showMode()
		return 0
	}
	i := 0
	for i < len(args) {
		a := args[i]
		if strings.HasPrefix(a, "-") {
			opt := strings.TrimLeft(a, "-")
			switch opt {
			case "wrap":
				i++
				if i < len(args) {
					sh.modeOpts.wrap, _ = strconv.Atoi(args[i])
				}
			case "wordwrap":
				i++
				if i < len(args) {
					b, _ := booleanValue(args[i])
					sh.modeOpts.wordwrap = b
				}
			case "ww":
				sh.modeOpts.wordwrap = true
			case "quote":
				sh.modeOpts.quote = true
				if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
					i++
					if args[i] == "off" {
						sh.modeOpts.quote = false
					}
				}
			case "noquote":
				sh.modeOpts.quote = false
			case "null":
				i++
				if i < len(args) {
					sh.nullValue = args[i]
				}
			case "colsep":
				i++
				if i < len(args) {
					sh.colSep = unescapeArg(args[i])
				}
			case "rowsep":
				i++
				if i < len(args) {
					sh.rowSep = unescapeArg(args[i])
				}
			case "tablename":
				i++
				if i < len(args) {
					sh.modeTable = args[i]
				}
			case "title", "titles":
				i++
				if i < len(args) {
					b, _ := booleanValue(args[i])
					sh.headers = b
					sh.headerSet = true
				}
			case "escape":
				i++
				if i < len(args) {
					switch args[i] {
					case "symbol":
						sh.escMode = 1
					case "ascii":
						sh.escMode = 0
					case "off":
						sh.escMode = 2
					}
				}
			case "reset":
				sh.modeOpts = modeOptions{}
				sh.setMode(modeList)
				sh.nullValue = ""
				sh.headers = false
			case "widths":
				i++
				sh.widths = nil
				if i < len(args) {
					for _, x := range strings.Split(args[i], ",") {
						v, _ := strconv.Atoi(strings.TrimSpace(x))
						sh.widths = append(sh.widths, v)
					}
				}
			case "list":
				fmt.Fprintf(sh.out, "available modes: ascii box column count csv html insert json line list markdown off psql qbox quote split table tabs tcl\n")
			case "border", "align", "blob-quote", "charlimit", "linelimit", "limits", "multiinsert", "sw", "screenwidth", "tag", "textjsonb", "titlelimit":
				i++
			case "v", "verbose", "once":
			default:
				sh.modeError(args, i, "unknown option")
				return 1
			}
			i++
			continue
		}
		m := strings.ToLower(a)
		found := -1
		for k, nm := range modeNames {
			if nm == m {
				found = k
			}
		}
		switch m {
		case "lines":
			found = modeLine
		case "qbox":
			found = modeBox
			sh.modeOpts.quote = true
		case "psql", "split":
			found = modeColumn
		}
		if found < 0 {
			sh.modeError(args, i, "unknown mode")
			return 1
		}
		sh.setMode(found)
		if found == modeColumn || found == modeTable || found == modeBox || found == modeMarkdown {
			if !sh.headerSet {
				sh.headers = true
			}
		}
		if found == modeInsert {
			if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
				i++
				sh.modeTable = args[i]
			} else {
				sh.modeTable = ""
			}
		}
		i++
	}
	return 0
}

func (sh *Shell) modeError(args []string, i int, msg string) {
	line := ".mode " + strings.Join(args, " ")
	off := len(".mode ")
	for k := 0; k < i; k++ {
		off += len(args[k]) + 1
	}
	ln := sh.curLine
	if ln == 0 {
		ln = 1
	}
	sh.errf("line %d: %s\n", ln, line)
	sh.errf("line %d: %s^--- %s\n", ln, strings.Repeat(" ", off), msg)
	sh.errf("line %d: Use \".help .mode\" for more info\n", ln)
}

func (sh *Shell) showMode() {
	m := modeNames[sh.mode]
	s := ".mode " + m
	if sh.mode == modeInsert {
		s += fmt.Sprintf(" --tablename \"%s\"", sh.modeTable)
	}
	if sh.mode == modeTcl {
		s += " --blob-quote tcl"
	}
	switch sh.mode {
	case modeColumn, modeTable, modeBox, modeMarkdown:
		if !sh.headers {
			s += " --titles off"
		}
	case modeJson, modeLine, modeHtml, modeOff, modeCount:
	default:
		if sh.headers {
			s += " --titles on"
		}
	}
	if sh.modeOpts.wrap > 0 {
		s += fmt.Sprintf(" --wrap %d", sh.modeOpts.wrap)
		if sh.modeOpts.wordwrap {
			s += " --ww"
		}
	}
	fmt.Fprintf(sh.out, "%s\n", s)
}

func (sh *Shell) doOutput(args []string, once bool) int {
	sh.out.Flush()
	if sh.outFile != nil {
		sh.outFile.Close()
		sh.outFile = nil
		sh.out = sh.stdout
		sh.outName = ""
	}
	var file string
	for _, a := range args {
		if strings.HasPrefix(a, "-") && a != "-" {
			continue
		}
		file = a
	}
	if file == "" || file == "stdout" || file == "-" {
		sh.out = sh.stdout
		return 0
	}
	if strings.HasPrefix(file, "|") {
		sh.out = sh.stdout
		return 0
	}
	f, err := os.Create(file)
	if err != nil {
		sh.errf("Error: cannot open \"%s\"\n", file)
		return 1
	}
	sh.outFile = f
	sh.outName = file
	sh.out = bufio.NewWriter(f)
	sh.onceActive = once
	return 0
}

func (sh *Shell) endOnce() {
	if sh.onceActive {
		sh.out.Flush()
		if sh.outFile != nil {
			sh.outFile.Close()
			sh.outFile = nil
		}
		sh.out = sh.stdout
		sh.outName = ""
		sh.onceActive = false
	}
}

func (sh *Shell) doParameter(args []string) int {
	c := sh.conn
	if len(args) == 0 {
		return 0
	}
	switch args[0] {
	case "init":
	case "clear", "unset":
		if args[0] == "unset" && len(args) > 1 {
			delete(c.params, args[1])
			for i, n := range c.paramOrder {
				if n == args[1] {
					c.paramOrder = append(c.paramOrder[:i], c.paramOrder[i+1:]...)
					break
				}
			}
			return 0
		}
		c.params = map[string]Value{}
		c.paramOrder = nil
	case "list":
		names := append([]string(nil), c.paramOrder...)
		sort.Strings(names)
		for _, n := range names {
			fmt.Fprintf(sh.out, "%s %s\n", n, sqlQuote(c.params[n]))
		}
	case "set":
		if len(args) < 3 {
			sh.errf("Usage: .parameter set NAME VALUE\n")
			return 1
		}
		name := args[1]
		valSQL := strings.Join(args[2:], " ")
		v := sh.evalParamValue(valSQL)
		if _, ok := c.params[name]; !ok {
			c.paramOrder = append(c.paramOrder, name)
		}
		c.params[name] = v
		c.totalChanges++
	}
	return 0
}

func (sh *Shell) evalParamValue(s string) Value {
	st, _, err := ParseStatement("SELECT "+s, 0)
	if err == nil && st != nil {
		p, err2 := sh.conn.Prepare(st)
		if err2 == nil {
			var res Value
			got := false
			if sh.conn.Execute(p, func(row []Value) bool {
				res = row[0]
				got = true
				return false
			}) == nil && got {
				return res
			}
		}
	}
	return TextValue(s)
}

func (sh *Shell) doLimit(args []string) {
	limits := []struct {
		name string
		val  int64
	}{
		{"length", 1000000000}, {"sql_length", 1000000000}, {"column", 2000}, {"expr_depth", 1000}, {"compound_select", 500}, {"vdbe_op", 250000000}, {"function_arg", 1000}, {"attached", 10}, {"like_pattern_length", 50000}, {"variable_number", 250000}, {"trigger_depth", 1000}, {"worker_threads", 0},
	}
	if len(args) == 0 {
		for _, l := range limits {
			fmt.Fprintf(sh.out, "%20s %d\n", l.name, l.val)
		}
		return
	}
	for _, l := range limits {
		if strings.EqualFold(l.name, args[0]) {
			fmt.Fprintf(sh.out, "%20s %d\n", l.name, l.val)
		}
	}
}

func (sh *Shell) doHelp(args []string) {
	if len(args) > 0 {
		pat := strings.TrimPrefix(args[0], ".")
		for _, l := range strings.Split(helpText, "\n") {
			if strings.HasPrefix(l, "."+pat) {
				fmt.Fprintf(sh.out, "%s\n", l)
			}
		}
		return
	}
	fmt.Fprint(sh.out, helpText)
}

const helpText = `.archive ...             Manage SQL archives
.auth ON|OFF             Show authorizer callbacks
.backup ?DB? FILE        Backup DB (default "main") to FILE
.bail on|off             Stop after hitting an error.  Default OFF
.cd DIRECTORY            Change the working directory to DIRECTORY
.changes on|off          Show number of rows changed by SQL
.check OPTIONS ...       Verify the results of a .testcase
.clone NEWDB             Clone data into NEWDB from the existing database
.connection [close] [#]  Open or close an auxiliary database connection
.crlf ?on|off?           Whether or not to use \r\n line endings
.databases               List names and files of attached databases
.dbconfig ?op? ?val?     List or change sqlite3_db_config() options
