package main

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

const dbMagic = "-- sqlite3clone database v1\n"

func (c *Conn) mainFileDisplay() string {
	if c.filename == "" || c.filename == ":memory:" {
		return ""
	}
	abs, err := filepath.Abs(c.filename)
	if err != nil {
		return c.filename
	}
	return abs
}

func (sh *Shell) openDB(file string, fromDot bool) {
	sh.filename = file
	if file == ":memory:" || file == "" {
		sh.conn = NewConn()
		sh.conn.filename = ""
		return
	}
	c, err := loadDatabase(file)
	if err != nil {
		c = NewConn()
		c.openErr = err.Error()
	}
	c.filename = file
	c.journalMode = "delete"
	sh.conn = c
}

func (sh *Shell) closeDB() {
	if sh.conn != nil {
		sh.conn.persistNow()
	}
}

func (c *Conn) persist() {
	c.needSave = true
}

func (c *Conn) persistNow() {
	if c.filename == "" || c.filename == ":memory:" || c.openErr != "" {
		return
	}
	if !c.needSave && !c.dirty {
		if _, err := os.Stat(c.filename); err == nil {
			return
		}
		// create empty file only if something was written
		if len(c.main.entries) == 0 && c.userVersion == 0 {
			return
		}
	}
	c.saveTo(c.filename)
	c.needSave = false
}

func (c *Conn) saveTo(file string) error {
	f, err := os.Create(file)
	if err != nil {
		return err
	}
	defer f.Close()
	w := bufio.NewWriter(f)
	w.WriteString(dbMagic)
	fmt.Fprintf(w, "PRAGMA user_version=%d;\n", c.userVersion)
	if c.appID != 0 {
		fmt.Fprintf(w, "PRAGMA application_id=%d;\n", c.appID)
	}
	s := c.main
	for _, e := range s.entries {
		switch o := e.obj.(type) {
		case *Table:
			if strings.EqualFold(o.Name, "sqlite_sequence") {
				w.WriteString("--@sequence\n")
				continue
			}
			w.WriteString(escapeStmt(o.SQL))
			w.WriteString(";\n")
		case *Index:
			if o.SQL == "" {
				continue
			}
			w.WriteString(escapeStmt(o.SQL))
			w.WriteString(";\n")
		case *View:
			w.WriteString(escapeStmt(o.SQL))
			w.WriteString(";\n")
		case *Trigger:
			w.WriteString(escapeStmt(o.SQL))
			w.WriteString(";\n")
		}
	}
	w.WriteString("--@data\n")
	for _, e := range s.entries {
		t, ok := e.obj.(*Table)
		if !ok {
			continue
		}
		for _, r := range t.rows {
			fmt.Fprintf(w, "--@row %s %d", quoteIdent(t.Name), r.Rowid)
			for i, v := range r.Vals {
				if i == t.IPK {
					v = NullValue
				}
				w.WriteString(" ")
				w.WriteString(encodeValue(v))
			}
			w.WriteString("\n")
		}
	}
	return w.Flush()
}

func escapeStmt(s string) string {
	return strings.ReplaceAll(s, "\n", "\n--@cont ")
}

func encodeValue(v Value) string {
	switch v.K {
	case KNull:
		return "N"
	case KInt:
		return fmt.Sprintf("I%d", v.I)
	case KReal:
		return "R" + fmt.Sprintf("%x", mathFloat64bits(v.F))
	case KText:
		return "T" + hexEncode(v.S)
	case KBlob:
		return "B" + hexEncode(v.S)
	}
	return "N"
}

func loadDatabase(file string) (*Conn, error) {
	c := NewConn()
	data, err := os.ReadFile(file)
	if err != nil {
		if os.IsNotExist(err) {
			return c, nil
		}
		return nil, err
	}
	if len(data) == 0 {
		return c, nil
	}
	if !strings.HasPrefix(string(data), dbMagic) {
		return nil, errors.New("file is not a database")
	}
	lines := strings.Split(string(data[len(dbMagic):]), "\n")
	var stmts []string
	var cur strings.Builder
	dataStart := len(lines)
	for i, l := range lines {
		if l == "--@data" {
			dataStart = i + 1
			break
		}
		if strings.HasPrefix(l, "--@cont ") {
			cur.WriteString("\n")
			cur.WriteString(l[len("--@cont "):])
			continue
		}
		if cur.Len() > 0 {
			stmts = append(stmts, cur.String())
			cur.Reset()
		}
		if l == "--@sequence" {
			stmts = append(stmts, "--@sequence")
			continue
		}
		cur.WriteString(l)
	}
	if cur.Len() > 0 {
		stmts = append(stmts, cur.String())
	}
	for _, s := range stmts {
		if s == "--@sequence" {
			sch := c.main
			sq := &Table{Name: "sqlite_sequence", Schema: sch, IPK: -1, SQL: "CREATE TABLE sqlite_sequence(name,seq)"}
			sq.Cols = []*Column{{Name: "name", Aff: AffNone}, {Name: "seq", Aff: AffNone}}
			sq.rebuildColMap()
			sq.RootPage = sch.allocPage()
			sch.Tables["sqlite_sequence"] = sq
			sch.addEntry("table", "sqlite_sequence", "sqlite_sequence", sq)
			continue
		}
		s = strings.TrimSuffix(strings.TrimSpace(s), ";")
		if s == "" {
			continue
		}
		st, _, perr := ParseStatement(s, 0)
		if perr != nil || st == nil {
			continue
		}
		if ct, ok := st.(*CreateTableStmt); ok && ct.AutoInc() {
			// sequence table created by registerTable; avoid duplicates
		}
		p, err := c.Prepare(st)
		if err != nil {
			continue
		}
		c.Execute(p, func([]Value) bool { return true })
	}
	for _, l := range lines[dataStart:] {
		if !strings.HasPrefix(l, "--@row ") {
			continue
		}
		parts := strings.Split(l[len("--@row "):], " ")
		if len(parts) < 2 {
			continue
		}
		name := parts[0]
		if strings.HasPrefix(name, "\"") {
			// quoted name may contain spaces; rejoin
			j := 0
			for j < len(parts) && !strings.HasSuffix(parts[j], "\"") {
				j++
			}
			name = strings.Join(parts[:j+1], " ")
			parts = append([]string{name}, parts[j+1:]...)
			name = strings.ReplaceAll(name[1:len(name)-1], "\"\"", "\"")
		}
		t := c.main.Tables[strings.ToLower(name)]
		if t == nil {
			continue
		}
		var rowid int64
		fmt.Sscanf(parts[1], "%d", &rowid)
		vals := make([]Value, len(t.Cols))
		for i := 0; i < len(t.Cols) && i+2 < len(parts); i++ {
			vals[i] = decodeValue(parts[i+2])
		}
		c.rawInsert(t, &Row{Rowid: rowid, Vals: vals})
	}
	c.undo = nil
	c.dirty = false
	c.needSave = false
	return c, nil
}

func decodeValue(s string) Value {
	if s == "" {
		return NullValue
	}
	switch s[0] {
	case 'I':
		var i int64
		fmt.Sscanf(s[1:], "%d", &i)
		return IntValue(i)
	case 'R':
		var u uint64
		fmt.Sscanf(s[1:], "%x", &u)
		return RealValue(mathFloat64frombits(u))
	case 'T':
		return TextValue(hexDecode(s[1:]))
	case 'B':
		return BlobValue(hexDecode(s[1:]))
	}
	return NullValue
}

func hexDecode(s string) string {
	b := make([]byte, len(s)/2)
	for i := range b {
		b[i] = byte(hexVal(s[2*i])<<4 | hexVal(s[2*i+1]))
	}
	return string(b)
}

func (s *CreateTableStmt) AutoInc() bool {
	for _, c := range s.Cols {
		if c.AutoInc {
