func (c *Conn) persistNow() {
	if c.filename == "" || c.filename == ":memory:" || c.openErr != "" {
		return
	}
	if !c.needSave && !c.dirty {
		if _, err := os.Stat(c.filename); err == nil {
			return
		}
		// create empty file only if something was written
		if len(c.main.entries) == 0 && c.userVersion == 0 {
			return
		}
	}
	c.saveTo(c.filename)
	c.needSave = false
}

func (c *Conn) saveTo(file string) error {
	f, err := os.Create(file)
	if err != nil {
		return err
	}
	defer f.Close()
	w := bufio.NewWriter(f)
	w.WriteString(dbMagic)
	fmt.Fprintf(w, "PRAGMA user_version=%d;\n", c.userVersion)
	if c.appID != 0 {
		fmt.Fprintf(w, "PRAGMA application_id=%d;\n", c.appID)
	}
	s := c.main
	for _, e := range s.entries {
		switch o := e.obj.(type) {
		case *Table:
			if strings.EqualFold(o.Name, "sqlite_sequence") {
				w.WriteString("--@sequence\n")
				continue
			}
			w.WriteString(escapeStmt(o.SQL))
			w.WriteString(";\n")
		case *Index:
			if o.SQL == "" {
				continue
			}
			w.WriteString(escapeStmt(o.SQL))
			w.WriteString(";\n")
		case *View:
			w.WriteString(escapeStmt(o.SQL))
			w.WriteString(";\n")
		case *Trigger:
			w.WriteString(escapeStmt(o.SQL))
			w.WriteString(";\n")
		}
	}
	w.WriteString("--@data\n")
	for _, e := range s.entries {
		t, ok := e.obj.(*Table)
		if !ok {
			continue
		}
		for _, r := range t.rows {
			fmt.Fprintf(w, "--@row %s %d", quoteIdent(t.Name), r.Rowid)
			for i, v := range r.Vals {
				if i == t.IPK {
					v = NullValue
				}
				w.WriteString(" ")
				w.WriteString(encodeValue(v))
			}
			w.WriteString("\n")
		}
	}
	return w.Flush()
}

