func encodeValue(v Value) string {
	switch v.K {
	case KNull:
		return "N"
	case KInt:
		return fmt.Sprintf("I%d", v.I)
	case KReal:
		return "R" + fmt.Sprintf("%x", mathFloat64bits(v.F))
	case KText:
		return "T" + hexEncode(v.S)
	case KBlob:
		return "B" + hexEncode(v.S)
