package main

import (
	"fmt"
	"strings"
)

type eqpTree struct {
	detail string
	kids   []*eqpTree
}

func (cp *compiler) prepExplain(s *ExplainStmt) *Prepared {
	c := cp.conn
	if s.QueryPlan {
		cp.eqpOn = true
		cp.eqpSubN = 0
		var tree []*eqpTree
		switch st := s.Stmt.(type) {
		case *SelectStmt:
			cs := cp.compileSelect(st.Sel, nil, nil)
			tree = cs.eqp
		default:
			p := cp.prepareStmt(s.Stmt, nil)
			_ = p
			tree = cp.lastEqp
		}
		cp.eqpOn = false
		var rows [][]Value
		id := 0
		var walk func(nodes []*eqpTree, parent int)
		walk = func(nodes []*eqpTree, parent int) {
			for _, n := range nodes {
				id++
				my := id
				rows = append(rows, []Value{IntValue(int64(my)), IntValue(int64(parent)), IntValue(0), TextValue(n.detail)})
				walk(n.kids, my)
			}
		}
		walk(tree, 0)
		return &Prepared{isQuery: true, colNames: []string{"id", "parent", "notused", "detail"}, isExplain: 2, run: func(pc *Ctx, emit func([]Value) bool) {
			for _, r := range rows {
				if !emit(r) {
					return
				}
			}
		}}
	}
	// plain EXPLAIN: produce a minimal bytecode-like listing
	p := cp.prepareStmt(s.Stmt, nil)
	_ = p
	rows := [][]Value{
		{IntValue(0), TextValue("Init"), IntValue(0), IntValue(1), IntValue(0), NullValue, IntValue(0), NullValue},
		{IntValue(1), TextValue("Halt"), IntValue(0), IntValue(0), IntValue(0), NullValue, IntValue(0), NullValue},
	}
	_ = c
	return &Prepared{isQuery: true, colNames: []string{"addr", "opcode", "p1", "p2", "p3", "p4", "p5", "comment"}, isExplain: 1, run: func(pc *Ctx, emit func([]Value) bool) {
		for _, r := range rows {
			if !emit(r) {
				return
			}
		}
	}}
}

func (sh *Shell) printEQPTree(rows [][]Value) {
	type node struct {
		id, parent int
		detail     string
	}
	var nodes []node
	for _, r := range rows {
		nodes = append(nodes, node{int(r[0].I), int(r[1].I), r[3].Text()})
	}
	fmt.Fprintf(sh.out, "QUERY PLAN\n")
	var rec func(parent int, prefix string)
	rec = func(parent int, prefix string) {
		var kids []node
		for _, n := range nodes {
			if n.parent == parent {
				kids = append(kids, n)
			}
		}
		for i, k := range kids {
			last := i == len(kids)-1
			if last {
				fmt.Fprintf(sh.out, "%s`--%s\n", prefix, k.detail)
				rec(k.id, prefix+"   ")
			} else {
				fmt.Fprintf(sh.out, "%s|--%s\n", prefix, k.detail)
				rec(k.id, prefix+"|  ")
			}
		}
	}
	rec(0, "")
}

func (sh *Shell) runEQP(p *Prepared, loc string) bool {
	var rows [][]Value
	err := sh.conn.Execute(p, func(r []Value) bool {
		rows = append(rows, r)
		return true
	})
	if err != nil {
		sh.errf("Error %s: %s\n", loc, err.Error())
		return false
	}
	if sh.mode == modeList || sh.mode == modeColumn || sh.mode == modeBox || sh.mode == modeTable || sh.mode == modeMarkdown || true {
		sh.printEQPTree(rows)
	}
	return true
}

func (sh *Shell) showEQP(stmt Stmt) {
	ex := &ExplainStmt{QueryPlan: true, Stmt: stmt}
	p, err := sh.conn.Prepare(ex)
	if err != nil {
		return
	}
	var rows [][]Value
	sh.conn.Execute(p, func(r []Value) bool {
		rows = append(rows, r)
		return true
	})
	sh.printEQPTree(rows)
}

// describe access path for EQP
func eqpDetail(s *fromSrc) string {
	name := s.info.name
	if s.kind == srcTable && s.table != nil {
		if s.item != nil && s.item.Alias != "" {
			name = s.item.Alias
		} else {
			name = s.table.Name
		}
	}
	ap := s.path
	suffix := ""
	if s.join&JLeft != 0 {
		suffix = " LEFT-JOIN"
	}
	if ap == nil {
		return "SCAN " + name + suffix
	}
	switch ap.kind {
	case apRowidEq, apRowidIn:
