package main

import (
	"fmt"
	"strings"
)

type eqpTree struct {
	detail string
	kids   []*eqpTree
}

func (cp *compiler) prepExplain(s *ExplainStmt) *Prepared {
	c := cp.conn
	if s.QueryPlan {
		cp.eqpOn = true
		cp.eqpSubN = 0
		var tree []*eqpTree
		switch st := s.Stmt.(type) {
		case *SelectStmt:
			cs := cp.compileSelect(st.Sel, nil, nil)
			tree = cs.eqp
		default:
			p := cp.prepareStmt(s.Stmt, nil)
			_ = p
			tree = cp.lastEqp
		}
		cp.eqpOn = false
		var rows [][]Value
		id := 0
		var walk func(nodes []*eqpTree, parent int)
		walk = func(nodes []*eqpTree, parent int) {
			for _, n := range nodes {
				id++
				my := id
				rows = append(rows, []Value{IntValue(int64(my)), IntValue(int64(parent)), IntValue(0), TextValue(n.detail)})
				walk(n.kids, my)
			}
		}
		walk(tree, 0)
		return &Prepared{isQuery: true, colNames: []string{"id", "parent", "notused", "detail"}, isExplain: 2, run: func(pc *Ctx, emit func([]Value) bool) {
			for _, r := range rows {
				if !emit(r) {
					return
				}
			}
		}}
	}
	// plain EXPLAIN: produce a minimal bytecode-like listing
	p := cp.prepareStmt(s.Stmt, nil)
	_ = p
	rows := [][]Value{
		{IntValue(0), TextValue("Init"), IntValue(0), IntValue(1), IntValue(0), NullValue, IntValue(0), NullValue},
		{IntValue(1), TextValue("Halt"), IntValue(0), IntValue(0), IntValue(0), NullValue, IntValue(0), NullValue},
	}
	_ = c
	return &Prepared{isQuery: true, colNames: []string{"addr", "opcode", "p1", "p2", "p3", "p4", "p5", "comment"}, isExplain: 1, run: func(pc *Ctx, emit func([]Value) bool) {
		for _, r := range rows {
			if !emit(r) {
				return
			}
		}
	}}
