func (sh *Shell) printEQPTree(rows [][]Value) {
	type node struct {
		id, parent int
		detail     string
	}
	var nodes []node
	for _, r := range rows {
		nodes = append(nodes, node{int(r[0].I), int(r[1].I), r[3].Text()})
	}
	fmt.Fprintf(sh.out, "QUERY PLAN\n")
	var rec func(parent int, prefix string)
	rec = func(parent int, prefix string) {
		var kids []node
		for _, n := range nodes {
			if n.parent == parent {
				kids = append(kids, n)
			}
		}
		for i, k := range kids {
			last := i == len(kids)-1
			if last {
				fmt.Fprintf(sh.out, "%s`--%s\n", prefix, k.detail)
				rec(k.id, prefix+"   ")
			} else {
				fmt.Fprintf(sh.out, "%s|--%s\n", prefix, k.detail)
				rec(k.id, prefix+"|  ")
			}
		}
	}
	rec(0, "")
}

func (sh *Shell) runEQP(p *Prepared, loc string) bool {
	var rows [][]Value
	err := sh.conn.Execute(p, func(r []Value) bool {
		rows = append(rows, r)
		return true
	})
	if err != nil {
		sh.errf("Error %s: %s\n", loc, err.Error())
		return false
	}
	if sh.mode == modeList || sh.mode == modeColumn || sh.mode == modeBox || sh.mode == modeTable || sh.mode == modeMarkdown || true {
