{"command":"cd /workspace/src && cat > btree.go <<'EOF'
package main

// Generic in-memory B-tree.

const btDegree = 32
const btMaxItems = 2*btDegree - 1
const btMinItems = btDegree - 1

type btNode[T any] struct {
	items    []T
	children []*btNode[T]
}

type BTree[T any] struct {
	root   *btNode[T]
	length int
	cmp    func(a, b T) int
}

func NewBTree[T any](cmp func(a, b T) int) *BTree[T] {
	return &BTree[T]{cmp: cmp}
}

func (t *BTree[T]) Len() int { return t.length }

// find returns index of first item >= x in node, and whether equal
func (t *BTree[T]) find(n *btNode[T], x T) (int, bool) {
	lo, hi := 0, len(n.items)
	for lo < hi {
		m := (lo + hi) / 2
		if t.cmp(n.items[m], x) < 0 {
			lo = m + 1
		} else {
			hi = m
		}
	}
	if lo < len(n.items) && t.cmp(n.items[lo], x) == 0 {
		return lo, true
	}
	return lo, false
}

func (t *BTree[T]) Get(x T) (T, bool) {
	n := t.root
	for n != nil {
		i, found := t.find(n, x)
		if found {
			return n.items[i], true
		}
		if len(n.children) == 0 {
			break
		}
		n = n.children[i]
	}
	var zero T
	return zero, false
}

func (n *btNode[T]) split(i int) (T, *btNode[T]) {
	item := n.items[i]
	next := &btNode[T]{}
	next.items = append(next.items, n.items[i+1:]...)
	var zero T
	for k := i; k < len(n.items); k++ {
		n.items[k] = zero
	}
	n.items = n.items[:i]
	if len(n.children) > 0 {
		next.children = append(next.children, n.children[i+1:]...)
		for k := i + 1; k < len(n.children); k++ {
			n.children[k] = nil
		}
		n.children = n.children[:i+1]
	}
	return item, next
}

func insertAt[T any](s []T, i int, x T) []T {
	var zero T
	s = append(s, zero)
	copy(s[i+1:], s[i:])
	s[i] = x
	return s
}

func removeAt[T any](s []T, i int) ([]T, T) {
	x := s[i]
	copy(s[i:], s[i+1:])
	var zero T
	s[len(s)-1] = zero
	return s[:len(s)-1], x
}

// ReplaceOrInsert inserts x; if an equal item exists, replaces it and returns (old, true).
func (t *BTree[T]) ReplaceOrInsert(x T) (T, bool) {
	var zero T
	if t.root == nil {
		t.root = &btNode[T]{items: []T{x}}
		t.length++
		return zero, false
	}
	if len(t.root.items) >= btMaxItems {
		item, second := t.root.split(btMaxItems / 2)
		old := t.root
		t.root = &btNode[T]{items: []T{item}, children: []*btNode[T]{old, second}}
	}
	old, found := t.insert(t.root, x)
	if !found {
		t.length++
	}
	return old, found
}

func (t *BTree[T]) maybeSplitChild(n *btNode[T], i int) bool {
	if len(n.children[i].items) < btMaxItems {
		return false
	}
	first := n.children[i]
	item, second := first.split(btMaxItems / 2)
	n.items = insertAt(n.items, i, item)
	n.children = insertAt(n.children, i+1, second)
	return true
}

func (t *BTree[T]) insert(n *btNode[T], x T) (T, bool) {
	var zero T
	for {
		i, found := t.find(n, x)
		if found {
			old := n.items[i]
			n.items[i] = x
			return old, true
		}
		if len(n.children) == 0 {
			n.items = insertAt(n.items, i, x)
			return zero, false
		}
		if t.maybeSplitChild(n, i) {
			c := t.cmp(x, n.items[i])
			if c == 0 {
				old := n.items[i]
				n.items[i] = x
				return old, true
			}
			if c > 0 {
				i++
			}
		}
		n = n.children[i]
	}
}

const (
	rmItem = iota
	rmMin
	rmMax
)

func (t *BTree[T]) Delete(x T) (T, bool) {
	var zero T
	if t.root == nil || len(t.root.items) == 0 {
		return zero, false
	}
	out, ok := t.remove(t.root, x, rmItem)
	if len(t.root.items) == 0 && len(t.root.children) > 0 {
		t.root = t.root.children[0]
	}
	if ok {
		t.length--
	}
	return out, ok
}

func (t *BTree[T]) remove(n *btNode[T], x T, typ int) (T, bool) {
	var zero T
	var i int
	var found bool
	switch typ {
	case rmMax:
		if len(n.children) == 0 {
			var it T
			n.items, it = removeAt(n.items, len(n.items)-1)
			return it, true
		}
		i = len(n.items)
	case rmMin:
		if len(n.children) == 0 {
			var it T
			n.items, it = removeAt(n.items, 0)
			return it, true
		}
		i = 0
	case rmItem:
		i, found = t.find(n, x)
		if len(n.children) == 0 {
			if found {
				var it T
				n.items, it = removeAt(n.items, i)
				return it, true
			}
			return zero, false
		}
	}
	if len(n.children[i].items) <= btMinItems {
		return t.growChildAndRemove(n, i, x, typ)
	}
	child := n.children[i]
	if found {
		out := n.items[i]
		var pred T
		pred, _ = t.remove(child, zero, rmMax)
		n.items[i] = pred
		return out, true
	}
	return t.remove(child, x, typ)
}

func (t *BTree[T]) growChildAndRemove(n *btNode[T], i int, x T, typ int) (T, bool) {
	if i > 0 && len(n.children[i-1].items) > btMinItems {
		child := n.children[i]
		steal := n.children[i-1]
		var stolen T
		steal.items, stolen = removeAt(steal.items, len(steal.items)-1)
		child.items = insertAt(child.items, 0, n.items[i-1])
		n.items[i-1] = stolen
		if len(steal.children) > 0 {
			var sc *btNode[T]
			steal.children, sc = removeAt(steal.children, len(steal.children)-1)
			child.children = insertAt(child.children, 0, sc)
		}
	} else if i < len(n.items) && len(n.children[i+1].items) > btMinItems {
		child := n.children[i]
		steal := n.children[i+1]
		var stolen T
		steal.items, stolen = removeAt(steal.items, 0)
		child.items = append(child.items, n.items[i])
		n.items[i] = stolen
		if len(steal.children) > 0 {
			var sc *btNode[T]
			steal.children, sc = removeAt(steal.children, 0)
			child.children = append(child.children, sc)
		}
	} else {
		if i >= len(n.items) {
			i--
		}
		child := n.children[i]
		var mergeItem T
		n.items, mergeItem = removeAt(n.items, i)
		var mergeChild *btNode[T]
		n.children, mergeChild = removeAt(n.children, i+1)
		child.items = append(child.items, mergeItem)
		child.items = append(child.items, mergeChild.items...)
		child.children = append(child.children, mergeChild.children...)
	}
	return t.remove(n, x, typ)
}

// Ascend calls fn for each item in order until fn returns false.
func (t *BTree[T]) Ascend(fn func(T) bool) bool {
	if t.root == nil {
		return true
	}
	return t.root.ascend(fn)
}

func (n *btNode[T]) ascend(fn func(T) bool) bool {
	for i, it := range n.items {
		if len(n.children) > 0 {
			if !n.children[i].ascend(fn) {
				return false
