}

func (ix *Index) tree() *BTree[idxEntry] {
	if ix.etree == nil {
		ix.etree = NewBTree[idxEntry](func(a, b idxEntry) int { return ix.cmpEntry(a, b.key, b.rowid) })
	}
	return ix.etree
}

func (ix *Index) insertEntry(key []Value, rowid int64) {
	ix.tree().ReplaceOrInsert(idxEntry{key: key, rowid: rowid})
}

func (ix *Index) deleteEntry(key []Value, rowid int64) {
	if _, ok := ix.tree().Delete(idxEntry{key: key, rowid: rowid}); ok {
		return
	}
	// fallback: linear search by rowid
	var found *idxEntry
	ix.tree().Ascend(func(e idxEntry) bool {
		if e.rowid == rowid {
			ee := e
			found = &ee
			return false
		}
		return true
	})
	if found != nil {
		ix.tree().Delete(*found)
	}
}

func (ix *Index) prefixCmp(e []Value, key []Value) int {
	for j := 0; j < len(key); j++ {
		c := compareValues(e[j], key[j], ix.Cols[j].Coll)
		if c != 0 {
			if ix.Cols[j].Desc {
				return -c
			}
			return c
		}
	}
	return 0
}

// scanEq iterates entries whose leading columns equal key
func (ix *Index) scanEq(key []Value, fn func(e idxEntry) bool) bool {
	return ix.tree().AscendFrom(func(e idxEntry) bool { return ix.prefixCmp(e.key, key) >= 0 }, func(e idxEntry) bool {
		if ix.prefixCmp(e.key, key) != 0 {
			return false
		}
		return fn(e)
	})
}

func (ix *Index) scanAll(fn func(e idxEntry) bool) bool {
	return ix.tree().Ascend(fn)
}

// scanFirstCol iterates entries in index order over a range of the first column.
// lo/hi are in index order terms (for DESC indexes, caller swaps).
func (ix *Index) scanFirstCol(lo *Value, loIncl bool, hi *Value, hiIncl bool, fn func(e idxEntry) bool) bool {
	coll := ix.Cols[0].Coll
	desc := ix.Cols[0].Desc
	c1 := func(a, b Value) int {
		c := compareValues(a, b, coll)
		if desc {
			return -c
		}
		return c
	}
	ge := func(e idxEntry) bool { return true }
	if lo != nil {
		lv := *lo
		if loIncl {
			ge = func(e idxEntry) bool { return c1(e.key[0], lv) >= 0 }
		} else {
			ge = func(e idxEntry) bool { return c1(e.key[0], lv) > 0 }
		}
	}
	return ix.tree().AscendFrom(ge, func(e idxEntry) bool {
		if hi != nil {
			c := c1(e.key[0], *hi)
			if c > 0 || (c == 0 && !hiIncl) {
				return false
			}
		}
		return fn(e)
	})
}

func (ix *Index) count() int { return ix.tree().Len() }

func (ix *Index) clearEntries() { ix.etree = nil }

func (ix *Index) snapshot() []idxEntry { return ix.tree().Items() }

func (ix *Index) restore(es []idxEntry) {
	ix.etree = nil
	for _, e := range es {
		ix.tree().ReplaceOrInsert(e)
	}
}

