func (cp *compiler) compileViewInsert(s *InsertStmt, v *View, t *Table, parent *scope) *Prepared {
	c := cp.conn
	var colMap []int
	if s.Cols != nil {
		for _, cn := range s.Cols {
			ci := t.colIndex(cn)
			if ci < 0 {
				throw("table %s has no column named %s", t.Name, cn)
			}
			colMap = append(colMap, ci)
		}
	} else {
		for i := range t.Cols {
			colMap = append(colMap, i)
		}
	}
	var src *compiledSelect
	if !s.Default {
		src = cp.compileSelect(s.Sel, parent, nil)
		if len(src.colNames) != len(colMap) {
			if s.Cols != nil {
				throw("%d values for %d columns", len(src.colNames), len(colMap))
			}
			throw("table %s has %d columns but %d values were supplied", t.Name, len(colMap), len(src.colNames))
		}
	}
	p := &Prepared{isDML: true}
	p.run = func(pc *Ctx, emit func([]Value) bool) {
		var rows [][]Value
		if s.Default {
			rows = [][]Value{{}}
		} else {
			src.run(pc, func(r []Value) bool {
				rows = append(rows, append([]Value(nil), r...))
				return true
			})
