package main

import (
	"encoding/binary"
	"math"
	"math/big"
	"os"
	"strconv"
	"strings"
)

// ---- Keccak / SHA3 ----

var keccakRC = [24]uint64{
	0x0000000000000001, 0x0000000000008082, 0x800000000000808A, 0x8000000080008000,
	0x000000000000808B, 0x0000000080000001, 0x8000000080008081, 0x8000000000008009,
	0x000000000000008A, 0x0000000000000088, 0x0000000080008009, 0x000000008000000A,
	0x000000008000808B, 0x800000000000008B, 0x8000000000008089, 0x8000000000008003,
	0x8000000000008002, 0x8000000000000080, 0x000000000000800A, 0x800000008000000A,
	0x8000000080008081, 0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
}

var keccakRot = [25]uint{0, 1, 62, 28, 27, 36, 44, 6, 55, 20, 3, 10, 43, 25, 39, 41, 45, 15, 21, 8, 18, 2, 61, 56, 14}

func keccakF(a *[25]uint64) {
	for round := 0; round < 24; round++ {
		var c [5]uint64
		for x := 0; x < 5; x++ {
			c[x] = a[x] ^ a[x+5] ^ a[x+10] ^ a[x+15] ^ a[x+20]
		}
		for x := 0; x < 5; x++ {
			d := c[(x+4)%5] ^ (c[(x+1)%5]<<1 | c[(x+1)%5]>>63)
			for y := 0; y < 25; y += 5 {
				a[y+x] ^= d
			}
		}
		var b [25]uint64
		for x := 0; x < 5; x++ {
			for y := 0; y < 5; y++ {
				r := keccakRot[x+5*y]
				v := a[x+5*y]
				if r != 0 {
					v = v<<r | v>>(64-r)
				}
				b[y+5*((2*x+3*y)%5)] = v
			}
		}
		for x := 0; x < 5; x++ {
			for y := 0; y < 25; y += 5 {
				a[y+x] = b[y+x] ^ (^b[y+(x+1)%5] & b[y+(x+2)%5])
			}
		}
		a[0] ^= keccakRC[round]
	}
}

func sha3Sum(data []byte, bits int) []byte {
	rate := 200 - 2*(bits/8)
	var st [25]uint64
	buf := make([]byte, 0, len(data)+rate)
	buf = append(buf, data...)
	// padding
	buf = append(buf, 0x06)
	for len(buf)%rate != 0 {
		buf = append(buf, 0)
	}
	buf[len(buf)-1] |= 0x80
	for off := 0; off < len(buf); off += rate {
		for i := 0; i < rate/8; i++ {
			st[i] ^= binary.LittleEndian.Uint64(buf[off+8*i:])
		}
		keccakF(&st)
	}
	out := make([]byte, 200)
	for i := 0; i < 25; i++ {
		binary.LittleEndian.PutUint64(out[8*i:], st[i])
	}
	return out[:bits/8]
}

func base64Encode(in []byte) string {
	const al = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	var b strings.Builder
	nCol := 0
	i := 0
	n := len(in)
	for n-i >= 3 {
		b.WriteByte(al[in[i]>>2])
		b.WriteByte(al[((in[i]<<4)|(in[i+1]>>4))&0x3f])
		b.WriteByte(al[((in[i+1]&0xf)<<2)|(in[i+2]>>6)])
		b.WriteByte(al[in[i+2]&0x3f])
		i += 3
		nCol += 4
		if nCol >= 72 || n-i <= 0 {
			b.WriteByte('\n')
			nCol = 0
		}
	}
	if n-i > 0 {
		rem := n - i
		qv := uint32(in[i]) << 16
		if rem > 1 {
			qv |= uint32(in[i+1]) << 8
		}
		chars := []byte{al[(qv>>18)&0x3f], al[(qv>>12)&0x3f], '=', '='}
		if rem > 1 {
			chars[2] = al[(qv>>6)&0x3f]
		}
		b.Write(chars)
		b.WriteByte('\n')
	}
	return b.String()
}

func base64Decode(s string) []byte {
	val := func(c byte) int {
		switch {
		case c >= 'A' && c <= 'Z':
			return int(c - 'A')
		case c >= 'a' && c <= 'z':
			return int(c-'a') + 26
		case c >= '0' && c <= '9':
			return int(c-'0') + 52
		case c == '+':
			return 62
		case c == '/':
			return 63
		}
		return -1
	}
	var out []byte
	var acc uint32
	nb := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '=' {
			break
		}
		v := val(c)
		if v < 0 {
			if isSpaceByte(c) {
				continue
			}
			break
		}
		acc = acc<<6 | uint32(v)
		nb++
		if nb == 4 {
			out = append(out, byte(acc>>16), byte(acc>>8), byte(acc))
			acc = 0
			nb = 0
		}
	}
	switch nb {
	case 2:
		out = append(out, byte(acc>>4))
	case 3:
		out = append(out, byte(acc>>10), byte(acc>>2))
	}
	return out
}

func init() {
	regFunc("sha3", 1, 2, func(c *Ctx, a []Value) Value {
		if a[0].K == KNull {
			return NullValue
		}
		bits := 256
		if len(a) > 1 {
			bits = int(a[1].Int())
			if bits != 224 && bits != 256 && bits != 384 && bits != 512 {
				throw("SHA3 size should be one of: 224 256 384 512")
			}
		}
		return BlobValue(string(sha3Sum([]byte(a[0].Text()), bits)))
	})
	regFunc("base64", 1, 1, func(c *Ctx, a []Value) Value {
		v := a[0]
		switch v.K {
		case KNull:
			return NullValue
		case KBlob:
			return TextValue(base64Encode([]byte(v.S)))
		case KText:
			return BlobValue(string(base64Decode(v.S)))
		}
		throw("base64 accepts only blob or text")
		return NullValue
	})
	regFunc("ieee754", 1, 2, func(c *Ctx, a []Value) Value {
		if len(a) == 2 {
			m := a[0].Int()
			e := a[1].Int()
			if m == 0 {
				return RealValue(0)
			}
			return RealValue(math.Ldexp(float64(m), int(e)))
		}
		v := a[0]
		if v.K == KBlob && len(v.S) == 8 {
			return RealValue(math.Float64frombits(binary.BigEndian.Uint64([]byte(v.S))))
		}
		f := v.Float()
		if f == 0 {
			return TextValue("ieee754(0,0)")
		}
		m, e := ieeeParts(f)
		return TextValue("ieee754(" + strconv.FormatInt(m, 10) + "," + strconv.Itoa(e) + ")")
	})
	regFunc("ieee754_mantissa", 1, 1, func(c *Ctx, a []Value) Value {
		m, _ := ieeeParts(a[0].Float())
		return IntValue(m)
	})
	regFunc("ieee754_exponent", 1, 1, func(c *Ctx, a []Value) Value {
		_, e := ieeeParts(a[0].Float())
		return IntValue(int64(e))
	})
	regFunc("ieee754_to_blob", 1, 1, func(c *Ctx, a []Value) Value {
		b := make([]byte, 8)
		binary.BigEndian.PutUint64(b, math.Float64bits(a[0].Float()))
		return BlobValue(string(b))
	})
	regFunc("ieee754_from_blob", 1, 1, func(c *Ctx, a []Value) Value {
		if a[0].K != KBlob || len(a[0].S) != 8 {
			return NullValue
		}
		return RealValue(math.Float64frombits(binary.BigEndian.Uint64([]byte(a[0].S))))
	})
	regFunc("readfile", 1, 1, func(c *Ctx, a []Value) Value {
		data, err := os.ReadFile(a[0].Text())
		if err != nil {
			return NullValue
		}
		return BlobValue(string(data))
	})
