var keccakRot = [25]uint{0, 1, 62, 28, 27, 36, 44, 6, 55, 20, 3, 10, 43, 25, 39, 41, 45, 15, 21, 8, 18, 2, 61, 56, 14}

func keccakF(a *[25]uint64) {
	for round := 0; round < 24; round++ {
		var c [5]uint64
		for x := 0; x < 5; x++ {
			c[x] = a[x] ^ a[x+5] ^ a[x+10] ^ a[x+15] ^ a[x+20]
		}
		for x := 0; x < 5; x++ {
			d := c[(x+4)%5] ^ (c[(x+1)%5]<<1 | c[(x+1)%5]>>63)
			for y := 0; y < 25; y += 5 {
				a[y+x] ^= d
			}
		}
		var b [25]uint64
		for x := 0; x < 5; x++ {
			for y := 0; y < 5; y++ {
				r := keccakRot[x+5*y]
				v := a[x+5*y]
				if r != 0 {
					v = v<<r | v>>(64-r)
				}
				b[y+5*((2*x+3*y)%5)] = v
			}
		}
		for x := 0; x < 5; x++ {
			for y := 0; y < 25; y += 5 {
				a[y+x] = b[y+x] ^ (^b[y+(x+1)%5] & b[y+(x+2)%5])
			}
		}
		a[0] ^= keccakRC[round]
	}
}

func sha3Sum(data []byte, bits int) []byte {
	rate := 200 - 2*(bits/8)
	var st [25]uint64
	buf := make([]byte, 0, len(data)+rate)
	buf = append(buf, data...)
	// padding
	buf = append(buf, 0x06)
	for len(buf)%rate != 0 {
		buf = append(buf, 0)
	}
	buf[len(buf)-1] |= 0x80
	for off := 0; off < len(buf); off += rate {
		for i := 0; i < rate/8; i++ {
			st[i] ^= binary.LittleEndian.Uint64(buf[off+8*i:])
		}
		keccakF(&st)
	}
	out := make([]byte, 200)
	for i := 0; i < 25; i++ {
		binary.LittleEndian.PutUint64(out[8*i:], st[i])
	}
	return out[:bits/8]
