// orderByIndex adjusts the access path so that rows are produced in an order
// satisfying ORDER BY when an index (or the rowid) can provide it, mimicking SQLite.
func (cp *compiler) orderByIndex(s *fromSrc, orderBy []*OrderTerm) {
	if s.kind != srcTable || s.table == nil {
		return
	}
	t := s.table
	ap := s.path
	if ap == nil {
		ap = &accessPath{kind: apFull}
		s.path = ap
	}
	type term struct {
		col  int // -1 rowid
		desc bool
		coll string
	}
	var terms []term
	for _, ot := range orderBy {
		e := ot.E
		coll := ""
		if e.Op == ECollate {
			coll = strings.ToUpper(e.Name)
			e = e.L
		}
		if e.Op != EColumn || ot.Nulls != 0 {
			return
		}
		if e.Table != "" && !strings.EqualFold(e.Table, s.info.name) {
			return
		}
		ci := t.colIndex(e.Column)
		if ci < 0 {
