		for _, tm := range terms[1:] {
			_ = tm
		}
		if ap.kind == apFull || ap.kind == apRowidRange || ap.kind == apRowidEq {
			ap.reverse = terms[0].desc
		}
		return
	}
	match := func(ix *Index, skip int) (bool, bool) {
		k := skip
		reverse := false
		for i, tm := range terms {
			if k >= len(ix.Cols) {
				if tm.col == -1 && !t.WithoutRowid {
					r := tm.desc
					if i > 0 && r != reverse {
						return false, false
					}
