// transitiveTerms derives implied column equalities (a=b, b=c => a=c) for planning.
func (cp *compiler) transitiveTerms(srcs []*fromSrc, terms []*termInfo, sc *scope) []*termInfo {
	type colRef struct {
		e   *Expr
		src int
		col int
	}
	cp.noEqp++
	defer func() { cp.noEqp-- }()
