		ok := false
		func() {
			defer func() { recover() }()
			c, deps := cp.compileWithDeps(e, sc)
			if c.isColumn && c.depth == 0 && deps == uint64(1)<<uint(c.srcIdx) {
				r = colRef{e: e, src: c.srcIdx, col: c.colIdx}
				ok = true
			}
		}()
		return r, ok
	}
	parent := map[[2]int][2]int{}
	exprs := map[[2]int]*Expr{}
	var find func(k [2]int) [2]int
	find = func(k [2]int) [2]int {
		p, ok := parent[k]
		if !ok || p == k {
			parent[k] = k
			return k
		}
		r := find(p)
		parent[k] = r
		return r
	}
	direct := map[[4]int]bool{}
	for _, t := range terms {
		if t.isOn {
			continue
		}
		e := t.e
		if e.Op != EBinary || e.Name != "=" {
			continue
		}
		a, ok1 := resolve(e.L)
		b, ok2 := resolve(e.R)
		if !ok1 || !ok2 || a.src == b.src {
			continue
		}
		ka, kb := [2]int{a.src, a.col}, [2]int{b.src, b.col}
		exprs[ka] = e.L
		exprs[kb] = e.R
		parent[find(ka)] = find(kb)
		direct[[4]int{a.src, a.col, b.src, b.col}] = true
		direct[[4]int{b.src, b.col, a.src, a.col}] = true
	}
	groups := map[[2]int][][2]int{}
	for k := range exprs {
		r := find(k)
		groups[r] = append(groups[r], k)
	}
	var out []*termInfo
	for _, g := range groups {
		if len(g) < 3 {
			continue
		}
		sort.Slice(g, func(i, j int) bool {
			if g[i][0] != g[j][0] {
				return g[i][0] < g[j][0]
